(window.GIM_TP=window.GIM_TP||{})["Z.Tazria.0"]={"from":0,"a":[[["(ויקרא י״ב:ב׳) וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה לֵאמֹר אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר וְגוֹ'. רִבִּי אֶלְעָזָר פָּתַח, (שיר השירים ג׳:א׳) עַל מִשְׁכָּבִי בַּלֵּילוֹת בִּקַּשְׁתִּי וְגוֹ'. עַל מִשְׁכָּבִי, בְּמִשְׁכָּבִי מִבָּעֵי לֵיהּ, מַהוּ עַל מִשְׁכָּבִי. אֶלָּא כְּנֶסֶת יִשְׂרָאֵל אָמְרָה קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וּבָעָאת מִנֵּיהּ עַל גָּלוּתָא, בְּגִין דְּהִיא יָתְבָא בֵּין שְׁאָר עַמִּין עִם בְּנָהָא, וּשְׁכִיבַת לְעַפְרָא, וְעַל דְּהִיא שְׁכִיבַת בְּאַרְעָא אָחֳרָא מִסְאֲבָא, אָמְרָה, עַל מִשְׁכָּבִי בָּעֵינָא, דְּכָאִיבְנָא (נ\"א דשכיבנא) בְּגָלוּתָא, וְעַל דָּא, בִּקַּשְׁתִּי אֵת שֶׁאָהֲבָה נַפְשִׁי וּלְאַפָּקָא לִי מִנֵּיהּ."],[[0,"וידבר ה' אל משה וגו׳:","וידבר ה׳ אל משה לאמר אשה כי תזריע וילדה זכר וגו'. ר׳ אלעזר פתח, על משכבי בלילות בקשתי את שאהבה נפשי וגו׳. שואל, אומר, על משכבי, במשכבי היה צריך לומר, מהו על משכבי. ומשיב, אלא כנסת ישראל אמרה לפני הקב״ה, ובקשה ממנו על הגלות, משום שהיא יושבת בין שאר העמים עם בניה, ושוכבת לעפר, ועל שהיא שוכבת בארץ אחרת הטמאה, אמרה, \u0003על\u0004 משכבי אני מבקש, שאני שוכבת בגלות, והגלות מכונה לילות. ועל כן, \u0003בקשתי את שאהבה נפשי,\u0004 שיוציאני ממנה."]],[[0,"","וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵאמֹר אִשָּׁה כִי תַזְרִיעַ וְיָלְדָה זָכָר וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח, (שיר ג) עַל מִשְׁכָּבִי בַּלֵּילוֹת בִּקַּשְׁתִּי וְגוֹ'. עַל מִשְׁכָּבִי?! בְּמִשְׁכָּבִי הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה עַל מִשְׁכָּבִי? אֶלָּא כְּנֶסֶת יִשְׂרָאֵל אָמְרָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמְבַקֶּשֶׁת מִמֶּנּוּ עַל הַגָּלוּת, מִשּׁוּם שֶׁהִיא יוֹשֶׁבֶת בֵּין שְׁאָר הָעַמִּים עִם בָּנֶיהָ וְשׁוֹכֶבֶת לֶעָפָר. וְעַל שֶׁהִיא שׁוֹכֶבֶת בְּאֶרֶץ טְמֵאָה אַחֶרֶת, אוֹמֶרֶת: עַל מִשְׁכָּבִי אֲנִי מְבַקֶּשֶׁת, שֶׁאֲנִי כּוֹאֶבֶת (שוכבת) בַּגָּלוּת, וְעַל זֶה - בִּקַּשְׁתִּי אֵת שֶׁאָהֲבָה נַפְשִׁי, וּלְהוֹצִיא אוֹתִי מִמֶּנּוּ."]]],[["בִּקַּשְׁתִּיו וְלֹא מְצָאתִיו, דְּלָאו אָרְחֵיהּ לְאִזְדַּוְּוגָא בִּי אֶלָּא בְּהֵיכָלֵיהּ, קְרָאתִיו וְלֹא עָנָנִי. דְּהָא בֵּינִי עַמִּין אָחֳרָנִין יָתִיבְנָא, וְקָלֵיהּ לָא שַׁמְעִין אֶלָּא בְּנוֹי. דִּכְתִּיב, (דברים ד׳:ל״ג) הֲשָׁמַע עָם קוֹל אֱלֹהִים וְגוֹ'.","רִבִּי יִצְחָק אָמַר, עַל מִשְׁכָּבִי בַּלֵּילוֹת. אָמְרָה כְנֶסֶת יִשְׂרָאֵל עַל מִשְׁכָּבִי אִתְרָעַמְנָא קַמֵּיהּ, דִּיְהֵא מִזְדְּוַּוג עַמִּי לְמֶחְדֵּי לִי, וּלְבָרְכָא לִי, בְּחֵידוּ שְׁלִים. דְּהָכִי תָּנֵינָן דְּמִזִוּוּגָא דְּמַלְכָּא בִּכְּנֶסֶת יִשְׂרָאֵל, כַּמָּה צַדִּיקִים יַרְתּוּ יְרוּתַת אַחֲסַנְתָּא קַדִּישָׁא, וְכַמָּה בִּרְכָאן מִשְׁתַּכְּחֵי בְּעָלְמָא.","רִבִּי אַבָּא הֲוָה אָזִיל לִכְפָר קַנְיָּא, (ס\"א בפרקמטיא) לִמְעַרְתָּא דְלוּד. וַהֲווּ עִמֵּיהּ רִבִּי יוֹסֵי וְרִבִּי חִיָּיא. אָמַר רִבִּי יוֹסֵי, כְּתִיב, (משלי י״ב:ד׳) אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ וְגוֹ'. אֵשֶׁת חַיִל, דָּא כְּנֶסֶת יִשְׂרָאֵל. וּכְרָקָב בְּעַצְמוֹתָיו מְבִישָׁה. אִלֵּין (נ\"א דא מהימנותא דשאר) עַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, דְּקוּדְשָׁא בְּרִיךְ הוּא לָא יָכִיל לְמִסְבַּל לוֹן בְּעָלְמָא, כְּמָה דְאַתְּ אָמֵר, (ויקרא כ׳:כ״ג) וָאָקוּץ בָּם. כְּהָנֵי קוֹצִין וְגוּבִין דְּדַחֲקִין לֵיהּ לְבַּר נָשׁ וְלָא יָכִיל לְמִסְבַּל לוֹן. אָמַר רִבִּי אַבָּא, הָכִי הוּא וַדַּאי, אֵשֶׁת חַיִל, דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּהִיא גְּבִירְתָּא מִכַּמָּה חַיָּילִין וְכַמָּה מַשִּׁרְיָין דְּמִשְׁתַּכְּחֵי בְּעָלְמָא, עֲטֶרֶת בַּעְלָהּ, כְּמָה דְאַתְּ אָמֵר, עֲטֶרֶת תִּפְאֶרֶת, וְכֹלָּא חַד. (ל\"ג וכו' אשת חיל דא כנסת ישראל דהא בזווגא דמלכא אפיקת כמה חיילין כמה משיריין כמה צדיקים בעלמא וכלהו אקרון בנים לקודשא בריך הוא ולכנסת ישראל כמה דכתיב (דברים י״ד:א׳) בנים אתם ליי' אלהיכם.) עַד דַּהֲווֹ אָזְלֵי, אָמַר רִבִּי אַבָּא כָּל חַד לֵימָא מִלָּה, בִּכְּנֶסֶת יִשְׂרָאֵל.","רִבִּי אַבָּא פָּתַח וְאָמַר. (משלי ל״א:י׳) אֵשֶׁת חַיִל מִי יִמְצָא, דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי אֵשֶׁת חַיִל, כְּמָה דְּאַמָרָן. מִי יִמְצָא, כְּמָה דְאַתְּ אָמֵר, אֲשֶׁר יִמְצָא אֶתְכֶם בְּאַחֲרִית הַיָּמִים. (ל\"ג מי ימצא לאגחא ביה קרבא) מִי יִמְצָא, מַאן יִזְכֶּה לְמֶהֱוִי בֵּהּ בִּשְׁלִימוּ, וּלְאִשְׁתַּכְּחָא עִמָּהּ תָּדִיר.","וְרָחוֹק מִפְּנִינִים מִכְרָהּ, מִכְרָהּ, מִקְחָהּ מִבָּעֵי לֵיהּ. אֶלָּא, לְכָל אִינּוּן דְּלָא אִתְדַּבְּקָן בָּהּ בִּשְׁלִימוּ, וְלָא שְׁלֵמִין בַּהֲדָהּ, הִיא מָכְרָה לוֹן וְאַסְגְּרָא לוֹן בִּידָא דְּעַמָמִין אָחֳרָנִין. כְּמָה דְאַתְּ אָמֵר, (שמואל א י״ב:ט׳) וַיַּעַזְבוּ בְּנֵי יִשְׂרָאֵל אֶת יְיָ' וַיִמְכּוֹר אוֹתָם בְּיַד סִיסְרָא. וּכְדֵין כֻּלְּהוּ רְחִיקִין מֵאִלֵּין פְּנִינִים עִלָּאִין קַדִּישִׁין, דְּלָא יְהֵא חוּלָקָא בְּהוּ. הֲדָא הוּא דִכְתִיב וְרָחוֹק מִפְּנִינִים מִכְרָהּ.","רִבִּי חִיָּיא פָּתַח קְרָא אֲבַתְרֵיהּ וְאָמַר, בָּטַח בָּהּ לֵב בַּעְלָהּ וְשָׁלָל לֹא יֶחְסָר. בָּטַח בָּהּ לֵב בַּעְלָהּ, דָּא קוּדְשָׁא בְּרִיךְ הוּא, דִּבְגִינֵי כַּךְ מָנֵי לֵהּ עַל עָלְמָא, לְאִתְדַבְּרָא עָלָהּ, כָּל זִיּוּנִין דִּלֵיהּ אַפְקִיד בִּידָהָא, וְכָל אִינּוּן מַגִּיחֵי קְרָבָא, וְעַל דָּא, וְשָׁלָל לֹא יֶחְסָר.","רִבִּי יוֹסֵי פָּתַח קְרָא אֲבַתְרֵיהּ, וְאָמַר, גְּמָלַתְהוּ טוֹב וְלֹא רָע כָּל יְמֵי חַיֶּיהָ. גְּמָלַתְהוּ טוֹב, הִיא זְמִינַת טָב לְעָלְמָא, זְמִינַת טָב לְהֵיכָלָא דְּמַלְכָּא וְלִבְנֵי הֵיכָלֵיהּ. וְלֹא רָע. בְּגִין דִּכְתִּיב, (בראשית ב׳:ט׳) וְעֵץ הַדַּעַת טוֹב וָרָע, טּוֹב אֵימָתַי, בְּזִמְנָא דְּאִינּוּן יְמֵי הַשָּׁמַיִם, נָהֲרִין עָלָה, וּמִזְדַּוְּוגַן עִמָּהּ כְּדְקָא יֵאוֹת, דְּאִינּוּן יְמֵי חַיֶּיהָ. בְּגִין דְּעֵץ הַחַיִּים, שָׁדַר לָהּ חַיִּים, וְנָהִיר לָהּ. וּבְהַהוּא זִמְנָא גְּמָלַתְהוּ טוֹב וְלָא רָע. אָמַר רִבִּי אַבָּא שַׁפִּיר הוּא, וְכֻלְּהוּ קְרָאֵי בִּכְנֶסֶת יִשְׂרָאֵל אִתְּמָרוּ.","(ויקרא י״ב:ב׳) אִשָּׁה כִּי תַזְרִיעַ. תָּנֵינָן, אִשָּׁה מַזְרַעַת תְּחִלָּה יוֹלֶדֶת זָכָר. רִבִּי אֲחָא אָמַר, הָא תָּנֵינָן, דְּקוּדְשָׁא בְּרִיךְ הוּא גָּזַר עַל הַהִיא טִפָּה, אִי אִיהוּ דְּכַר אִי אִיהִי נוּקְבָּא, וְאַתְּ אַמְרַת אִשָׁה מַזְרַעַת תְּחִלָּה יוֹלֶדֶת זָכָר. אָמַר רִבִּי יוֹסֵי, וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא אַבְחִין בֵּין טִפָּה דִּדְכוּרָא וּבֵין טִפָּה דְּנוּקְבָּא, וּבְגִין דְּאַבְחִין לֵיהּ, גָּזַר עָלֵיהּ, אִי לִהֱוִי דְּכַר אוֹ נוּקְבָּא.","אָמַר רִבִּי אֲחָא, וְיָלְדָה זָכָר, וְכִי כֵּיוָן דְּמַזְרַעַת יוֹלֶדֶת, דִּכְתִּיב, וְיָלְדָה (אלא), הַאי קְרָא הָכִי מִבָּעֵי לֵיהּ, אִשָׁה כִּי תַּהַר וְיָלְדָה זָכָר. (ס\"א תזריע ויהיה זכר) מַהוּ, כִּי תַזְרִיעַ וְיָלְדָה. אָמַר רִבִּי יוֹסֵי, אִתְּתָא, מִן יוֹמָא דְּאִתְעַבְּרַת עַד יוֹמָא דְּיוֹלִדַת לֵית לָהּ בְּפוּמָא, אֶלָּא יְלִידוּ דִּילָהּ אִי לִהֱוִי דְּכַר, וְעַל דָּא, אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר.","אִשָּׁה כִּי תַזְרִיעַ. רִבִּי חִזְקִיָּה פָּתַח, (תהילים ק״ד:כ״ד) מַה רַבּוּ מַעֲשֶׂיךָ יְיָ'. כַּמָה סַגִּיאִין עוֹבָדוֹהִי דְּמַלְכָּא קַדִּישָׁא בְּעָלְמָא, מְתַל לְבַּר נָשׁ דְּנָטִיל בִּידוֹהִי כַּמָה מַקְטוּרִין כַּחֲדָא, וְזָרַע לוֹן בְּזִמְנָא חֲדָא, וּלְבָתַר נָפִיק כָּל חַד וְחַד בִּלְחוֹדוֹי. כַּךְ קוּדְשָׁא בְּרִיךְ הוּא עֲבִיד עוֹבָדוֹהִי בְּחָכְמָה, וּבְחָכְמָה נָטִיל כֹּלָּא כַּחֲדָא וְזָרַע לוֹן, וּלְבָתַר נָפְקוּ כָּל חַד וְחַד בְּזִמְנֵיהּ, הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:כ״ד) כֻּלָּם בְּחָכְמָה עָשִׂיתָ."],[[0,"בקשתיו ולא מצאתיו:","משום, כי אין דרכו להזדווג בי רק בהיכלו. ולא בגלות. \u0003קראתיו ולא ענני.\u0004 כי ישבתי בין עמים אחרים, וקולו אינם שומעים אלא בניו. שכתוב, השמע עם קול אלקים וגו׳."],[1,"ר׳ יצחק אמר וכו׳:","רי״א, על משכבי בלילות. אמרה כנסת ישראל, שהיא השכינה, על משכבי התרעמתי לפניו, דהיינו שבקשתיו, שיזדווג עמי לשמח אותי. מקו שמאל, ולברך אותי, מקו ימין, בשמחה שלימה, מקו האמצעי. כי כך למדנו שמזווג המלך, שהוא ז״א, עם כנסת ישראל, יורשים כמה צדיקים ירושת נחלה קדושה, דהיינו מוחין עליונים, וכמה ברכות נמצאות בעולם."],[2,"ר׳ אבא הוה וכו׳:","ר״א היה הולך לכפר קניא, למערה של לוד. והיו עמו ר׳ יוסי ור׳ חייא. א״ר יוסי, כתוב. אשת חיל עטרת בעלה וגו׳. \u0003אשת חיל,\u0004 זו היא כנסת ישראל, שהיא השכינה. וכרקב בעצמותיו מבישה אלו הם עמים עכו״ם, שהקב״ה אינו יכיל לסובלם בעולם, כש׳׳א, ואקוץ בם. כאלו קוצים ודרדרים שמצירים לאדם ואינו יכול לסובלם. א״ר אבא, כך הוא ודאי, אשת חיל, זו היא כנסת ישראל, שהיא גברת על כמה צבאות וכמה מחנות מלאכים הנמצאים בעולם, דהיינו כל דרי בי״ע המתפשטים ממנה. ואשת חיל פירושו גברת ואדון, \u0003עטרת בעלה,\u0004 הוא כש״א עטרת תפארת, והכל אחד. כי התפארת, היא בעלה של השכינה. בעוד שהיו הולכים, א\"ר אבא כל אחד יאמר דבר, בכנסת ישראל."],[3,"ר׳ אבא פתח וכו׳:","רא״פ ואמר. \u0003אשת חיל מי ימצא,\u0004 זו כנסת ישראל, שהיא אשת חיל, כמו שאמרנו. \u0003מי ימצא.\u0004 הוא כש\"א, אשר ימצא אתכם באחרית הימים. שפירושו, אשר ישיג אתכם, אף כאן, מי ימצא, פירושו, מי יזכה וישיגה להיות בה בשלמות, ולהמצא עמה תמיד."],[4,"ורחוק מפנינים מכרה וגו׳:","שואל, אומר, מכרה, מקחה היה צריך לומר, דהיינו שקשה לקנותה יותר מפנינים. מהו שאומר מכרה. ומשיב, אלא, כל אלו שאינם מתדבקים בה בשלמות, ואינם שלמים עמה, היא \u0003מוכרת\u0004 אותם ומסגירה אותם בידי עמים אחרים. כמו שאתה אומר, ויעזבו בני ישראל את ה׳ \u0003וימכור\u0004 אותם ביד סיסרא. ואז כולם \u0003רחוקים\u0004 מאלו \u0003פנינים\u0004 העליונים הקדושים, שהם סודות ופנימיות התורה, שלא יהיה להם חלק בהם. ז״ש ורחוק מפנינים מכרה."],[5,"ר׳ חייא פתח וכו׳:","רח״פ המקרא שלאחריו ואמר, בטח בה לב בעלה ושלל לא יחסר. \u0003בטח בה לב בעלה,\u0004 זהו הקב״ה, שהוא ז״א, שמשום זה הפקיד אותה על העולם שיתנהג על ידה, כל הנשק שלו הפקיד בידה, וכל אלו עושי מלחמה. ועל כן, \u0003ושלל לא יחסר.\u0004 פירוש. שכל הכחות לעשות מלחמה ולהכניע הסטרא אחרא, נתן בידיה, שעי״ז מוציאה הניצוצין קדישין שנפלו לחיצונים בסבת החטא, ומחזרת אותם לקדושה, ואלו ניצוצין קדישין, מכונים שלל. בסוד שלל המלחמה."],[6,"ר׳ יוסי פתח וכו׳:","ר״י פתח הכתוב שלאחריו, ואמר, גמלתהו טוב ולא רע כל ימי חייה. \u0003גמלתהו טוב,\u0004 היינו, שהיא נותנת טוב לעולם ונותנת טוב להיכל המלך ולבני היכלו. \u0003ולא רע.\u0004 היה צריך לומר זה, משום שכתוב, ועץ הדעת טוב ורע, שהמלכות נקראת עץ הדעת טוב ורע, מטעם, זכה הא טוב לא זכה הא רע (כנ״ל בהקדמת ספר הזוהר אות קכ״ג) וע״כ אומר \u0003ולא רע.\u0004 מתי היא טוב, ולא רע, הוא בזמן שימי השמים, שהם הספירות דז״א, מאירים עליה, ומזדווגים עמה כראוי. שימי השמים, הם \u0003ימי חייה.\u0004 משום שעץ החיים, שהוא ז״א, שולח לה חיים, שהם המוחין מבינה, ומאיר לה. ובזמן ההוא, \u0003גמלתהו טוב ולא רע.\u0004 אמר ר׳ אבא יפה הוא. וכל הכתובים אלו בכנסת ישראל נאמרו."],[7,"אשה כי תזריע:","למדנו, אשה מזרעת תחילה יולדת זכר. ר׳ אחא אמר, זה שלמדנו, שהקב״ה גוזר על הטפה, אם הוא זכר או נקבה, ואתה אומר, אשה מזרעת תחילה יולדת זכר. וא״כ לא צריכים לגזירת הקב״ה. א״ר יוסי, ודאי שהקב״ה מבחין בין טפה של זכר ובין טפה של נקבה, ומשום שהבחין בה, גזר עליה, אם תהיה זכר או נקבה."],[7,"","פירוש. כי ג׳ שותפין באדם, הקב״ה ואביו ואמו, שאביו נותן הלבן שבו, ואמו האדום שבו, והקב״ה נותן הנשמה. ואם הטפה היא זכר נותן הקב״ה נשמה של זכר ואם נקבה, נותן הקב״ה נשמה של נקבה. ונמצא, שבזה שאשה הזריעה תחילה, עוד לא היתה הטפה בסופה לזכר, אם הקב״ה לא שלח בה נשמה של זכר. והבחנה זו שהקב\"ה מבחין בהטפה שהיא ראויה לנשמה של זכר או של נקבה. נחשבת לגזירה של הקב״ה. שאם לא הבחין בזה, ולא שלח נשמה של זכר, לא היתה נגמרת הטפה להיות זכר. ונמצא שב׳ המאמרים אינם סותרים זה את זה."],[8,"א״ר אחא וכו׳:","אר״א, \u0003וילדה זכר,\u0004 וכי כיון שמזרעת יולדת, שהכתוב אומר, כי תזריע וילדה, הלא בהריון תלוי הדבר, והכתוב הזה היה צריך לומר, אשה כי תהר וילדה זכר. מהו, כי תזריע וילדה. א״ר יוסי אשה, מיום שהזריעה ונתעברה עד יום שיולדת אין מלה בפיה, אלא הולד שלה אם יהיה זכר. וע״כ אוה״כ, אשה כי תזריע וילדה זכר."],[9,"אשה כי תזריע:","ר׳ חזקיה פתח, מה רבו מעשיך ה'. כמה מרובים מעשיו של המלך הקדוש בעולם, משל לאדם שלקח בידיו כמה מיני זרעים ביחד, וזורע אותם בזמן אחד, ואח\"כ יוצא כל מין ומין בפני עצמו. כך הקב״ה עושה מעשיו בחכמה, ובחכמה לוקח הכל ביחד וזורע אותם, ואח״כ יוצא כל אחד ואחד בזמנו. ז״ש כולם בחכמה עשית. \u0003מקטורין\u0004 פירושו מיני זרעים. לפי הענין."]],[[0,"","בִּקַּשְׁתִּיו וְלֹא מְצָאתִיו, שֶׁאֵין דַּרְכּוֹ לְהִזְדַּוֵּג עִמִּי אֶלָא בְּהֵיכָלוֹ, קְרָאתִיו וְלֹא עָנָנִי. שֶׁהִנֵּה בֵּין עַמִּים אֲחֵרִים אֲנִי יוֹשֶׁבֶת, וְאֵין שׁוֹמְעִים אֶת קוֹלוֹ אֶלָּא בָּנָיו, שֶׁכָּתוּב (דברים ד) הֲשָׁמַע עָם קוֹל אֱלֹהִים וְגוֹ'."],[1,"","רַבִּי יִצְחָק אָמַר, עַל מִשְׁכָּבִי בַּלֵּילוֹת - אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, עַל מִשְׁכָּבִי הִתְרַעַמְתִּי לְפָנָיו, שֶׁהָיָה מִזְדַּוֵּג עִמִּי לְשַׂמֵּחַ אוֹתִי וּלְבָרֵךְ אוֹתִי בְּשִׂמְחָה שְׁלֵמָה. שֶׁכָּךְ שָׁנִינוּ, שֶׁמִּזִּוּוּג שֶׁל הַמֶּלֶךְ עִם כְּנֶסֶת יִשְׂרָאֵל כַּמָּה צַדִּיקִים יָרְשׁוּ יְרֻשַּׁת נַחֲלָה הַקְּדוֹשָׁה, וְכַמָּה בְרָכוֹת נִמְצָאוֹת בָּעוֹלָם."],[2,"","רַבִּי אַבָּא הָיָה הוֹלֵךְ לִכְפָר קַנְיָא (בסחורה) לִמְעָרַת לוֹד, וְהָיוּ עִמִּי רַבִּי יוֹסֵי וְרַבִּי חִיָּיא. אָמַר רַבִּי יוֹסֵי, כָּתוּב (משלי יב) אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ וְגוֹ'. אֵשֶׁת חַיִל - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וּכְרָקָב בְּעַצְמוֹתָיו מְבִישָׁה - אֵלּוּ (זו האמונה של שאר) הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא יָכוֹל לִסְבֹּל אוֹתָם בָּעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא ב) וָאָקוּץ בָּם. כְּאוֹתָם קוֹצִים וְדַרְדָּרִים שֶׁדּוֹחֲקִים אֶת הָאָדָם וְלֹא יָכוֹל לִסְבֹּל אוֹתָם. אָמַר רַבִּי אַבָּא, כָּךְ זֶה וַדַּאי. אֵשֶׁת חַיִל - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא הַגְּבֶרֶת מִכַּמָּה חֲיָלוֹת וְכַמָּה מַחֲנוֹת שֶׁנִּמְצָאִים בָּעוֹלָם. עֲטֶרֶת בַּעְלָהּ - כְּמוֹ שֶׁנֶּאֱמַר עֲטֶרֶת תִּפְאֶרֶת, וְהַכֹּל אֶחָד. (ל\"ג אשת חיל זו כנסת ישראל, שהריבזווג המלך הוציאה כמה חילות, כמה מחנות, כמה צדיקים בעולם, וכלם נקראים בנים להקדוש ברוך הוא ולכנסת ישראל, כמו שכתוב (דברים יד) בנים אתם לה' אלהיכם) עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי אַבָּא, כָּל אֶחָד יֹאמַר דָּבָר בִּכְנֶסֶת יִשְׂרָאֵל."],[3,"","רַבִּי אַבָּא פָּתַח וְאָמַר, אֵשֶׁת חַיִל מִי יִמְצָא - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא אֵשֶׁת חַיִל, כְּמוֹ שֶׁאָמַרְנוּ. מִי יִמְצָא, כְּמוֹ שֶׁנֶּאֱמַר אֲשֶׁר יִמְצָא אֶתְכֶם בְּאַחֲרִית הַיָּמִים. (ל\"ג מי ימצא להגיח בו קרב) מִי יִמְצָא - מִי יִזְכֶּה לִהְיוֹת עִמָּהּ בִּשְׁלֵמוּת וּלְהִמָּצֵא עִמָּהּ תָּמִיד."],[4,"","וְרָחוֹק מִפְּנִינִים מִכְרָהּ, מִכְרָהּ?! מִקָּחָהּ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא לְכָל אוֹתָם שֶׁלֹּא נִדְבְּקוּ עִמָּהּ בִּשְׁלֵמוּת וְלֹא שְׁלֵמִים עִמָּהּ, הִיא מָכְרָה אוֹתָם וְהִסְגִּירָה אוֹתָם בִּידֵי עַמִּים אֲחֵרִים, כְּמוֹ שֶׁנֶּאֱמַר וַיַּעַזְבוּ בְּנֵי יִשְׂרָאֵל אֶת ה', וַיִּמְכֹּר אֹתָם בְּיַד סִיסְרָא. וְאָז הִתְרַחֲקוּ כֻלָּם מֵאוֹתָן פְּנִינִים עֶלְיוֹנוֹת קְדוֹשׁוֹת, שֶׁלֹּא יְהֵא חֵלֶק בָּהֶן. זֶהוּ שֶׁכָּתוּב וְרָחוֹק מִפְּנִינִים מִכְרָהּ."],[5,"","רַבִּי חִיָּיא פָּתַח בַּפָּסוּק אַחֲרָיו וְאָמַר, בָּטַח בָּהּ לֵב בַּעְלָהּ וְשָׁלָל לֹא יֶחְסָר, בָּטַח בָּהּ לֵב בַּעְלָהּ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁמִּשּׁוּם כָּךְ מִנָּה אוֹתָהּ עַל הָעוֹלָם לְהַנְהִיג אוֹתוֹ, כָּל כְּלֵי הַזַּיִן שֶׁלּוֹ הִפְקִיד בְּיָדֶיהָ, וְכָל אוֹתָם לוֹחֲמֵי הַקְּרָב, וְעַל כֵּן וְשָׁלָל לֹא יֶחְסָר."],[6,"","רַבִּי יוֹסֵי פָּתַח בַּפָּסוּק אַחֲרָיו וְאָמַר, גְּמָלַתְהוּ טוֹב וְלֹא רָע כָּל יְמֵי חַיֶּיהָ. גְּמָלַתְהוּ טוֹב, הִיא הִזְמִינָה טוֹב לָעוֹלָם, הִזְמִינָה טוֹב לְהֵיכַל הַמֶּלֶךְ וְלִבְנֵי הֵיכָלוֹ. וְלֹא רָע, מִשּׁוּם שֶׁכָּתוּב (בראשית ב) וְעֵץ הַדַּעַת טוֹב וָרָע. מָתַי טוֹב? בִּזְמַן שֶׁאוֹתָם יְמֵי הַשָּׁמַיִם מְאִירִים עָלֶיהָ וּמִזְדַּוְּגִים עִמָּהּ כָּרָאוּי, שֶׁהֵם יְמֵי חַיֶּיהָ. מִשּׁוּם שֶׁעֵץ הַחַיִּים שׁוֹלֵחַ לָהּ חַיִּים וּמֵאִיר לָהּ, וּבְאוֹתוֹ זְמַן - גְּמָלַתְהוּ טוֹב וְלֹא רָע. אָמַר רַבִּי אַבָּא, יָפֶה הוּא, וְכָל הַפְּסוּקִים נֶאֶמְרוּ עַל כְּנֶסֶת יִשְׂרָאֵל."],[7,"","אִשָּׁה כִּי תַזְרִיעַ. שָׁנִינוּ, אִשָּׁה מַזְרַעַת תְּחִלָּה, יוֹלֶדֶת זָכָר. רַבִּי אָחָא אָמַר, הֲרֵי שָׁנִינוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא גָּזַר עַל הַטִּפָּה הַהִיא אִם הִיא זָכָר אִם הִיא נְקֵבָה, וְאַתָּה אוֹמֵר אִשָּׁה מַזְרַעַת תְּחִלָּה יוֹלֶדֶת זָכָר? אָמַר רַבִּי יוֹסֵי, וַדַּאי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַבְחִין בֵּין טִפָּה שֶׁל זָכָר וּבֵין טִפָּה שֶׁל נְקֵבָה, וּמִשּׁוּם שֶׁמַּבְחִין בָּהּ, גּוֹזֵר עָלֶיהָ אִם תִּהְיֶה זָכָר אוֹ נְקֵבָה."],[8,"","אָמַר רַבִּי אָחָא, וְיָלְדָה זָכָר - וְכִי כֵּיוָן שֶׁמַּזְרַעַת יוֹלֶדֶת, שֶׁכָּתוּב וְיָלְדָה? (אלא) הַפָּסוּק הַזֶּה כָּךְ הָיָה צָרִיךְ לִהְיוֹת: אִשָּׁה כִּי תַהַר וְיָלְדָה זָכָר. (תזריעויהיהזכר) מַה זֶּה כִּי תַזְרִיעַ וְיָלְדָה? אָמַר רַבִּי יוֹסֵי, אִשָּׁה, מִיּוֹם שֶׁמִּתְעַבֶּרֶת עַד הַיּוֹם שֶׁמּוֹלִידָה, אֵין לָהּ בְּפִיהָ אֶלָּא הַיִּלּוֹד שֶׁלָּהּ אִם יִהְיֶה זָכָר, וְעַל כֵּן - אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר."],[9,"","אִשָּׁה כִּי תַזְרִיעַ. רַבִּי חִזְקִיָּה פָּתַח, מָה רַבּוּ מַעֲשֶׂיךְ ה', כַּמָּה רַבִּים מַעֲשֵׂי הַמֶּלֶךְ הַקָּדוֹשׁ בָּעוֹלָם. מָשָׁל לְאָדָם שֶׁלָּקַח בְּיָדוֹ כַּמָּה זְרָעִים יַחַד, וְזָרַע אוֹתָם בְּפַעַם אַחַת, וְאַחַר כָּךְ יוֹצֵא כָּל אֶחָד וְאֶחָד לְבַדּוֹ. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה מַעֲשָׂיו בְּחָכְמָה, וּבְחָכְמָה נָטַל הַכֹּל יַחַד וְזָרַע אוֹתָם, וְאַחַר כָּךְ יָצְאוּ כָּל אֶחָד וְאֶחָד בִּזְמַנּוֹ. זֶהוּ שֶׁכָּתוּב (תהלים קד) כֻּלָּם בְּחָכְמָה עָשִׂיתָ."]]],[["אָמַר רִבִּי אַבָּא, מָה רַבּוּ מַעֲשֶׂיךָ יְיָ', כַּמָה סַגִּיאִין אִינּוּן עוֹבָדוֹהִי דְּמַלְכָּא קַדִּישָׁא, וְכֻלְּהוּ, סְתִימִין בְּחָכְמָה, הֲדָא הוּא דִכְתִיב כֻּלָּם בְּחָכְמָה עָשִׂיתָ. כֻּלְּהוּ בְּחָכְמָה כְּלִילָן, וְלָא נָפְקֵי לְבַר אֶלָּא בִּשְׁבִילִין יְדִיעָן, לְגַבֵּי בִּינָה. וּמִתַּמָּן, אִתְעָבִידוּ כֹּלָּא וְאִתְתְּקָנוּ, הֲדָא הוּא דִכְתִיב, (משלי כ״ד:ג׳) וּבִתְבוּנָה יִתְכּוֹנָן. וְעַל דָּא כֻּלָּם בְּחָכְמָה עָשִׂיתָ, בְּבִינָה.","מָלְאָה הָאָרֶץ, הָאָרֶץ: דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּמִתַּמָּן אִתְמַלְּיָא מִכֹּלָּא, כְּמָה דְאַתְּ אָמֵר (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְגוֹ'. קִנְיָנֶיךָ. דְּהִיא אַפִּיקַת לוֹן לְבָתַר, הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ד׳) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּה' בְּרָאָם. בְּגִינֵי כַּךְ מָלְאָה הָאָרֶץ קִנְיָנֶיךָ.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּבַר נָשׁ אָתֵי לְאִתְקַדְשָׁא לְאִזְדַוְּוגָא בְּנוּקְבֵיהּ, (בכוונה) בִּרְעוּתָא קַדִּישָׁא דִּילֵיהּ, אִתְּעַר עָלֵיהּ רוּחָא (אחרא) קַדִּישָׁא, כָּלִיל דְּכַר וְנוּקְבָּא. וְרָמִיז קוּדְשָׁא בְּרִיךְ הוּא לְחַד שְׁלוּחָא מְמָנָא עַל עִדּוּיֵיהוֹן דִּבְנֵי נָשָׁא, וּמָנֵי בִּידֵיהּ הַהוּא רוּחָא, וְאוֹדַע לֵיהּ, לְאָן אֲתַר יִפְקוֹד לֵיהּ. הֲדָא הוּא דִּכְתִּיב, (איוב ג׳:ג׳) וְהַלַּיְלָה אָמַר הוֹרָה גָּבֶר. הַלַּיְלָה אָמַר, לְהַהוּא מְמָנָא, הוֹרָה גָּבֶר מִפְּלַנְיָא, וְקוּדְשָׁא בְּרִיךְ הוּא אַפְקִיד לֵיהּ, לְהַהוּא רוּחָא, כָּל מַה דְּאַפְקִיד, וְהָא אוּקְמוּהָ.","כְּדֵין רוּחָא נַחְתָּא, וְחַד צוּלְמָא עִמֵּיהּ, (ק\"ד ע\"ב) הַהוּא דְּקָאִים בְּדִיוּקְנֵיהּ לְעֵילָּא, בְּהַהוּא צוּלְמָא אִתְבְּרֵי (ס\"א אתרבי), בְּהַהוּא צוּלְמָא אָזִיל בְּהַאי עָלְמָא. הֲדָא הוּא דִּכְתִּיב, (תהילים ל״ט:ז׳) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ. בְּעוֹד דְּהַאי צוּלְמָא אִשְׁתְּכַח (ויחי ר\"כ ע\"א) עִמֵּיהּ דְּבַּר נָשׁ, (בצולמא דיליה) קָאִים בְּהַאי עָלְמָא, דְמִתְחֲבְּרָאן כַּחֲדָא (ס\"א אשתכח עמיה בר נש קאים בהאי עלמא ותרין אינון דמתחברן כחדא), וּשְׁלֹמֹה מַלְכָּא אַזְהַר לִבְנֵי נָשָׁא וְאָמַר, (שיר השירים ב׳:י״ז) עַד שֶׁיָּפוּחַ הַיּוֹם וְנָסוּ הַצְּלָלִים, תְּרֵי.","וּבְסִפְרָא דְּחָרָשִׁין דְּאַשְׁמְדַאי, אַשְׁכַּחְנָא דְּאִינּוּן דְּיַדְעֵי (ס\"א דבעו) לְחַרְשָׁא חָרָשִׁין מִסְטַר שְׂמָאלָא, וּלְאִתְדַּבְּקָא בְּהוּ, יְקוּם לִנְהוֹרָא דִּשְׁרָגָא, אוֹ בַּאֲתַר דְּיִתְחֲזוּן אִינּוּן צוּלְמִין דִּילֵיהּ, וְיֵימָא אִינּוּן מִלִּין דְּמִתַתְּקְנֵי לְאִינּוּן חָרָשִׁין, וְיִקְרֵי לוֹן, לְאִינּוּן סִטְרִין מִסְאֲבִין, בִּשְׁמָהָן מִסְאֲבִין דִּילְהוֹן, וְיַזְמִּין (ויומי) צוּלְמִין דִּילֵיהּ לְאִינּוּן דְּקָארֵי, וְיֵימָא דְּהוּא אִתְתָּקַּן בִּרְעוּתֵיהּ לְהוּ לְפִקּוּדַיְיהוּ, וְהַהוּא בַּר נָשׁ נָפַק מֵרְשׁוּ דְּמָארֵיהּ וּפִקְדוֹנָא דִּילֵיהּ, יָהַב לִסְטַר מִסְאֲבָא.","וּבְאִינּוּן מִלִּין דְּחָרָשִׁין דְּאִיהוּ יֵימָא, וְיַזְמִין (נ\"א ויומי) לוֹן לְצוּלְמֵי, אִתְחָזוּן תְּרֵין רוּחִין וּמִתְתַּקְּנִין בְּאִינּוּן צוּלְמִין דִּילֵיהּ, בְּחֵיזוּ דִּבְנֵי אֱנָשָׁא, וּמוֹדְעִין לֵיהּ מִלִּין לְאַבְאָשָׁא, וּמִלִּין לְאוֹטָבָא, לְזִמְנִין יְדִיעָן. וְאִלֵּין תְּרֵי רוּחִין, דְּלָא אִתְכְּלִילוּ בִּכְלָלָא דְּגוּפָא, הַשְׁתָּא אִתְכְּלִילָן בְּאִלֵּין צוּלְמִין, וּמִתְתַּקְּנָן בְּהוּ וּמוֹדְעִין לֵיהּ לְבַר נָשׁ מִלִּין לְאַבְאָשָׁא, וְדָא הוּא דְּנָפִיק מֵרְשׁוּתָא דְּמָארֵיהּ, וּפִקְדוֹנָא דִּילֵיהּ, יָהִיב לִסְטַר מִסְאֲבָא.","תָּא חֲזֵי, אָסִיר לֵיהּ לְבַר נָשׁ לְאַשְׁדָאָה מָאנֵי דְּבֵיתָא, וּלְאַפְקְדָא לֵיהּ לְסִטְרָא אָחֳרָא, דְּלָא אִצְטְרִיךְ, אוֹ מִלָּה אָחֳרָא דִּכְוָותֵיהּ, (ס\"א דביתיה לקבלא ליה) דְּהָא כַּמָה גַּרְדִּינֵי נִימוּסִין זְמִינִין לְהַהוּא מִלָּה לְקַבְּלָא לֵיהּ, וּמֵהַהוּא זִמְנָא, לָא שָׁארוּ עָלֵיהּ בִּרְכָאן, דְּהָא מִסִּטְרָא אָחֳרָא הוּא. כָּל שֶׁכֵּן מַאן דְּאַזְמִין בִּרְעוּתֵיהּ עַל הַהוּא טִיבוּ עִלָּאָה דִּילֵיהּ, לְאָחֳרָא וּלְסִטְרָא אָחֳרָא. דְּהָא, מֵהַהוּא דְּאַזְמִין לֵיהּ הֲוִי.","וְכַד קְרִיבוּ יוֹמִין דְּבַּר נָשׁ לְנָפְקָא מֵהַאי עָלְמָא, הַהוּא צוּלְמָא עִלָּאָה דְּיָהֲבֵי לֵיהּ, אַתְיָא הַהוּא רוּחָא בִּישָׁא דְּהֲוָה מִתְדָּבַּק בֵּיהּ בְּכָל יוֹמָא, וְנָטִיל לֵיהּ לְהַהוּא צוּלְמָא, וְאִתְתָּקַּן בֵּיהּ וְאָזִיל לֵיהּ, וְלָא אִתְחֲזָר בֵּיהּ בְּבַּר נָשׁ לְעָלְמִין. כְּדֵין יִנְדַּע דְּהָא אִתְדַּחְיָא הוּא מִכֹּלָּא.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּנִשְׁמְתָא נַחְתָּא לְאַעֲלָא לֵיהּ בְּהַאי עָלְמָא, נַחְתָּא בְּגִנְתָּא דְּעֵדֶן דְּאַרְעָא, וְחָמָאת יְקָרָא דְּרוּחֵיהוֹן דְּצַדִּיקַיָּיא קַיְימִין שׁוּרִין שׁוּרִין. לְבָתַר אַזְלַא לַגֵּיהִנָּם, וְחָמָאת לְהוּ לְרַשִׁיעַיָּיא דְּצַוְוחִין וַוי וַוי, וְלָא מֵרַחֲמֵי עָלַיְיהוּ. וּבְכֹלָּא אַסְהִידוּ בָּהּ סַהֲדוּתָא, וְהַהוּא צוּלְמָא קַדִּישָׁא קַיְּימָא עָלֵיהּ, עַד דְּנָפִיק לְעָלְמָא."],[[0,"אמר ר׳ אבא וכו׳:","אר\"א. מה רבו מעשיך ה׳, כמה מרובים הם מעשיו של מלך הקדוש, וכולם, כל המציאות שבעולמות, סתומים בחכמה. ז״ש כולם בחכמה עשית. כולם כלולים בחכמה, ואינם יוצאים לחוץ אלא בשבילים ידועים, שה\"ס ל״ב נתיבות החכמה, אל הבינה. ומשם, מן הבינה, נעשה הכל ומתתקן. ז״ש ובתבונה יתכונן. וע״כ אומר כולם בחכמה עשית, בבינה. על ידי הבינה."],[1,"מלאה הארץ:","הארץ, זו היא כנסת ישראל, שהיא המלכות, שמשם, מן הבינה, היא מתמלאת מן הכל. כש״א כל הנחלים הולכים אל הים וגו׳. \u0003קניניך.\u0004 שהיא, המלכות, הוציאה אותם אח\"כ, ז״ש, אלה תולדות השמים והארץ בהבראם, דהיינו בה׳ בראם. שהיא המלכות, שה״ס ה' אחרונה דהויה. משום זה מלאה הארץ קניניך."],[2,"ת״ח בשעתא דב״נ וכו׳:","בוא וראה, בשעה שהאדם בא להתקדש ולהזדווג בנוקביה, ברצון הקדוש שלו, מתעורר עליו רוח קדוש, הכלול מזכר ונקבה. משום שנולד ונמשך מז״א ומלכות, שה״ס זכר ונקבה, (ועי׳ להלאה אות כ״ב) ורומז הקב״ה לשליח אחד הממונה על עיבור בני אדם, ומוסר בידו רוח ההוא, ומודיע לו, לאיזה מקום יתן אותו. ז״ש, והלילה אמר הורה גבר. דהיינו, שהלילה, שהיא המלכות המכונה לילה, אמר, לממונה ההוא, הורה גבר מפלוני, כדי שיתן שם את הרוח. והקב״ה מצוה אותו, את הרוח ההוא, כל מה שמצוה, דהיינו שמשביע אותו שיהיה צדיק וכו׳ (נידה ל:) וכבר העמידוהו."],[3,"כדין רוחא נחתא וכו׳:","אז יורד הרוח, וצלם אחד עמו, אותו צלם העומד בצורה של מעלה, שוקרא צלם אלקים, בצלם הזה הוא נברא, בצלם הזה הולך בעולם הזה. ז״ש, אך בצלם יתהלך איש. בעוד שהצלם הזה נמצא עמו, האדם מתקיים בעולם הזה, ואם הצלם מסתלק ממנו הוא מת (כנ״ל ויקרא אות ר״י) ושני צלמים הם שמתחברים יחד (שם אות רי״א). ושלמה המלך הזהיר לבני אדם ואמר, עד שיפוח היום ונסו הצללים. שנים."],[4,"ובספרא דחרשין וכו׳:","ובספרם של המכשפים של אשמדאי, מצאתי, שאלו הרוצים לעשות כשפים מצד שמאל, ולהתדבק בהם, יקום לאור הנר, או במקום שנראים הצלמים שלו, דהיינו לאור הלבנה, ויאמר אלו המלים המתוקנות לאלו הכשפים, ויקרא להם, לאלו צדדי הטומאה, בשמות הטומאה שלהם, ויזמין הצלמים שלו לאלו שמות הטומאה שקרא. ויאמר שהוא מתתקן להם ברצונו לרשותם. ולמצותם, ואז יוצא אדם ההוא מרשות אדונו והפקדון של אדונו, דהיינו הנשמה שניתנה לו בפקדון מאדונו, הוא נותן לצד הטומאה."],[5,"ובאינון מלין דחרשין וכו׳:","ועל ידי אלו דברי הכשפים שאמר, ושהזמין אותם לצלמים שלו, נראים שני רוחות ומתתקנים באלו הצלמים שלו, להיות תואר בני אדם, ומודיעים לו לזמנים ידועים דברים להרע לו, ודברים להטיב לו. ואלו שני רוחות, שלא נכללו בכלל גוף, שלא הספיק לעשות להם גופים עד שקדש השבת (כנ״ל בהקדמת ספר הזהר אות רמ״ח ע״ש) עתה נכללו באלו הצלמים שנתן להם האדם, והם מתתקנים בהם ומודיעים אל האדם דברים להזיק לו. וזה הוא שיצא מרשות אדונו, והפקדון שלו, דהיינו הנפש, נתן לצד הטומאה."],[6,"ת״ח אסיר ליה וכו׳:","בוא וראה, אסור לו לאדם לזרוק כלי ביתו או דבר אחר שכמותו בכעסו. ולמסור אותם בידי הסטרא אחרא. (כנ״ל פקודי אות תתנ״א) שלא צריך לעשות כן, כי כמה חוקרי דין ומשפט מוכנים לקבל דבר ההוא. ומזמן ההוא. אינן שורות עליו ברכות, כי מסטרא אחרא הוא. כל שכן מי שמזמין מרצונו על הטוב ההוא העליון, דהיינו על הצלם שלו, לאחר ולסטרא אחרא. שזה, מחמת שהזמין אותם לצלמים שלו, היה."],[7,"וכד קריבו יומין וכו׳:","וכשימיו של האדם קרובים לצאת מעולם הזה, אותו צלם העליון שנתנו לו, בא אותו רוח הרע שהיה מתדבק בו בכל יום, ולוקח ממנו אותו הצלם, ומתתקן בו והולך לו, והצלם לא יחזור לאדם לעולם. אז ידע האדם שהוא נדחה מכל."],[8,"ת״ח בשעתא דנשמתא וכו׳:","בוא וראה, בשעה שהנשמה יורדת להכניסה בעולם הזה, יורדת תחילה לגן עדן הארץ ורואה כבוד הרוחות של הצדיקים העומדים טורים טורים. ואח״כ הולכת לגיהנם, ורואה את הרשעים שצועקים אוי אוי, ואין מרחם עליהם. ובכל דבר מעידים לה עדות, שהרשעים מעידים איך נענשים על כל חטא, והצדיקים מעידים על שכרם הטוב שמקבלים בעד כל מצוה. ואותו הצלם הקדוש עומד עליה. עד שהיא יוצאת לעולם הזה."]],[[0,"","אָמַר רַבִּי אַבָּא, מָה רַבּוּ מַעֲשֶׂיךְ ה', כַּמָּה רַבִּים מַעֲשֵׂי הַמֶּלֶךְ הַקָּדוֹשׁ, וְכֻלָּם סְתוּמִים בְּחָכְמָה. זֶהוּ שֶׁכָּתוּב כֻּלָּם בְּחָכְמָה עָשִׂיתָ. כֻּלָּם כְּלוּלִים בְּחָכְמָה, וְלֹא יוֹצְאִים הַחוּצָה אֶלָּא בִּשְׁבִילִים יְדוּעִים כְּלַפֵּי הַבִּינָה, וּמִשָּׁם נַעֲשִׂים הַכֹּל וְנִתְתַּקְּנִים. זֶהוּ שֶׁכָּתוּב (משלי כד) וּבִתְבוּנָה יִתְכּוֹנָן, וְעַל זֶה - כֻּלָּם בְּחָכְמָה עָשִׂיתָ, בְּבִינָה."],[1,"","מָלְאָה הָאָרֶץ. הָאָרֶץ - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁמִּשָּׁם הַכֹּל מִתְמַלֵּא, כְּמוֹ שֶׁנֶּאֱמַר (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְגוֹ'. קִנְיָנֶךְ - שֶׁהִיא מוֹצִיאָה אוֹתָם אַחַר כָּךְ. זֶהוּ שֶׁכָּתוּב (בראשיתב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּה' בְּרָאָם. מִשּׁוּם כָּךְ, מָלְאָה הָאָרֶץ קִנְיָנֶךְ."],[2,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁאָדָם בָּא לְהִתְקַדֵּשׁ לְהִזְדַּוֵּג בִּנְקֵבָתוֹ (בכונה) בְּרָצוֹן קָדוֹשׁ שֶׁלּוֹ, מִתְעוֹרֶרֶת עָלָיו רוּחַ (אחרת) קְדוֹשָׁה, כְּלוּלָה זָכָר וּנְקֵבָה, וְרוֹמֵז הַקָּדוֹשׁ בָּרוּךְ הוּא לְשָׁלִיחַ אֶחָד הַמְמֻנֶּה עַל הֶרְיוֹנוֹת בְּנֵי הָאָדָם, וּמַפְקִיד בְּיָדוֹ אוֹתָהּ הָרוּחַ, וּמוֹדִיעַ לוֹ לְאֵיזֶה מָקוֹם יִפְקֹד אוֹתוֹ. זֶהוּ שֶׁכָּתוּב (איוב ג) וְהַלַּיְלָה אָמַר הֹרָה גָבֶר. הַלַּיְלָה אָמַר לְאוֹתוֹ מְמֻנֶּה: הֹרָה גָבֶר מִפְּלוֹנִי. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַפְקִיד לוֹ, אֶת אוֹתָהּ הָרוּחַ, כָּל מַה שֶּׁמַּפְקִיד, וְהִנֵּה פֵּרְשׁוּהָ."],[3,"","אָז יוֹרֶדֶת רוּחַ, וְצֶלֶם אֶחָד עִמָּהּ, אוֹתוֹ שֶׁעוֹמֵד בִּדְיוֹקְנוֹ לְמַעְלָה, בְּאוֹתוֹ צֶלֶם נִבְרָא (התגדל), בְּאוֹתוֹ צֶלֶם הוֹלֵךְ בָּעוֹלָם הַזֶּה. זֶהוּ שֶׁכָּתוּב (תהלים לט) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ. בְּעוֹד שֶׁהַצֶּלֶם הַזֶּה נִמְצָא עִם הָאָדָם, בַּצֶּלֶם שֶׁלּוֹ עוֹמֵד בָּעוֹלָם הַזֶּה, שֶׁמִּתְחַבְּרִים כְּאֶחָד (נמצא עמו אדם עומד בעולם הזה, ושנים הם שמתחברים כאחד) הוּא עוֹמֵד בָּעוֹלָם הַבָּא, וּשְׁנַיִם הֵם שֶׁמְּחֻבָּרִים יַחַד. וּשְׁלֹמֹה הַמֶּלֶךְ מַזְהִיר אֶת בְּנֵי הָאָדָם וְאוֹמֵר, (שיר ב) עַד שֶׁיָּפוּחַ הַיּוֹם וְנָסוּ הַצְּלָלִים, שְׁנַיִם."],[4,"","וּבְסֵפֶר הַכְּשָׁפִים שֶׁל אַשְׁמְדַאי מָצָאנוּ, שֶׁאוֹתָם שֶׁיּוֹדְעִים (שרוצים) לְכַשֵּׁף כְּשָׁפִים מִצַּד הַשְּׂמֹאל וּלְהִדָּבֵק בָּהֶם, יָקוּם לְאוֹר הַנֵּר אוֹ בְּמָקוֹם שֶׁיִּרְאוּ אוֹתָם הַצְּלָמִים שֶׁלּוֹ, וְיֹאמַר אוֹתָם דְּבָרִים שֶׁמְּתֻקָּנִים לְאוֹתָם הַכְּשָׁפִים, וְיִקְרָא לָהֶם לְאוֹתָם צְדָדִים טְמֵאִים בַּשֵּׁמוֹת הַטְּמֵאִים שֶׁלָּהֶם, וְיַזְמִין (וישביע) הַצְּלָמִים שֶׁלּוֹ לְאוֹתָם שֶׁקּוֹרֵא, וְיֹאמַר שֶׁהוּא מִתְתַּקֵּן בִּרְצוֹנוֹ לָהֶם לְמִצְוָתָם, וְאוֹתוֹ הָאִישׁ יוֹצֵא מֵרְשׁוּת רִבּוֹנוֹ, וּפִקְדוֹנוֹ נוֹתֵן לַצַּד הָאַחֵר."],[5,"","וּבְאוֹתָם דִּבּוּרִים שֶׁל כְּשָׁפִים שֶׁהוּא יֹאמַר וְיַזְמִין (וישביע) אוֹתָם לַצְּלָמִים, נִרְאִים שְׁתֵּי רוּחוֹת, וּמִתְתַּקְּנִים בְּאוֹתָם צְלָמִים שֶׁלּוֹ בְּמַרְאֶה שֶׁל בְּנֵי אָדָם, וּמוֹדִיעִים לוֹ דְּבָרִים לְהָרַע וּדְבָרִים לְהֵיטִיב לִזְמַנִּים יְדוּעִים. וְאֵלּוּ שְׁתֵּי הָרוּחוֹת שֶׁלֹּא נִכְלְלוּ בִּכְלָל שֶׁל גּוּף, עַכְשָׁו נִכְלָלִים בַּצְּלָמִים הַלָּלוּ, וּמִתְתַּקְּנִים בָּהֶם וּמוֹדִיעִים לוֹ לָאָדָם דְּבָרִים לְהָרַע, וְזֶהוּ שֶׁיּוֹצֵא מֵרְשׁוּת רִבּוֹנוֹ, וּפִקְדוֹנוֹ נוֹתֵן לַצַּד הַטָּמֵא."],[6,"","בֹּא רְאֵה, אָסוּר לָאָדָם לִזְרֹק כְּלֵי הַבַּיִת וּלְהַפְקִידוֹ לַצַּד הָאַחֵר, שֶׁלֹּא צָרִיךְ, אוֹ דָבָר אַחֵר שֶׁכְּמוֹתוֹ (של ביתו לקבל אותו), שֶׁהֲרֵי כַּמָּה שׁוֹמְרֵי הַכְּלָלִים מְזֻמָּנִים לַדָּבָר הַהוּא לְקַבֵּל אוֹתוֹ, וּמֵאוֹתוֹ זְמַן לֹא שׁוֹרִים עָלָיו בְּרָכוֹת, שֶׁהֲרֵי הוּא מִצַּד אַחֵר. כָּל שֶׁכֵּן מִי שֶׁמַּזְמִין בִּרְצוֹנוֹ עַל אוֹתוֹ הַטּוֹב הָעֶלְיוֹן שֶׁלּוֹ, לְאַחֵר וְלַצַּד הָאַחֵר, שֶׁהֲרֵי הוּא מֵאוֹתוֹ שֶׁהִזְמִין אוֹתוֹ."],[7,"","וּכְשֶׁקְּרֵבִים יְמֵי הָאָדָם לָצֵאת מִן הָעוֹלָם הַזֶּה, אוֹתוֹ הַצֶּלֶם הָעֶלְיוֹן שֶׁנּוֹתְנִים לוֹ, בָּאָה אוֹתָהּ רוּחַ רָעָה שֶׁהָיָה נִדְבָּק בָּהּ בְּכָל יוֹם, וְנוֹטֶלֶת אוֹתוֹ הַצֶּלֶם, וּמִתְתַּקֵּן בּוֹ וְהוֹלֵךְ לוֹ, וְלֹא חוֹזֵר לָאָדָם לְעוֹלָמִים. אָז יֵדַע שֶׁהֲרֵי הוּא נִדְחֶה מִן הַכֹּל."],[8,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁהַנְּשָׁמָה יוֹרֶדֶת לְהִכָּנֵס לוֹ בָּעוֹלָם הַזֶּה, יוֹרֶדֶת לְגַן הָעֵדֶן שֶׁל הָאָרֶץ, וְרוֹאָה אֶת כְּבוֹדָם שֶׁל רוּחוֹת הַצַּדִּיקִים עוֹמְדִים שׁוּרוֹת שׁוּרוֹת. אַחַר כָּךְ הוֹלֶכֶת לַגֵּיהִנֹּם, וְרוֹאָה אֶת הָרְשָׁעִים שֶׁצּוֹוְחִים וַי וַי, וְלֹא מְרַחֲמִים עֲלֵיהֶם. וּבַכֹּל מְעִידִים בָּהּ עֵדוּת, וְאוֹתוֹ הַצֶּלֶם הַקָּדוֹשׁ עוֹמֵד עָלֶיהָ, עַד שֶׁיּוֹצֵאת לָעוֹלָם."]]],[["כַּד נָפִיק לְעָלְמָא, אִזְדְּמַן הַהוּא צוּלְמָא לְגַבֵּיהּ, וְאִשְׁתְּתַף בַּהֲדֵּיהּ, וְאִתְרַבֵּי עִמֵּיהּ. כְּמָה דְּאִתְּמַר, (תהילים ל״ט:ז׳) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ. וּבְהַהוּא צֶלֶם אִשְׁתָּתָּפוּ (אשתכחו) יוֹמוֹי דְּבַר נָשׁ, וְתַּלְיָין בֵּיהּ, הֲדָא הוּא דִכְתִיב, (איוב ח׳:ט׳) כִּי תְמוֹל אֲנַחְנוּ וְלֹא נֵדָע כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ. כִּי צֵל יָמֵינוּ וַדַּאי. וּמִן יוֹמָא דְּמִתְעַבְּרָא אִתְּתָא עַד יוֹמָא דְּאוֹלִידַת, לָא יַדְעִין בְּנֵי נָשָׁא עוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, כַּמָּה אִינּוּן רַבְרְבִין, וְכַמָּה אִינּוּן עִלָּאִין. הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:כ״ד) מַה רַבּוּ מַעֲשֶׂיךָ יְיָ' וְגוֹ'.","תָּא חֲזֵי, כָּל רוּחִין דְּעָלְמָא כְּלִילָן דְּכַר וְנוּקְבָּא, וְכַד נָפְקִין, דְּכַר וְנוּקְבָּא נָפְקִין, וּלְבָתַר מִתְפָּרְשָׁן בְּאָרְחַיְיהוּ, אִי זָכֵי בַּר נָשׁ, לְבָתַר מִזְדַּוְּוגֵי כַּחֲדָא. וְהַיְינוּ בַּת זוּגוֹ, וּמִתְחַבְּרָן בְּזִוּוּגָא (ס\"א בגוונא) חַד בְּכֹלָּא, רוּחָא וְגוּפָא. דִּכְתִּיב, (בראשית א׳:כ״ד) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ. מַאי לְמִינָהּ. הַהוּא רוּחָא דְּבַּר נָשׁ דְּנָפִיק זוּגֵיהּ דְּדָמֵי לֵיהּ.","וּמַאי הָאָרֶץ, כְּמָה דְאַתְּ אָמֵר, (תהילים קל״ט:ט״ו) רֻקַּמְתִּי בְּתַחְתִּיּוֹת אָרֶץ. וְהָא אוּקְמוּהָ. תּוֹצֵא הָאָרֶץ וַדַּאי, דְּהָא מִנָּהּ נָפְקִין נֶפֶשׁ חַיָּה, כְּמָה דְּאוֹקִימְנָא, דָּא רוּחֵיהּ דְּאָדָם קַדְמָאָה, הַיְינוּ דִּכְתִּיב, (בראשית ג׳:ג׳) וּמִפְּרִי הָעֵץ אֲשֶׁר בְּתוֹךְ הַגָּן. וּמִפְּרִי הָעֵץ, דָּא קוּדְשָׁא בְּרִיךְ הוּא, אֲשֶׁר בְּתוֹךְ הַגָּן, אֲשֶׁר בְּתוֹךְ הָאִשָּׁה, תָּנֵינָן, הַיְינוּ, אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר, כְּתִיב. וְלָא כָּלִיל דְּכַר וְנוּקְבָּא, כְּפוּם אוֹרְחוֹי דְּעָלְמָא, דְּאִינּוּן, גָּרְמוּ לֵיהּ, דְּלָא מִתְחַבְּרָן, כַּמָה דְּנַפְקָן מִלְּעֵילָּא זוּגוֹת.","בְּגִין דְּאָדָם קַדְמָאָה, וְזִוּוג דִּילֵיהּ, חָבוּ לְּקוּדְשָׁא בְּרִיךְ הוּא, וְעַל דָּא מִתְפָּרְשִׁין, כַּד נָפְקִין מִלְּעֵילָּא, עַד דְּהֲוָה רַעֲוָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אִי זָכָה בַּר נָשׁ, יָהֲבִין לֵיהּ זוּגָתוֹ, וְאִי לָא, מַפְרִישִׁין לֵהּ מִנֵּיהּ, וְיָהֲבִין לָהּ לְאָחֳרָא, מוֹלִידִין בְּנִין דְּלָא כְּדְקָא יֵאוֹת. וְעַל דָּא כְּתִיב, (בראשית ו׳:ג׳) לֹא יָדוֹן רוּחִי בָאָדָם. מַאי רוּחִי, רוּחוֹ מִבָּעֵי לֵיהּ, אִינּוּן תְּרֵין רוּחֵי, דְּנַפְקֵי זוּגוֹת, לָא יְדוּנוּן כַּחֲדָא, וְעַל דָּא כְּתִיב, וְיָלְדָה זָכָר, וְלָא כָּלִיל דְּכַר וְנוּקְבָּא, כְּפוּם אוֹרְחוֹי דְּעָלְמָא, דְּאִינּוּן גָּרְמוּ.","רִבִּי אֶלְעָזָר אָמַר לָאו הָכִי, דְּהָא כֹּלָּא, דְּכַר וְנוּקְבָּא כְּלִילָן כַּחֲדָא, וּמִתְפָּרְשָׁן לְבָתַר, אֲבָל וְיָלְדָה זָכָר, כְּלִילָן כַּחֲדָא מִסִּטְרָא דִּימִינָא, וְאִם נְקֵבָה תֵלֵד, כְּלִילָן בְּחַד נוּקְבָּא וּדְכַר מִסִּטְרָא שְׂמָאלָא, דְּשַׁלְטָא סְטָר שְׂמָאלָא עַל סְטָר יְמִינָא יַתִּיר, וּדְכוּרָא אִתְכַּפְיָא בִּימִינָא דְּלָא שַׁלְטָא, וּכְדֵין הַהוּא דְּכַר דְּנָפִיק מִגּוֹ נוּקְבָּא, מִסְּטַר שְׂמָאלָא, כָּל אוֹרְחוֹי כְּנוּקְבָּא (ולא אקרי דכר), אֲבָל דְּכַר דְּנָפִיק מִגּוֹ יְמִינָא, הוּא שַׁלְטָא, וְנוּקְבָּא דְּנָפְקָא מִנֵּיהּ אִתְכַּפְיָא, דְּהָא סְטָר שְׂמָאלָא לָא שַׁלְטָא, וְעַל דָּא וְיָלְדָה זָכָר כְּתִיב.","וְכַמָּה אֶלֶף וְרִבְבָן נַפְקֵי בְּזִמְנָא חֲדָא לְעָלְמָא. וּמִן יוֹמָא דְּאַפְקַת לוֹן, לָא אִקְרוּן נַפְשָׁן, עַד דְּאִתְיַישְּׁבָן בְּגוּפָא. וְכַמָּה הוּא, ל\"ג יָמִים. הַיְינוּ דִּכְתִּיב, וּשְׁלֹשִׁים יוֹם וּשְׁלֹשֶׁת יָמִים וְגוֹ'. וְטָמְאָה שִׁבְעַת יָמִים, דְּהָא כָּל שִׁבְעַת יָמִים לָא עָאלִין רוּחִין לְגַבָּהּ, לְאִתְקַשְּׁרָא בָּהּ, וְכָל אִלֵּין שִׁבְעַת יָמִים, רוּחָא אָזְלָא בְּגוּפָא, לְאַשְׁכְּחָא אַתְרֵיהּ. וּכְדֵין כְּתִיב, (ויקרא כ״ב:כ״ז) וְהָיָה שִׁבְעַת יָמִים תַּחַת אִמּוֹ.","וּבְיוֹמָא תְּמִינָאָה, אִתְהֲדָרוּ רוּחָא וְגוּפָא לְאִתְחֲזָאָה קָמֵי מַטְרוֹנִיתָא, וּלְאִתְקַשְּׁרָא בָּהּ, וּבִדְכוּרָא, בְּגוּפָא וּבְרוּחָא. וּשְׁלֹשִׁים יוֹם וּשְׁלֹשֶׁת יָמִים תֵּשֵׁב עַל דְּמֵי טָהֳרָה, לְאִתְיַישְּׁבָא רוּחָא בְּגוּפָא. וְג' יָמִים מַאי עֲבִידְתַּיְיהוּ. אֶלָּא שְׁלֹשֶׁת יָמִים דְּמִילָה, דְּרַבְיָא כָּאִיב, וְרוּחָא לָא שַׁרְיָא מָדוֹרֵיהּ בְּגוּפָא כִּשְׁאָר יוֹמִין, וְעַל דָּא וּשְׁלֹשִׁים יוֹם וּשְׁלֹשֶׁת יָמִים תֵּשֵׁב בִּדְמֵי טָהֳרָה.","בִּדְמֵי טָהֳרָה בְּקַדְמִיתָא, וּלְבָתַר יְמֵי טָהֳרָה. בִּדְמֵי טָהֳרָה, אִלֵּין, דְּמֵי מִילָה, דָּמָא בָּתַר דָּמָא דְּאָתֵי מֵרַבְיָא, וְקוּדְשָׁא בְּרִיךְ הוּא נָטִיר לְאִינּוּן דְּמֵי כָּל אִלֵּין יוֹמִין, הֲדָא הוּא דִכְתִיב, תֵּשֵׁב בִּדְמֵי טָהֳרָה. טָהֳרָה סְתָם, וְלָא אַדְכִּיר הֵ\"א בַּתְרָאָה, דְּלָא תֵּימָא טָהֳרָה דְּמַטְרוֹנִיתָא, אֶלָּא טָהֳרָה סְתָם, דְּמֵי טָהֳרָה אִקְרוּן אִלֵּין דְּמֵי דַּכְיָא.","(ויקרא י״ב:ד׳) בְּכָל קֹדֶשׁ לֹא תִגָּע וְאֶל הַמִּקְדָּשׁ וְגוֹ'. תָּא חֲזֵי, בְּכָל יוֹמָא וְיוֹמָא, כְּנֶסֶת יִשְׂרָאֵל, נַטְלָא מִבֵּי מַלְכָּא מְזוֹנָא לְרוּחֵיהוֹן דִּבְנֵי נָשָׁא, וְזָנַת לְהוּ בִּקְדוּשָּׁה. בַּר לְהָנֵי, עַד דְּאִתְיַישְּׁבָן בְּגוּפָא אִינּוּן רוּחִין, בָּתַר תְּלָתִין וּתְלַת יוֹמִין, אַשְׁגָחַת עָלַיְיהוּ כָּל יוֹמָא, דְּהָא רוּחִין מִתְקַשְּׁרָן בְּגוּפָא כִּשְׁאָר בְּנֵי עָלְמָא, כְּמָה דְּהִיא לָא שַׁרְיָא אֶלָּא בַּאֲתַר שְׁלִים, כַּךְ כָּל עוֹבָדוֹי כְּהַאי גַּוְונָא, עַד דְּאִשְׁתְּלִימוּ. בְּכָל קֹדֶשׁ לֹא תִגָע, לְאַשְׁגְּחָא עָלַיְיהוּ."],[[0,"כד נפיק לעלמא וכו׳:","כשיוצאת לעולם, מזדמן לה אותו הצלם, ומשתתף עמה, וגדל עמה. כמו שנאמר, אך בצלם יתהלך איש. ובצלם ההוא משתתפים ימיו של האדם ותלוים בו, שאם הוא מסתלק נפטר האדם מן העולם, (כנ״ל ויקרא אות ר״י) ז״ש, כי תמול אנחנו ולא נדע כי צל ימינו עלי ארץ. \u0003כי צל ימינו\u0004 ודאי. דהיינו, שימינו תלוים בצל הזה. ומיום שהאשה מתעברת עד היום שיולדת, אין בני אדם יודעים מעשיו של הקב״ה, כמה הם גדולים, וכמה הם עליונים. ז״ש, מה רבו מעשיך ה׳ וגו׳."],[1,"ת״ח כל רוחין וכו׳:","בוא וראה. כל הרוחות שבעולם כלולים מזכר ונקבה, וכשיוצאים לעולם הזה, יוצאים זכר ונקבה, ואח״כ מתחלקים כפי דרכם, הרוח של זכר מתלבש בזכר והרוח של נקבה בנקבה. ואח״כ, אם האדם זוכה, מזדווגים יחד. והיינו בת זוגו, ומתחברים בזווג אחד, בכל, ברוח ובגוף. שכתוב, תוצא הארץ נפש חיה למינה. מהו \u0003למינה.\u0004 הוא אותו הרוח של האדם היוצא עם זוגו הדומה אליו."],[2,"ומאי הארץ וכו׳:","שואל, ומהו הארץ, שבכתוב, תוצא הארץ, הוא כש״א, רקמתי בתחתיות ארץ. שהיא המלכות. וכבר העמידוהו. \u0003תוצא הארץ\u0004 ודאי, שהיא המלכות, כי ממנה יוצאת נפש חיה. כמו שהעמדנו, שזה רוחו של אדם הראשון, שיצא ונולד מן המלכות שנקראת ארץ. היינו שכתוב, ומפרי העץ אשר בתוך הגן. \u0003ומפרי העץ,\u0004 זה הקב\"ה, דהיינו ז״א הנקרא עץ החיים, שהפרי שלו היא רוחו של אדם הראשון, \u0003אשר בתוך הגן,\u0004 אשר בתוך האשה, למדנו, שהיא המלכות המכונה אשה, ומכונה גן. כי רוחו של אדם הראשון יצא מזווג ז״א ומלכות. והיינו, \u0003אשה כי תזריע וילדה זכר,\u0004 שאשה היא מלכות, שהיא יולדת הנשמות כנ״ל. וכתוב, וילדה זכר, ולא כלול זכר ונקבה, כפי דרך העולם, שהנשמות נולדות זכר ונקבה (כנ״ל אות י״ד) כי הם, התחתונים בעונותיהם, גורמים לה, למלכות, שהנשמות אינן מתחברות זכר ונקבה, כמו שיוצאים מלמעלה זוגות זוגות זכר ונקבה. וע״כ כתוב, וילדה זכר, שלא נגלה לעולם הזה, רק זכר שאינו כלול בנקבה."],[3,"בגין דאדם קדמאה וכו׳:","משום שאדם הראשון, והזווג שלו, חוה, חטאו להקב״ה, וע״כ מתחלקים הזכר ונקבה, כשיוצאים מלמעלה, לעולם הזה, שנשמת זכר נולד בפני עצמו ונשמת נקבה נולדת בפני עצמה, עד שיהיה רצון לפני הקב״ה, אם זכה האדם, נותנים לו זוגתו, דהיינו נשמת הנקבה שהיתה כלולה עמו למעלה, ואם לא, מפרידים אותה ממנו, ונותנים לה לאחר, ואז, מולידים בנים שאינם כראוי. וע״כ כתוב, לא ידון רוחי באדם מהו רוחי, רוחו היה צריך לומר, דהיינו רוחו של האדם. אלא שהם ב׳ רוחות, שיוצאים זוגות, כי אל תקרי רוחי עם ח׳ חרוקה, אלא עם ח׳ פתוחה, שהוא לשון רבים. ואומר הכתוב, שלא ידונו יחד. כי יוצאים בפירוד זה מזה. וע״כ כתוב, וילדה זכר, ולא כלל זכר ונקבה יחד כפי דרך העולם שלמעלה, כי הם גרמו."],[4,"ר׳ אלעזר אמר וכו׳:","ר״א אמר אינו כן, שוילדה זכר יהיה פירושו, שנולד מן המלכות לעולם הזה זכר בלי נקבה, שהרי הכל, באים זכר ונקבה כלולים יחד, ואחר כך, מתחלקים (ועי׳ לעיל פקודי אות תצ״ז) ובאים בזכר בפני עצמו ובנקבה בפני עצמה. אבל, \u0003וילדה זכר,\u0004 פירושו, שזכר ונקבה כלולים יחד מצד ימין, שהוא בחינת זכר. \u0003ואם נקבה תלד,\u0004 פירושו, שכלולים יחד נקבה וזכר מצד שמאל, שהוא בחינת נקבה. והצד שמאל שולט ביותר על צד ימין, והזכר שבימין נכנע שאינו שולט, ואז זכר ההוא שיוצא מן הנוקבא, שהיא המלכות, מצד שמאלה, כל דרכיו כנקבה, וע״כ נקרא נקבה. אבל זכר היוצא מצד ימין, של המלכות, הוא השולט, והנקבה היוצאת עמו נכנעת, כי הצד שמאל אינו שולט, וע״כ כתוב עליו \u0003וילדה זכר.\u0004"],[5,"וכמה אלף ורבוון וכו׳:","וכמה אלפים ורבבות נשמות יוצאות בפעם אחת לעולם. ומיום שהוציאה אותם, אינן נקראות נפשות, שיקבלו הארתן מן המלכות, עד שמתישבים בגוף. וכמה הוא, הוא ל״ג ימים. היינו שכתוב, ושלשים יום ושלשת ימים וגו׳. שעד אז, הגוף אינו שלם, שהנפש תתישב ותתלבש בו. וטמאה שבעת ימים, היינו הנפש, כי כל שבעת ימים אינן נכנסות רוחות אצלה, אל המלכות, להתקשר בה, וכל אלו שבעת ימים, הרוח הולך בגוף, כדי למצוא מקומו להתישב בו. ואז כתוב, והיה שבעת ימים \u0003תחת\u0004 אמו, שהיא המלכות, שהוא מתחתיה ואינו יכול להתקשר בה."],[6,"וביומא תמינאה אתהדרו וכו׳:","וביום השמיני, חוזר הרוח והגוף להראות לפני המלכה, ולהתקשר בה, ובדכר, דהיינו בז״א, בגוף ורוח. ושלשים יום ושלשת ימים תשב על דמי טהרה, שהוא כדי שהרוח יתישב בגוף. שואל, וג׳ ימים מה הם עושים. ומשיב, אלא הם ג׳ ימים שלאחר המילה שהילד סובל מכאב המילה, והרוח אין משכנו שורה בגוף כבשאר ימים. וע״כ ושלשים יום ושלשת ימים תשב בדמי טהרה."],[6,"","פירוש. כי נתבאר לעיל (משפטים דף ק׳ ד\"ה פנימיות) שאין האיילתא יכולה להוליד את הנשמה. אלא בסוד הנחש הנושך בערייתא, ע״ש, ולפיכך נטמאה הנשמה על ידי נשיכין שלו. (כמ״ש שם באות שכ״ג) שז״ש, \u0003וטמאה שבעת ימים, דהא כל שבעת ימים לא עאלין רוחין לגבה לאתקשרא בה,\u0004 כי נשיכת הנחש וזוהמא שלו מעוררת סוד נקודה דמדת הדין שאינה משותפת בבינה, שה״ס מנעולא, ומחמת זה אין הרוח שהוא האור יכול להתלבש בגוף שהיא הכלי, וצריך הרוח לעלות חזרה אל המלכות, שהיא נמתקת בבינה, בסוד מפתחא, ולהתקשר בה אז גם הוא מקבל המיתוק דשיתוף המלכות בבינה, ויוכל להתלבש בגוף. וזה סוד וטמאה שבעת ימים, דהיינו ז\"ס חג״ת נהי״מ שהמלכות צריכה לעלות, מבחינת המלכות אל הבינה, להתמתק בבינה. ומטרם שבאה לבינה, שה״ס יום השמיני \u0003לא עאלין רוחין לגבה לאתקשרא בה,\u0004 אמנם עלית המלכות לבינה הזו אינה לצורך עצמה אלא לצורך טהרת הנשמה מנשיכת הנחש בערייתא בשעת לידתה. וז״ש, \u0003ביומא תמינאה אתהדרו רוחא וגופא לאחזאה\u0004 וכו'. כי אחר שהנשמה קבלה המיתוק מבינה נעשית ראויה להתקשר בהמלכות, שהיא מתוקנת בסוד המפתחא. והרוח יכול להתלבש בגוף. ומה שקוראה \u0003רוח\u0004 ולא נשמה, הוא, כי ביום השמיני כשמקבל מיתוק מבינה, בסוד עלית המלכות לבינה אין לה עוד בחינת ג״ר שהוא נשמה, אלא רק הקטנות בלבד שנקרא \u0003רוח.\u0004"],[6,"","ובכדי לקבל בחינת נשמה, צריכה לשבת ל״ג ימים, \u0003בדמי טהרה.\u0004 פירוש, כי דמים פירושו, הדינים המתגלים ממסך דקטנות, המונעים הג״ר. ויש דם טהור, ויש דם טמא, והוא, כי ב׳ מיני מסכים הם, שיש מסך דמנעולא, שהוא מצמצום א׳ ויש מסך דמפתחא שהוא מצמצום ב׳, (כנ״ל לך י״ג ד״ה ונתבאר). והדינים דמסך דמנעולא נקראים \u0003דמים טמאים,\u0004 כי כל עוד שיש שמץ מזוהמתם בהנשמה אינה ראויה לשום אור. (כנ״ל ב״א ז׳. ד״ה וכבר) שזסו״ה, וטמאה שבעת ימים. והדינים הנמשכים ממסך דמפתחא נקראים \u0003דמים טהורים,\u0004 משום שהם ראוים לקבל אור. אמנם צריכה זמן שהמלכות תתקשר בחג״ת דז״א, שמהם מקבלת הג״ר. וז״ש \u0003ושלשים יום ושלשת ימים תשב בדמי טהרה לאתיישבא רוחא בגופא,\u0004 דהיינו שצריכה להשהות על הקטנות הממותק בבינה, הנקראת \u0003דמים טהורים\u0004 ל׳ יום, כדי שהרוח יקבל בחינת הג\"ר שלו, אשר אז הוא מתיישב בגוף. אבל לפי זה היה מספיק שלשים יום כנגד ג׳ ספירות חג״ת דז״א שכל אחת כלולה מעשר, \u0003וג' ימים מאי עבידתייהו.\u0004 ומשיב, \u0003אלא ג׳ ימים דמילה דרביא כאיב, ורוחא לא שריא\u0004 וכו' כי אחר המילה צריכים ג׳ ימים לרפא המילה, שה״ס ג׳ קוין שמבחינת הקטנות, שבקבלתם מתרפאת המילה. והמלכות תוכל לעלות להתקשר בג׳ קוין דגדלות, שהם שלשים יום."],[7,"בדמי טהרה בקדמיתא וכו׳:","שואל, תחילה אומר הכתוב, בדמי טהרה, ואחר כך ימי טהרה. ומשיב, \u0003בדמי טהרה,\u0004 אלו, דמים של המילה, דם אחר הדם הבא מן הילד. והקב״ה שומר לאלו הדמים כל אלו הימים. ז״ש. תשב בדמי טהרה. טהרה סתם, שאין בה מפיק \u0003ה',\u0004 ואינה נזכרה בקריאה, יורה שאינו מזכיר \u0003ה׳\u0004 אחרונה של שם הויה, שהיא המלכות. והוא, שאל תאמר שהמדובר היא בטהרת המטרוניתא, שהוא המלכות, שהיא אמה של הנשמה, אלא טהרה סתם, כי דמי טהרה סתם נקראים אלו דמים הטהורים, כי המדובר הוא רק בנשמה הנולדה ממנה. וכל עליות והתקשרות שנאמר במלכות, הם בבחינת מה שהמלכות הוא שורש אל הנשמה ההיא."],[7,"","פירוש. דמי מילה, שהם ביום השמיני הם שורש דם טהור, הנמשך ממסך דמפתחא, והדמים הנמשכים בל״ג ימים הם נמשכים מדם טהור של המילה. וז״ש, בדמי טהרה, \u0003אלין דמי מילה,\u0004 שהם שורשי דם טהור, \u0003דמא בתר דמא,\u0004 והדם הנראה בל\"ג יום, הם מבחינת דם מילה, שהוא דם טהור, דהיינו ממסך דמפתחא כנ״ל בדבור הסמוך. \u0003וקב״ה נטיר לאינון דמי\u0004 וכו', כי אם לא היו דינים אלו דקטנות, לא היה אפשר שתקבל פעם בחינת ג\"ר (כמ״ש לעיל ב״א ד״ה וכבר) וע״כ צריך הקב״ה לשמור אותם. כדי להכשירה לקבל ג״ר."],[8,"בכל קדש לא תגע וגו׳:","בוא וראה, בכל יום ויום, כנסת ישראל, שהיא המלכות, לוקחת מזון מבית המלך בשביל הרוחות של בני אדם, ומזינה אותם בקדושה. חוץ מאלו הרוחות שהם בבחינת ל״ג ימי טהרה, עד שאלו הרוחות מתישבים בגוף, אחר ל״ג ימים, היא משגחת עליהם בכל יום, כי אז הרוחות מתקשרים בגוף כשאר בני העולם. כמו שהיא, המלכות, אינה שורה אלא במקום שלם, כך כל מעשיה הוא באפן הזה, כלפי הרוחות של בני אדם, עד שנשלמו. ז״ש, \u0003בכל קדש לא תגע,\u0004 שפירושו, להשגיח על הנשמות. כלומר, שאינה נוגעת בקדש לקבל מזון מן הקדש, שהוא ז״א, בשביל הרוחות."]],[[0,"","כְּשֶׁיּוֹצֵאת לָעוֹלָם, מִזְדַּמֵּן לָהּ אוֹתוֹ הַצֶּלֶם, וּמִשְׁתַּתֵּף עִמָּהּ, וּמִתְגַּדֵּל עִמָּהּ, כְּמוֹ שֶׁנֶּאֱמַר אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ. וּבְאוֹתוֹ הַצֶּלֶם מִשְׁתַּתְּפִים (נמצאים) יְמֵי הָאָדָם וּתְלוּיִים בּוֹ. זֶהוּ שֶׁכָּתוּב (איוב ח) כִּי תְמוֹל אֲנַחְנוּ וְלֹא נֵדָע כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ. כִּי צֵל יָמֵינוּ וַדַּאי. וּמִיּוֹם שֶׁמִּתְעַבֶּרֶת הָאִשָּׁה עַד הַיּוֹם שֶׁמּוֹלִידָה, לֹא יוֹדְעִים בְּנֵי אָדָם אֶת מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא כַּמָּה הֵם גְּדוֹלִים וְכַמָּה הֵם עֶלְיוֹנִים. זֶהוּ שֶׁכָּתוּב (תהלים קד) מָה רַבּוּ מַעֲשֶׂיךְ ה' וְגוֹ'."],[1,"","בֹּא רְאֵה, כָּל רוּחוֹת הָעוֹלָם כְּלוּלוֹת זָכָר וּנְקֵבָה, וּכְשֶׁיּוֹצְאוֹת, יוֹצְאוֹת זָכָר וּנְקֵבָה, וְאַחַר כָּךְ נִפְרָדִים בְּדַרְכֵיהֶם, אִם זוֹכֶה הָאָדָם, אַחַר כָּךְ מִזְדַּוְּגִים יַחַד. וְהַיְנוּ בַּת זוּגוֹ, וּמִתְחַבְּרִים בְּזִוּוּג (בגון) אֶחָד בַּכֹּל, רוּחַ וְגוּף, שֶׁכָּתוּב (בראשית א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ. מַה זֶה לְמִינָהּ? אוֹתָהּ רוּחַ הָאָדָם שֶׁיּוֹצֵאת זִוּוּגוֹ שֶׁדּוֹמָה לוֹ."],[2,"","וּמַה זֶּה הָאָרֶץ? כְּמוֹ שֶׁנֶּאֱמַר רֻקַּמְתִּי בְּתַחְתִּיּוֹת אָרֶץ, וְהִנֵּה פֵּרְשׁוּהָ. תּוֹצֵא הָאָרֶץ וַדַּאי, שֶׁהֲרֵי מִמֶּנָּה יוֹצְאִים נֶפֶשׁ חַיָּה, כְּמוֹ שֶׁבֵּאַרְנוּ, זוֹ רוּחוֹ שֶׁל אָדָם הָרִאשׁוֹן, זֶהוּ שֶׁכָּתוּב (שם ג) וּמִפְּרִי הָעֵץ אֲשֶׁר בְּתוֹךְ הַגָּן. וּמִפְּרִי הָעֵץ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. אֲשֶׁר בְּתוֹךְ הַגָּן - אֲשֶׁר בְּתוֹךְ הָאִשָּׁה שָׁנִינוּ, הַיְנוּ אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר כָּתוּב. וְלֹא כוֹלֵל זָכָר וּנְקֵבָה כְּפִי דֶּרֶךְ הָעוֹלָם, שֶׁהֵם גָּרְמוּ לוֹ, שֶׁלֹּא מִתְחַבְּרִים כְּמוֹ שֶׁיּוֹצְאִים מִלְמַעְלָה זוּגוֹת."],[3,"","מִשּׁוּם שֶׁאָדָם הָרִאשׁוֹן וְזִוּוּגוֹ חָטְאוּ לַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל כֵּן נִפְרָדִים כְּשֶׁיּוֹצְאִים מִלְמַעְלָה, עַד שֶׁיִּהְיֶה רָצוֹן מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אִם זוֹכֶה אָדָם, נוֹתְנִים לוֹ זוּגָתוֹ, וְאִם לֹא - מַפְרִידִים אוֹתָהּ מִמֶּנּוּ, וְנוֹתְנִים אוֹתָהּ לְאַחֵר, מוֹלִידִים בָּנִים שֶׁלֹּא כָּרָאוּי. וְעַל זֶה כָּתוּב (שם ו) לֹא יָדוֹן רוּחִי בָאָדָם. מַה זֶּה רוּחִי? רוּחוֹ הָיָה צָרִיךְ לִהְיוֹת! אוֹתָן שְׁתֵּי רוּחוֹת שֶׁיּוֹצְאוֹת זוּגוֹת, לֹא יִדּוֹנוּ יַחַד. וְעַל זֶה כָּתוּב וְיָלְדָה זָכָר, וְלֹא כוֹלֵל זָכָר וּנְקֵבָה כְּפִי דֶּרֶךְ הָעוֹלָם, שֶׁהֵם גָּרְמוּ."],[4,"","רַבִּי אֶלְעָזָר אָמַר, לֹא כָּךְ, שֶׁהֲרֵי הַכֹּל, זָכָר וּנְקֵבָה כְּלוּלִים יַחַד, וְאַחַר כָּךְ נִפְרָדִים. אֲבָל וְיָלְדָה זָכָר, כְּלוּלִים יַחַד מִצַּד הַיָּמִין. וְאִם תֵּלֵד נְקֵבָה, כְּלוּלִים בְּאֶחָד נְקֵבָה וְזָכָר מִצַּד הַשְּׂמֹאל, שֶׁיּוֹתֵר שׁוֹלֵט צַד הַשְּׂמֹאל עַל צַד הַיָּמִין, וְהַזָּכָר נִכְנָע בַּיָּמִין שֶׁלֹּא שׁוֹלֵט, וְאָז אוֹתוֹ הַזָּכָר שֶׁיּוֹצֵא מִן הַנְּקֵבָה מִצַּד הַשְּׂמֹאל, כָּל דְּרָכָיו כְּמוֹ נְקֵבָה (ולא נקרא זכר). אֲבָל הַזָּכָר שֶׁיּוֹצֵא מִתּוֹךְ הַיָּמִין, הוּא שׁוֹלֵט, וְהַנְּקֵבָה שֶׁיּוֹצֵאת מִמֶּנּוּ נִכְנַעַת, שֶׁהֲרֵי צַד הַשְּׂמֹאל לֹא שׁוֹלֵט, וְעַל כֵּן כָּתוּב וְיָלְדָה זָכָר."],[5,"","וְכַמָּה אֲלָפִים וּרְבָבוֹת יוֹצְאִים בְּפַעַם אַחַת בָּעוֹלָם. וּמֵהַיּוֹם שֶׁמּוֹצִיאָה אוֹתָם, לֹא נִקְרָאִים נְפָשׁוֹת, עַד שֶׁהֵן מִתְיַשְּׁבוֹת בַּגּוּף. וְכַמָּה הוּא? שְׁלֹשִׁים וּשְׁלֹשָׁה יָמִים. הַיְנוּ שֶׁכָּתוּב וּשְׁלֹשִׁים יוֹם וּשְׁלֹשֶׁת יָמִים וְגוֹ'. וְטָמְאָה שִׁבְעַת יָמִים, שֶׁהֲרֵי כָּל שִׁבְעַת יָמִים לֹא נִכְנָסִים אֵלֶיהָ רוּחוֹת לְהִתְקַשֵּׁר בָּהּ, וְכָל שִׁבְעַת הַיָּמִים הַלָּלוּ הָרוּחַ הוֹלֶכֶת בַּגּוּף לִמְצֹא אֶת מְקוֹמָהּ, וְאָז כָּתוּב (ויקרא כב) וְהָיָה שִׁבְעַת יָמִים תַּחַת אִמּוֹ."],[6,"","וּבַיּוֹם הַשְּׁמִינִי חוֹזְרִים הָרוּחַ וְהַגּוּף לְהֵרָאוֹת לִפְנֵי הַגְּבִירָה וּלְהִקָּשֵׁר עִמָּהּ, וּבְזָכָר, בְּגוּף וּבְרוּחַ. וּשְׁלֹשִׁים יוֹם וּשְׁלֹשֶׁת יָמִים תֵּשֵׁב עַל (ב) דְּמֵי טָהֳרָה, שֶׁתִּתְיַשֵּׁב הָרוּחַ בַּגּוּף. וּשְׁלֹשָׁה יָמִים מָה עוֹשִׂים? אֵלּוּ שְׁלֹשֶׁת יְמֵי הַמִּילָה, שֶׁלַּתִּינוֹק כּוֹאֵב, וְהָרוּחַ לֹא שָׂמָה אֶת מְדוֹרָהּ בַּגּוּף כְּבִשְׁאָר הַיָּמִים, וְעַל כֵּן - וּשְׁלֹשִׁים יוֹם וּשְׁלֹשֶׁת יָמִים תֵּשֵׁב בִּדְמֵי טָהֳרָה."],[7,"","בִּדְמֵי טָהֳרָה בָּרִאשׁוֹנָה, וְאַחַר כָּךְ יְמֵי טָהֳרָה. בִּדְמֵי טָהֳרָה - אֵלּוּ דְּמֵי מִילָה, דָּם אַחַר דָּם שֶׁבָּא מֵהַתִּינוֹק, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אוֹתָם דָּמִים כָּל הַיָּמִים הַלָּלוּ. זֶהוּ שֶׁכָּתוּב תֵּשֵׁב בִּדְמֵי טָהֳרָה, טָהֳרָה סְתָם, וְלֹא הִזְכִּיר הֵ\"א הָאַחֲרוֹנָה, שֶׁלֹּא תֹאמַר הַטָּהֳרָה שֶׁל הַגְּבִירָה, אֶלָּא טָהֳרָה סְתָם. דְּמֵי טָהֳרָה נִקְרָאִים יְמֵי הַטֹּהַר הַלָּלוּ."],[8,"","בְּכָל קֹדֶשׁ לֹא תִגָּע וְאֶל הַמִּקְדָּשׁ וְגוֹ'. בּא רְאֵה, בְּכָל יוֹם וָיוֹם כְּנֶסֶת יִשְׂרָאֵל נוֹטֶלֶת מִבֵּית הַמֶּלֶךְ מָזוֹן לְרוּחוֹת בְּנֵי הָאָדָם וְזָנָה אוֹתָם בִּקְדֻשָּׁה, פְּרָט לְאֵלֶּה, שֶׁעַד שֶׁמִּתְיַשְּׁבוֹת בַּגּוּף אוֹתָן רוּחוֹת. אַחַר שְׁלֹשִׁים וּשְׁלֹשָׁה יָמִים הִיא מַשְׁגִּיחָה עֲלֵיהֶם כָּל יוֹם, שֶׁהֲרֵי הָרוּחוֹת נִקְשָׁרוֹת בַּגּוּף כִּשְׁאָר בְּנֵי הָעוֹלָם. כְּמוֹ שֶׁהִיא לֹא שׁוֹרָה אֶלָּא בְּמָקום שָׁלֵם, כָּךְ כָּל מַעֲשָׂיו כְּגון זֶה, עַד שֶׁנִּשְׁלָמִים. בְּכָל קֹדֶשׁ לֹא תִגָּע, לְהַשְׁגִּיחַ עֲלֵיהֶם."]]],[["וְאִם נְקֵבָה תֵלֵד. כְּמָה דְּאוֹקִימְנָא, דְּשַׁלְטָא סְטָר שְׂמָאלָא יַתִיר וְאִתְכַּפְיָא יְמִינָא, וְעַל דָּא כֹּלָּא עַל חַד תְּרֵין, רְחִיקָא נוּקְבָּא, מִדְּכוּרָא, לְאִתְקַשְּׁרָא רוּחָא בְּגוּפָא, דְּהָא שְׂמָאלָא לָא אִתְיַישְׁבָא הָכִי כִּימִינָא, וְאִשְׁתְּכָחַת בְּתוּקְפָא יַתִיר.","\u0003רעיא מהימנא\u0004 (ויקרא י״ב:ג׳) וּבַיּוֹם הַשְּׁמִינִי יִמּוֹל בְּשַׂר עָרְלָתוֹ. פִּקּוּדָא דָּא, לְמִגְזַר לִתְמַנְיָּא יוֹמִין גְּזִירוּ דְּקַּיָּימָא קַדִּישָׁא. רָזָא עִלָּאָה, דִּכְתִּיב, (תהילים כ״ה:י״ד) סוֹד יְיָ' לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם. לְמַאן, לְאִינּוּן יְרֵאָיו אִינּוּן דַּחֲלֵי חַטָאָה, דְּהָא רָזָא דְּקַּיָּימָא קַדִּישָׁא לָא אִתְחֲזִי לְגַלָּאָה בַּר לְהוּ. וְרָזָא דְּקַּיָּימָא קַדִּישָׁא, הָא אוּקְמוּהָ וְאִתְּמַר בְּכַמָּה דּוּכְתִּין.","וְרָזָא דָּא, לַח' יוֹמִין, אִיהוּ חִיוּבָא עַל עָלְמָא, לְכָל עַמָּא קַדִּישָׁא. דִּכְתִּיב, וּבַיּוֹם הַשְּׁמִינִי יִמּוֹל בְּשַׂר עָרְלָתוֹ. יוֹם הַשְּׁמִינִי, דָּא הוּא אָת קַיָּימָא קַדִּישָׁא, וְאִיהוּ תְּמִינָאָה לְכָל דַּרְגִּין. וּגְזִירוּ דְּהַהוּא קַיָּימָא, לְאַעְבְּרָא הַהוּא עָרְלָה. מִקַּמֵּי בְּרִית.","דְּהָא בְּהַהוּא זִמְנָא דְּמִתְכַּנְשֵׁי עַמָּא קַדִּישָׁא לְאַעְבְּרָא הַהוּא עָרְלָה מִקַּמֵּי בְּרִית, קוּדְשָׁא בְּרִיךְ הוּא כָּנִישׁ כָּל פָּמַלְיָא דִּילֵיהּ, וְאִתְגְּלֵי וַדַּאי לְאַעְבְּרָא לְהַהוּא עָרְלָה לְעֵילָּא, מִקַּמֵּי בְּרִית קַיָּימָא קַדִּישָׁא. דְּהָא כָּל עוֹבָדִין דְּיִשְׂרָאֵל עַבְדִּין לְתַתָּא, מִתְעָרֵי עוֹבָדָא לְעֵילָּא. וּבְהַהוּא זִמְנָא אִתְדַּחְיָיא הַהוּא עָרְלָה, מִכָּל עַמָּא קַדִּישָׁא לְעֵילָּא. וּלְהַהוּא עָרְלָה מְתַקְּנֵי מָאנָא חֲדָא בְּעַפְרָא, לְאַשְׁרָאָה הַהוּא עָרְלָה בְּגַוִיהּ. בְּרָזָא דִּכְתִּיב, (ישעיהו ס״ה:כ״ה) וְנָחָשׁ עָפָר לַחְמוֹ. (בראשית ג׳:י״ד) וְעָפָר תֹּאכַל כָּל יְמֵי חַיְּיךָ.","מִכָּאן, (תיקון ס\"א) דְּלָא אִצְּטְרִיךְ לְאַנְהֲגָא קְלָנָא בְּהַהוּא אֲתַר, אַף עַל גַּב דִּמְעַבְרֵי לֵיהּ מִקַּמֵּי הַאי בְּרִית, וְדוּכְתֵיהּ, כַּד מִתְעַבְּרָא מֵהַאי בְּרִית, עַפְרָא אִיהוּ, (ס\"א דהא) דְּהָרֵי בָּתַר דְּהַהוּא נָחָשׁ אִתְעַבָּר מִקַּמֵּי אָדָם, קוּדְשָׁא בְּרִיךְ הוּא שַׁוִּי לֵיהּ מָדוֹרֵיהּ בֶּעָפָר, דִּכְתִּיב וְעָפָר תֹּאכַל כָּל יְמֵי חַיְּיךָ. וְכֵיוָן דְּקוּדְשָׁא בְּרִיךְ הוּא כַּד אַעְבָּר לֵיהּ מִקַּמֵּי אָדָם שַׁוִּי מָדוֹרֵיהּ בְּעַפְרָא וְאַתְקִין לֵיהּ, כַּךְ בְּהַהוּא גַּוְונָא מַמָּשׁ, אֲנָן צְּרִיכִין כַּד מְעַבְּרִין לַעָרְלָה, לְאִתְתַּקְנָא לֵיהּ עַפְרָא, לְמֶהֱוִי בֵּיהּ מָדוֹרֵיהּ.","כָּל בַּר נָשׁ אִצְּטְרִיךְ לְקָרְבָא הַהוּא בְּרָא קָרְבְּנָא לְּקוּדְשָׁא בְּרִיךְ הוּא, בְּחֶדְוָה, בִּרְעוּ דְּלִבָּא, לְמֵיעַל לֵיהּ תְּחוֹת גַּדְפּוֹי דִּשְׁכִינְתָּא, וְאִתְחַשָּׁב קָמֵי קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ קָרְבְּנָא, שְׁלִים לְאִתְקַבְּלָא בְּרַעֲוָא.","וְקָרְבְּנָא דָּא, כְּגַוְונָא דְּקָרְבְּנָא דִּבְעִירָא, דָּא לַח' יוֹמִין, וְדָא לַח' יוֹמִין, דִּכְתִּיב, וּמִיּוֹם הַשְּׁמִינִי וָהָלְאָה יִרָצֶּה, בְּמַאי יִרָצֶּה. בְּמֶעְבַּר עָלֵיהּ חַד שַׁבְּתָא, כֵּיוָן דְּאַעְבָּר עָלֵיהּ חַד שַׁבְּתָא, כְּדֵין יִרָצֶּה דָּא לְקָרְבְּנָא, וְדָא לְקָרְבְּנָא. אֲמַאי. בְּגִין דְּאִתְדְּבַק וְאִזְדְּמַן לְגַבֵּי הַהוּא שַׁבָּת, רָזָא דִּבְרִית קַדִּישָׁא, וְעַל דָּא כֹּלָּא בְּרָזָא עִלָּאָה אִיהוּ. (ע\"כ רעיא מהימנא)","(ויקרא י״ב:ב׳) אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר וְגוֹ'. רִבִּי יְהוּדָה פָּתַח, (שמואל א ב׳:ב׳) אֵין קָדוֹשׁ כַּיְיָ' כִּי אֵין בִּלְתֶּךָ וְאֵין צוּר כֵּאלֹהֵינוּ, הַאי קְרָא קַשְׁיָא, אֵין קָדוֹשׁ כַּיְיָ', מַשְׁמַע דְּאִיכָּא קָדוֹשׁ אָחֳרָא, בְּגִין דִּכְתִּיב כַּיְיָ', וְאֵין צוּר כֵּאלֹהֵינוּ, מַשְׁמַע דְּאִיכָּא צוּר אָחֳרָא.","אֶלָּא וַדַּאי, אֵין קָדוֹשׁ כַּיְיָ', דְּכַמָּה קַדִּישִׁין נִינְהוּ, קַדִישִׁין לְעֵילָּא, דִּכְתִיב, (דניאל ד׳:י״ד) וּמֵאמַר קַדִישִׁין שְׁאֵלְתָּא. יִשְׂרָאֵל קַדִּישִׁין נִינְהוּ, דִּכְתִּיב, (ויקרא יט) קְדוֹשִׁים תִּהְיוּ. וְכֻלְּהוּ קַדִּישִׁין, וְלָאו קַדִּישִׁין כַּיְיָ'. וּמַאי טַעְמָא. בְּגִין דִּכְתִיב, כִּי אֵין בִּלְתֶּךָ. מַאי, כִּי אֵין בִּלְתֶּךָ, אֶלָּא קְדוּשָּׁה דְּקוּדְשָׁא בְּרִיךְ הוּא בִּלְתִּי קְדוּשָּׁא דִּלְהוֹן, דְּהוּא לָא אִצְטְרִיךְ לִקְדוּשָּׁה דִּלְהוֹן. אֲבָל אִינּוּן, לָאו אִינּוּן קַדִּישִׁין בִּלְתֶּךָ, וְדָא הוּא, כִּי אֵין בִּלְתֶּךָ, אֵין קְדוּשָּׁה דִּלְהוֹן, בִּלְתֶּךָ.","וְאֵין צוּר כֵּאלֹהֵינוּ. כְּמָה דְּאוּקְמוּהָ, דְּקוּדְשָׁא בְּרִיךְ הוּא צָר צוּרָה בְּגוֹ צוּרָה, וְתָקִין לֵיהּ, וְנָפַח רוּחָא דְּחַיֵּי, וְאַפִּיק לֵיהּ לַאֲוִירָא דְּעָלְמָא, דָּבָר אַחֵר, וְאֵין צוּר כֵּאלֹהֵינוּ. אִית צוּר, דְּאִקְרֵי צוּר, (ישעיהו נ״א:א׳) הַבִּיטוּ אֶל צוּר חוּצַּבְתֶּם. (שמות י״ז:ו׳) וְהִכִּיתָ בַצּוּר. הִנְנִי עוֹמֵד לְפָנֶיךָ שָּׁם עַל הַצּוּר בְּחוֹרֵב. וְכֻלְּהוּ אִקְרוּן צוּר, וְאֵין צוּר בְּכֻלְּהוּ כֵּאלֹהֵינוּ, דִּילֵיהּ שׁוּלְטָנוּ וּמַלְכוּתָא עַל כֹּלָּא.","רִבִּי חִיָּיא וְרִבִּי אֲחָא הֲווֹ יַתְבֵי לֵילְיָא חַד קַמֵּיהּ דְּרִבִּי אַבָּא. קָמוּ בְּפַלְגוּת לֵילְיָא לְמִלְעֵי בְּאוֹרַיְיתָא. עַד דְּנָפְקוּ לְבַר, חָמוּ חַד כֹּכָבָא דְּהֲוָה בָּטַשׁ ג' זִמְנֵי בְּכֹכָבָא אָחֳרָא וְסָתִים נְהוֹרֵיהּ. אַדְהָכִי שָׁמְעוּ תְּרֵי קָלֵי בִּתְרֵי סִטְרֵי, קָלָא חַד לִסְטַר צָפוֹן לְעֵילָּא, וְקָלָא חַד לְתַתָּא. וְהַהוּא קָלָא אַכְרִיז וְאָמַר, עוּלוּ וְאִתְכְּנִישׁוּ לְאַתְרַיְיכוּ, הַשְׁתָּא אִסְתַּמְרוּתָא דְּנוּקְבָּא פְּתִיחָא, קוּדְשָׁא בְּרִיךְ הוּא עָאל לְטַיְילָא בְּגִנְתָא, לְאִשְׁתַּעְשְׁעָא בְּצַדִיקַיָּיא דִּי בְּגִנְתָא, אַעְבָר הַהוּא קָלָא וְשָׁכִיךְ."],[[0,"ואם נקבה תלד:","היינו כמו שהעמדתי, שהוא משום שהצד שמאל שלט יותר והימין נכנע אליו, וע״כ הכל על אחד שנים, נתרחקה הנוקבא, שהיא המלכות, מדכורא, שהוא ז״א, וכדי להתקשר הרוח שיתלבש בגוף, כי השמאל אינו מתישב בגוף כך כמו הימין, כי נמצא בתוקף הגבורות יותר."],[0,"","פירוש. כי בימין שהוא זכר, לא היה להמתיק אלא דינים דנוקבא, שה״ס דמים טמאים וטהורים כנ״ל. אבל הנקבה שהשמאל גובר בה, צריכים לתקן גם דינים דשמאל שהם דינים דדכורא וע״כ נכפל הכל. שהטומאה היא שבועים, כנגד דינין דדכורא ודינין דנוקבא. וכן ימי טוהר הם ששים וששה ימים, לי׳ג כנגד דינין דדכורא, ול״ג כנגד דינין דנוקבא."],[1,"וביום השמיני ימול בשר ערלתו:","מצוה זו, היא, למול לשמונת ימים מילת ברית קודש. והוא סוד עליון, שכתוב, סוד ה׳ ליראיו \u0003ובריתו\u0004 להודיעם. למי מודיע הסוד, שהוא ברית, לאלו היראים שהם יראי חטא, כי סוד ברית קודש אינו ראוי לגלות חוץ מלהם. וסוד ברית קודש, הרי העמדנו ולמדנו בכמה מקומות."],[2,"ורזא דא לח׳ וכו׳:","וסוד זה, שהוא, לשמונת ימים, הוא חיוב על העולם, לכל העם הקדוש. שכתוב, וביום השמיני ימול בשר ערלתו. \u0003יום השמיני,\u0004 זה הוא אות ברית קודש, דהיינו ספירת היסוד, שהוא שמיני לכל המדרגות, אם תספור המדרגות מחכמה ולמטה נמצא היסוד מדרגה השמינית. וכתר ה״ס א״ס שאינו מן המנין. והמילה של ברית ההוא, הוא, להעביר ערלה ההוא, שה״ס נחש הטמא, מפני הברית, שהוא יסוד הקדוש. ואין להקשות שפעם אומר שיום השמיני הוא בינה דהיינו ממטה למעלה. ופעם אומר שיום השמיני הוא יסוד, דהיינו ממעלה למטה. והוא מטעם ערך ההפכי שיש בין כלים לאורות. כי באור התחתון נכנס תחילה. ומתחילים מלמטה ובכלים העליונים נגמר תחילה ומתחילים ממעלה למטה."],[3,"דהא בההוא זמנא וכו׳:","כי בזמן ההוא שמתאספים העם הקדוש להעביר ערלה ההיא מפני הברית, הקב״ה אוסף כל הפמליא שלו, ומתגלה להעביר ודאי אותו הערלה למעלה מפני אות ברית קדש, שהוא היסוד. כי כל המעשים שישראל עושים למטה מעוררים מעשה למעלה. וע״כ בזמן ההוא נדחת ערלה ההיא, שהיא נחש הטמא, מכל העם הקדוש למעלה. ולערלה ההיא מתקנים כלי אחד עם עפר, להשרות ערלה ההיא בתוכו. בסוד שכתוב, ונחש עפר לחמו. ועפר תאכל כל ימי חייך."],[4,"מכאן דלא אצטריך וכו׳:","מכאן נשמע, שאין אדם צריך לנהוג בזיון במקום ההוא, דהיינו בערלה, אע״פ שמעברים אותו מפני הברית. ומקומו, אחר שנעבר מברית הזה, הוא בעפר, שהרי אחר שנחש ההוא נעבר מפני אדם, נתן הקב״ה משכנו בעפר, שכתוב, ועפר תאכל כל ימי חייך. וכיון שהקב״ה כשהעביר אותו מפני אדם שם משכנו בעפר והתקין אותו, כך באותו אופן ממש, כשאנו מעבירים את הערלה, אנו צריכים לתקן בשבילו עפר, שיהיה בו משכנו."],[5,"כל בר נש וכו׳:","כל אדם צריך להקריב בן ההוא קרבן להקב\"ה, בשמחה, ברצון הלב, להכניסו תחת כנפי השכינה, ונחשב לפני הקב״ה שהוא קרבן שלם להתקבל ברצון."],[6,"וקרבנא דא כגוונא וכו׳:","וקרבן הזה, הוא כמו קרבן מן הבהמה, כי זה לח׳ ימים וזה לח׳ ימים, שכתוב, ומיום השמיני והלאה ירצה. במה ירצה. הוא, מפני שעבר עליו שבת אחד. כי בין ח׳ ימים מוכרח להיות שבת אחד. כיון שעבר עליו שבת אחד, אז \u0003ירצה\u0004 זה לקרבן, שהיא הבהמה, וזה לקרבן שהוא ילד הנימול. למה. הוא משום שנתדבק ונזדמן לשבת הזה, שהיא המלכות, סוד ברית קודש, שהוא היסוד. כלומר שבשבת נמצא היסוד בכל שלמותו, ע״כ מקבל ממנו הילד הארה לתקון ברית קודש שלו. וכן הבהמה ירצה לקרבן, כי הקרבן מיחד יסוד ומלכות, וצריך משום זה לקבל תקון מיסוד השלם ביום השבת. וע״כ הכל הוא בסוד עליון. (ע״כ רעיא מהימנא)."],[7,"אשה כי תזריע וגו׳:","ר׳ יהודה פתח, אין קדוש כה׳ כי אין בלתך ואין צור כאלקינו, מקרא זה קשה, שכתוב, אין קדוש כה׳, משמע שיש קדוש אחר על כל פנים, הגרוע מעט מה׳, משכתוב כה׳. וכן, אין צור כאלקינו, משמע שיש צור אחר, אלא שהוא גרוע מעט מה׳."],[8,"אלא ודאי אין וכו׳:","ומשיב, אלא ודאי, אין קדוש כה', כי יש הרבה קדושים, יש קדושים למעלה דהיינו המלאכים, שכתוב, ומאמר קדישין שאילתא. וכן ישראל קדושים הם, שכתוב, קדושים תהיו. וכולם קדושים, ואינם קדושים כה׳. ומהו הטעם. משום שכתוב, \u0003כי אין בלתך.\u0004 מהו, כי אין בלתך, אלא קדושתו של הקב״ה הוא בלי קדושה שלהם, של המלאכים ושל ישראל, כי הוא לא צריך לקדושה שלהם. אבל הם אינם קדושים בלתך, וזה הוא, כי אין בלתך אין קדושה שלהם, בלתך."],[9,"ואין צור כאלקינו:","פירושו הוא, כמו שהעמידוהו, שהקב״ה צר צורה בתוך צורה, דהיינו צורת העובר בתוך צורת אמו, ומתקן אותה, ונופח בה רוח החיים, ומוציא אותה לאויר העולם. פירוש אחר, ואין צור כאלקינו. שיש צור, שהוא רק נקרא צור, כמ״ש, הביטו אל צור חוצבתם. והכית בצור. הנני עומד לפניך שם על הצור. וכולם נקראים צור, ואין צור בכולם כאלקינו, שיש לו ממשלה ומלכות על כל."],[10,"רבי חייא ור׳ אחא וכו׳:","ר״ח ור״א היו יושבים לילה אחד לפני ר׳ אבא. קמו בחצות לילה לעסוק בתורה. בעוד שיצאו לחוץ, ראו ככב אחד שהיה מכה שלש פעמים בככב אחר וסתם אורו. בתוך כך שמעו ב׳ קולות בב׳ צדדים, קול אחד לצד צפון למעלה, וקול אחד למטה. וקול ההוא שלמטה מכריז ואמר, הכנסו והתאספו למקומכם, כי עתה נפתחה השמירה של הנוקבא, שהיא המלכות, כי הקב״ה נכנס לטייל בגן, להשתעשע עם הצדיקים אשר בגן. עבר קול ההוא ונשתתק."],[10,"","פירוש. הלילה נחלק לד׳ חלקים חסד וגבורה ת\"ת ומלכות. שבחצי הלילה הראשון שולטים ב׳ קוין חסד וגבורה שבמלכות, ובחצות לילה מתחיל לשלוט ת״ת שהוא קו אמצעי להכריע וליחד ב׳ הקוין חסד וגבורה שבמלכות. (עי׳ לעיל ויקהל אות ט״ו בהסולם שהארכנו לבאר זה היטב) שז״ס שהקב״ה, שה״ס ת״ת, קו האמצעי, נכנס בגן עדן, שהוא המלכות, ומיחד ימין ושמאל. שבה. ונודע שכדי ליחד הימין והשמאל, מוכרח הקו האמצעי להמשיך המסך דחירק בשתי בחינותיו, במפתחא ובמנעולא, שאין השמאל נכנע להתיחד עם הימין זולתם, (כנ״ל לך דף י״ג ד״ה ונתבאר, ע״ש) שהמסך הזה ממעט הג״ר דקו שמאל וסותם אותו. ע״ש."],[10,"","וז״ש \u0003קמו בפלנות ליליא\u0004 וכו' \u0003חמו חד ככבא דהוה בטש ג' זמני בככבא אחרא וסתים נהוריה. חד כוכבא,\u0004 ה״ס קו האמצעי, \u0003דהוה בטש בככבא אחרא,\u0004 היינו בקו שמאל, \u0003וסתים נהוריה\u0004 היינו שסתם אור הג\"ר שלו. \u0003ג׳ זמני,\u0004 היינו שעשה היחוד של ג׳ קוין המתיחדים לאחד."],[10,"","ואלו ב׳ פעולות במפתחא ומנעולא הנפעלים ע״י מסך דחירק, (כנ״ל לך י״ג ד״ה ונתבאר) הם מכונים ב׳ קולות (כמ״ש לעיל ויקהל אות ש״ט בהסולם באורך ע״ש) וז״ש, \u0003אדהכי שמעו תרי קלי בתרי סטרי,\u0004 דהיינו ב׳ פעולות שבקו האמצעי, \u0003קלא חד לסטר צפון לעילא,\u0004 שהוא קול דמפתחא, דהיינו הממותק בבינה. \u0003וקלא חד לתתא,\u0004 שהוא קול דמנעולא, דהיינו קול המלכות שלמטה שלא נמתקה בבינה. \u0003וההוא קלא,\u0004 של המנעולא, שהוא פעולה א׳ דקו האמצעי שהוא עיקר הכח הממעט קו השמאל, \u0003אכריז ואמר, עולו ואתכנישו לאתרייכו,\u0004 היינו לאותם הדבוקים בקו שמאל ורוצים להמשיך מג״ר דשמאל אומר להם הקול הזה דמנעולא, שיתאספו וישובו למקומם, בסוד, אם רץ לבך שוב לאחור. כי \u0003אסתמרותא דנוקבא פתיחא,\u0004 כי נפתחה השמירה של המלכות. כי עד חצות לא היה שמירה לקו שמאל של המלכות, והיו הרשעים יכולים לינק מקו שמאל, אבל עתה בחצות, שכבר שולט קו האמצעי, וגילה המנעולא, הממעט קו השמאל וסותם אותו, יש שמירה שלא יוכלו עוד הרשעים לינק מה מן השמאל שבמלכות. וז״ש \u0003קב״ה.\u0004 שהוא קו האמצעי, \u0003עאל לטיילא בגנתא.\u0004 שהוא המלכות, שהוא מגלה קול הזה דמנעולא. אעבר ההוא \u0003קלא ושכיך.\u0004 דהיינו אחר שהשמיע הכרוז הנ״ל, והכל ראו שנסתם קו השמאל, אז נשתתק, דהיינו שנגנז, כדי שיוכל לשלוט הקול שמצד צפון, שהוא פעולה הב׳ שבמסך דחירק, הבא ממלכות הממותקת בבינה, שה״ס מפתחא, כדי שיוכל לחזור ולהמשיך בחי׳ ו״ק דג״ר דקו שמאל. (כנ״ל לך י״ג ד״ה ונתבאר, ולעיל ויקהל אות ש״ט בהסולם) ולולא שנשתתק הקול דמנעולא, לא היה יכול לשלוט הקול דמפתחא, ולא היה אפשרות להמשיך בחינת ג״ר לגמרי. כמ״ש שם."]],[[0,"","וְאִם נְקֵבָה תֵלֵד. כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁיּוֹתֵר צַד הַשְּׂמֹאל שׁוֹלֵט, וְהַיָּמִין נִכְנָע. וְעַל כֵּן הַכֹּל, עַל כָּל אֶחָד שְׁנַיִם, רְחוֹקָה הַנְּקֵבָה מִן הַזָּכָר לְהִקָּשֵׁר הָרוּחַ בַּגּוּף, שֶׁהֲרֵי הַשְּׂמֹאל אֵינוֹ מִתְיַשֵּׁב כָּךְ כְּמוֹ הַיָּמִין, וְנִמְצָא יוֹתֵר בְּתֹקֶף."],[1,"","וּבַיּוֹם הַשְּׁמִינִי יִמּוֹל בְּשַׂר עָרְלָתוֹ. מִצְוָה זוֹ לָמוּל לִשְׁמֹנָה יָמִים מִילַת בְּרִית הַקֹּדֶשׁ. סוֹד עֶלְיוֹן, שֶׁכָּתוּב (תהלים כה) סוֹד ה' לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם. לְמִי? לְאוֹתָם יְרֵאָיו, אוֹתָם יִרְאֵי חֵטְא, שֶׁהֲרֵי סוֹד הַבְּרִית הַקָּדוֹשׁ לֹא רָאוּי לְגַלּוֹת, רַק לָהֶם. וְאֶת סוֹד הַבְּרִית הַקָּדוֹשׁ הֲרֵי פֵּרְשׁוּהוּ, וְנִתְבָּאֵר בְּכַמָּה מְקוֹמוֹת."],[2,"","וְסוֹד זֶה לִשְׁמֹנָה יָמִים הוּא חִיּוּב עַל הָעוֹלָם, לְכָל הָעָם הַקָּדוֹשׁ, שֶׁכָּתוּב וּבַיּוֹם הַשְּׁמִינִי יִמּוֹל בְּשַׂר עָרְלָתוֹ. יוֹם הַשְּׁמִינִי - זֶהוּ אוֹת בְּרִית הַקֹּדֶשׁ, וְהוּא שְׁמִינִי לְכָל הַדְּרָגוֹת, וּמִילַת אוֹתוֹ הַבְּרִית לְהַעֲבִיר אוֹתָהּ עָרְלָה מִלִּפְנֵי הַבְּרִית."],[3,"","שֶׁהֲרֵי בְּאוֹתוֹ הַזְּמַן שֶׁמִּתְכַּנְּסִים הָעָם הַקָּדוֹשׁ לְהַעֲבִיר אוֹתָהּ הָעָרְלָה מִלִּפְנֵי הַבְּרִית, הַקָּדוֹשׁ בָּרוּךְ הוּא מְכַנֵּס אֶת כָּל הַפָּמַלְיָא שֶׁלּוֹ וּמִתְגַּלֶּה וַדַּאי לְהַעֲבִיר אֶת אוֹתָהּ הָעָרְלָה לְמַעְלָה מִלִּפְנֵי בְּרִית הַקָּדוֹשׁ. שֶׁהֲרֵי כָּל הַמַּעֲשִׂים שֶׁיִּשְׂרָאֵל עוֹשִׂים לְמַטָּה, מְעוֹרְרִים מַעֲשֶׂה לְמַעְלָה. וּבְאוֹתוֹ זְמַן נִדְחֵית אוֹתָהּ הָעָרְלָה מִכָּל הָעָם הַקָּדושׁ לְמַעְלָה, וּמַתְקִינִים לְאותָהּ הָעָרְלָה כְּלִי אֶחָד עִם עָפָר לְהַשְׁרוֹת אוֹתָהּ הָעָרְלָה בְּתוֹכוֹ, בְּסוֹד הַכָּתוּב (ישעיה סה) וְנָחָשׁ עָפָר לַחְמוֹ. (בראשית ג) וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךְ."],[4,"","מִכָּאן שֶׁלֹּא צָרִיךְ לִנְהֹג בִּזָּיוֹן בַּמָּקוֹם הַהוּא. אַף עַל גַּב שֶׁמַּעֲבִירִים אוֹתוֹ מֵהַבְּרִית הַזּוֹ, וּמְקוֹמוֹ כַּאֲשֶׁר נִפְרָד מֵהַבְּרִית הַזּוֹ הוּא עָפָר, (שהנה) שֶׁהֲרֵי אַחַר שֶׁהַנָּחָשׁ הַהוּא הָעֳבַר מִלִּפְנֵי הָאָדָם, הַקָּדוֹשׁ בָּרוּךְ הוּא שָׂם לוֹ אֶת מְדוֹרוֹ בֶּעָפָר, שֶׁכָּתוּב וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךְ. וְכֵיוָן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁהֶעֱבִיר אוֹתוֹ מִלִּפְנֵי אָדָם, שָׂם מְדוֹרוֹ בֶּעָפָר וְהִתְקִין אוֹתוֹ, כָּךְ בְּאוֹתוֹ גָּוֶן מַמָּשׁ אָנוּ צְרִיכִים כְּשֶׁמַּעֲבִירִים אֶת הָעָרְלָה, לְהַתְקִין לָהּ עָפָר שֶׁיִּהְיֶה בּוֹ הַמָּדוֹר שֶׁלּוֹ."],[5,"","כָּל אָדָם צָרִיךְ לְהַקְרִיב אוֹתוֹ בֵּן קָרְבָּן לַקָּדוֹשׁ בָּרוּךְ הוּא, בְּשִׂמְחָה, בִּרְצוֹן הַלֵּב, לְהַכְנִיסוֹ תַּחַת כַּנְפֵי הַשְּׁכִינָה, וְנֶחְשָׁב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא קָרְבָּן שָׁלֵם שֶׁיִּתְקַבֵּל בְּרָצוֹן."],[6,"","וְהַקָּרְבָּן הַזֶּה, כְּמוֹ קָרְבַּן הַבְּהֵמָה. זֶה לִשְׁמֹנָה יָמִים, וְזֶה לִשְׁמֹנָה יָמִים, שֶׁכָּתוּב וּמִיּוֹם הַשְּׁמִינִי וָהָלְאָה יֵרָצֶה. בַּמֶּה יֵרָצֶה? בָּזֶה שֶׁעוֹבֶרֶת עָלָיו שַׁבָּת אַחַת. כֵּיוָן שֶׁעוֹבֶרֶת עָלָיו שַׁבָּת אַחַת, אָז זֶה יֵרָצֶה לְקָרְבָּן, וְזֶה לְקָרְבָּן. לָמָּה? מִשּׁוּם שֶׁנִּדְבָּק וְנִזְדַּמֵּן אֶל אוֹתָהּ הַשַּׁבָּת, סוֹד בְּרִית הַקֹּדֶשׁ, וְעַל כֵּן הַכֹּל הוּא בְּסוֹד עֶלְיוֹן. (ע\"כ רעיא מהימנא)."],[7,"","אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (שמואל א ב) אֵין קָדוֹשׁ כַּה' כִּי אֵין בִּלְתֶּךְ וְאֵין צוּר כֵּאלֹהֵינוּ. הַפָּסוּק הַזֶּה קָשֶׁה, אֵין קָדוֹשׁ כַּה', מַשְׁמָע שֶׁיֵּשׁ קָדוֹשׁ אַחֵר, מִשּׁוּם שֶׁכָּתוּב כַּה'. וְאֵין צוּר כֵּאלֹהֵינוּ, מַשְׁמָע שֶׁיֵּשׁ צוּר אַחֵר."],[8,"","אֶלָּא וַדַּאי, אֵין קָדוֹשׁ כַּה', שֶׁכַּמָּה קְדוֹשִׁים הֵם, קְדוֹשִׁים לְמַעְלָה, שֶׁכָּתוּב (דניאל ד) וּמֵאמַר קַדִּישִׁין שְׁאֵלְתָא. יִשְׂרָאֵל הֵם קְדוֹשִׁים, שֶׁכָּתוּב (ויקרא יט) קְדשִׁים תִּהְיוּ. וְכֻלָּם קְדוֹשִׁים, וְלֹא קְדוֹשִׁים כַּה'. וּמָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב כִּי אֵין בִּלְתֶּךְ. מַה זֶּה כִּי אֵין בִּלְתֶּךְ? אֶלָּא קְדֻשַּׁת הַקָּדוֹשׁ בָּרוּךְ הוּא בִּלְתִּי הַקְּדֻשָּׁה שֶׁלָּהֶם, שֶׁהוּא לֹא צָרִיךְ אֶת הַקְּדֻשָּׁה שֶׁלָּהֶם. אֲבָל הֵם אֵינָם קְדוֹשִׁים בִּלְתֶּךְ, וְזֶהוּ כִּי אֵין בִּלְתֶּךְ, אֵין הַקְּדֻשָּׁה שֶׁלָּהֶם בִּלְתֶּךְ."],[9,"","וְאֵין צוּר כֵּאלֹהֵינוּ. כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא צָר צוּרָה בְּתוֹךְ צוּרָה וּמַתְקִין אוֹתָהּ, וְנוֹפֵחַ רוּחַ חַיִּים, וּמוֹצִיא אוֹתָהּ לַאֲוִיר הָעוֹלָם. דָּבָר אַחֵר וְאֵין צוּר כֵּאלֹהֵינוּ - יֵשׁ צוּר שֶׁנִּקְרָא צוּר, (ישעיה נא) הַבִּיטוּ אֶל צוּר חֻצַּבְתֶּם. (שמות יז) וְהִכִּיתָ בַצּוּר. הִנְנִי עֹמֵד לְפָנֶיךְ שָּׁם עַל הַצּוּר בְּחֹרֵב. וְכֻלָּם נִקְרָאִים צוּר, וְאֵין צוּר בְּכֻלָּם כֵּאלֹהֵינוּ, שֶׁלּוֹ הַשִּׁלְטוֹן וְהַמַּלְכוּת עַל הַכֹּל."],[10,"","רַבִּי חִיָּיא וְרַבִּי אָחָא הָיוּ יוֹשְׁבִים לַיְלָה אֶחָד לִפְנֵי רַבִּי אַבָּא. קָמוּ בַּחֲצוֹת הַלַּיְלָה לַעֲסֹק בַּתּוֹרָה. עַד שֶׁיָּצְאוּ הַחוּצָה, רָאוּ כּוֹכָב אֶחָד שֶׁהָיָה מַכֶּה שָׁלֹשׁ פְּעָמִים בְּכוֹכָב אַחֵר וּמַסְתִּיר אוֹרוֹ. בֵּינְתַיִם שָׁמְעוּ שְׁנֵי קוֹלוֹת בִּשְׁנֵי צְדָדִים, קוֹל אֶחָד לְצַד צָפוֹן לְמַעְלָה, וְקוֹל אֶחָד לְמַטָּה, וְהַקּוֹל הַהוּא מַכְרִיז וְאוֹמֵר: הִכָּנְסוּ וְהִתְכַּנְּסוּ לִמְקוֹמְכֶם, עַכְשָׁו הִשְׁתַּמְּרוּת שֶׁל נְקֵבָה פְּתוּחָה, הַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לְטַיֵּל בַּגָּן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים שֶׁבַּגָּן. עָבַר אוֹתוֹ הַקּוֹל וְשָׁכַךְ."]]],[["אָהַדְרוּ רִבִּי אֲחָא וְרִבִּי חִיָיא, אָמְרוּ, הָא וַדַאי עִדָּן רְעוּתָא, דְּאִתְעָרוּתָא דְּכְּנֶסֶת יִשְׂרָאֵל (עדן) הוּא לְאִתְחַבְּרָא בְּמַלְכָּא קַדִּישָׁא, אָמַר רִבִּי אֲחָא, וַדַאי, לָא (אתחברת) אֲנְגִידָת לָהּ כְּנֶסֶת יִשְׂרָאֵל בְּקוּדְשָׁא בְּרִיךְ הוּא אֶלָּא מִגּוֹ שִׁירָתָא, מִגּוֹ שְׁבָחָא דִּילָהּ לְגַבֵּיהּ. עַד דְּאָתֵי צַפְרָא, וְאוֹשִׁיט לָהּ מַלְכָּא חוּטָא דְּחֶסֶד, וְרָזָא דְּמִלָּה כְּמָה דְּאַמְרִינָן, (אסתר ה׳:ב׳) וַיּוֹשֶׁט הַמֶּלֶךְ לְאֶסְתֵּר אֶת שַׁרְבִיט הַזָּהָב אֲשֶׁר בְּיָדוֹ וְגוֹ'. וְלָא תֵּימָא דְּלָהּ בִּלְחוֹדָהָא אוֹשִׁיט לָהּ מַלְכָּא דָּא, אֶלָּא לָהּ, וּלְכָל אִינּוּן דְּמִתְחַבְּרָן בָּה. תָּא וְנִתְחַבֵּר כַּחֲדָא. יָתְבוּ.","פָּתַח רִבִּי אֲחָא וְאָמַר, (בראשית ב׳:י״ח) וַיֹּאמֶר יְיָ' אֱלֹהִים לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ וְגוֹ'. אֲמַאי פָּתַח קְרָא הָכִי, אֶלָּא הָא אִתְּמַר, דְּעַל דָּא לָא כְּתִיב, כִּי טוֹב בַּשֵּׁנִי, בְּגִין דְּזַמִּין אָדָם לְאִתְפָּרְשָׁא, וּכְתִיב, לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ.","וְכִי לְבַדּוֹ הֲוָה, וְהָא כְּתִיב, (בראשית ה׳:ב׳) זָכָר וּנְקֵבָה בְּרָאָם. וְתָנֵינָן אָדָם דּוּ פַּרְצוּפִין אִתְבְּרֵי, וְאַתְּ אַמְרַת, לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ. אֶלָּא דְּלָא אִשְׁתְּדַּל בְּנוּקְבֵיהּ, וְלָא הַוַת לֵיהּ, סֶמֶךְ לָקֳבְלֵיהּ, בְּגִין דְּהֲוַת בְּסִטְרוֹי, וַהֲווּ כַּחֲדָא מֵאֲחוֹרָא, וּכְדֵין הֲוָה הָאָדָם לְבַדּוֹ.","אֶעֱשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ. מַהוּ כְּנֶגְדּוֹ, לָקֳבֵל אַנְפּוֹי, לְאִתְדַּבְּקָא דָּא בְּדָא אַנְפִּין בְּאַנְפִּין, מָה עֲבַד קוּדְשָׁא בְּרִיךְ הוּא, נָסַר לֵיהּ וְנָטִיל נוּקְבָּא מִנֵּיהּ, הֲדָא הוּא דִכְתִיב, (בראשית ב׳:כ״א) וַיִּקַּח אַחַת מִצַּלְעוֹתָיו. מַהוּ אַחַת. דָּא נוּקְבָּא דִּילֵיהּ. כְּמָה דְאַתְּ אָמֵר, (שיר השירים ו׳:ט׳) אַחַת הִיא יוֹנָתִי תַמָּתִי. וַיְבִיאֶהָ אֶל הָאָדָם, אַתְקִין לָהּ כְּכַלָּה וְאַיְיתֵי לָהּ לְמֶהֱוִי לָקֳבֵיל אַנְפּוֹי נְהִירִין אַנְפִּין בְּאַנְפִּין. וּבְעוֹד דְּהֲוָה מִתְדַּבְּקָא נוּקְבָּא בְּסִטְרוֹי, הֲוָה הָאָדָם לְבַדּוֹ. לְבָתַר, סְלִיקוּ תְּרֵין, וְקָמוּ שֶׁבַע כַּחֲדָא.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּאִתְכְּנָשׁ (ס\"א דאתתקנת) לְגַבֵּי אָדָם, קוּדְשָׁא בְּרִיךְ הוּא בְּרִיךְ לוֹן, הֲדָא הוּא דִכְתִיב, (בראשית א׳:כ״ב) וַיְבָרֶךְ אוֹתָם אֱלֹהִים. כְּחַזָּן דִּמְבָרֵךְ לְכַלָּה בְּשֶׁבַע בְּרָכוֹת. מִכָּאן אוֹלִיפְנָא, חָתָן וְכַלָּה, כֵּיוָן דְּאִתְבָּרְכָן בְּשֶׁבַע בְּרָכוֹת אִתְדַּבְּקָן כַּחֲדָא, כְּדוּגְמָא דִּלְעֵילָּא.","וְעַל דָּא מַאן דְּאָתֵי לְאִתְחַבְּרָא בְּאִנְתּוּ דְּאָחֳרָא, הָא פָּגִים זִוּוּגָא, (כביכול עביד ב' רשויות לעילא) דְּהָא זִוּוּגָא דְּכְּנֶסֶת יִשְׂרָאֵל, בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, בְּזִמְנָא דְּאִיהוּ בְּרַחֲמֵי, וּבְזִמְנָא דְּאִיהוּ בְּדִינָא. תָּא חֲזֵי, מַאן דְּמִתְחַבָּר בְּאִנְתּוּ דְּאָחֳרָא, כְּאִילּוּ מְשַׁקֵּר בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא וּבִּכְּנֶסֶת יִשְׂרָאֵל, וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא לָא מְכַפֵּר לֵיהּ בִּתְשׁוּבָה, וּתְשׁוּבָה תַּלְיָא עַד דְּיִסְתָּלַק מֵעָלְמָא, הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ב:י״ד) אִם יְכוּפַּר הֶעָוֹן הַזֶּה לָכֶם עַד תְּמוּתוּן. וְאֵימָתַי, בְּשַׁעֲתָא דְּעָאל בִּתְשׁוּבָה לְהַהוּא עָלְמָא, וְאִית לֵיהּ לְקַבְּלָא עוֹנְשָׁא.","רִבִּי אֶלְעָזָר אָמַר, מַאן דִּמְשַׁקֵּר בִּכְּנֶסֶת יִשְׂרָאֵל, לָא יִתְקָבַּל בִּתְשׁוּבָה, עַד דְּיִתְדָּן בְּדִינָא דְּגֵיהִנָּם. כָּל שֶׁכֵּן, מַאן דִּמְשַׁקֵּר בִּכְּנֶסֶת יִשְׂרָאֵל וּבְּקוּדְשָׁא בְּרִיךְ הוּא. וְכָּל שֶׁכֵּן אִי אַטְרַח לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד דִּיּוּקְנָא דְּמַמְזֵר בְּאִנְתּוּ דְּאָחֳרָא, וְאַכְחִישׁ פּוּמְבִּי דְּמַלְכָּא.","רִבִּי חִיָּיא פָּתַח וְאָמַר, (משלי כ״ח:כ״ד) גּוֹזֵל אָבִיו וְאִמּוֹ וְגוֹ'. אָבִיו, דָּא קוּדְשָׁא בְּרִיךְ הוּא. אִמּוֹ, דָּא כְּנֶסֶת יִשְׂרָאֵל. מַאי גּוֹזֵל. כְּמָה דְאַתְּ אָמֵר, (ישעיהו ג׳:י״ד) גְּזֵלַת הֶעָנִי בְּבָתֵּיכֶם. וּמַאן אִיהוּ, מַאן דְּחָמִיד אִתְּתָא אָחֳרָא דְּלָאו אִיהִי בַּת זוּגֵיהּ.","תַּמָּן תָּנֵינָן, כָּל הַנֶּהנֶה מִן הָעוֹלָם הַזֶּה בְּלֹא בְּרָכָה, כְּאִלּוּ גּוֹזֵל לְּקוּדְשָׁא בְּרִיךְ הוּא וּכְּנֶסֶת יִשְׂרָאֵל, דִּכְתִיב גּוֹזֵל אָבִיו וְאִמּוֹ וְגוֹ'. כָּל הַנֶּהֱנֶה מִן הָעוֹלָם הַזֶּה, כְּלָל דָּא, אִיהוּ אִינְתּוּ. מַאן דְּאִתְדַּבָּק בְּאִנְתּוּ לְמֵהֱנֵי מִנָּהּ, וְאַף עַל גַּב, דְּאִיהִי פְּנוּיָה, וְאַהֲנֵי מִנָּהּ בְּלָא בְּרָכָה, כְּאִלּוּ גּוֹזֵל קוּדְשָׁא בְּרִיךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל. מַאי טַעְמָא, בְּגִין דְּזִוּוּגָא דִּלְהוֹן, בְּשֶׁבַע בְּרָכוֹת הוּא. וּמַה עַל פְּנוּיָה כַּךְ, מַאן דְּיִתְדְּבַּק בְּאִנְתּוּ דְּאָחֳרָא, דְּקָאִים כְּגַוְונָא דִּלְעֵילָּא, בְּזִוּוּגָא דְּז' בְּרָכוֹת, עַל אַחַת כַּמָה וְכַמָּה.","(משלי כ״ח:כ״ד) חָבֵר הוּא לְאִישׁ מַשְׁחִית, דָּא יָרָבְעָם, כְּמָה דְּאוּקְמוּהָ, וְאֹמֵר אֵין פָּשַׁע דְּאָמַר הָא פְּנוּיָה הִיא, אֲמַאי אָסוּר. בְּגִין דָּא גּוֹזֵל אָבִיו וְאִמּוֹ הֲוִי. וְלֹא עוֹד אֶלָּא דְּחָבֵר הוּא לְאִישׁ מַשְׁחִית. מַאן הוּא אִישׁ מַשְׁחִית. דְּפָגִים דִּיּוּקְנָא וְתִקּוּנָא דִּלְעֵילָּא. כָּל שֶׁכֵּן מַאן דְּחָמִיד לְאִנְתּוּ דְּחַבְרֵיהּ לְאִתְדַּבְּקָא (ס\"א ואתדבק בה) בָּהּ, דְּפָגִים יַתִּיר. וְעַל דָּא אִתְפְּגִים הוּא לְעָלְמִין. אִישׁ מַשְׁחִית, דְּפָגִים לְעֵילָּא, וּפָגִים לְתַתָּא, וּפָגִים לְנַפְשֵׁיהּ, דִּכְתִּיב מַשְׁחִית, וּכְתִיב, (משלי ו׳:ל״ב) מַשְׁחִית נַפְשׁוֹ הוּא יַעֲשֶׂנָּה."],[[0,"","[א] \u0003אהדרו ר׳ אחא וכו׳:\u0004 חזרו ר׳ אחא ור׳ חייא לבית, ואמרו, הנה ודאי עת רצון. שהיא התעוררות כנסת ישראל להתחבר במלך הקדוש. שהוא ז״א. שהוא קו אמצעי. א״ר אחא, ודאי, שלא נתחברה כנסת ישראל בהקב״ה אלא מתוך שירה, מתוך השבח שלה אליו."],[0,"","פירוש. כי לעיל אומר, \u0003עד דנפקי לבר, חמו\u0004 וכו׳, שהפירוש הוא, כי מטרם נקודת החצות, שאז זמן שליטת השמאל, נבחן הארתו לבחינת \u0003חיצוניות.\u0004 וז״ש, שעוד מטרם \u0003דנפקי לבר,\u0004 מטרם שקבלו הארה \u0003חיצוניות\u0004 משמאל, כבד ראו איך \u0003חד ככבא דהוה בטש\u0004 וכו׳ דהיינו שהגיע נקודת החצות והאיר קו האמצעי, בב׳ פעולותיו, ויחד השמאל עם הימין, ואז נחשב הארתם \u0003לפנימיות,\u0004 וז״ש כאן, \u0003אהדרו ר׳ אחא ור' חייא,\u0004 דהיינו שלא יצאו \u0003לחוץ,\u0004 דהיינו לקבל הארה מקו שמאל, אלא חזרו \u0003לפנימיות\u0004 לבית. כי כבר נתיחדו ימין ושמאל ע״י קו האמצעי, שהארתם נבחן לפנימיות, וז\"ש, \u0003לא אתחברת לה כ״י בקב״ה אלא מגו שירתא, מגו שבחא דילה.\u0004 כי בשעת שליטת השמאל שבמלכות, דהיינו טרם נקודת חצות לילה. המלכות, שעיקר בנינה הוא מקו שמאל, אע״פ שהיא חושך בלי החסדים דקו האמצעי, מ״מ היא מרוחקת מן הת״ת שהוא קו האמצעי הנוטה לחסדים ולימין, כמו הקו שמאל מטרם הכרעת קו האמצעי (כנ״ל ב״א דף נ״ז ד״ה וזה ע\"ש) ובחצות לילה, כשבא הקב״ה וייחד השמאל עם הימין בב' פעולותיו הנ״ל, אז הכירה המלכות בשבחו של הקב״ה שהוא קו האמצעי, מחמת שלמות היחוד דימין ושמאל. ואז נתחברה עם הקב״ה."],[0,"","[ב] \u0003עד דאתי צפרא וכו׳:\u0004 עד שמגיע הבקר, והמלך מושיט לה חוט של חסד, שאז מתלבשת החכמה שבה בחסד ונשלמת וסוד הדבר כמו שנאמר, ויושט המלך לאסתר אה שרביט הזהב אשר בידו. שהמלך, הוא ז״א, ואסתר, היא המלכות. ושרביט הזהב, הוא חוט של חסד. שעם התלבשות בו החכמה שבמלכות נקרא, שרביט של זהב. ואל תאמר שלה לבדה מושיט המלך השרביט של זהב, אלא לה, ולכל אלו שמתחברים בה. בא ונתחבר יחד. ישבו."],[1,"פתח ר׳ אחא וכו׳:","פר״א ואמר, ויאמר ה׳ אלקים לא טוב היות האדם לבדו וגו׳. שואל, למה פתח הכתוב כן. ומשיב, אלא למדנו, שעל כן לא כתוב, כי טוב, ביום שני, משום שאדם עתיד להתחלק, דהיינו שיתחלק ממנו הצלע לבנין הנוקבא. פירוש, כי יום שני ה״ס גבורה וקו שמאל (כנ״ל ב״א דף נ״ו ד״ה כד) והשלמת קו השמאל הוא רק במלכות הנבנית ממנו, וכיון שאדם, שה״ס ז״א, היה לבדו, ועוד לא נתנסרה ממנו המלכות. וכתוב, לא טוב היות האדם לבדו. ע״כ לא נאמר כי טוב ביום שני. כי מטרם שהמלכות נתנסרה מז״א, ונבנית לפרצוף בפני עצמה, לא נשלם קו השמאל דז״א, שהוא יום שני, ונאמר עליו לא טוב וגו׳."],[2,"וכי לבדו הוה וכו׳:","שואל, וכי היה לבדו, והרי כתוב, זכר ונקבה בראם. ולמדנו שאדם הראשון נברא דו פרצופין, דהיינו ב׳ פרצופין זכר ונקבה דבוקים זה בזה מאחוריהם. ואתה אומר, לא טוב היות האדם לבדו. ומשיב, אלא שלא השתדל בנוקביה, ולא היתה לו, עזר כנגדו, משום שהיתה בצדו, והיו דבוקים יחד מאחוריהם, ואז היה האדם לבדו."],[3,"אעשה לו עזר כנגדו:","מהו \u0003כנגדו:\u0004 ומשיב, פירושו כנגד הפנים, כדי שיתחברו זה בזה פנים בפנים. מה עשה הקב״ה, נסר אותו ולקח הנקבה ממנו. ז\"ש, ויקח אחת מצלעותיו. מהו \u0003אחת.\u0004 הוא הנוקבא שלו. כש״א, אחת היא יונתי תמתי. \u0003ויביאה אל האדם,\u0004 היינו שהתקין אותה ככלה, והביאה שתהיה כנגד פניו מאירים פנים בפנים. ובעוד שהיתה הנוקבא מתדבקת בצדו, היה האדם לבדו. ואח״כ עלו שנים, ונזדווגו, וקמו שבע יחד, דהיינו קין עם תאומתו והבל עם ב׳ תאומות, הרי חמשה, ועם אדם וחוח, הם שבעה."],[4,"ת״ח בשעתא דאתתקנת וכו׳:","בוא וראה, בשעה שחוה נתתקנה אל אדם, הקב״ה בירך אותם. ז״ש, ויברך אותם אלקים. כמו חזן המברך את הכלה בשבע ברכות. מכאן למדנו, חתן וכלה, כיון שנתברכו בשבע ברכות מתדבקים יחד. כדמיון שלמעלה, שהמלכות מתברכת בז׳ ברכות מחג״ת נהי״מ דז״א."],[5,"ועל דא מאן וכו׳:","ועל כן מי שבא להתחבר באשת אחר, הוא פוגם הזווג, כי הזווג של כנסת ישראל, הוא בהקב״ה בלבד, הן בזמן שהוא ברחמים והן בזמן שהוא בדין. בוא וראה. מי שמתחבר באשת אחר, הוא כאלו משקר בהקב״ה ובכנסת ישראל, וע״כ הקב״ה אינו מכפר לו על ידי תשובה, והתשובה תלויה לו עד שיסתלק מן העולם. ז\"ש, אם יכופר העון הזה לכם עד תמותון. ומתי מתכפר לו. הוא, בשעה שנכנס בתשובה לעולם ההוא, ויש לו לקבל עונש שם. ואז מכופר לו."],[6,"ר׳ אלעזר אמר וכו׳:","מי שמשקר בכנסת ישראל, דהיינו שבא להתחבר באשת אחר, אינו מתקבל על ידו תשובה, מטרם שנדון בגיהנם. כל שכן, מי שמשקר בכנסת ישראל ובהקב״ה. וכל שכן אם מטריח הקב״ה לעשות צורת ממזר באשת אחר, ומשקר במלך בפרהסיא בגלוי."],[7,"ר׳ חייא פתח וכו׳:","רח\"פ ואמר, גוזל אביו ואמו וגו׳. \u0003אביו,\u0004 זה הקב״ה, \u0003אמו,\u0004 זו כנסת ישראל. מהו \u0003גוזל.\u0004 הוא כמש״א, גזלת העני בבתיכם. ומה היא הגזילה. מי שחומד אשה אחרת שאינה בת זוגו."],[8,"תמן תנינן וכו׳:","שם למדנו, כל הנהנה מעולם הזה בלא ברכה, כאלו גוזל להקב״ה וכנסת ישראל, שכתוב גוזל אביו ואמו ואומר אין פשע חבר הוא לאיש משחית. כל הנהנה מן העולם הזה, כלל זה, שאומר כל הנהנה, הוא אשה. כי מי שמתדבק באשה להנות ממנה, ואע״פ, שהיא פנויה, ונהנה ממנה בלא ברכה, דהיינו בלי שבע ברכות שמברכים את הכלה, הוא, כאלו גוזל להקב״ה וכנסת ישראל. מהו הטעם, משום שהזווג שלהם, הוא בשבע ברכות. והנהנה בלי שבע ברכות, פוגם שבע ברכות שלמעלה. ומה על פנויה כך, כ״ש מי שמתדבק באשת אחר, שהיא עומדת בזווג בשבע ברכות, על ידי בעלה, כעין של מעלה, על אחת כמה וכמה."],[9,"חבר הוא לאיש משחית:","זה ירבעם, כמו שהעמידוהו, (ברכות לה:) \u0003ואמר אין פשע\u0004 שאומר הרי פנויה היא, למה אסור. משום זה הוא גוזל אביו ואמו. ולא עוד אלא שהוא חבר \u0003לאיש משחית.\u0004 מי הוא איש משחית. הוא מי שפוגם הצורה והתקון של מעלה. כל שכן מי שחומד אשת חברו להתדבק בה, שפוגם יותר. וע״כ הוא נפגם לעולם. \u0003איש משחית,\u0004 כי פוגם למעלה, ופוגם למטה, ופוגם את נפשו, שכתוב \u0003משחית,\u0004 וכתוב, משחית נפשו הוא יעשנה."]],[[0,"","חָזְרוּ רַבִּי אָחָא וְרַבִּי חִיָּיא. אָמְרוּ, הִנֵּה וַדַּאי עֵת רָצוֹן, שֶׁהִתְעוֹרְרוּת שֶׁל כְּנֶסֶת יִשְׂרָאֵל (זמן) הִיא לְהִתְחַבֵּר עִם הַמֶּלֶךְ הַקָּדוֹשׁ. אָמַר רַבִּי אָחָא, וַדַּאי לֹא (מתחברת) מֻשְׁפַּעַת לָהּ כְּנֶסֶת יִשְׂרָאֵל עִם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא מִתּוֹךְ שִׁירָה וּמִתּוֹךְ הַשֶּׁבַח שֶׁלָּהּ אֵלָיו. עַד שֶׁבָּא הַבּקֶר, וּמוֹשִׁיט לָהּ הַמֶּלֶךְ חוּט שֶׁל חֶסֶד, וְסוֹד הַדָּבָר כְּמוֹ שֶׁאָמַרְנוּ, (אסתר ה) וַיּוֹשֶׁט הַמֶּלֶךְ לְאֶסְתֵּר אֶת שַׁרְבִיט הַזָּהָב אֲשֶׁר בְּיָדוֹ וְגוֹ'. וְאַל תֹּאמַר שֶׁלָּהּ לְבַדָּהּ מוֹשִׁיט הַמֶּלֶךְ אֶת זֶה, אֶלָּא לָהּ, וּלְכָל אוֹתָם שֶׁמִּתְחַבְּרִים עִמָּהּ. בֹּא וְנִתְחַבֵּר יַחַד. יָשְׁבוּ."],[1,"","פָּתַח רַבִּי אָחָא וְאָמַר, (בראשית ב) וַיֹּאמֶר ה' אֱלֹהִים לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ וְגוֹ'. לָמָּה פָּתַח הַפָּסוּק כָּךְ? אֶלָּא הִנֵּה נִתְבָּאֵר, שֶׁעַל זֶה לֹא כָתוּב כִּי טוֹב בַּשֵּׁנִי, מִשּׁוּם שֶׁעָתִיד אָדָם לְהִפָּרֵד, וְכָתוּב לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ."],[2,"","וְכִי לְבַדּוֹ הָיָה? וַהֲרֵי כָּתוּב (שם ה) זָכָר וּנְקֵבָה בְּרָאָם. וְשָׁנִינוּ, אָדָם דּוּ פַרְצוּפִים נִבְרָא, וְאַתָּה אוֹמֵר לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ?! אֶלָּא שֶׁלֹּא הִשְׁתַּדֵּל עִם נְקֵבָתוֹ, וְלֹא הָיְתָה לוֹ עֵזֶר כְּנֶגְדּוֹ, מִשּׁוּם שֶׁהָיְתָה בְּצִדּוֹ, וְהָיוּ יַחַד מֵאָחוֹר, וְאָז הָיָה הָאָדָם לְבַדּוֹ."],[3,"","אֶעָשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ. מַה זֶּה כְּנֶגְדּוֹ? כְּנֶגֶד פָּנָיו, לְהִדָּבֵק זֶה עִם זֶה פָּנִים בְּפָנִים. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? נִסֵּר אוֹתוֹ וְנָטַל הַנְּקֵבָה מִמֶּנּוּ, זֶהוּ שֶׁכָּתוּב וַיִּקַּח אַחַת מִצַּלְעֹתָיו. מַה זֶּה אַחַת? זוֹ הַנְּקֵבָה שֶׁלּוֹ, כְּמוֹ שֶׁנֶּאֱמַר אַחַת הִיא יוֹנָתִי תַמָּתִי. וַיְבִיאֶהָ אֶל הָאָדָם, הִתְקִינָהּ כְּכַלָּה, וְהֵבִיא אוֹתָהּ לִהְיוֹת כְּנֶגֶד פָּנָיו הַמְּאִירוֹת פָּנִים בְּפָנִים. וּבְעוֹד שֶׁהָיְתָה דְבוּקָה הַנְּקֵבָה בְּצִדּוֹ, הָיָה הָאָדָם לְבַדּוֹ. אַחַר כָּךְ עָלוּ שְׁנַיִם, וְקָמוּ שֶׁבַע יַחַד."],[4,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁנִּכְנְסָה (שהתתקנה) אֵצֶל אָדָם, הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּרַךְ אוֹתָם, זֶהוּ שֶׁכָּתוּב (שם א) וַיְבָרֶךְ אֹתָם אֱלֹהִים, כְּחַזָּן שֶׁמְּבָרֵךְ אֶת הַכַּלָּה בְּשֶׁבַע בְּרָכוֹת. מִכָּאן לָמַדְנוּ, חָתָן וְכַלָּה, כֵּיוָן שֶׁמִּתְבָּרְכִים בְּשֶׁבַע בְּרָכוֹת, נִדְבָּקִים יַחַד, כְּמוֹ דֻגְמָא שֶׁלְּמַעְלָה."],[5,"","וְעַל כֵּן, מִי שֶׁבָּא לְהִתְחַבֵּר עִם אִשָּׁה שֶׁל שֶׁל אַחֵר, הִנֵּה פּוֹגֵם אֶת הַזִּוּוּג, (כביכול עושה שתי רשיות למעלה) שֶׁהֲרֵי הַזִּוּוּג שֶׁל כְּנֶסֶת יִשְׂרָאֵל עִם הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, בִּזְמַן שֶׁהוּא בְּרַחֲמִים וּבִזְמַן שֶׁהוּא בְּדִין. בּא רְאֵה, מִי שֶׁמִּתְחַבֵּר לְאִשָּׁה שֶׁל אַחֵר, כְּאִלּוּ מְשַׁקֵּר בַּקָּדוֹשׁ-בָּרוּךְ-הוּא וּבִכְנֶסֶת יִשְׂרָאֵל, וְעַל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מְכַפֵּר לוֹ בִּתְשׁוּבָה, וְהַתְּשׁוּבָה תְלוּיָה עַד שֶׁיִּסְתַּלֵּק מִן הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (ישעיה כב) אִם יְכֻפַּר הֶעָון הַזֶּה לָכֶם עַד תְּמֻתוּן. וּמָתַי? בְּשָׁעָה שֶׁנִּכְנָס בִּתְשׁוּבָה לָעוֹלָם הַהוּא, וְיֵשׁ לוֹ לְקַבֵּל עֹנֶשׁ."],[6,"","רַבִּי אֶלְעָזָר אָמַר, מִי שֶׁמְּשַׁקֵּר בִּכְנֶסֶת יִשְׂרָאֵל לֹא יִתְקַבֵּל בִּתְשׁוּבָה עַד שֶׁיִּדּוֹן בְּדִין שֶׁל גֵּיהִנֹּם. כָּל שֶׁכֵּן מִי שֶׁמְּשַׁקֵּר בִּכְנֶסֶת יִשְׂרָאֵל וּבַקָּדוֹשׁ-בָּרוּךְ- הוּא. וְכָל שֶׁכֵּן אִם מַטְרִיחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת דְּמוּת שֶׁל מַמְזֵר בְּאִשְׁתּוֹ שֶׁל הָאַחֵר וּמַכְחִישׁ אֶת פִּרְסוּם הַמֶּלֶךְ."],[7,"","רַבִּי חִיָּיא פָּתַח וְאָמַר, (משליכ) גּוֹזֵל אָבִיו וְאִמּוֹ וְגוֹ'. אָבִיו - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. אִמּוֹ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. מַה גּוֹזֵל? כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ג) גְּזֵלַת הֶעָנִי בְּבָתֵּיכֶם. וּמִי הִיא? מִי שֶׁחוֹמֵד אִשָּׁה אַחֶרֶת שֶׁאֵינָהּ בַּת זוּגוֹ."],[8,"","שָׁם שָׁנִינוּ, כָּל הַנֶּהֱנֶה מִן הָעוֹלָם הַזֶּה בְּלֹא בְרָכָה, כְּאִלּוּ גּוֹזֵל אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְאֶת כְּנֶסֶת יִשְׂרָאֵל, שֶׁכָּתוּב גּוֹזֵל אָבִיו וְאִמּוֹ וְגוֹ'. כָּל הַנֶּהֱנֶה מִן הָעוֹלָם הַזֶּה, כְּלָל זֶה הוּא הָאִשָּׁה. מִי שֶׁנִּדְבָּק בְּאִשָּׁה לֵהָנוֹת מִמֶּנָּה, וְאַף עַל גַּב שֶׁהִיא פְּנוּיָה, וְנֶהֱנֶה מִמֶּנָּה בְּלֹא בְרָכָה, כְּאִלּוּ גּוֹזֵל אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְאֶת כְּנֶסֶת יִשְׂרָאֵל. מָה הַטַּעַם? מִשּׁוּם שֶׁהַזִּוּוּג שֶׁלָּהֶם הוּא בְּשֶׁבַע בְּרָכוֹת. וּמָה עַל פְּנוּיָה כָּךְ - מִי שֶׁנִּדְבָּק בְּאִשְׁתּוֹ שֶׁל אַחֵר, שֶׁעוֹמֵד כְּמוֹ שֶׁלְּמַעְלָה, בְּזִוּוּג שֶׁל שֶׁבַע בְּרָכוֹת, עַל אַחַת כַּמָּה וְכַמָּה."],[9,"","חָבֵר הוּא לְאִישׁ מַשְׁחִית - זֶה יָרָבְעָם, כְּמוֹ שֶׁבֵּאֲרוּהָ, וְאֹמֵר אֵין פָּשַׁע, שֶׁאוֹמֵר הִנֵּה הִיא פְּנוּיָה, לָמָּה אָסוּר? מִשּׁוּם זֶה הוּא גּוֹזֵל אָבִיו וְאִמּוֹ. וְלֹא עוֹד, אֶלָּא שֶׁחָבֵר הוּא לְאִישׁ מַשְׁחִית. מִי הוּא אִישׁ מַשְׁחִית? שֶׁפּוֹגֵם הַדְּמוּת וְהַתִּקּוּן שֶׁל מַעְלָה. כָּל שֶׁכֵּן מִי שֶׁחוֹמֵד אֶת אִשְׁתּוֹ שֶׁל חֲבֵרוֹ לְהִדָּבֵק (ונדבק בה) עִמָּהּ, שֶׁפּוֹגֵם יוֹתֵר, וְעַל זֶה הוּא נִפְגָּם לְעוֹלָמִים. אִישׁ מַשְׁחִית - שֶׁפּוֹגֵם לְמַעְלָה, וּפוֹגֵם לְמַטָּה, וּפוֹגֵם אֶת נַפְשׁוֹ, שֶׁכָּתוּב מַשְׁחִית, וְכָתוּב (משלי ו) מַשְׁחִית נַפְשׁוֹ הוּא יַעֲשֶׂנָּה."]]],[["רִבִּי אַבָּא פָּתַח וְאָמַר, (בראשית ל״ב:כ״ז) וַיֹּאמֶר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר וְגוֹ'. וַיֹּאמֶר שַׁלְּחֵנִי, וְכִי עָקוּד הֲוָה בִּידֵיהּ דְּיַעֲקֹב. אֶלָּא זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּקוּדְשָׁא בְּרִיךְ הוּא חָס עַל יְקָרָא דִּלְהוֹן, וְלָא שָׁבִיק לוֹן לְעָלְמִין. הֲדָא הוּא דִכְתִיב, (תהילים נ״ה:כ״ג) לֹא יִתֵּן לְעוֹלָם מוֹט לַצַּדִיק. וְהָא כְּתִיב, (בראשית ל״ב:כ״ו) וַתֵּקַע כַּף יֶרֶךְ יַעֲקֹב.","אֶלָּא לְדִידֵיהּ גָּבָה. וְהָא אִתְּמַר, כְּתִיב (בראשית ל״ב:כ״ב) וְהוּא לָן בַּלַּיְלָה הַהוּא בַּמַּחֲנֶה. וּכְתִיב וַיִּקָּחֵם וַיַּעֲבִירֵם אֶת הַנָּחַל מַאי הֲוָה דַּעְתֵּיהּ דְּיַעֲקֹב, לְמַעֲבְּרָא לְהוֹן בְּנַחֲלָא בְּלֵילְיָא. אֶלָּא חָמָא מְקַטְרְגָא אָזִיל בֵּין מַשִּׁרְיָיא דִּילֵיהּ, אָמַר יַעֲקֹב אַעְבָּר לְגִיסָא אָחֳרָא דְּנַהֲרָא, דִּלְמָא לָא יִשְׁתְּכַּח עִרְבּוּבְיָא.","מַאי קָא חָמָא. חָמָא שַׁלְהוֹבָא דְּאֶשָּׁא מְלָהֲטָא, אַזְלָא וְטָאס בֵּין מַשִׁרְיָיתֵיהּ אָמַר יַעֲקֹב מוּטָב לְנַטְלָא מֵהָכָא, וְנַהֲרָא פָּסִיק בְּגַוָון, וְלָא יִשְׁתְּכַּח עִרְבּוּבְיָא. מִיַּד וַיִּקָּחֵם וַיַּעֲבִירֵם אֶת הַנָּחַל. וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ, מִכָּאן אוֹלִיפְנָא מַאן דְּאִשְׁתְּכַח בִּלְחוֹדוֹי בְּבֵיתָא בְּלֵילְיָא, אוֹ בִּימָמָא בְּבַיִת מְיַחֲדָא, כָּל שֶׁכֵּן בְּלֵילְיָא, מַאי מְיַחֲדָא. מְיַחֲדָא מִשְּׁאָר בֵּיתִין. אוֹ מַאן דְּאָזִיל בִּלְחוֹדוֹי בְּלֵילְיָא יָכִיל לְאִתְזְקָא.","תָּא חֲזֵי וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ, כְּדֵין וַיֵּאָבֵק אִישׁ עִמּוֹ וְגוֹ'. תָּנֵינָן מִסִּטְרָא דְּדִינָא קָא אָתֵי, וְשׁוּלְטָנֵיהּ בִּסְטָר לֵילְיָא. מַאי בִּסְטָר לֵילְיָא. לְאַעֲלָא גָלוּתָא (נ\"א בגלותא) כֵּיוָן דְּסָלִיק נְהוֹרָא, תָּשַׁשׁ חֵילֵיהּ, וְאִתְגַּבָּר עָלֵיהּ חֵילֵיהּ דְּיַעֲקֹב. (נ\"א הוא) דְּהָא מִסִּטְרָא דְּלֵילְיָא קָא אָתֵי, וּבִזְמְנָא דְּהֲוָה לֵילְיָא לָא הֲוָה יָכִיל בֵּיהּ יַעֲקֹב. כַּד סָלִיק נְהוֹרָא אִתְתְּקַף חֵילָא דְּיַעֲקֹב, וְאָחִיד בֵּיהּ, וְאִתְגַּבָּר עָלֵיהּ. חָמָא לֵיהּ יַעֲקֹב דְּהָא שְׁלִיחָא הוּא.","אָמַר לֵיהּ שְׁבוֹק לִי דְּלָא יָכִילְנָא לָךְ. מַאי טַעְמָא לָא יָכִיל לֵיהּ. בְּגִין דְּהֲוָה סָלִיק נְהוֹרָא, וְאִתְּבַּר חֵילָא דִּידֵיהּ, דִּכְתִּיב, (איוב ל״ח:ז׳) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. מַאי וַיָּרִיעוּ. דְּאִתְּבָּרוּ כָּל אִינּוּן דְּאַתְיָין מִסִּטְרָא דְּדִינָא. כְּדֵין אִתְתָּקַּף יַעֲקֹב וְאָחִיד בֵּיהּ.","אָמַר לֵיהּ שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר, מָטָא זִמְנָא לְשַׁבְּחָא שְׁבָחָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְאִתְכַּנְּשָׁא. וַיֹּאמֶר לֹא אֲשַׁלֵּחֲךָ כִּי אִם בֵּרַכְתָּנִי, אִם תְּבָרְכֵנִי מִבָּעֵי לֵיהּ, מַאי אִם בֵּרַכְתָּנִי. אֶלָּא אָמַר לֵיהּ יַעֲקֹב, וַדַּאי אַבָּא בְּרִיךְ לִי אִינּוּן בִּרְכָאן דְּבָעָא לְבָרְכָא לְעֵשָׂו, וּמִסְתָּפֵינָא מִנָךְ, עַל אִינּוּן בִּרְכָאן, אִי אוֹדִית עָלַיְיהוּ, (או) אִי לָאו, אוֹ תִּשְׁתְּכַח עָלַי מְקַטְרְגָא בְּגִינֵיהוֹן.","מִיַּד אָמַר לֵיהּ, וַיֹּאמֶר לֹא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְךָ. מַאי קָאָמַר לֵיהּ, אֶלָּא הָכִי קָאָמַר לֵיהּ, לָאו בְּחַכִּימוּ, וְלָאו בְּעוּקְבָא (דילך), רַוְוחַת לְאִינּוּן בִּרְכָאן, לָא יֵאָמֵר עוֹד שִׁמְךָ יַעֲקֹב, דְּהָא לָאו בְּעוּקְבָא הֲוָה, כִּי אִם יִשְׂרָאֵל, יִשְׂרָאֵל וַדַּאי אוֹדֵי עֲלָךְ, וּמִנֵּיהּ נָפְקוּ בִּרְכָאן, בְּגִין דְּאַנְתְּ אָחִיד בֵּיהּ, וְעַל דָּא, אֲנָא וְכָל שְׁאָר אוּכְלוּסִין, אוֹדֵינָא עָלַיְיהוּ.","כִּי שָׂרִיתָ עִם אֱלֹהִים וְעִם אֲנָשִׁים וַתּוּכָל, עִם אֱלֹהִים כָּל אִינּוּן דְּאַתְיָין מִסִּטְרָא דְּדִינָא קַשְׁיָא. וְעִם אֲנָשִׁים, דָּא עֵשָׂו וְאוּכְלוּסִין דִּילֵיהּ. וַתּוּכָל, יָכִילַת לְהוֹן, וְאִינּוּן לָא יַכְלִין לָךְ. וְלָא שָׁבִיק לֵיהּ יַעֲקֹב, עַד דְּאוֹדֵי לֵיהּ עַל אִינּוּן בִּרְכָאן, הֲדָא הוּא דִכְתִיב וַיְבָרֶךְ אוֹתוֹ שָׁם.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּסָלִיק נְהוֹרָא, אִתְכַּפְיָין כָּל אִינּוּן מָארֵי דְּדִינִין, וְלָא מִשְׁתַּכְּחֵי, וּכְּנֶסֶת יִשְׂרָאֵל מִשְׁתָּעֵי בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. וְהַהִיא שַׁעֲתָא עִידָּן דְּרַעֲוָא הוּא לְכֹלָּא, וְאוֹשִׁיט לָהּ מַלְכָּא וּלְכָל אִינּוּן דְּמִשְׁתַּכְּחֵי עִמָּהּ, שַׁרְבִיטָא דְּחוּטָא דְּחֶסֶד, לְאִשְׁתַּכְּחָא בִּשְׁלִימוּ בְּמַלְכָּא קַדִּישָׁא, וְהָא אִתְּמַר.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּכַח בָּהּ בִּכְּנֶסֶת יִשְׂרָאֵל, בְּאִינּוּן זִמְנִין דְּאִשְׁתְּכַח עִמָּהּ, וְהִיא מַתְעָרַת רְעוּתָא לְגַבֵּיהּ בְּקַדְמִיתָא, וּמַשְׁכַאת לֵיהּ לְגַבָּהּ, בִּסְגִיאוּת חִבָּתָא וְתִיאוּבְתָּא, כְּדֵין אִתְמַלְּיָא מִסִּטְרָא דִּימִינָא, וְכַמָּה אוּכְלוּסִין מִשְׁתַּכְּחֵי בְּסִטְרָא דִּימִינָא, בְּכֻלְּהוּ עָלְמִין. וְכַד קוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר חֲבִיבוּתָא וּרְעוּתָא בְּקַדְמִיתָא, וְהִיא אִתְּעָרַת לְבָתַר, וְלָאו בְּזִמְנָא דְּאִיהוּ אִתְּעַר, כְּדֵין כֹּלָּא בְּסִטְרָא דְּנוּקְבָּא אִשְׁתְּכַח, וּשְׂמָאלָא אִתְּעַר, וְכַמָּה אוּכְלוּסִין קַיְימֵי וּמִתְעָרֵי בְּסִטְרָא דִּשְׂמָאלָא בְּכֻלְּהוּ עָלְמִין. כְּהַאי גַּוְונָא כְּתִיב, (נ\"א הדא הוא דכתיב) אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר וְגוֹ'. מַאי טַעְמָא. תָּנֵינָן, עָלְמָא תַּתָּאָה כְּגַוְונָא דְּעָלְמָא עִלָּאָה אִשְׁתְּכַח, וְדָא כְּדוּגְמָא דְּדָא."],[[0,"רבי אבא פתח וכו׳:","רא׳״פ ואמר, ויאמר שלחני כי עלה השחר וגו׳. שואל, \u0003ויאמר שלחני,\u0004 וכי אסיר היה בידו של יעקב. ומשיב, אלא אשרי הם הצדיקים, שהקב״ה חס על הכבוד שלהם, ואינו עוזב אותם לעולם. ז״ש, לא יתן לעולם מוט לצדיק. שואל, והרי כתוב. ותקע כף ירך יעקב."],[1,"אלא לדידיה גבה וכו׳:","ומשיב. אלא המלאך לקח את שלו. ולמדנו, שכתוב והוא לן בלילה ההוא במחנה. וכתוב, ויקחם ויעבירם את הנחל. שואל, מה היה דעתו של יעקב. להעבירם את הנחל בלילה. ומשיב, אלא ראה את המקטרג שהולך בין המחנות שלו, אמר יעקב אעבירם לצד האחר של הנהר. אולי לא תהיה מבוכה."],[2,"מאי קא חמא וכו׳:","שואל, מה ראה. ואומר, ראה שלהבת אש לוהט הולכת ומעופפת בין מחנותיו, אמר יעקב, מוטב לקחת אותם מכאן לעבר הנהר, והנהר יפסיק ביניהם, ולא תמצא מבוכה. כי המזיקים אינם עוברים נהרות. מיד, ויקהם ויעבירם את הנחל ויותר יעקב לבדו. וכיון שיעקב הפריע אותו מלהזיק המחנות, ע״כ נגע בכף ירכו ותקע כף ירך יעקב. כי לקח ממנו את שלו. מכאן למדנו. מי שנמצא לבדו בבית בלילה, או ביום בבית מיוחד, ומכל שכן בלילה, בבית מיוחד. מהו בית מיוחד. היינו שמיוחד ונפרד משאר בתים. או מי שהולך לבדו בלילה יכול להנזק."],[3,"ת״ח ויותר יעקב וכו׳:","בוא וראה, ויותר יעקב לבדו אז ויאבק איש עמו וגו׳. למדנו, המלאך מצד הדין הוא בא, וממשלתו בצד של הלילה, מהו בצד לילה. היינו שהוא ממונה להכניס את ישראל בגלות שהוא בחינת לילה וחשך. כיון שעלה האור, נחלש כחו, ונתגבר עליו כחו של יעקב. כי מצד של הלילה בא. וע״כ בזמן שהיה לילה לא יכול לו יעקב. וכשעלה האור נתחזק כחו של יעקב, ואחז בו ונתגבר עליו. אז, ראה אותו יעקב שהוא מלאך."],[4,"א\"ל שבוק לי וכו׳:","אמר לו, המלאך, עזוב אותי, כי איני יכול לך. מהו הטעם שלא יכול לו. משום שעלה האור ונשבר כח שלו, שכתוב, בדן יחד ככבי בקר ויריעו כל בני אלקים. מהו ויריעו. היינו שנשברו כל אלו שהם מצד הדין. ויריעו, פירושו שנשברו, מלשון רועה התרועעה הארץ. בני אלהים, היינו אותם הבאים מצד הדין הנק' אלקים. אז נתחזק יעקב ואחז בו."],[5,"א״ל שלחני כי וגו׳:","אמר לו, שלחני כי עלה השחר. היינו שהגיע הזמן להתקבץ ולשבח שבחו של הקב״ה. ויאמר לא אשלחך כי אם ברכתני. שואל, אם תברכני היה צריך לומר, מהו אם ברכתני. שהוא לשון עבר. ומשיב, אלא אמר לו יעקב, ודאי אבי ברך אותי אלו הברכות, שרצה לברך את עשו, ואני ירא ממך, על אלו הברכות אם אתה מודה עליהן, ואם לא, אולי תהיה מקטרג עלי בשבילם."],[6,"מיד אמר ליה וכו׳:","מיד אמר לו ויאמר לא יעקב יקרא עוד שמך. שואל, מה אמר לו. ומשיב, אלא כך אמר לו, לא במרמה, ולא בעקבה, השגת אלו הברכות, ע״כ \u0003לא יאמר עוד שמך יעקב\u0004 שהוא כמו שאמר עשו, על כן וגו׳ ויעקבני זה פעמים, כי לא בעקבה היה. \u0003כי אם ישראל,\u0004 ישראל. שהוא ז״א, שממנו יוצאות הברכות, ודאי, מודה עליך, שהברכות שלך הוא, משום שאתה אחוז בו. וע״כ אני וכל שאר מחנות המלאכים, מודים עליהן, שהברכות הן שלך."],[7,"כי שרית עם וגו׳:","כי שרית עם אלקים ועם אנשים ותוכל. \u0003עם אלקים,\u0004 היינו כל אלו הבאים מצד הדין הקשה. \u0003ועם אנשים,\u0004 זהו עשו והמחנות שלו. \u0003ותוכל,\u0004 אתה יכולת להם, והם לא יוכלו לך. ולא עזב אותו יעקב, עד שהודה לו על אלו הברכות. ז״ש ויברך אותו שם."],[8,"ת״ח בשעתא דסליק וכו':","בוא וראה, בשעה שהאור של הבינה, עולה, נכנעים כל אלו בעלי הדינים ואינם נמצאים, וכנסת ישראל מספרת עם הקב״ה. ושעה ההיא עת רצון היא לכל, והמלך מושיט לה, להמלכות, ולכל אלו הנמצאים עמה, שרביט חוט של חסד, להמצא בשלמות במלך הקדוש. וכבר למדנו."],[9,"ת״ח בשעתא וכו׳:","בוא וראה, בשעה שהקב״ה נמצא יחד עם כנסת ישראל, שהיא המלכות, בכל פעם שנמצא עמה והיא, מעוררת תחילה הרצון אליו, ומושכת אותו אצלה ברוב אהבה והשתוקקות, אז נתמלאה המלכות מצד ימין, שהוא חסדים לבחינת זכר. וכמה מחנות מלאכים נמצאים בצד ימין בכל העולמות. וכשהקב״ה מעורר תחילה אהבה ורצון, והמלכות מתעוררת אח\"כ, ולא בזמן שהקב״ה נתעורר, אז הכל נמצא בבחינת הנקבה, שהיא המלכות, והשמאל נתעורר, וכמה מחנות עומדים ומתעוררים בצד השמאל בכל העולמות. כעין זה כתוב, אשה כי תזריע וילדה זכר. דהיינו אם האשה מזרעת תחילה יולדת זכר. מה הטעם, למדנו, שהוא משום שעולם התחתון נמצא כעין עולם העליון, וזה דומה לזה. וכמו שלמעלה אם המלכות מעוררת תחילה הרצון, נתמלאה מצד ימין, שהיא בחינת זכר, אף למטה כן."]],[[0,"","רַבִּי אַבָּא פָּתַח וְאָמַר, (בראשית לב) וַיֹּאמֶר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר וְגוֹ'. וַיֹּאמֶר שַׁלְּחֵנִי, וְכִי קָשׁוּר הָיָה בְיָדוֹ שֶׁל יַעֲקֹב? אֶלָּא אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל כְּבוֹדָם וְלֹא עוֹזֵב אוֹתָם לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב (תהלים נה) לֹא יִתֵּן לְעוֹלָם מוֹט לַצַּדִּיק. וְהִנֵּה כָּתוּב, וַתֵּקַע כַּף יֶרֶךְ יַעֲקֹב."],[1,"","אֶלָּא אֶת שֶׁלּוֹ גָּבָה. וְהִנֵּה נִתְבָּאֵר, כָּתוּב (בראשית לב) וְהוּא לָן בַּלַּיְלָה הַהוּא בַּמַּחֲנֶה. וְכָתוּב וַיִּקָּחֵם וַיַּעֲבִרֵם אֶת הַנָּחַל. מֶה הָיְתָה דַעְתּוֹ שֶׁל יַעֲקֹב לְהַעֲבִירֵם בַּנַּחַל בַּלַּיְלָה? אֶלָּא רָאָה אֶת הַמְקַטְרֵג הוֹלֵךְ בֵּין הַמַּחֲנֶה שֶׁלּוֹ, אָמַר יַעֲקֹב, אֶעֱבֹר לַצַּד הָאַחֵר שֶׁל הַנָּהָר, אוּלַי לֹא יִמָּצֵא עִרְבּוּבְיָה."],[2,"","מָה רָאָה? רָאָה שַׁלְהֶבֶת שֶׁל אֵשׁ לוֹהֶטֶת, הוֹלֶכֶת וְטָסָה בֵּין מַחֲנוֹתָיו. אָמַר יַעֲקֹב, מוּטָב לִנְסֹעַ מִכָּאן, וְהַנָּהָר מַפְסִיק בֵּינֵינוּ, וְלֹא תִמָּצֵא עִרְבּוּבְיָה. מִיָּד - וַיִּקָּחֵם וַיַּעֲבִרֵם אֶת הַנָּחַל. וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ, מִכָּאן לָמַדְנוּ, מִי שֶׁנִּמְצָא לְבַדּוֹ בַּבַּיִת בַּלַּיְלָה, אוֹ בַּיּוֹם בְּבַיִת מְיֻחָד, כָּל שֶׁכֵּן בַּלַּיְלָה, מַה זֶּה מְיֻחָד? מְיֻחָד מִשְּׁאָר הַבָּתִּים, אוֹ מִי שֶׁהוֹלֵךְ לְבַדּוֹ בַּלַּיְלָה, יָכוֹל לְהִנָּזֵק."],[3,"","בֹּא רְאֵה, וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ, אָז - וַיֵּאָבֵק אִישׁ עִמּוֹ וְגוֹ'. שָׁנִינוּ, הוּא בָּא מִצַּד הַדִּין, וְשִׁלְטוֹנוֹ בַּצַּד שֶׁל הַלַּיְלָה. מַה זֶּה בְּצַד הַלַּיְלָה? לְהִכָּנֵס לַגָּלוּת (בגלותם). כֵּיוָן שֶׁעָלָה הָאוֹר, תָּשַׁשׁ כֹּחוֹ, וּמִתְגַּבֵּר עָלָיו הַכֹּחַ שֶׁל יַעֲקֹב, (הוא) שֶׁהֲרֵי מִצַּד הַלַּיְלָה הוּא בָּא. וּבִזְמַן שֶׁהָיָה לַיְלָה, לֹא הָיָה יָכוֹל לוֹ יַעֲקֹב. כְּשֶׁעָלָה הָאוֹר, הִתְחַזֵּק הַכֹּחַ שֶׁל יַעֲקֹב וְאָחַז בּוֹ, וְהִתְגַּבֵּר עָלָיו. רָאָה אוֹתוֹ יַעֲקֹב שֶׁהִנֵּה הוּא שָׁלִיחַ."],[4,"","אָמַר לוֹ, עֲזֹּב אוֹתְךְ, שֶׁאֵינִי יָכוֹל לְךְ. מָה הַטַּעַם לֹא יָכֹל לוֹ? מִשּׁוּם שֶׁהָיָה עוֹלֶה הָאוֹר, וְנִשְׁבַּר הַכֹּחַ שֶׁלּוֹ, שֶׁכָּתוּב (איוב לח) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. מַה זֶּה וַיָּרִיעוּ? שֶׁנִּשְׁבְּרוּ כָּל אוֹתָם שֶׁבָּאִים מִצַּד הַדִּין. אָז הִתְחַזֵּק יַעֲקֹב וְאָחַז בּוֹ."],[5,"","אָמַר לוֹ, שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר, הִגִּיעַ הַזְּמַן לְשַׁבֵּחַ אֶת שִׁבְחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהִתְכַּנֵּס. וַיֹּאמֶר לֹא אֲשַׁלֵּחֲךְ כִּי אִם בֵּרַכְתָּנִי. אִם תְּבָרְכֵנִי הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אִם בֵּרַכְתָּנִי? אֶלָּא אָמַר לוֹ יַעֲקֹב, וַדַּאי שֶׁאַבָּא בֵּרַךְ אוֹתִי אוֹתָן הַבְּרָכוֹת שֶׁרָצָה לְבָרֵךְ אֶת עֵשָׂו, וַאֲנִי פּוֹחֵד מִמְּךְ עַל אוֹתָן הַבְּרָכוֹת, אִם תּוֹדֶה לִי עֲלֵיהֶן (או) אִם לָאו, אוֹ שֶׁיִּמָּצֵא עָלַי מְקַטְרֵג בִּגְלָלָם."],[6,"","מִיָּד אָמַר לוֹ, וַיֹּאמֶר לֹא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְךְ. מָה אָמַר לוֹ? אֶלָּא כָּךְ אָמַר לוֹ, לֹא בְהִתְחַכְּמוּת וְלֹא בַעֲקֵבוּת (שלך) הִרְוַחְתָּ אֶת אוֹתָן הַבְּרָכוֹת, לֹא יֵאָמֵר עוֹד שִׁמְךְ יַעֲקֹב, שֶׁהֲרֵי לֹא בַעֲקֵבוּת זֶה הָיָה, כִּי אִם יִשְׂרָאֵל, וַדַּאי יִשְׂרָאֵל הוֹדָה עָלֶיךְ וּמִמֶּנּוּ יָצְאוּ הַבְּרָכוֹת, מִשּׁוּם שֶׁאַתָּה אָחוּז בּוֹ, וְעַל זֶה אֲנִי וְכָל שְׁאָר הָאוּכְלוּסִין הוֹדֵינוּ עֲלֵיהֶן."],[7,"","כִּי שָׂרִיתָ עִם אֱלֹהִים וְאִם אֲנָשִׁים וַתּוּכָל. עִם אֱלֹהִים - כָּל אוֹתָם שֶׁבָּאִים מִצַּד הַדִּין הַקָּשֶׁה. וְעִם אֲנָשִׁים - זֶה עֵשָׂו וְהָאוּכְלוּסִים שֶׁלּוֹ. וַתּוּכָל - יָכֹלְתָּ לָהֶם, וְהֵם לֹא יָכְלוּ לְךְ. וְלֹא עָזַב אוֹתוֹ יַעֲקֹב עַד שֶׁהוֹדָה לוֹ עַל אוֹתָן הַבְּרָכוֹת. זֶהוּ שֶׁכָּתוּב וַיְבָרֶךְ אֹתוֹ שָׁם."],[8,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁעָלָה הָאוֹר, נִכְנָעִים כָּל אוֹתָם בַּעֲלֵי הַדִּינִים וְאֵינָם נִמְצָאִים, וּכְנֶסֶת יִשְׂרָאֵל מְסַפֶּרֶת עִם הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאוֹתָהּ הַשָּׁעָה הִיא עֵת רָצוֹן לַכֹּל, וּמוֹשִׁיט לָהּ הַמֶּלֶךְ וּלְכָל אוֹתָם שֶׁנִּמְצָאִים עִמָּהּ שַׁרְבִיט שֶׁל חוּט שֶׁל חֶסֶד, לְהִמָּצֵא בִשְׁלֵמוּת עִם הַמֶּלֶךְ הַקָּדוֹשׁ, וְהִנֵּה נִתְבָּאֵר."],[9,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא עִם כְּנֶסֶת יִשְׂרָאֵל, בְּאוֹתָם הַזְּמַנִּים שֶׁנִּמְצָא עִמָּהּ, וְהִיא מְעוֹרֶרֶת רָצוֹן אֵלָיו בָּרִאשׁוֹנָה, וּמוֹשֶׁכֶת אוֹתוֹ אֵלֶיהָ בְּרֹב חִבָּה וּתְשׁוּקָה, אָז מִתְמַלֵּאת מִצַּד הַיָּמִין, וְכַמָּה אוּכְלוּסִים נִמְצָאִים בְּצַד הַיָּמִין בְּכָל הָעוֹלָמוֹת. וּכְשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֵעִיר חֲבִיבוּת וְרָצוֹן בָּרִאשׁוֹנָה, וְהִיא מְעִירָה אַחַר כָּךְ, וְלֹא בִּזְמַן שֶׁהוּא מֵעִיר, אָז הַכֹּל נִמְצָא בְּצַד הַנְּקֵבָה, וְהַשְּׂמֹאל מִתְעוֹרֵר, וְכַמָּה אוּכְלוּסִים עוֹמְדִים וּמִתְעוֹרְרִים בְּצַד הַשְּׂמֹאל בְּכָל הָעוֹלָמוֹת. כָּךְ גַּם כָּתוּב, (זהושכתוב) אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר וְגוֹ'. מָה הַטַּעַם? שָׁנִינוּ, הָעוֹלָם הַתַּחְתּוֹן נִמְצָא כְּמוֹ הָעוֹלָם הָעֶלְיוֹן, וְזֶה כְּדֻגְמָא שֶׁל זֶה."]]],[["וְעַל דָּא, קוּדְשָׁא בְּרִיךְ הוּא גָּזַר דְּכַר אוֹ נוּקְבָּא, לְאִשְׁתַּכְּחָא רְעוּתָא בְּעָלְמָא. וּבְכֹלָּא בָּעֵי בַּר נָשׁ לְאִתְדַּבְּקָא רְעוּתָא לְעֵילָּא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, לְאִשְׁתַּכְּחָא רַעֲוָון בְּעָלְמָא. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, דְּאִינּוּן יַדְעִין לְאַדְבְּקָא רְעוּתְהוֹן לְגַבֵּי מַלְכָּא קַדִּישָׁא, עָלַיְיהוּ כְּתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.","(ויקרא י״ג:ב׳) אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ שְׂאֵת אוֹ סַפַּחַת אוֹ בַהֶרֶת וְגוֹ'. רִבִּי יְהוּדָה פָּתַח וְאָמַר, (שיר השירים א׳:ו׳) אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחוֹרֶת שֶׁשְּׁזָפַתְנִי הַשָּׁמֶשׁ, הַאי קְרָא אִתְּמַר, אֲבָל בְּשַׁעֲתָא דְּסִיהֲרָא אִתְכַּסְּיָא בְּגָלוּתָא, הִיא אָמְרָה, אַל תִּרְאוּנִי. לָאו דְּאִיהִי פְּקִידַת דְּלָא לְמֵחמֵי לָהּ, אֶלָּא בְּגִין דְּאִיהִי חָמָת תִּיאוּבְתָּא דְּיִשְׂרָאֵל לְגַבָּהּ, לְמֵחֱמֵי נְהוֹרָהָא, הִיא אַמְרַת אַל תִּרְאוּנִי, לָא תֵּיכְלוּן לְמֵחֱמֵי לִי. אַל תִּרְאוּנִי וַדַּאי. מַאי טַעְמָא. בְּגִין שֶׁאֲנִי שְׁחַרְחוֹרֶת, בְּגִין דַּאֲנָא בְּקַדְרוּתָא.","מַאי שְׁחַרְחוֹרֶת, שְׁחוֹרָה מִבָּעֵי לֵיהּ. אֶלָּא, תְּרֵין קַדְרוּתֵי, חַד שֶׁשְּׁזָפַתְנִי הַשָּׁמֶשׁ, דְּאִסְתַּלָּק מִנִּי שִׁמְשָׁא, לְאַנְהֲרָא לִי, וּלְאִסְתַּכְּלָא בִּי. וְחַד דִּבְנֵי אִמִּי נִחֲרוּ בִי.","שֶׁשְּׁזָפַתְנִי, שְׁזָפַתְנִי מִבָּעֵי לֵיהּ. אֶלָּא רְמָז הוּא דְּקָא רָמִיז, בְּשֵׁשׁ. דְּכַד נַהֲרָא שִׁמְשָׁא בְּשֵׁשׁ נְהוֹרִין נָהִיר, וְכַד אִסְתַּלָּק, כָּל אִינּוּן שִׁית נְהוֹרִין אִסְתְּלָקוּ. בְּנֵי אִמִּי, אִלֵּין אִינּוּן דְּאַתְיָין מִסִּטְרָא דְּדִינָא קַשְׁיָא. נִחֲרוּ בִי, כְּמָה דְאַתְּ אָמֵר (תהילים ס״ט:ד׳) נִחַר גְּרוֹנִי, הֲדָא הוּא דִכְתִיב, (איכה ה׳:ה׳) עַל צַוָּארֵנוּ נִרְדָּפְנוּ דְּכַד הֲווֹ עַיְילִין יִשְׂרָאֵל בְּגָלוּתָא, הֲווֹ אָזְלֵי יְדַיְיהוּ מְהַדְּקָן לַאֲחוֹרָא, וְרֵיחַיִין עַל צַוָארֵיהוֹן, וְלָא יָכִילוּ לְאַפְתְּחָא פּוּמָא.","שָׂמוּנִי נוֹטֵרָה אֶת הַכְּרָמִים, לְמֵהַךְ בְּגָלוּתָא, לְנַטְרָא לִשְׁאַר עַמִּין בְּגִינֵהוֹן דְּיִשְׂרָאֵל. כַּרְמִי שֶׁלִּי לֹא נָטָרְתִּי, דְּהָא לָא יָכִילְנָא לְנַטְרָא לְהוֹן כַּד בְּקַדְמִיתָא. בְּקַדְמִיתָא נְטִירְנָא כַּרְמִי שֶׁלִּי, וּמִנֵּיהּ אִתְנְטָרוּ שְׁאָר כַּרְמִין. הַשְׁתָּא נְטִירְנָא שְׁאָר כַּרְמִין בְּגִין כַּרְמִי שֶׁלִּי דְּלִהֱוִי נָטִיר בֵּינַיְיהוּ.","רִבִּי חִיָּיא וְרִבִּי יוֹסֵי הֲווֹ אָזְלֵי בְּאוֹרְחָא, כַּד מָטוּ חַד בֵּי חֲקַל, חָמוּ חַד דַּפְטִירָא דְּקִיטְפָא בֵּין אָרְחָא לִסְטַר יְמִינָא. אָמַר רִבִּי יוֹסֵי, עֲטִיפָא דְּקוּטְרָא בְּעַיְינִין שְׁכִיחַ, לֵית לָן רְשׁוּ לְמֵחמֵי בְּחֶדְוָותָא, מִיּוֹמָא דְּאִתְחֲרִיב בֵּי מַקְדְּשָׁא.","פָּתַח וְאָמַר, (תהילים כ״ד:א׳) לַיְיָ' הָאָרֶץ וּמְלוֹאָהּ תֵּבֵל וְיוֹשְׁבֵי בָהּ, כֵּיוָן דְּאָמַר לַיְיָ' הָאָרֶץ וּמְלוֹאָהּ, אֲמַאי תֵּבֵל וְיוֹשְׁבֵי בָה, וְכִי תֵּבֵל לָאו מִן אַרְעָא הוּא. אֶלָּא הָכִי קָאָמַר, לַיְיָ' הָאָרֶץ וּמְלוֹאָהּ, דָּא אַרְעָא קַדִּישָׁא, דְּאִקְרֵי אֶרֶץ הַחַיִּים. תֵּבֵל וְיוֹשְׁבֵי בָהּ, דָּא שְׁאָר אַרְעָאן, כְּמָה דְאַתְּ אָמֵר (תהילים ט׳:ט׳) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק, דְּתֵבֵל בְּצֶדֶק תַּלְיָא, וְכֹלָּא חַד מִלָּה.","רִבִּי חִיָּיא אָמַר, לַיְיָ' הָאָרֶץ וּמְלוֹאָהּ. הָאָרֶץ תִּינַח, וּמְלוֹאָהּ מַאי הִיא. אֶלָּא אִלֵּין נִשְׁמָתִין דְּצַדִּיקַיָּיא. תֵּבֵל וְיוֹשְׁבֵי בָהּ, תֵּבֵל: דָּא אַרְעָא דִּלְתַתָּא. וְיוֹשְׁבֵי בָהּ: אִלֵּין אִינּוּן בְּנֵי נָשָׁא. אָמַר רִבִּי יוֹסֵי, אִי הָכִי בְּמַאי אוֹקִימְנָא כִּי הוּא עַל יַמִּים יְסָדָהּ וְעַל נְהָרוֹת יְכוֹנְנֶהָ. אָמַר לֵיהּ וַדַּאי הָכִי הוּא, דְּהַהִיא אֶרֶץ הַחַיִּים עַל יַמִּים יְסָדָהּ וְעַל נְהָרוֹת יְכוֹנְנֶהָ, דְּכֻלְּהוּ נַפְקֵי מֵהַהוּא נָהָר עִלָּאָה דְּנָגִיד וְנָפִיק מֵעֵדֶן, וּבְהוּ אִתְתְּקָנַת לְאִתְעַטְּרָא בְּמַלְכָּא קַדִּישָׁא, וּלְמֵיזָן עָלְמִין. (ובגין כך)","מִי יַעֲלֶה בְהַר יְיָ' וְגוֹ', נְקִי כַפַּיִם וּבַר לֵבָב אֲשֶׁר לֹא נָשָׂא לַשָּׁוְא נַפְשִׁי וְגוֹ'. נַפְשׁוֹ כְּתִיב, מַהוּ נַפְשִׁי וְנַפְשׁוֹ. אֶלָּא כֹּלָּא חַד מִלָּה, כְּמָה דְּאַתְּ אָמַר (עמוס ו) נִשְׁבַּע יְיָ' בְּנַפְשׁוֹ (שמואל א ב׳:ל״ה) כַּאֲשֶׁר בִּלְבָבִי וּבְנַפְשִׁי יַעֲשֶׂה. וְדָוִד מַלְכָּא אִתְאֲחִיד בְּהַהוּא לֵב וּבְהַהוּא נֶפֶשׁ, וְעַל דָּא לֹא נָשָׂא לַשָּׁוְא נַפְשׁוֹ."],[[0,"ועל דא קב״ה וכו׳:","ועל כן הקב״ה גוזר זכר או נקבה, להמצא רצון תחילה בעולם, שהוא המלכות, אשר אז מתעוררת גם האשה למטה להזריע תחילה, וילדה זכר. כי הכל תלוי למעלה, ולא למטה. ובכל, צריך האדם שרצונו יתדבק למעלה, להקב״ה, שימצא רצון תחילה בעולם, שהיא המלכות, ואז גם אשתו תזריע תחילה ותלד זכר. אשרי חלקם של הצדיקים שיודעים להדביק רצונם אל המלך הקדוש. עליהם כתוב, ואתם הדבקים בה׳ אלקיכם חיים כלכם היום."],[1,"אדם כי יהיה בעור בשרו וגו׳:","ר׳ יהודה פתח ואמר, אל תראוני שאני שחרחורת ששזפתני השמש. מקרא זה למדנו. אבל בשעה שהלבנה שהיא המלכות, מתכסה בגלות, היא אומרת, אל תראוני, ולא שהיא מצוה שלא לראותה, אלא משום שהיא רואה תשוקת ישראל אליה, לראות אורה היא אומרת, \u0003אל תראוני,\u0004 דהיינו, שלא תוכלו לראות אותי, אל תראוני ודאי. מהו הטעם. הוא משום שאני שחרחורת, מפני שאני בחשכה."],[2,"מאי שחרחורת וכו׳:","שואל, מהו שחרחורת, שחורה היה צריך לומר. ומשיב, אלא שתי חשכות הן, אחת, ששזפתני השמש, דהיינו, שנסתלק ממני השמש, שהוא ז״א, להאיר בי, ולהסתכל בי. ואחת שבני אמי נחרו בי שמוני נוטרה וגו׳."],[3,"ששזפתני שזפתני וכו׳:","שואל, אומר ששזפתני, שזפתני היה צריך לומר. ומשיב, אלא רמז הוא שרומז ב \u0003שש,\u0004 כי ששזפתני הוא אותיות \u0003שש\u0004 זפתני. כי בעת שמאיר השמש. שהוא ז״א, בשש אורות הוא מאיר, דהיינו בשש ספירות חג\"ת נה״י. וכשמסתלק, כל אלו שש אורות מסתלקים. \u0003בני אמי,\u0004 הם אלו הבאים מצד דין הקשה, לענוש על החטאים, \u0003נחרו בי,\u0004 הוא כש״א \u0003נחר\u0004 גרוני. ז\"ש על צוארנו נרדפנו. כי כשבאו ישראל בגלות היו ידיהם קשורות לאחור, וריחים על צוארם, ולא יכלו לפתוח פה. והיינו שכתוב, נחרו בי."],[4,"שמוני נוטרה את הכרמים:","היינו ללכת בגלות, ולשמור שאר העמים בשביל ישראל שהם בתוכם בגלות. \u0003כרמי שלי לא נטרתי,\u0004 כי איני יכול לשמור אותם כמו בתחילה. בתחילה נטרתי כרמי שלי, דהיינו ישראל, וממנו נשמרו שאר הכרמים, שהם האומות. עתה, אני נוטר שאר הכרמים, בשביל כרמי שלי, שיהיה שמור ביניהם."],[5,"ר׳ חייא ור' יוסי וכו׳:","ר״ח ור״י היו הולכים בדרך. כשהגיעו לשדה אחד, ראו עץ אפרסמון בדרך לצד ימין. א״ר יוסי עטיפה של עשן נמצא בעינינו, אין לנו רשות לראות בדבר של שמחה, כמו אפרסמון, מיום שנחרב בית המקדש. \u0003דפטירא,\u0004 הוא כמו דופרא, מלשון, חוץ משל דפרא, שפירושו אילן (דמאי א'). \u0003קיטפא,\u0004 הוא צרי, כי צרי מתרגם קטף (בראשית ל״ז) \u0003עטיפא,\u0004 הוא מלשון יעטף שית חמס (תהלים ע״ג). \u0003דקוטרא,\u0004 הוא עשן, מלשון קטרת."],[6,"פתח ואמר וכו׳:","פתח ואמר, לה׳ הארץ ומלואה תבל ויושבי בה. שואל. כיון שאמר, לה׳ הארץ ומלואה, למה כופל הלשון, תבל ויושבי בה. וכי תבל אינו ארץ. ומשיב, אלא כך הוא אומר, \u0003לה׳ הארץ ומלואה,\u0004 זהו ארץ הקדושה, שנקראת ארץ החיים. \u0003תבל ויושבי בה,\u0004 זהו שאר ארצות, כש״א, והוא ישפוט תבל בצדק. כי תבל תלויה בצדק. והכל דבר אחד הוא."],[7,"ר״ח אמר וכו׳:","ר׳ חייא אמר, לה׳ הארץ ומלואה, \u0003הארץ,\u0004 ידועה שהיא המלכות, \u0003ומלואה\u0004 מה הוא. ומשיב, אלא אלו הם נשמות הצדיקים שהם במלכות. \u0003תבל ויושבי בה,\u0004 תבל, זו היא הארץ שלמטה, בעולם הזה, ויושבי בה, אלו הם בני אדם. אמר ר׳ יוסי, אם כן, אשר הארץ פירושו המלכות, איך נפרש, כי הוא על ימים יסדה ועל נהרות יכוננה. אמר לו ודאי כך הוא, כי ארץ החיים ההיא, שהיא מלכות, על ימים יסדה ועל נהרות יכוננה. כי כולם, כל המוחין, יוצאים מנהר העליון ההוא, הנמשך ויוצא מעדן, שהוא בינה, והמלכות מהתקנת בהם להתעטר במלך הקדוש, ולזון העולמות."],[8,"מי יעלה וגו׳:","מי יעלה בהר ה׳ וגו׳ לא נשא לשוא נפשי וגו׳. שואל, נפשו כתיב, וקרי נפשי, מהו נפשי ונפשו שאומר הכתוב, ומשיב, אלא הכל דבר אחד, כמש״א נשבע ה׳ בנפשו. כאשר בלבבי ובנפשי יעשה, שנפשי הזו היא המלכות, ודוד המלך נתאחד בלב ההוא ונפש ההוא, דהיינו במלכות. וע״כ אומר, אשר לא נשא לשוא נפשו."]],[[0,"","וְעַל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹזֵר זָכָר אוֹ נְקֵבָה, שֶׁיִּמָּצֵא רָצוֹן בָּעוֹלָם. וּבַכֹּל צָרִיךְ אָדָם לְהַדְבִּיק רָצוֹן לְמַעְלָה אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁיִּמָּצְאוּ רְצוֹנוֹת בָּעוֹלָם. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים, שֶׁהֵם יוֹדְעִים לְהַדְבִּיק אֶת רְצוֹנָם אֶל הַמֶּלֶךְ הַקָּדוֹשׁ, עֲלֵיהֶם כָּתוּב, (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם."],[1,"","אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ שְׂאֵת אוֹ סַפַּחַת אוֹ בַהֶרֶת וְגוֹ'. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (שיר א) אַל תִּרְאֻנִי שֶׁאֲנִי שְׁחַרְחֹרֶת שֶׁשְּׁזָפַתְנִי הַשָּׁמֶשׁ. הַפָּסוּק הַזֶּה נִתְבָּאֵר, אֲבָל בְּשָׁעָה שֶׁהַלְּבָנָה מִתְכַּסֵּית בַּגָּלוּת, הִיא אוֹמֶרֶת, אַל תִּרְאֻנִי. לֹא שֶׁהִיא מְצַוָּה שֶׁלֹּא לִרְאוֹת אוֹתָהּ, אֶלָּא מִשּׁוּם שֶׁהִיא רוֹאָה אֶת תְּשׁוּקָתָם שֶׁל יִשְׂרָאֵל אֵלֶיהָ, לִרְאוֹת אֶת אוֹרָהּ, הִיא אוֹמֶרֶת אַל תִּרְאֻנִי, לֹא תוּכְלוּ לִרְאוֹת אוֹתִי. אַל תִּרְאֻנִי וַדַּאי. מָה הַטַּעַם? מִשּׁוּם שֶׁאֲנִי שְׁחַרְחֹרֶת, מִשּׁוּם שֶׁאֲנִי בְּקַדְרוּת."],[2,"","מַה זֶּה שְׁחַרְחֹרֶת? שְׁחֹרָה הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא שְׁתֵּי קַדְרֻיּוֹת, אַחַת - שֶׁשְּׁזָפַתְנִי הַשָּׁמֶשׁ, שֶׁהִסְתַּלֵּק מִמֶּנִּי הַשֶּׁמֶשׁ לְהָאִיר לִי וּלְהִסְתַּכֵּל בִּי, וְאַחַת - שֶׁבְּנֵי אִמִּי נִחֲרוּ בִי."],[3,"","שֶׁשְּׁזָפַתְנִי?! שְׁזָפַתְנִי הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא רֶמֶז הוּא רוֹמֵז, בְּשֵׁשׁ. שֶׁכַּאֲשֶׁר מֵאִיר הַשֶּׁמֶשׁ, בְּשִׁשָּׁה אוֹרוֹת הוּא מֵאִיר, וּכְשֶׁמִּסְתַּלֵּק, כָּל אוֹתָם שֵׁשֶׁת הָאוֹרוֹת מִסְתַּלְּקִים. בְּנֵי אִמִּי - אֵלּוּ הֵם שֶׁבָּאִים מִצַּד הַדִּין הַקָּשֶׁה. נִחֲרוּ בִי, כְּמוֹ שֶׁנֶּאֱמַר נִחַר גְּרוֹנִי. זֶהוּ שֶׁכָּתוּב (איכה ה) עַל צַוָּארֵנוּ נִרְדָּפְנוּ. שֶׁכַּאֲשֶׁר הָיוּ יִשְׂרָאֵל נִכְנָסִים לַגָּלוּת, הָיוּ הוֹלְכִים יְדֵיהֶם מְהֻדָּקוֹת לְאָחוֹר, וְרֵחַיִם עַל צַוָּארָם, וְלֹא יָכְלוּ לִפְתֹּחַ אֶת הַפֶּה."],[4,"","שָׂמוּנִי נֹטֵרָה אֶת הַכְּרָמִים, לָלֶכֶת לַגָּלוּת, לִשְׁמֹר אֶת שְׁאָר הָעַמִּים בִּשְׁבִיל יִשְׂרָאֵל. כַּרְמִי שֶׁלִּי לֹא נָטָרְתִּי, שֶׁהֲרֵי לֹא יָכֹלְתִּי לִשְׁמֹר אוֹתָם כְּבָרִאשׁוֹנָה. בָּרִאשׁוֹנָה שָׁמַרְתִּי אֶת כַּרְמִי שֶׁלִּי, וּמִמֶּנּוּ נִשְׁמְרוּ שְׁאָר הַכְּרָמִים. עַכְשָׁו אֲנִי שׁוֹמֶרֶת אֶת שְׁאָר הַכְּרָמִים בִּשְׁבִיל כַּרְמִי שֶׁלִּי שֶׁיִּהְיֶה שָׁמוּר בֵּינֵיהֶם."],[5,"","רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. כְּשֶׁהִגִּיעוּ לְשָׂדֶה אַחַת, רָאוּ עֵץ אֲפַרְסְמוֹן אֶחָד בְּצַד יְמִין הַדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי, עֲטִיפָה שֶׁל עָשָׁן מְצוּיָה בָעֵינַיִם, אֵין לָנוּ רְשׁוּת לִרְאוֹת בְּשִׂמְחָה מִיּוֹם שֶׁחָרַב בֵּית הַמִּקְדָּשׁ."],[6,"","פָּתַח וְאָמַר, (תהלים כד) לַה' הָאָרֶץ וּמְלוֹאָהּ תֵּבֵל וְיֹשְׁבֵי בָהּ. כֵּיוָן שֶׁאָמַר לַה' הָאָרֶץ וּמְלוֹאָהּ, לָמָּה תֵּבֵל וְיֹשְׁבֵי בָהּ? וְכִי תֵבֵל אֵינֶנָּה מִן הָאָרֶץ? אֶלָּא כָּךְ אָמַר, לַה' הָאָרֶץ וּמְלוֹאָהּ - זוֹ הָאָרֶץ הַקְּדוֹשָׁה, שֶׁנִּקְרֵאת עֵץ הַחַיִּים. תֵּבֵל וְיֹשְׁבֵי בָהּ - אֵלּוּ שְׁאָר הָאֲרָצוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שם ט) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק, שֶׁתֵּבֵל תְּלוּיָה בְצֶדֶק, וְהַכֹּל דָּבָר אֶחָד."],[7,"","רַבִּי חִיָּיא אָמַר, לַה' הָאָרֶץ וּמְלוֹאָהּ, מֵילָא הָאָרֶץ, מַה זֶּה וּמְלוֹאָהּ? אֶלָּא אֵלּוּ נִשְׁמוֹת הַצַּדִּיקִים. תֵּבֵל וְיֹשְׁבֵי בָהּ. תֵּבֵל - זוֹ הָאָרֶץ שֶׁלְּמַטָּה. וְיֹשְׁבֵי בָהּ - אֵלּוּ הֵם בְּנֵי הָאָדָם. אָמַר רַבִּי יוֹסֵי, אִם כָּךְ, בַּמֶּה בֵּאַרְנוּ כִּי הוּא עַל יַמִּים יְסָדָהּ וְעַל נְהָרוֹת יְכוֹנְנֶהָ? אָמַר לוֹ, וַדַּאי כָּךְ זֶה, שֶׁאוֹתָהּ אֶרֶץ הַחַיִּים עַל יַמִּים יְסָדָהּ וְעַל נְהָרוֹת יְכוֹנְנֶהָ, שֶׁכֻּלָּם יוֹצְאִים מֵאוֹתוֹ הַנָּהָר הָעֶלְיוֹן שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן, וּבָהֶם מִתְתַּקֶּנֶת לְהִתְעַטֵּר עִם הַמֶּלֶךְ הַקָּדוֹשׁ וְלָזוּן אֶת הָעוֹלָמוֹת. (ומשום כך)"],[8,"","מִי יַעֲלֶה בְהַר ה' וְגוֹ', נְקִי כַפַּיִם וּבַר לֵבָב אֲשֶׁר לֹא נָשָׂא נַפְשִׁי וְגוֹ'. נַפְשׁוֹ כָּתוּב, מַה זֶּה נַפְשִׁי וְנַפְשׁוֹ? אֶלָּא הַכֹּל דָּבָר אֶחָד, כְּמוֹ שֶׁנֶּאֱמַר (עמוס ו) נִשְׁבַּע אֲדנָי יֱהִֹוִה בְּנַפְשׁוֹ. (שמואל א ב) כַּאֲשֶׁר בִּלְבָבִי וּבְנַפְשִׁי יַעֲשֶׂה. וְדָוִד הַמֶּלֶךְ נֶאֱחַז בְּאוֹתוֹ לֵב וּבְאוֹתָהּ נֶפֶשׁ, וְעַל כֵּן לֹא נָשָׂא לַשָּׁוְא נַפְשׁוֹ."]]],[["עַד דַּהֲווֹ אָזְלֵי, אִעֲרָעוּ בְּחַד בַּר נָשׁ, וְאַנְפּוֹי מַלְיָין מַכְתְּשִׁין, וַהֲוָה קָם מִתְּחוֹת אִילָנָא חַד, אִסְתְּכָּלוּ בֵּיהּ, וְחָמוּ אַנְפּוֹי סוּמָקִין בְּאִינּוּן מַכְתְּשִׁין. אָמַר רִבִּי חִיָּיא מַאן אַנְתְּ. אָמַר לֵיהּ יוּדָאי אֲנָא. אָמַר רִבִּי יוֹסֵי חַטָּאָה הוּא, דְּאִי לָאו הָכִי, לָא אִתְרְשִׁימוּ אַנְפּוֹי בְּאִלֵּין מַרְעִין בִּישִׁין, וְאִלֵּין לָא אִקְרוּן יִסּוּרִין דְּאַהֲבָה. אָמַר רִבִּי חִיָּיא הָכִי הוּא וַדַּאי, דְּיִסוּרִין דְּאַהֲבָה מִתְחַפְּיָין אִינּוּן מִבְּנֵי נָשָׁא.","תָּא חֲזֵי, דִּכְתִּיב אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ שְׂאֵת אוֹ סַפַּחַת אוֹ בַהֶרֶת. הָא ג' זִינִין הָכָא, וְכֻלְּהוּ אִקְרוּן נֶגַע צָרַעַת, הֲדָא הוּא דִכְתִיב וְהָיָה בְעוֹר בְּשָׂרוֹ לְנֶגַע צָרָעַת. מַאי נֶגַע צָרָעַת. סְגִירוּ. סְגִירוּ בְּכֹלָּא, וּכְתִיב וְהוּבָא אֶל אַהֲרֹן הַכֹּהֵן וְגוֹ'. אֲבָל אִינּוּן דְּיִתְחֲזוּן לְבַר כְּתִיב, וְרָאָהוּ הַכֹּהֵן וְטִמֵּא אוֹתוֹ. דְּהָא וַדַּאי אִינּוּן דְּיִתְחֲזוּן לְבַר בִּבְנֵי נָשָׁא, מִסִּטְרָא דִּמְסָאֲבָא קָא אַתְיָין, וְלָאו יִסּוּרִין דְּאַהֲבָה נִינְהוּ.","אָמַר רִבִּי יוֹסֵי, מְנָא לָן. אָמַר רִבִּי חִיָּיא, דִּכְתִּיב, (משלי כ״ז:ה׳) טוֹבָה תּוֹכַחַת מְגוּלָה מֵאַהֲבָה מְסוּתָּרֶת. אֵי הַהִיא תּוֹכַחַת מֵאַהֲבָה (ס\"א אינהו תוכחת מאהבה כד איהי), מְסוּתָּרֶת מִבְּנֵי נָשָׁא. כְּגַוְונָא דָּא מַאן דְּאוֹכַח לְחַבְרֵיהּ בִּרְחִימוּתָא, בָּעֵי לְאַסְתְּרָא מִלּוֹי מִבְּנֵי נָשָׁא, דְּלָא יִכְסוֹף מִנַּיְיהוּ חַבְרֵיהּ, וְאִי מִלּוֹי אִינּוּן בְּאִתְגַּלְיָיא קָמֵי בְּנֵי נָשָׁא, לָאו אִינּוּן בִּרְחִימוּתָא.","כַּךְ קוּדְשָׁא בְּרִיךְ הוּא כַּד אוֹכַח לְבַּר נָשׁ, בְּכֹלָּא אוֹכַח בִּרְחִימוּתָא, בְּקַדְמִיתָא מָחֵי לֵיהּ בְּגַרְמֵיהּ דִּלְגוֹ. אִי הָדָר בֵּיהּ, מוּטָב. וְאִי לָאו מָחֵי לֵיהּ תְּחוֹת תּוֹתְבֵיהּ, וְאִלֵּין (בעורו) אִקְרוּן יִסּוּרִין דְּאַהֲבָה, אִי הָדָר בֵּיהּ מוּטָב, וְאִי לָאו מָחֵי לֵיהּ בְּאִתְגַּלְיָיא בְּאַנְפּוֹי, קָמֵי כֹּלָּא, בְּגִין דְּיִסְתַּכְּלוּן בֵּיהּ, וְיִנְדְּעוּן דְּהָא חַטָּאָה אִיהוּ, וְלָאו רְחִימָא דְּמָארֵיהּ הוּא.","אָמַר לוֹן הַהוּא בַּר נָשׁ, בְּקִיטְרָא דְּעֵיטָא חַד אֲתִיתוּן גַּבָּאי, וַדַּאי לָאו אַתּוּן אֶלָּא מֵאִינּוּן דְּדִיּוּרֵיהוֹן בְּבֵי רִבִּי שִׁמְעוֹן בֶּן יוֹחָאי דְּלָא דַּחֲלִין מִכֹּלָּא. אִי בָּנַי דְּאַתְיָין אֲבַתְרָאי יְקַטְרְגוּ בְּכוּ, אֵיךְ מִלַּיְיכוּ בְּאִתְגַּלְיָיא. אָמַר לֵיהּ אוֹרַיְיתָא הָכִי הוּא, דִּכְתִּיב, (משלי א׳:כ״א) בְּרֹאשׁ הוֹמִיּוֹת תִּקְרָא בְּפִתְחֵי שְׁעָרִים בָּעִיר אֲמָרֶיהָ תֹאמֵר. וּמַה אִי בְּמִלֵּי דְּאוֹרַיְיתָא אֲנָן דַּחֲלֵי מִקָּמָּךְ, הָא נִשְׁתְּכַח בְּכִסּוּפָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. וְלֹא עוֹד, אֶלָּא דְּאוֹרַיְיתָא בָּעֵי צָחוּתָא. פָּתַח הַהוּא גַּבְרָא וְאָמַר (מיכה ז׳:י״ח) מִי אֵל כָּמוֹךָ נוֹשֵׂא עָוֹן וְגוֹ'. אָרִים יְדוֹי וּבָכָה. אַדְּהָכִי מָטוּן בְּנוֹי. אָמַר בְּרֵיהּ זְעֵירָא סִיַּיעְתָּא דִּשְׁמַיָּיא הָכָא.","פָּתַח וְאָמַר (קהלת ז׳:ט״ו) אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי יֵשׁ צַדִּיק אוֹבֵד בְּצִדְקוֹ וְיֵשׁ רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ. הַאי קְרָא אוֹלִיפְנָא בֵּי רִבִּי דּוֹסְתָּאי סָבָא, דְּהֲוָה אָמַר מִשְּׁמֵיהּ דְּרִבִּי יֵיסָא סָבָא. אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי, וְכִי שְׁלֹמֹה מַלְכָּא דְּהֲוָה חַכִּים עַל כֹּלָּא, אֵיךְ אָמַר הָכִי דְּאִיהוּ חָמָא כֹּלָּא בְּזִמְנָא דְּאִיהוּ אָזִיל בַּחֲשׁוֹכֵי עָלְמָא דְּהָא כָּל מַאן דְּאִשְׁתְּדַל בַּחֲשׁוֹכֵי עָלְמָא, לָא חָמֵי מִדִי, וְלָא יָדַע מִדִי.","אֶלָּא הָכִי אִתְּמַר, בְּיוֹמוֹי דִּשְׁלֹמֹה מַלְכָּא, קַיְּימָא סִיהֲרָא בְּאַשְׁלְמוּתָא, וְאִתְחַכָּם שְׁלֹמֹה עַל כָּל בְּנֵי עָלְמָא, וּכְדֵין חָמָא כֹּלָּא, וְיָדַע כֹּלָּא. וּמַאי חָמָא. חָמָא כֹּ\"ל, דְּלָא אַעְדֵּי מִן סִיהֲרָא. וַהֲוָה נָהִיר לָהּ שִׁמְשָׁא (ס\"א ליה כשמשא). הֲדָא הוּא דִכְתִיב אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי. מַאן הֶבְלִי. דָּא סִיהֲרָא דְּאִתְכְּלִילַת מִן כֹּלָּא, מִן מַיָּא וְאֶשָּׁא וְרוּחָא כַּחֲדָא. כְּהֶבֶל דְּנָפִיק מִן פּוּמָא, דְּכָלִיל מִכֹּלָּא.","וְהוּא חָמָא כֹּ\"ל, בְּהַהוּא הֶבֶל דִּילֵיהּ, דְּאָחִיד בֵּיהּ. יֵשׁ צַדִּיק אוֹבֵד בְּצִדְקוֹ, תָּא חֲזֵי, בְּזִמְנָא דְּאַסְגִּיאוּ זַכָּאִין בְּעָלְמָא, הַאי כֹּ\"ל לָא אַעְדֵּי מִן סִיהֲרָא לְעָלְמִין, וְהַאי כֹּ\"ל נָטַל כָּל מְשַׁח וּרְבוּ וְחֵדוּ דִּלְעֵילָּא, וְאִתְמְלֵּי (ס\"א ידוי ורוי) וְחַדֵּי וְרַבֵּי, בְּגִין לְאִזְדַּוְּוגָא בְּסִיהֲרָא, וְהוּא רָוַוח בְּגִינָהּ.","וּבְזִמְנָא דְּאַסְגִּיאוּ חַיָּיבִין בְּעָלְמָא, וְסִיהֲרָא אִתְחַשְּׁכַת, כְּדֵין צַדִּיק אוֹבֵד בְּצִדְקוֹ, צַדִיק נֶאֱבַד לָא כְּתִיב, אֶלָּא צַדִּיק אוֹבֵד, דְּהָא לָא אִתְחֲזֵי (נ\"א אתחבר) בְּסִיהֲרָא, וְלָא נָטִיל מְשַׁח וּרְבוּ וְחֵדוּ לְמַלְיָּא לָהּ, וּלְאִזְדַּוְּוגָא עִמָּהּ. וְעַל דָּא צַדִיק אוֹבֵד, בְּצִדְקוֹ, דָּא סִיהֲרָא, דִּבְגִין סִיהֲרָא דְּלָא אִשְׁתְּכַחַת לְאִזְדַּוְּוגָא עִמֵּיהּ, הוּא אָבִיד, דְּלָא שָׁאִיב מֵחֵידוּ כְּמָה דְּהֲוָה עָבִיד. וּכְדֵין כָּל סְטָר שְׂמָאלָא אִתְּעַר, וְחַיָּיבִין מַאֲרִיכִין בְּשַׁלְוָה בְּעָלְמָא, הֲדָא הוּא דִּכְתִּיב, וְיֵשׁ רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ. מַאי בְּרָעָתוֹ בְּהַהוּא סְטָר (נ\"א בההיא רעה) דְּאִתְדְּבַק בֵּיהּ."],[[0,"עד דהוו אזלי וכו׳:","בעוד שהיו הולכים פגשו באדם אחד ופניו מלאים נגעים, והיה קם מתחת אילן אחד. הסתכלו בו, וראו פניו אדומים מחמת הנגעים. אמר לו ר׳ חייא, מי אתה. אמר לו, יהודי אני. א\"ר יוסי, חוטא הוא, שאם לא כן לא היו נרשמים בפניו אלו נגעים הרעים, ואלו לא נקראו יסורים של אהבה. א\"ר חייא כך הוא ודאי, כי יסורים של אהבה מכוסים הם מבני אדם."],[1,"ת״ח דכתיב וכו׳:","בוא וראה, שכתוב, אדם כי יהיה בעור בשרו שאת או ספחת או בהרת. הרי ג׳ מינים כאן, וכולם נקראים נגע צרעת, ז״ש, והיה בעור בשרו לנגע צרעת. מהו נגע צרעת. הוא סגירו, דהיינו כתרגומו, וזה יורה לשון סגורה, שסגור הוא בכל, כלומר שהנגע מכוסה וסגור מעין רואה, וכתוב על זה והובא אל אהרן הכהן וגו׳. אבל אלו נגעים הנראים לחוץ, כתוב, וראהו הכהן וטמא אותו. כי ודאי אלו הנראים לחוץ לבני אדם, באים מצד הטומאה ואינם יסורים של אהבה."],[2,"א״ר יוסי מנלן וכו׳:","אר״י, מאין לנו זה. א״ר חייא, שכתוב, טובה תוכחת מגולה מאהבה מסותרת, שפירושו, טובה תוכחת מגולה ואם התוכחה היא מאהבה, היא מסותרת מבני אדם. כעין זה מי שמוכיח את חבירו באהבה, צריך להסתיר דבריו מבני אדם, שחברו לא יתבייש מהם. ואם דבריו הם בגלוי לפני בני אדם, אין הם באהבה."],[3,"כך קב״ה כד וכו׳:","כך הקב״ה כשהוא מוכיח את האדם, מוכיחו באהבה בכל, תחילה מכה אותו בגופו מבפנים. אם חזר בו טוב, ואם לא, מכה אותו תחת מלבושיו. ואלו נקראים יסורים של אהבה, אם חזר בו טוב, ואם לא, מכה אותו בגלוי, בפניו לפני כל, כדי שיסתכלו בו וידעו שהוא חוטא, ואינו אהובו של אדונו."],[4,"אמר לון ההוא וכו׳:","אמר להם אדם ההוא, בקשר של עצה אחת באתם עלי ודאי לבזות אותי. אינכם, אלא מאותם היושבים בבית ר׳ שמעון בן יוחאי, שאינם יראים מכל. אם יבואו בני הבאים אחרי יצירו אתכם, ולמה דבריכם בגלוי. הרי אתם צריכים לירא מבני. אמרו לו, התורה כך היא, שכתוב, בראש הומיות תקרא בפתחי שערים בעיר אמריה תאמר. ומה אם בדברי תורה נירא מפניך, הרי אנו נמצאים בבזיון לפני הקב\"ה. ולא עוד אלא התורה צריכה צחות. דהיינו לדבר בגלוי. פתח האיש ואמר, מי אל כמוך נושא עון וגו׳. הרים ידיו ובכה. בתוך כך הגיעו בניו. אמר בנו הקטן. כאן עזרת השמים. לאבי."],[5,"פתח ואמר וכו׳:","פו״א, את הכל ראיתי בימי הבלי יש צדיק אובד בצדקו ויש רשע מאריך ברעתו. מקרא זה למדתי אצל רבי דוסתאי סבא, שהיה אומר משמיה דר׳ ייסא סבא. את הכל ראיתי בימי הבלי. שואל, וכי שלמה המלך שהיה חכם מכל, איך אמר כך, שראה הכל בזמן שהוא הלך בחשכות העולם. דהיינו בימי הבלו. שהרי כל מי שעוסק בחשכות העולם. אינו רואה כלום, ואיני יודע כלום."],[6,"אלא הכי אתמר וכו׳:","ומשיב, אלא כך למדנו, בימיו של שלמה המלך עמדה הלבנה במלואה, ונחכם שלמה מכל בני העולם, ואז ראה הכל וידע הכל. ומה ראה. ראה \u0003כל,\u0004 שהוא יסוד הנקרא, כל, שאינו סר מן הלבנה, שהיא המלכות, והיה מאיר לה השמש. ז״ש, את הכל ראיתי בימי הבלי מהו הבלי. הוא הלבנה, שהוא המלכות, שכלולה מכל, מן מים, שהוא חסד, מאש, שהוא גבורה, ורוח, שהוא תפארת, ביחד, כמו הבל היוצא מן הפה הכלול מכל, ממים ורוח ואש."],[7,"והוא חמא כל וכו׳:","והוא ראה \u0003כל,\u0004 שהוא יסוד, בהבל ההוא, שהוא מלכות, שנאחז בו. \u0003יש צדיק אובד בצדקו.\u0004 בוא וראה, בזמן שמרובים צדיקים בעולם, \u0003כל,\u0004 ההוא, שהוא יסוד, לא הוסר מן הלבנה, שהיא מלכות, לעולם. ו \u0003כל\u0004 הזה, לוקח כל השמן והעוז והשמחה שלמעלה, ונתמלא ושמח ומתנשא, כדי להזדווג בלבנה. והוא מרויח כל זה בשבילה."],[8,"ובזמנא דאסגיאו חייבין וכו׳:","ובשעה שהרשעים מרובים בעולם, והלבנה נחשכה, אז צדיק, שהוא יסוד, אובד בצדקו. צדיק נאבד לא כתוב, אלא צדיק אובד. הוא משום שאינו נראה בלבנה, דהיינו שאינו משפיע לה, ואינו לוקח שמן ועוז ושמחה למלא אותה ולהתחבר עמה. וע״כ \u0003צדיק אובד,\u0004 כל זה, \u0003בצדקו\u0004 שהיא הלבנה, שבשביל הלבנה שאינה נמצאת להתחבר עמו, הוא אובד, ואינו שואב מן השמחה שלמעלה, כמו שהיה עושה. ואז כל צד השמאל מתעורר, ורשעים מאריכים בשלוה בעולם. ז״ש, ויש רשע מאריך ברעתו. מהו ברעתו. הוא באותו הצד הרע שנתדבק בו."]],[[0,"","בְּעוֹדָם הוֹלְכִים, פָּגְשׁוּ בְאִישׁ אֶחָד, וּפָנָיו מְלֵאוֹת בְּמַכּוֹת, וְהָיָה קָם מִתַּחַת אִילָן אֶחָד. הִסְתַּכְּלוּ בוֹ, וְרָאוּ פָנָיו אֲדֻמּוֹת בְּאוֹתָן הַמַּכּוֹת. אָמַר רַבִּי חִיָּיא, מִי אַתָּה? אָמַר לוֹ, אֲנִי יְהוּדִי. אָמַר רַבִּי יוֹסֵי, חוֹטֵא הוּא, שֶׁאִם לֹא כָּךְ, לֹא נִרְשְׁמוּ פָנָיו בְּאֵלּוּ הֶחֳלָאִים הָרָעִים, וְאֵלּוּ לֹא נִקְרָאִים יִסּוּרִים שֶׁל אַהֲבָה. אָמַר רַבִּי חִיָּיא, כָּךְ הוּא וַדַּאי, שֶׁיִּסּוּרִים שֶׁל אַהֲבָה מְכֻסִּים הֵם מִבְּנֵי אָדָם."],[1,"","בֹּא רְאֵה, שֶׁכָּתוּב אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ שְׂאֵת אוֹ סַפַּחַת אוֹ בַהֶרֶת. הִנֵּה שְׁלֹשָׁה מִינִים כָּאן, וְכֻלָּם נִקְרָאִים נֶגַע צָרַעַת. זֶהוּ שֶׁכָּתוּב וְהָיָה בְעוֹר בְּשָׂרוֹ לְנֶגַע צָרָעַת. מַה זֶּה נֶגַע צָרָעַת? הַסְגָּרָה, הַסְגָּרָה בַּכֹּל, וְכָתוּב וְהוּבָא אֶל אַהֲרֹן הַכֹּהֵן וְגוֹ'. אֲבָל אוֹתָם שֶׁיֵּרָאוּ לַחוּץ, כָּתוּב וְרָאָהוּ הַכֹּהֵן וְטִמֵּא אֹתוֹ. שֶׁהֲרֵי וַדַּאי אוֹתָם שֶׁיֵּרָאוּ בַחוּץ בִּבְנֵי אָדָם, הֵם בָּאִים מִצַּד הַטֻּמְאָה, וְאֵינָם יִסּוּרִים שֶׁל אַהֲבָה."],[2,"","אָמַר רַבִּי יוֹסֵי, מִנַּין לָנוּ? אָמַר רַבִּי חִיָּיא, שֶׁכָּתוּב (משלי כז) טוֹבָה תּוֹכַחַת מְגֻלָּה מֵאַהֲבָה מְסֻתָּרֶת. אֵיזוֹהִי תוֹכַחַת מֵאַהֲבָה? (זוהי תוכחת מאהבה כאשר היא) מְסֻתָּרֶת מִבְּנֵי אָדָם. כְּמוֹ זֶה מִי שֶׁמּוֹכִיחַ אֶת חֲבֵרוֹ בְּאַהֲבָה, צָרִיךְ לְהַסְתִּיר דְּבָרָיו מִבְּנֵי אָדָם, שֶׁלֹּא יִתְבַּיֵּשׁ מֵהֶם חֲבֵרוֹ. וְאִם דְּבָרָיו הֵם בְּגָלוּי לִפְנֵי בְּנֵי אָדָם, אֵינָם בְּאַהֲבָה."],[3,"","כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּשֶׁמּוֹכִיחַ אֶת הָאָדָם, בַּכֹּל הוּא מוֹכִיחַ בְּאַהֲבָה. בָּרִאשׁוֹנָה מַכֶּה אוֹתוֹ בְּגוּפוֹ בִּפְנִים. אִם חוֹזֵר בּוֹ - מוּטָב, וְאִם לֹא - מַכֶּה אוֹתוֹ תַּחַת לְבוּשׁוֹ, וְאֵלּוּ (בעורו) נִקְרָאִים יִסּוּרִים שֶׁל אַהֲבָה. אִם חָזַר בּוֹ - מוּטָב, וְאִם לֹא - מַכֶּה אוֹתוֹ בְּגָלוּי בְּפָנָיו, לִפְנֵי כֻלָּם, כְּדֵי שֶׁיִּסְתַּכְּלוּ בוֹ וְיֵדְעוּ שֶׁהִנֵּה הוּא חוֹטֵא, וְלֹא אָהוּב שֶׁל רִבּוֹנוֹ הוּא."],[4,"","אָמַר לָהֶם אוֹתוֹ הָאִישׁ, בְּקֶשֶׁר שֶׁל עֵצָה אַחַת בָּאתֶם אֵלַי, וַדַּאי אֵינְכֶם אֶלָּא מֵאוֹתָם שֶׁדִּיּוּרָם בְּבֵית רַשְׁבִּ\"י, שֶׁלֹּא פוֹחֲדִים מֵהַכֹּל. אִם בָּנַי שֶׁבָּאִים אַחֲרַי יִתְגָּרוּ בָכֶם, אֵיךְ דִּבְרֵיכֶם בְּגָלוּי? אָמַר לוֹ, הַתּוֹרָה כָּךְ הִיא, שֶׁכָּתוּב (משלי א) בְּרֹאשׁ הֹמִיּוֹת תִּקְרָא בְּפִתְחֵי שְׁעָרִים בָּעִיר אֲמָרֶיהָ תֹאמֵר. וּמָה אִם בְּדִבְרֵי תוֹרָה אָנוּ פוֹחֲדִים מִפָּנֶיךְ, הֲרֵי נִמָּצֵא בְּבוּשָׁה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא עוֹד, אֶלָּא שֶׁהַתּוֹרָה צְרִיכָה צַחוּת. פָּתַח אוֹתוֹ הָאִישׁ וְאָמַר, (מיכה ז) מִי אֵל כָּמוֹךְ נֹשֵׂא עָון וְגוֹ'. הֵרִים יָדָיו וּבָכָה. בֵּינְתַיִם הִגִּיעוּ בָנָיו. אָמַר בְּנוֹ הַקָּטָן, יֵשׁ כָּאן סִיּוּעַ שְׁמֵימִי."],[5,"","פָּתַח וְאָמַר, (קהלת ז) אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי יֵשׁ צַדִּיק אֹבֵד בְּצִדְקוֹ וְיֵשׁ רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ. הַפָּסוּק הַזֶּה לָמַדְנוּ בְּבֵית רַבִּי דּוֹסְתַאי סָבָא, שֶׁהָיָה אוֹמֵר מִשְּׁמוֹ שֶׁל רַבִּי יֵיסָא סָבָא. אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי, וְכִי שְׁלֹמֹה הַמֶּלֶךְ שֶׁהָיָה חָכָם עַל הַכֹּל, אֵיךְ אָמַר כָּךְ שֶׁהוּא רָאָה הַכֹּל בִּזְמַן שֶׁהוּא הָלַךְ בֶּחֳשָׁכִים שֶׁל הָעוֹלָם? שֶׁהֲרֵי כָּל מִי שֶׁמִּשְׁתַּדֵּל בֶּחֳשָׁכִים שֶׁל הָעוֹלָם, לֹא רוֹאֶה דָבָר וְלֹא יוֹדֵעַ דָּבָר?"],[6,"","אֶלָּא כָּךְ נִתְבָּאֵר, בִּימֵי שְׁלֹמֹה הַמֶּלֶךְ עָמְדָה הַלְּבָנָה בִּשְׁלֵמוּתָהּ, וּשְׁלֹמֹה הִתְחַכֵּם עַל כָּל בְּנֵי הָעוֹלָם, וְאָז רָאָה הַכֹּל וְיָדַע הַכֹּל. וּמָה רָאָה? רָאָה כֹּ\"ל, שֶׁלָּא זָז מִן הַלְּבָנָה, וְהָיָה מֵאִיר לָהּ הַשֶּׁמֶשׁ (לה כשמש). זֶהוּ שֶׁכָּתוּב אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי. מַה זֶּה הֶבְלִי? זוֹ הַלְּבָנָה שֶׁנִּכְלֶלֶת מִן הַכֹּל, מִמַּיִם וְאֵשׁ וְרוּחַ יַחַד. כְּהֶבֶל שֶׁיּוֹצֵא מִן הַפֶּה שֶׁכָּלוּל מִן הַכֹּל."],[7,"","וְהוּא רָאָה כֹּ\"ל, בְּאוֹתוֹ הַהֶבֶל שֶׁלּוֹ שֶׁאָחַז בּוֹ. יֵשׁ צַדִּיק אֹבֵד בְּצִדְקוֹ, בֹּא וּרְאֵה, בִּזְמַן שֶׁמִּתְרַבִּים הַצַּדִּיקִים בָּעוֹלָם, הַכֹּ\"ל הַזֶּה לֹא זָז מֵהַלְּבָנָה לְעוֹלָמִים, וְהַכֹּ\"ל הַזֶּה נוֹטֵל כָּל שֶׁמֶן וּמִשְׁחָה וְשִׂמְחָה שֶׁלְּמַעְלָה, וּמִתְמַלֵּא (ידיוורוה) וְשָׂמֵחַ וְגָדֵל, כְּדֵי לְהִזְדַּוֵּג עִם הַלְּבָנָה, וְהוּא מַרְוִיחַ בִּשְׁבִילָהּ."],[8,"","וּבִזְמַן שֶׁמִּתְרַבִּים הָרְשָׁעִים בָּעוֹלָם וְהַלְּבָנָה נֶחְשֶׁכֶת, אָז הַצַּדִּיק אֹבֵד בְּצִדְקוֹ. לֹא כָתוּב צַדִּיק נֶאֱבָד, אֶלָּא צַדִּיק אֹבֵד, שֶׁהֲרֵי לֹא נִרְאֶה (מתחבר) בַּלְּבָנָה, וְלֹא נוֹטֵל שֶׁמֶן וּמִשְׁחָה וְשִׂמְחָה לְמַלֵּא אוֹתָהּ וּלְהִזְדַּוֵּג עִמָּהּ. וְעַל זֶה צַדִּיק אֹבֵד בְּצִדְקוֹ, זוֹ הַלְּבָנָה, שֶׁבִּגְלַל הַלְּבָנָה שֶׁלֹּא נִמְצֵאת לְהִזְדַּוֵּג עִמּוֹ, הוּא אוֹבֵד, שֶׁלֹּא שׁוֹאֵב מֵהַשִּׂמְחָה כְּמוֹ שֶׁהָיָה עוֹשֶׂה. וְאָז מִתְעוֹרֵר כָּל צַד הַשְּׂמֹאל, וְהָרְשָׁעִים מַאֲרִיכִים בְּשַׁלְוָה בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב וְיֵשׁ רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ. מַה זֶּה בְּרָעָתוֹ? בְּאוֹתוֹ הַצַּד (באותה רעה) שֶׁנִּדְבָּק בּוֹ."]]],[["תּוּ יֵשׁ צַדִּיק אוֹבֵד בְּצִדְקוֹ, דְּכַד חַיָּיבִין סְגִיאוּ בְּעָלְמָא, וְדִינָא תַּלְיָא (בחובייהו) צַדִּיק אוֹבֵד בְּצִדְקוֹ, אִיהוּ אִתְּפַס בְּחוֹבַיְיהוּ, כְּגוֹן אַבָּא דְּאִתְפַּס בְּחוֹבַיְיהוּ דִּבְנֵי מָאתֵיהּ, דַּהֲווֹ כֻּלְּהוּ חֲצִיפִין (לגביה), וְהוּא לָא אַסְהִיד בְּהוּ וְלָא אַכְסִיף לְהוּ לְעָלְמִין, וּמָחֵי בִּידָן, דְּלָא נִתְגְּרֵי בְּהוּ בְּרַשִׁיעַיָּא (נ\"א ולא מחי בידיהון דלא מתגרו בהו). וַהֲוָה אָמַר לָן, (תהילים ל״ז:א׳) לְדָוִד אַל תִּתְחַר בַּמְּרֵעִים אַל תְּקַנֵּא בְּעוֹשֵׂי עַוְלָה. אָמַר אֲבוּי, וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא אַעְנִישׁ לִי בְּדָא, דְּהָא הֲוָה רְשׁוּ בִּידִי לִמְחֳאָה בִּידַיְיהוּ, וְלָא עֲבָדִית, וְלָא אַכְסִיפְנָא (נ\"א אוכיחנא) לְהוּ, לָא בִּטְמִירוּ, וְלָא בְּאִתְגַּלְיָא.","תּוּ פָּתַח בְּרֵיהּ אָחֳרָא וְאָמַר, (בראשית ב׳:ז׳) וַיִּיצֶר יְיָ' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה וְגוֹ'. וַיִּיצֶר יְיָ' אֱלֹהִים, בִּתְרֵי יוֹדִין, בִּתְרֵין יִצְרִין, יֵצֶר טוֹב וְיֵצֶר רָע, חַד לָקֳבֵל מַיָּא, וְחַד לָקֳבֵל אֶשָּׁא. יְיָ' אֱלֹהִים, שֵׁם מָלֵא. אֶת הָאָדָם, כָּלִיל דְּכַר וְנוּקְבָּא. עָפָר מִן הָאֲדָמָה, דָּא עַפְרָא דְּאַרְעָא קַדִּישָׁא, דְּמִתַּמָּן אִתְבְּרֵי, וְהוּא אֲתַר דְּבֵי מַקְדְּשָׁא.","וַיִפַּח בְּאַפָּיו נִשְׁמַת חַיִּים, דָּא נִשְׁמְתָא קַדִּישָׁא, דְּאִתְמַשְּׁכָא מֵאִינּוּן חַיִּים דִּלְעֵילָּא. וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה, אָדָם אִתְכְּלִיל בְּנַפְשָׁא קַדִּישָׁא, מֵחַיָּה עִלָּאָה. דְּאַפִּיקַת אַרְעָא דִּכְתִּיב, (בראשית א׳:כ״ד) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, נֶפֶשׁ דְּהַהִיא חַיָּה עִלָּאָה.","תָּא חֲזֵי, בְּכָל זִמְנָא דְּהַאי נִשְׁמְתָא קַדִּישָׁא, אִתְדַּבְּקַת בֵּיהּ בְּבַר נָשׁ. רְחִימָא הוּא דְּמָארֵיהּ. כַּמָה נְטוּרִין נַטְרִין לֵיהּ מִכָּל סִטְרִין, רְשִׁימָא הוּא לְטָב לְעֵילָּא וְתַתָּא, וּשְׁכִינְתָּא קַדִּישָׁא שַׁרְיָא עֲלוֹי.","וּבְזִמְנָא דְּאִיהוּ אַסְטֵי אָרְחוֹי, שְׁכִינְתָּא אִסְתְּלָקַת מִנֵּיהּ, וְנִשְׁמְתָא קַדִּישָׁא לָא אִתְדְּבָקַת בֵּיהּ. וּמִסִּטְרָא דְּחִוְיָא בִּישָׁא תַּקִּיפָא, אִתְּעַר רוּחָא חַד, דְּשָׁט וְאָזִיל בְּעָלְמָא, דְּלָא שַׁרְיָא אֶלָּא בַּאֲתַר דִּקְדוּשָּׁה עִלָּאָה אִסְתְּלַּק מִתַּמָּן. וּכְדֵין אִסְתְּאַב בַּר נָשׁ, וְאִתְפְּגִים בִּבְשָׂרֵיהּ, בְּחֵיזוּ דְּאַנְפּוֹי בְּכֹלָּא.","וְתָּא חֲזֵי, בְּגִין דְּהַאי נֶפֶשׁ חַיָּה אִיהִי קַדִּישָׁא עִלָּאָה, כַּד אַרְעָא קַדִּישָׁא מַשְׁכָא לָהּ, וְאִתְכְּלִילַת בְּגַוָּוה, כְּדֵין קָרֵינָן לָהּ נְשָׁמָה. וְדָא הִיא דְּסַלְּקָא לְעֵילָּא, וּמְמַלְּלָא קָמֵי מַלְכָּא קַדִּישָׁא, וְעַיְילָא בְּכָל תַּרְעִין, וְלֵית דְּיִמְחֵי בִּידָהָא. וְעַל דָּא אִתְקְרֵי רוּחָא מְמַלְּלָא, דְּהָא כָּל שְׁאָר נַפְשָׁתָא לֵית לוֹן רְשׁוּ לְמַלְּלָא קָמֵי מַלְכָּא, בַּר הַאי.","וְעַל דָּא אוֹרַיְיתָא אַכְרִיזַת וְאַמְרַת, (תהילים ל״ד:י״ד) נְצוֹר לְשׁוֹנְךָ מֵרָע וְגוֹ', וּכְתִיב (משלי כ״א:כ״ג) שׁוֹמֵר פִּיו וּלְשׁוֹנוֹ וְגוֹ', בְּגִין דְּאִי שִׁפְוָותֵיהּ וְלִישָׁנֵיהּ מְמַלְּלָן מִלִּין בִּישִׁין, אִינּוּן מִלִּין סַלְּקִין לְעֵילָּא, וּבְשַׁעֲתָא דְּסַלְּקִין, כֹּלָּא מַכְרִיזִין וְאָמְרִין אִסְתֵּלָקוּ מִסּוֹחֲרָנֵיהּ דְּמִלָּה בִּישָׁא דִּפְלַנְיָא, פְּנוּן אֲתַר לְאָרְחֵיהּ דְּחִוְיָא תַּקִּיפָא. כְּדֵין נִשְׁמְתָא קַדִּישָׁא אִתְעַבְּרָא מִנֵּיהּ וְאִסְתְּלָּקַת, וְלָא יַכְלָא לְמַלְּלָא, כְּמָה דְאַתְּ אָמֵר (תהילים ל״ט:ג׳) נֶאֱלַמְתִּי דּוּמִיָּה הֶחֱשֵׁיתִי מִטּוֹב.","וְהַהִיא נִשְׁמְתָא סַלְּקָא בְּכִסּוּפָא, בְּעָאקוּ דְּכֹלָּא, וְלָא יָהֲבִין לָהּ אֲתַר כְּמִלְּקַדְּמִין. וְעַל דָּא כְּתִיב, שׁוֹמֵר פִּיו וּלְשׁוֹנוֹ שׁוֹמֵר מִצָּרוֹת נַפְשׁוֹ. נַפְשׁוֹ וַדַּאי הַהִיא דַּהֲוַת מְמַלְּלָא, אִתְעָבִידַת מַשְׁתּוּקָא, בְּגִין מִלּוּלָא בִּישָׁא. וּכְדֵּין חִוְיָא אִזְדְּמַן, דְּכֹלָּא לְאַתְרֵיהּ אִתְהַדָּר, וְכַד הַהִיא מִלָּה בִּישָׁא סַלְּקָא בְּאוֹרְחִין יְדִיעָן, וְשָׁארִי קַמֵּיהּ דְּחִוְיָא תַּקִּיפָא, כַּמָה רוּחִין מִתְעָרִין בְּעָלְמָא, וְרוּחָא נַחְתָּא מֵהַהוּא סִטְרָא, וְאַשְׁכַּח דְּהַהוּא בַּר נָשׁ אִתְּעַר לֵיהּ בְּמִלָּה בִּישָׁא, וְהָא רוּחָא מְמַלְּלָא קַדִּישָׁא אִתְעַבְּרָא מִנֵּיהּ, כְּדֵין שַׁרְיָא עֲלוֹי וְסָאִיב לֵיהּ, וּכְדֵין הוּא סָגִיר.","כְּמָה דְּעוֹנְשָׁא דְּהַאי בַּר נָשׁ בְּגִין מִלָּה בִּישָׁא. כַּךְ עוֹנְשֵׁיהּ בְּגִין מִלָּה טָבָא, דְּקָאתֵי לִידֵיהּ, וְיָכִיל לְמַלְּלָא, וְלָא מַלִּיל. בְּגִין דְּפָגִים לְהַהוּא רוּחָא מְמַלְּלָא, דְּהִיא אִתְתְּקָנַת לְמַלְּלָא לְעֵילָּא, וּלְמַלְּלָא לְתַתָּא, וְכֹלָּא בִּקְדוּשָּׁה. כָּל שֶׁכֵּן אִי עַמָּא אַזְלִין בְּאוֹרְחָא עֲקִימָא, וְהוּא יָכִיל לְמַלְּלָא לְהוּ וּלְאוֹכָחָא לְהוּ, וְשָׁתִיק וְלָא מַלִּיל, כַּמָה דַּאֲמֵינָא דִּכְתִּיב, נֶאֱלַמְתִּי דוּמִיָּה הֶחֱשֵׁיתִי מִטּוֹב וּכְאֵבִי נֶעְכָּר. נֶעְכָּר בְּמַכְתְּשִׁין דִּמְסָאֲבוּתָא, וְדָא הוּא דְּאָמַר דָּוִד מַלְכָּא אַלְקֵי בְּהַאי, וְאִתְפְּנֵי מִנֵּיהּ, דִּכְתִּיב, (תהילים כ״ה:ט״ז) פְּנֵה אֵלַי וְחָנֵּנִי. מַהוּ פְּנֵה אֵלַי. כְּמָה דְאַתְּ אָמֵר (במדבר י״ב:י׳) וַיִּפֶן אַהֲרֹן. נַחְתּוּ רִבִּי חִיָּיא וְרִבִּי יוֹסֵי, וּנְשָּׁקוּהוּ. אִזְדָּוָּוגוּ כַּחֲדָא כָּל הַהוּא אוֹרְחָא, קָרָא רִבִּי חִיָּיא עָלַיְיהוּ, (משלי ד׳:י״ח) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם."],[[0,"תו יש צדיק וגו׳:","עוד, יש צדיק אובד בצדקו. כי כשהרשעים מרובים בעולם, והדין תלוי, צדיק אובד בצדקו, שהוא נתפס בעונותיהם, כמו אבי, שנתפס בעונותיהם של בני עירו, שהיו כולם עזי פנים, והוא לא הזהיר אותם ולא היה מביישם לעולם, והיה מעכב בידינו, שלא נתגרה ברשעים. והיה אומר לנו, לדוד אל תתחר במרעים אל תקנא בעושי עולה. אמר אביו, ודאי הקב״ה. העניש אותי בזה, כי היה רשות בידי למחות בידם ולא עשיתי, ולא בזיתי אותם, לא בסתר ולא בגלוי."],[1,"תו פתח בריה אחרא וכו':","עוד פתח בנו האחר, ואמר, וייצר ה׳ אלקים את האדם עפר מן האדמה וגו׳. \u0003וייצר ה׳ אלקים,\u0004 כתוב, וייצר עם ב׳ יודין, יורה שהאדם נברא בשני יצרים, ביצר הטוב, וביצר הרע, אחד, יצר הטוב, כנגד מים, ואחד היצר הרע, כנגד אש. \u0003הויה אלקים,\u0004 הוא שם מלא. \u0003את האדם,\u0004 כלול זכר ונקבה. כי \u0003את\u0004 רומז על הנקבה. \u0003עפר מן האדמה\u0004 זהו עפר של ארץ קדושה, שמשם נברא, והוא מקום בית המקדש."],[1,"","פירוש. עפר הוא מלכות. האדמת, היא בינה, שה״ס ארץ אדום, דהיינו שאדם הראשון נברא ממלכות הממותקת בבינה. וז״ש \u0003והוא אתר דבי מקדשא.\u0004 כי עפר בית המקדש היא בחינת מלכות הממותקת בבינה."],[2,"ויפח באפיו נשמת חיים:","זו היא הנשמה הקדושה, שנמשכת מאלו החיים, שלמעלה, מבינה. \u0003ויהי האדם לנפש חיה,\u0004 שהאדם נכלל מנפש הקדושה של חיה עליונה ההיא, שהיא בינה, שהוציאה הארץ, שהיא מלכות. שכתוב. \u0003תוצא הארץ נפש חיה.\u0004 נפש, של חיה ההיא העליונה, שהיא בינה."],[3,"תא חזי בכל וכו׳:","בוא וראה, בכל שעה שהנשמה הקדושה ההיא דבוקה באדם, הוא אהובו של אדונו. כמה שמירות שומרים אותו מכל הצדדים, רשום הוא לטוב, למעלה ולמטה, והשכינה הקדושה שורה עליו."],[4,"ובזמנא דאיהו אסטי וכו׳:","ובשעה שהיא מטה דרכיו. השכינה מסתלקת ממנו, והנשמה הקדושה אינה מתדבקת בו, ומצד נחש הרע הקשה, נתעורר רוח אחד, המשוטט והולך בעולם שאינו שורה אלא במקום שהקדושה העליונה נסתלקה משם. והוא שורה על האדם. ואז נטמא האדם. ונפגם בבשרו, בכל, ובמראה פניו."],[5,"ות״ח בגין דהאי וכו׳:","ובוא וראה, משום שנפש חיה הזו, היא קדושה ועליונה, דהיינו מן הבינה, כשארץ הקדושה, שהיא המלכות, מושכת אותה ונכללת בתוכה, אז קוראים אותה, \u0003נשמה.\u0004 כי אור הבינה נקרא נשמה. וזו היא שעולה למעלה ומדברת לפני המלך הקדוש, ונכנסת בכל השערים ואין מי שימחה בידה, ועל כן נקראת רוחא ממללא, בתרגום, דהיינו רוח המדבר, כי כל שאר הנפשות, שאינן מן הבינה, אין להן רשות לדבר לפני המלך חוץ מזו, שהיא מבינה."],[6,"ועל דא אורייתא וכו׳:","ועל כן התורה מכריזה ואומרת, נצור לשונך מרע וגו׳. וכתוב, שומר פיו ולשונו וגו׳. משום שאם שפתיו ולשונו מדברים דברים רעים אלו הדברים עולים למעלה, ובשעה שעולים, כולם מכריזים ואומרים הסתלקו מסביב דבור הרע של פלוני, תנו מקום לדרכו של נחש הקשה. אז נעברת ממנו הנשמה הקדושה, ומסתלקת ואינה יכולה לדבר. כש״א נאלמתי דומיה החשיתי מטוב."],[7,"וההיא נשמתא סלקא וכו׳:","ונשמה ההיא עולה בבזיון, בצרה, מכל. ולא נותנים לה מקום כבתחילה. ועל זה כתוב, שומר פיו ולשונו שומר מצרות נפשו. נפשו ודאי אותה שהיתה מדברת, נעשית שותקת, משום דבורים הרעים שדברה. ואז נזדמן הנחש. כי הכל חזר למקומו, לתחילתו. כמו מטרם שזכה לנשמה. וכשהדבור הרע עולה בדרכים ידועים, ושורה לפני הנחש הקשה, כמה רוחות מתעוררים בעולם, ורוח טמא יורד מצד ההוא של הנחש, ומוצא שאדם ההוא עורר אותו בדבור הרע, ומוצא שהרוח המדבר הקדוש נעבר ממנו, אז שורה עליו הרוח הטמא ומטמא אותו, ואז הוא מצורע."],[8,"כמה דעונשא דהאי וכו׳:","כמו שעונש האדם הוא משום דיבור רע, כך עונשו, משום דיבור טוב שבא לידו ויכול לדבר ולא דיבר. משום שפגם ברוח המדבר ההוא, כי הוא נתתקן לדבר למעלה, ולדבר למטה, והכל בקדושה. כל שכן, אם העם הולך בדרך עקום, והוא יכול לדבר להם, ולהוכיח אותם, ושותק ואינו מדבר. כמו שאמרתי, שעליו נאמר, נאלמתי דומיה החשיתי מטוב וכאבי נעכר. נעכר בנגעים של הטומאה. וזה הוא שאמרו, שדוד המלך נלקה בזה, בצרעת, והקב״ה פנה ממנו. שכתוב, שבקש, פנה אלי וחנני. משמע שהפנה פניו ממנו. מהו פנה אלי. הוא כש״א ויפן אהרן, כמו ששם הוא בצרעת, אף כאן הוא בצרעת. ירדו ר׳ חייא ור׳ יוסי ונשקוהו, נתחברו יחד בכל הדרך ההוא. קרא ר׳ חייא עליהם, וארח צדיקים כאור נגה הולך ואור עד נכון היום."]],[[0,"","עוֹד יֵשׁ צַדִּיק אֹבֵד בְּצִדְקוֹ, שֶׁכַּאֲשֶׁר הָרְשָׁעִים רַבִּים בָּעוֹלָם וְהַדִּין תָּלוּי (בחטאיהם), הַצַּדִּיק אֹבֵד בְּצִדְקוֹ, הוּא נִתְפָּס בְּחֶטְאָם, כְּמוֹ אַבָּא שֶׁנִּתְפָּס בַּחֲטָאֵי בְּנֵי עִירוֹ, שֶׁכֻּלָּם הָיוּ חֲצוּפִים (אליו), וְהוּא לֹא הִתְרָה בָהֶם וְלֹא בִיֵּשׁ אוֹתָם לְעוֹלָמִים, וּמָחָה בְיָדֵינוּ שֶׁלֹּא נִתְגָּרֶה בָּרְשָׁעִים (ולא מחה בידם שלא להתגרות בהם), וְהָיָה אוֹמֵר לָנוּ, (תהלים לז) לְדָוִד אַל תִּתְחַר בַּמְּרֵעִים אַל תְּקַנֵּא בְּעֹשֵׂי עַוְלָה. אָמַר אָבִי, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא הֶעֱנִישׁ אוֹתִי בָּזֶה, שֶׁהֲרֵי הָיְתָה רְשׁוּת בְּיָדִי לִמְחוֹת בִּידֵיהֶם וְלֹא עָשִׂיתִי, וְלֹא בִיַּשְׁתִּי (הוכחתי) אוֹתָם לֹא בַסֵּתֶר וְלֹא בַגָּלוּי."],[1,"","עוֹד פָּתַח בְּנוֹ אַחֵר וְאָמַר, (בראשית ב) וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה וְגוֹ'. וַיִּיצֶר ה' אֱלֹהִים, בִּשְׁנֵי יוֹדִי\"ם, בִּשְׁנֵי יְצָרִים, יֵצֶר טוֹב וְיֵצֶר רָע, אֶחָד כְּנֶגֶד מַיִם וְאֶחָד כְּנֶגֶד אֵשׁ. ה' אֱלֹהִים - שֵׁם מָלֵא. אֶת הָאָדָם - כּוֹלֵל זָכָר וּנְקֵבָה. עָפָר מִן הָאֲדָמָה - זֶה עֲפַר הָאָרֶץ הַקְּדוֹשָׁה, שֶׁמִּשָּׁם נִבְרָא, וְהוּא מְקוֹם בֵּית הַמִּקְדָּשׁ."],[2,"","וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים - זוֹ הַנְּשָׁמָה הַקְּדוֹשָׁה שֶׁנִּמְשֶׁכֶת מֵאוֹתָם הַחַיִּים שֶׁלְּמַעְלָה. וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה, אָדָם נִכְלָל בַּנֶּפֶשׁ הַקְּדוֹשָׁה, מֵהַחַיָּה הָעֶלְיוֹנָה שֶׁהוֹצִיאָה הָאָרֶץ, שֶׁכָּתוּב (שם א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, הַנֶּפֶשׁ שֶׁל הַחַיָּה הָעֶלְיוֹנָה הַהִיא."],[3,"","בֹּא רְאֵה, בְּכָל זְמַן שֶׁהַנְּשָׁמָה הַקְּדוֹשָׁה הַזּוֹ נִדְבֶּקֶת בָּאָדָם, אֲהוּב רִבּוֹנוֹ הוּא. כַּמָּה שׁוֹמְרִים שׁוֹמְרִים אוֹתוֹ מִכָּל הַצְּדָדִים, רָשׁוּם הוּא לְטוֹב, לְמַעְלָה וּלְמַטָּה, וְהַשְּׁכִינָה הַקְּדוֹשָׁה שׁוֹרָה עָלָיו."],[4,"","וּבִזְמַן שֶׁהוּא מַסְטֶה אֶת דַּרְכּוֹ, הַשְּׁכִינָה מִסְתַּלֶּקֶת מִמֶּנּוּ, וְהַנְּשָׁמָה הַקְּדוֹשָׁה לֹא נִדְבֶּקֶת בּוֹ. וּמִצַּד הַנָּחָשׁ הָרָע הַתַּקִּיף מִתְעוֹרֶרֶת רוּחַ אַחַת שֶׁמְּשׁוֹטֶטֶת וְהוֹלֶכֶת בָּעוֹלָם, שֶׁלֹּא שׁוֹרָה אֶלָּא בְּמָקוֹם שֶׁהַקְּדֻשָּׁה הָעֶלְיוֹנָה הִסְתַּלְּקָה מִשָּׁם, וְאָז הָאִישׁ נִטְמָא, וְנִפְגָּם בִּבְשָׂרוֹ בְּמַרְאֵה פָנָיו בַּכֹּל."],[5,"","וּבֹא רְאֵה, מִשּׁוּם שֶׁנֶּפֶשׁ חַיָּה הַזּוֹ הִיא קְדוֹשָׁה עֶלְיוֹנָה, כְּשֶׁמּוֹשֶׁכֶת אוֹתָהּ הָאָרֶץ הַקְּדוֹשָׁה וְנִכְלֶלֶת בְּתוֹכָהּ, אָז קוֹרְאִים לָהּ נְשָׁמָה, וְזוֹ הִיא שֶׁעוֹלָה לְמַעְלָה וּמְדַבֶּרֶת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְנִכְנֶסֶת בְּכָל הַשְּׁעָרִים, וְאֵין מוֹחֶה בְיָדָהּ, וְעַל כֵּן נִקְרֵאת רוּחַ מְמַלְּלָא, שֶׁהֲרֵי לְכָל שְׁאָר הַנְּפָשׁוֹת אֵין רְשׁוּת לְדַבֵּר לִפְנֵי הַמֶּלֶךְ, פְּרָט לָזוֹ."],[6,"","וְעַל כֵּן הַתּוֹרָה מַכְרִיזָה וְאוֹמֶרֶת: (תהלים לד) נְצֹר לְשׁוֹנְךְ מֵרָע וְגוֹ', וְכָתוּב (משלי כא) שֹׁמֵר פִּיו וּלְשׁוֹנוֹ וְגוֹ'. מִשּׁוּם שֶׁאִם שִׂפְתוֹתָיו וּלְשׁוֹנוֹ מְדַבְּרִים דְּבָרִים רָעִים, אוֹתָם הַדִּבּוּרִים עוֹלִים לְמַעְלָה, וּבְשָׁעָה שֶׁעוֹלִים, הַכֹּל מַכְרִיזִים וְאוֹמְרִים: הִסְתַּלְּקוּ מִסְּבִיב הַדִּבּוּר הָרָע שֶׁל פְּלוֹנִי! פַּנּוּ מָקוֹם לְדַרְכּוֹ שֶׁל הַנָּחָשׁ הַתַּקִּיף! אָז הַנְּשָׁמָה הַקְּדוֹשָׁה עוֹבֶרֶת מִמֶּנּוּ וּמִסְתַּלֶּקֶת וְלֹא יְכוֹלָה לְדַבֵּר, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לט) נֶאֱלַמְתִּי דוּמִיָּה הֶחֱשֵׁיתִי מִטּוֹב."],[7,"","וְאוֹתָהּ הַנְּשָׁמָה עוֹלָה בְּבוּשָׁה, בַּצָּרָה שֶׁל הַכֹּל, וְלֹא נוֹתְנִים לָהּ מָקוֹם כְּמִקֹּדֶם. וְעַל זֶה כָּתוּב, שֹׁמֵר פִּיו וּלְשׁוֹנוֹ שֹׁמֵר מִצָּרוֹת נַפְשׁוֹ. נַפְשׁוֹ וַדַּאי. אוֹתָהּ שֶׁהָיְתָה מְדַבֶּרֶת, נֶעֶשְׂתָה מְשֻׁתֶּקֶת מִשּׁוּם הַדִּבּוּר הָרָע. וְאָז מִזְדַּמֵּן הַנָּחָשׁ, שֶׁהַכֹּל חוֹזֵר לִמְקוֹמוֹ, וּכְשֶׁאוֹתוֹ הַדִּבּוּר הָרָע עוֹלֶה בִדְרָכִים יְדוּעוֹת וְשׁוֹרֶה לִפְנֵי הַנָּחָשׁ הַתַּקִּיף, כַּמָּה רוּחוֹת מִתְעוֹרְרוֹת בָּעוֹלָם, וְרוּחַ יוֹרֶדֶת מֵהַצַּד הַהוּא, וּמוֹצֵאת אוֹתוֹ הָאִישׁ מְעוֹרֵר אוֹתוֹ בְּדִבּוּר רָע, וְהָרוּחַ הַמְמַלֶּלֶת הַקְּדוֹשָׁה הַזּוֹ עוֹבֶרֶת מִמֶּנּוּ. אָז שׁוֹרָה עָלָיו וּמְטַמֵּאת אוֹתוֹ, וְאָז הוּא סָגוּר."],[8,"","כְּמוֹ שֶׁעָנְשׁוֹ שֶׁל הָאִישׁ הַזֶּה מִשּׁוּם דִּבּוּר רָע, כָּךְ עָנְשׁוֹ מִשּׁוּם דִּבּוּר טוֹב, שֶׁבָּא לְיָדוֹ וְיָכֹל לְדַבֵּר וְלֹא דִבֵּר. מִשּׁוּם שֶׁפָּגַם אוֹתָהּ הָרוּחַ הַמְמַלֶּלֶת, שֶׁהִיא מְתֻקֶּנֶת לְדַבֵּר לְמַעְלָה וּלְדַבֵּר לְמַטָּה, וְהַכֹּל בִּקְדֻשָּׁה. כָּל שֶׁכֵּן אִם הָעָם הוֹלְכִים בְּדֶרֶךְ עֲקֻמָּה, וְהוּא יָכוֹל לְדַבֵּר לָהֶם וּלְהוֹכִיחַ אוֹתָם, וְשׁוֹתֵק וְלֹא מְדַבֵּר, כְּמוֹ שֶׁאָמַרְנוּ שֶׁכָּתוּב נֶאֱלַמְתִּי דוּמִיָּה הֶחֱשֵׁיתִי מִטּוֹב וּכְאֵבִי נֶעְכָּר. נֶעִכָּר בְּמַכּוֹת שֶׁל טֻמְאָה. וְזֶהוּ שֶׁאָמַר דָּוִד הַמֶּלֶךְ, מַלְקֶה בָּזֶה וּמִתְפַּנֶּה מִמֶּנּוּ, שֶׁכָּתוּב (תהלים פז) פְּנֵה אֵלַי וְחָנֵּנִי. מַה זֶּה פְּנֵה אֵלַי? כְּמוֹ שֶׁנֶּאֱמַר (במדבר יב) וַיִּפֶן אַהֲרֹן. יָרְדוּ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי וּנְשָׁקוּהוּ. הִתְחַבְּרוּ יַחַד כָּל אוֹתָהּ הַדֶּרֶךְ. קָרָא עֲלֵיהֶם רַבִּי חִיָּיא, (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם."]]],[["(ויקרא י״ג:ט׳) נֶגַע צָרָעַת כִּי תִהְיֶה בְּאָדָם וְהוּבָא אֶל הַכֹּהֵן. אָמַר רִבִּי יוֹסֵי, הַאי נֶגַע, כָּל גַּוְונִין דִּילֵיהּ אִתְּעֲרוּ בְּהוּ חַבְרַיָּיא, וְכַהֲנָא הֲוָה יָדַע בְּהוּ לְדַכְיָא וּלְמְסָאֲבָא, הֲוָה יָדַע, אִינּוּן דַּהֲווֹ יִסּוּרִין דִּרְחִימוּתָא, אוֹ אִינּוּן דְּאִשְׁתְּכָחוּ בְּמַאן דְּמָאִיס בֵּיהּ מָארֵיהּ וְרָחִיק בֵּיהּ, דְּהָא לְפוּם אָרְחוֹי דְּבַּר נָשׁ גָּרִים נֶגַע בְּעָלְמָא.","כְּתִיב (תהילים קמ״א:ד׳) אַל תַּט לִבִּי לְדָבָר רָע לְהִתְעוֹלֵל עֲלִילוֹת בְּרֶשַׁע, מִכָּאן תָּנֵינָן בְּאָרְחָא דְּבַּר נָשׁ בָּעֵי לְמֵיהַךְ בָּהּ מַדְבְּרִין לֵיהּ. אָמַר רִבִּי יִצְחָק, הַאי קְרָא קַשְׁיָא, וְכִי קוּדְשָׁא בְּרִיךְ הוּא אַסְטֵי לֵיהּ לְבַר נָשׁ לְמֵהַךְ בְּאֹרַח חַטָּאָה, וּלְמֶעְבַּד עוֹבָדִין בִּישִׁין, אִי הָכִי לֵית דִּינָא בְּעָלְמָא דָּא, וְלָא בְּעָלְמָא דְּאָתֵי, וְאוֹרַיְיתָא לָא אִתְתְּקָנַת, דִּכְתִּיב בָּהּ אִם תִּשְׁמַע וְאִם לֹא תִּשְׁמַע.","אֶלָּא דָּוִד אַזְהַר לְלִבֵּיהּ, לְדַבְּרָא לֵיהּ בְּאוֹרַח קְשׁוֹט, כְּמָה דְאַתְּ אָמֵר (דברים ד׳:ל״ט) וַהֲשֵׁבוֹתָ אֶל לְבָבֶךָ. מַאי וַהֲשֵׁבוֹתָ. אֶלָּא זִמְנָא חַד, וּתְרֵין, וּתְלַת, לְאַהְדָרָא לָקֳבְלֵיהּ, וּלְדַבְּרָא, וּלְאַזְהָרָא לֵיהּ. וְהָכִי קָאָמַר לֵיהּ, אַל תַּט לִבִּי לְדָבָר רָע, לְלִבֵּיהּ קָאָמַר דָּוִד (כלומר) אַל תַּט לְפוּם אוֹרְחוֹי דְּבַּר נָשׁ (נ\"א והכי קאמר ליה, לבי, אל תט לדבר רע) דְּהָא דָּבָר רָע גָּרִים נֶגַע בְּעָלְמָא, וְדִינָא שַׁרְיָא בְּעָלְמָא, וְהַיְינוּ נֶגַע צָרַעַת.","נֶגַע צָרַעַת, הָא אִתְּעֲרוּ חַבְרַיָּיא, אֲבָל צָרַעַת כְּתַרְגּוּמוֹ, אָמַר רִבִּי יְהוּדָה, מַאי כְּתַרְגּוּמוֹ. סְגִירוּ, דְּסָגִיר וְלָא פָּתַח, וְכַד סָגִיר הוּא וְלָא פָּתַח, נֶגַע הוּא דְּאִקְּרֵי. רִבִּי יוֹסֵי אָמַר, דְּלָא מִסְתַּפְּקִין אֲבָהָן, כָּל שֶׁכֵּן בְּנִין. וְהַיְינוּ דִּכְתִּיב נֶגַע צָרַעַת כִּי תִהְיֶה בְּאָדָם, בָּאָדָם מַמָּשׁ, וּמִכָּאן נָחִית לְמַאן דְּנָחִית, אִשְׁתְּכַח נֶגַע לְכֹלָּא, מֵהַהוּא סְגִירוּ.","אָמַר רִבִּי יִצְחָק, וַדַּאי דָּא הוּא רָזָא דְּמִלָּה, דִּכְתִּיב, (איכה ב׳:ז׳) נִאֵר מִקְדָּשׁוֹ. מַאי טַעְמָא. מִשּׁוּם דִּבְנֵי עָלְמָא גָּרְמוּ הַאי, דִּכְתִּיב, (במדבר י״ט:כ׳) אֶת מִקְדַּשׁ יְיָ' טִמֵּא, טִמֵּא מַמָּשׁ. אָמַר רִבִּי אֶלְעָזָר, טִמֵּא, מִשּׁוּם דְּאִסְתַּלְקַת (שכינתא מניה) מַאן דְּאִסְתַּלָּק, וְחִוְיָא תַּקִּיפָא שַׁרְיָא, וְאָטִיל זוּהֲמָא, וְסָאִיב לְמַאן דְּסָאִיב, וְכֻלְּהוּ בְּגִין חוֹבֵי עָלְמָא.","תָּאנֵי, כַּד שָׁאֲרִי חִוְיָא (תקיפא) לְאִתְגַּלָּאָה, מִסְתַּלְּקִין סַמְכִין וּבִנְיָינִין וּמִתְעַבְּרִין, וְאָתֵי חִוְיָא תַּקִּיפָא וְאָטִיל זוּהֲמָא, וּכְדֵין אִשְׁתְּכַח מַקְדְּשָׁא מִסְאָב, מַאן מַקְדְּשָׁא. כְּמָה דְּאִתְּמַר (ויקרא י״ד:ל״ד) וְנָתַתִּי נֶגַע צָרַעַת בְּבֵית אֶרֶץ אֲחוּזָּתְכֶם. וּכְתִיב (בראשית ג׳:א׳) וְהַנָּחָשׁ הָיָה עָרוּם מִכֹּל חַיַּת הַשָּׂדֶה אֲשֶׁר עָשָׂה יְיָ' אֱלֹהִים וַיֹּאמֶר אֶל הָאִשָּׁה. אֶל הָאִשָּׁה מַמָּשׁ, דְּאֲתַר מַקְדְּשָׁא אִתְאֲחִיד בְּגַוָּוהּ, וְהַיְינוּ אֶת מִקְדַּשׁ יְיָ' טִמֵּא בְּגִין חוֹבוֹי, מִשּׁוּם דְּאִתְגַּלְיָא חִוְיָא תַּקִּיפָא.","מַאן חוֹבוֹי. דָּא לִישָׁנָא בִּישָׁא, דִּבְגִין לִישָׁנָא בִּישָׁא, חִוְיָא אִזְדָּמַן, בֵּין לְעֵילָּא בֵּין לְתַתָּא, דִּכְתִּיב, (במדבר כ״א:ו׳) וַיְשַׁלַּח יְיָ' בָּעָם אֵת הַנְּחָשִׁים הַשְּׂרָפִים. הַשׂוֹרְפִים אוֹ הַשְׂרוּפִים לָא כְּתִיב, אֶלָּא הַשְּׂרָפִים, מַאן שְׂרָפִים. דִּכְתִּיב (תהילים ע״ד:י״ג) רָאשֵׁי תַנִּינִים (תרי, חד אתאחיד לעילא, וחד לתתא) (ס\"א תרי, חד אתחזרו לזמנין) וּכְתִיב (ישעיהו ו׳:ב׳) שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ, מִמַּעַל לוֹ וַדַּאי, כְּמָה דְאַתְּ אָמֵר (איוב א) לְהִתְיַצֵּב עַל יְיָ', וּכְדֵין סְגִירוּ בְּכֹלָּא, וְלֵית מַאן דְּפָתַח, וְעַל דָּא כְּתִיב (משלי ל׳:כ׳) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת אָכְלָה וּמָחֲתָה פִיהָ וְגוֹ', מַאי מְנָאָפֶת. מְנָאָפֶת מַמָּשׁ וַדַּאי, אָכְלָה וּמָחֲתָה פִיהָ וְאָמְרָה לֹא פָעַלְתִּי אָוְן.","אָמַר רִבִּי חִיָּיא אָמַר רִבִּי יִצְחָק, בִּרְעוּתָא דְּכֹלָּא לָא אִשְׁתְּכַח לְתַתָּא, אֶלָּא בְּגִין דְּאִשְׁתְּכַח לְעֵילָּא. וּלְעֵילָּא לָא אִשְׁתְּכַח, אֶלָּא כַּד אִשְׁתְּכַח לְתַתָּא בְּחוֹבֵי עָלְמָא, דְּיַלְפֵינָן דְּכֹלָּא תַּלְיָיא הַאי בְּהַאי, וְהַאי בְּהַאי.","(ויקרא י״ג:מ׳) וְאִישׁ כִּי יִמָּרֵט רֹאשׁוֹ וְגוֹ'. רִבִּי חִיָּיא פָּתַח וְאָמַר (קהלת ב׳:י״ג) וְרָאִיתִי אָנִי שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה מִן הַסִּכְלוּת וְגוֹ', בְּכַמָּה אֲתַר אִסְתַּכַּלְנָא בְּמִלּוֹי דִּשְׁלֹמֹה מַלְכָּא, וְאָשְׁגַּחְנָא בְּחָכְמְתָא סַגִּיאָה דִּילֵיהּ, וְאַסְתִּים מִלּוֹי בְּגוֹ, לְגוֹ הֵיכָלָא קַדִּישָׁא. הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, אֲמַאי אָמַר וְרָאִיתִי אָנִי, וְכִי שְׁאָר בְּנֵי עָלְמָא לָא יַדְעֵי וְלָא חָמָאן דָּא. אֲפִילּוּ מַאן דְּלָא יָדַע חָכְמְתָא מִן יוֹמוֹי, וְלָא אַשְׁגַּח בָּהּ, יָדַע הַאי שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה מִן הַסִּכְלוּת כִּיתְרוֹן הָאוֹר מִן הַחֹשֶׁךְ. וְהוּא שָׁבַּח גַּרְמֵיהּ וְאָמַר רָאִיתִי אָנִי."],[[0,"נגע","וגו' \u0003והובא אל הכהן:\u0004 אמר ר׳ יוסי, נגע זה, כל הצבעים שלו, העירו בו החברים. והכהן היה יודע בהם לטהר ולטמא, היה יודע, אלו שהם יסורים של אהבה, או אלו שנמצאים במי שאדונו מואס בו, ורחוק ממנו. כי לפי דרכיו של האדם, נגרם הנגע בעולם."],[1,"כתיב אל תט וגו׳:","כתוב, אל תט לבי לדבר רע להתעולל עלילות ברשע. מכאן למדנו, בדרך שאדם רוצה לילך מוליכים אותו. א״ר יצחק, מקרא זה קשה, וכי הקב״ה מטה את האדם ללכת בדרך החטא, ולעשות מעשים רעים, שאומר, אל תט לבי לדבר רע, א״כ אין דין בעולם הזה ולא בעולם הבא. והתורה אינה מתוקנת, שכתוב בה, אם תשמע ואם לא תשמע. שמשמע שהכל תלוי באדם."],[2,"אלא דוד אזהר וכו׳:","ומשיב, אלא דוד הזהיר אל לבו, במה שאמר אל תט לבי לדבר רע, לנהוג אותו בדרך האמת, כש״א, והשבות אל לבבך, מהו והשבות. אלא פירושו שצריך לחזור עליו, על הלב, פעם פעמים ושלש פעמים, להנהיגו בדרך האמת, ולהזהירו. וכך אמר לו, \u0003לבי אל תט לדבר רע,\u0004 כי דבר רע גרם נגע בעולם, ודין שורה בעולם. והיינו נגע צרעת."],[3,"נגע צרעת הא וכו׳:","נגע צרעת, הרי העירו החברים, אבל צרעת, פירושו כתרגומו, א״ר יהודה, מהו כתרגומו. הוא סגירו. כי סוגר אורות העליונים ואינו פותח, וכשהוא סוגר ואינו פותח נקרא נגע. ר׳ יוסי אמר, שהאבות שהם חג״ת, אינם מתכלכלים, שאינם מקבלים אור, וכל שכן הבנים, שהם נה״י. והיינו שכתוב, נגע צרעת כי תהיה באדם, באדם ממש, דהיינו בז״א שה״ס הויה דאלפים שבגי׳ אדם. ומכאן יורד למי שיורד, דהיינו לאדם התחתון שגרם לזה, וסותם אורו, ונמצא נגע לכל, מאותו סגירת האורות."],[4,"א״ר יצחק ודאי וכו׳:","אר\"י, ודאי זה הוא סוד הדבר, שכתוב, נאר מקדשו. דהיינו שנסגרו האורות של המקדש שהוא המלכות. מהו הטעם. משום שבני העולם גרמו בעונותיהם שכתוב, את מקדש ה׳ טמא, טמא ממש. א״ר אלעזר \u0003טמא,\u0004 משום שנסתלק מי שנסתלק, דהיינו ז״א, ונחש הקשה שורה ומטיל זוהמא ומטמא מי שמטמא. והכל משום עונות העולם."],[5,"תאני כד שארי וכו׳:","למדנו כשמתחיל הנחש הקדמוני להתגלות מסתלקים הסומכים, שהם נו\"ה, ובנינים שהם המוחין, ונעברים מן המלכות, ובא הנחש התקיף ומטיל זוהמא, ואז נמצא שהמקדש נטמא. מי הוא המקדש. הוא כמו שלמדנו, ונתתי נגע צרעת בבית ארץ אחוזתכם. וכתוב, והנחש היה ערום וגו׳ ויאמר אל האשה. אל האשה ממש, שמקום המקדש מתאחד בה, שהוא המלכות. והיינו את מקדש ה׳ טמא, משום עונותיו, כי ע״י עונותיו נתגלה הנחש התקיף."],[6,"מאן חובוי דא וכו׳:","מה הם עונותיו. הם לשון הרע, שבשביל לשון הרע, מזדמן הנחש הקדמוני, בין למעלה, ובין למטה, שכתוב, וישלח ה׳ בעם את הנחשים השרפים. השורפים או השרופים אינו כתוב, אלא השרפים, מה הם שרפים. ומשיב, אלא שסובב על הנחש הקדמוני, ומה שאומר, נחשים, לשון רבים, הוא כמו שכתוב, ראשי תנינים, שנים, כי אחד נאחז למעלה, ואחד נאחז למטה בעולם הזה. וכתוב שרפים עומדים ממעל לו, ממעל לו, ודאי, דהיינו כש״א, להתיצב על ה'. שפירושו, כנגד ה', כי בני אלקים הם הדינים, וה' הוא רחמים, אף כאן, ממעל לו, הם כמו כנגד לו, ואז הוא סגירה בכל, דהיינו שנסגרו כל האורות, ואין מי שיפתח. שאז בא הנחש ומטיל זוהמא, בשורש נשמתו של החוטא אשר במלכות, שזה נבחן לניאוף וע״כ כתוב, כן דרך אשה מנאפת אכלה ומחתה פיה ואמרה לא פעלתי און. מהו מנאפת. היינו מנאפת ממש, ודאי, שעליו נאמר, אכלה ומחתה פיה ואמרה לא פעלתי און."],[7,"א״ר חייא א״ר יצחק וכו׳:","אר״ח אר״י, ברצון הכל, דהיינו ברצון העליון, אין הנחש נמצא למטה, אלא משום שנמצא למעלה. ולמעלה אינו נמצא אלא כשנמצא למטה בעונות העולם. שלמדנו, שהכל תלוי, זה בזה, וזה בזה."],[7,"","ביאור המאמר. כבר ידעת, שיש ב׳ נקודות במלכות, אחת היא נקודת המלכות דצמצום א׳ שלא נמתקה בבינה שהיא מדת הרחמים, ומבחינה זו אינה ראויה לקבל שום אור, כי כח המסך והצמצום רוכב עליה. ונקודה הב׳ היא נקודת המלכות שנמתקה במדת הרחמים, שהיא בינה. וכל האורות שהמלכות מקבלת הם מבחינת נקודה הב׳ (כנ״ל ב״א דף ז׳ ד״ה וכבר). ולפיכך נקודה הא' היא גנוזה בתוכה ורק נקודה הב' היא גלויה ושולטת בה, וע\"כ היא ראויה לקבל אורות העליונים. ומטעם זה, המלכות נקראת עץ הדעת טוב ורע. כי אם האדם זוכה, הרי \u0003טוב.\u0004 שנקודה א׳ גנוזה, ורק נקודה ב׳ שולטת, ואז יש במלכות כל טוב, והתחתון מקבל ממנה. אם לא זכה, שהוא חוטא, אז יש כח בנחש לגלות נקודה הא׳ במלכות, שלא נשתתפה בבינה, אז היא רע, כי מסתלקים ממנה כל האורות, כי נתגלה, שכח הצמצום רוכב עליה (כנ\"ל בהקדמת ספר הזהר דף קכ\"ד אות קכ״ג ולעיל ויצא י״ג ד\"ה סתרא). וזסו״ה, לפתח חטאת רובץ. שהחוטא נותן כח לסטרא אחרא להמשיך משמאל ממעלה למטה, כמו שעשה קין, אז הנחש, שנקרא חטאת, הרובץ בפתח המלכות מגלה נקודה הא׳ הגנוזה במלכות, וכל האורות מסתלקים משורש נשמתו של האדם החוטא שהיא במלכות. בסוד, לא זכי הא רע. ואח״כ הנחש מתגבר עוד ומטיל זוהמא, דהיינו שפוגם ומסלק האורות, גם מבינה דמלכות. מטעם, כי אחר שנשתתפה המלכות בבינה קבלה הבינה צורת מלכות, וע״כ אחר שנפגמה המלכות מטעם התגלות הצמצום שעליה, נפגמה גם הבינה שבמלכות, מטעם שיש לה צורת מלכות. באפן, שתחילה נפגמת רק המלכות בלבדה מכח הגילוי שהיא מלכות דמדת הדין. ואח״כ נפגמת גם הבינה דמלכות מטעם שיש לה צורת המלכות מכח השיתוף של נקודה הב'. ואומר כאן שהם ב׳ נחשים, כי מי שמגלה נקודת הצמצום א׳, שהוא פוגם רק המלכות בלבדה ולא כלום הט׳ ספירות ראשונות, אינו יכול לפגום אח״כ בבינה, אלא נחש אחר מתעורר, שהוא עולה ונאחז בבינה מחמת שיש לה צורת מלכות מכח השיתוף."],[7,"","וזה אמרו. \u0003כד שארי חויא לאתגלאה,\u0004 דהיינו שהחוטא גורם לגילוי הנחש בסו״ה לפתח חטאת רובץ, שהנחש קונה כח ע״י חטאו לגלות נקודת צמצום א׳ הגנוזה, \u0003מסתלקין סמכין ובנינין ומתעברן,\u0004 דהיינו שמסתלקים הכלים דנה״י דבינה, שיש במלכות, שבהם מקבלת המלכות כל אורותיה, וכלים דנה״י אלו קבלה מבינה, ע״י השתוף דמדת הרחמים, בסוד \u0003אמא אוזיפת לברתא מאנהא\u0004 (כנ״ל בהקסה״ז דף כ׳ ד״ה ואמא) שהכלים האלו נקראים \u0003סמכין,\u0004 וכל האורות שבכלים האלו נקראים \u0003בנינים,\u0004 והם מסתלקים עמהם, כי נתקלקל סוד השיתוף שבה מבינה, מכח גילוי נקודת המלכות דצמצום א׳ שאינה משותפת כלל בבינה. ואחר שכבר נסתלקו כל האורות מטעם גילוי נקודה הא׳ שנאחזה בה הנחש. אז, \u0003ואתי חויא תקיפא ואטיל זוהמא, וכדין אשתכח מקדשא מסאב,\u0004 דהיינו שבא נחש ב׳, ומטיל זוהמא בבינה דמלכות שנקראת מקדש, ואז נטמא המקדש. ולפיכך קורא את נחש הב׳ \u0003חויא תקיפא,\u0004 משום שעלה ונאחז שלא במקומו, דהיינו בבינה. שהיא כולה רחמים ואין בה דין כלל. אלא שיש לו כח להאחז בה, מטעם שנשתתפה במלכות כדי להמתיקה."],[7,"","וז״ש, \u0003ויאמר אל האשה, אל האשה ממש,\u0004 דהיינו המלכות המכונה אשה. וכיון \u0003דאתר מקדשא אתאחיד בגווה,\u0004 שהכלים דבינה שה״ס מקום המקדש, נכללו במלכות, מכח שיתוף המלכות בבינה כנ״ל, \u0003והיינו את מקדש ה׳ טמא,\u0004 שהנחש הטיל זוהמא בבינה דמלכות, הנקראת מקדש ה׳, שמטעם השיתוף דמלכות בבינה, קבלה הבינה צורת מלכות, והיה כח לנחש להטיל בה זוהמא, כנ״ל. \u0003בגין חובוי, משום דאתגליא חויא תקיפא,\u0004 דהיינו שנגלה נחש הב׳, שנק׳ חויא תקיפא, שהוא העולה ונאחז בבינה כנ״ל, \u0003מאן חובוי, דא לישנא בישא, דבגין לישנא בישא חויא אזדמן,\u0004 כי המדבר לשון הרע, דהיינו שמטיל פגמים על חבירו, מה שאינם בו, גורם כח לנחש הב׳ שיטיל זוהמא ויפגום הבינה דמלכות אע״פ שהיא נקיה מכל צמצום ודין. אמנם כיון שנחש הב׳ לא יוכל לפעול אלא מכח הקדם הפגם שבמלכות ע״י הנחש הא׳ ע״כ נמצא פוגם \u0003בין לעילא ובין לתתא,\u0004 הן בבינה, ע״י נחש הב׳, והן במלכות, ע״י נחש הא׳. כי כדי לתת כח לנחש הב׳, מתעורר בהכרח נחש הא׳. ומביא ראיה, שיש ב׳ נחשים, מן הכתוב, \u0003וישלח ה׳ בעם את הנחשים השרפים,\u0004 שאומר נחשים לשון רבים. \u0003דכתיב ראשי תנינים, תרי,\u0004 כיון שכתוב תנינים, שהוא לשון רבים, כי \u0003חד אתאחיד לעילא,\u0004 דהיינו בבינה דמלכות, \u0003וחד לתתא,\u0004 במלכות לבדה, כנ״ל. וע״כ אומר הנחשים השרפים לשון רבים. \u0003השורפים או השרופים לא כתיב, אלא השרפים, מאן שרפים, דכתיב שרפים עומדים ממעל לו,\u0004 (כן צ״ל, דהיינו להקדים הכתוב ראשי תנינים על הקושיא, השורפים וכו') דהיינו שאל תטעה שנחשים השרפים הם נחשים גשמיים, ע״כ נאמר שרפים, לגזירה שוה, שמלמד שרפים שרפים לגזירה שוה מן הכתוב, \u0003שרפים\u0004 עומדים ממעל לו, וע״כ נאמר כאן שרפים ולא שורפים. \u0003ממעל לו ודאי,\u0004 דהיינו כנגדו, כש״א להתיצב על ה׳, שפירושו, שבני אלקים שהם דינים נתיצבו כנגד הויה, שהוא רחמים, אף בהכתוב שרפים עומדים ממעל לו, הם כנגד ה׳ דהיינו שהם התנינים הנזכרים לעיל. ויליף שרפים שרפים לגזירה שוה, שאף הנחשים השרפים שבכאן, הם התנינים הנ״ל. וז\"ש, \u0003וכדין סגירו בכלא ולית מאן דפתח,\u0004 דהיינו שנסגרו כל האורות כי בכל מקום שנתגלתה נקודת מלכות דצמצום א׳, נסגרים כל האורות ואין מי שיפתחם. כי במלכות דצמצום א׳ אין תשובה מועילה, אלא רק במלכות דצמצום ב׳ (כנ״ל ויקרא אות רנ״ו)."],[7,"","וז״ש וע״ד כדי שתועיל תשובה כתיב, \u0003כן דרך אשה מנאפת\u0004 וגו׳ \u0003מאי מנאפת, מנאפת ממש,\u0004 כי ענין גילוי נקודת דצמצום א׳ ע״י הנחש ואחיזתו בה, המסלק את האורות דקדושה, נבחן, שהנחש הוא אשה מנאפת ממש. \u0003ודאי, אכלה ומחתה פיה ואמרה\u0004 וגו׳. פירוש. כי קשה כאן, כיון שנחש הא׳ גילה נקודת צמצום א׳ שאינה משותפת בבינה, שמחמת זה נאבד ממנה, השיתוף דמדת הרחמים, שהוא בינה. א״כ, מאחר שנתפרדה השותפות בבינה, כבר אין בבינה צורת מלכות, וא״כ איך יוכל נחש הב׳ להטיל זוהמא בבינה, מחמת שיש לה צורת מלכות. שהם תרתי דסתרי. וע״כ מביא הכתוב של, \u0003כן דרך אשה מנאפת,\u0004 שהוא הנחש הא', \u0003אכלה ומחתה פיה,\u0004 אחר שפגם במלכות ונסתלקו אורותיה מחמת קלקול השיתוף דמדת הרחמים, הוא מוחה ומקנח פיו, כמו שלא עשה דבר, ואומר, \u0003לא פעלתי און,\u0004 כדי שתשאר צורת שיתוף המלכות בבינה כמקודם קלקול הנחש, ויוכל נחש הב׳ להתאחז בבינה, מכח שיש לה צורת מלכות."],[7,"","אמנם באמת ענין עליה זו של הנחש להתאחז בבינה, הוא מוקש אל הנחש, כמ״ש לעיל (וירא אות ק״ט ואות ק״י עש״ה). כי עתה שנאחז בבינה והנחש בעצמו ביטל הפגם דמלכות דצמצום א', ונקבע הפגם של החטא בבחינת המלכות דצמצום ב', נעשתה אפשרות לבטל הפגם על ידי תשובה, כי ע״י תשובה יורדת הארה מע״ב ס״ג דא״ק, המורידה את המלכות מבינה, והבינה נטהרה מן זוהמת הנחש. משא״כ אם לא היה נאחז בבינה, אז, היה נשאר הפגם של נחש הא׳, דהיינו הגילוי של נקודת המלכות דצמצום א', שכח הצמצום רוכב על המלכות שאינה ראויה לקבל אור, ומבחינה זו לא שייכת תשובה, כי התשובה לא תבטל את הצמצום א׳ והמסך, המונע מן המלכות לקבל אור העליון. הרי שענין נחש הב' הנאחז בבינה, בכוונה ניתנה לו אחיזה זו, כדי שתועיל תשובה. והוא רק מוקש אל הנחש."],[7,"","וז״ש, \u0003ברעותא דכלא,\u0004 ברצון הכל, דהיינו ברצון עליון, \u0003לא אשתכח לתתא, אלא בגין דאשתכח לעילא,\u0004 כי כיון שנמצאת אחיזת הנחש למעלה, המכשירה את החוטא לעשות תשובה, ע״כ נמצאת אחיזת הנחש למטה, לגלות הצמצום א׳ במלכות כנ״ל, ואין פחד מה שאינו מועיל שם תשובה, והפגם ישאר לעולם. שהרי ודאי הוא שהנחש יעלה ויתאחז למעלה בבינה, והוא עצמו יבטל הפגם דצמצום א', כנ״ל, בסו״ה אכלה ומחתה פיה ואמרה לא פעלתי און. ואז תועיל תשובה. גם אין חשש, שמא לא יעלה הנחש להתאחז בבינה, כי כך הושם בטבע הנחש, להשתוקק תמיד לאחוז במקום גבוה יותר, ואם נראה לו דרך להתאחז בבינה, ודאי הוא שיתאחז בה. \u0003ולעילא לא אשתכח אלא כד אשתכח לתתא,\u0004 כי אם לא היה הנחש מגלה תחילה את הפגם דצמצום א׳ שיש במלכות, שלא לקבל אור, לא היה יכול הנחש הב' להתאחז בבינה ולפגום אותה, מחמת שיש לה צורת מלכות, בעוד שבמלכות עצמה לא נגלה הפגם. \u0003דילפינן דכלא תלייא האי בהאי, והאי בהאי,\u0004 כי אם לא היתה אחיזת הנחש למעלה. הנותנת אפשרות של תשובה ותקון הפגם, לא היו נותנים מלמעלה אפשרות, שיתאחז הנחש למטה במלכות. ואם לא היתה מקודם לכן אחיזת הנחש למטה לא יצוייר כלל אחיזת הנחש למעלה בבינה. כמבואר. הרי שזה תלוי בזה. וזה תלוי בזה."],[8,"ואיש כי ימרט ראשו וגו׳:","רבי חייא פתח ואמר, וראיתי אני שיש יתרון לחכמה מן הסכלות וגו׳. בכמה מקומות הסתכלתי בדברי שלמה המלך, והסתכלתי בחכמה הגדולה שלו, שסתם דבריו בפנים בתוך היכל הקדוש, מקרא זה יש להסתכל בו. למה אמר, \u0003וראיתי אני,\u0004 וכי שאר בני העולם אינם יודעים ואינם רואים זאת, הרי אפילו מי שלא ידע חכמה מימיו, ולא הסתכל בה, יודע זאת, שיש יתרון לחכמה מן הסכלות כיתרון האור מן החשך, והוא משבח את עצמו, ואמר, וראיתי אני."]],[[0,"","נֶגַע צָרַעַת כִּי תִהְיֶה בְּאָדָם וְהוּבָא אֶל הַכֹּהֵן. אָמַר רַבִּי יוֹסֵי, הַנֶּגַע הַזֶּה בְּכָל הַגְּוָנִים שֶׁלּוֹ הִתְעוֹרְרוּ הַחֲבֵרִים, וְהַכֹּהֵן הָיָה יוֹדֵעַ בָּהֶם לְטַהֵר וּלְטַמֵּא, הָיָה יוֹדֵעַ אוֹתָם שֶׁהָיוּ יִסּוּרִים שֶׁל אַהֲבָה, אוֹ אוֹתָם שֶׁנִּמְצְאוּ בְּמִי שֶׁמָּאַס בּוֹ רִבּוֹנוֹ וְהִרְחִיק אוֹתוֹ, שֶׁהֲרֵי לְפִי דַּרְכֵי הָאִישׁ גּוֹרֵם נֶגַע בָּעוֹלָם."],[1,"","כָּתוּב (תהלים קמא) אַל תַּט לִבִּי לְדָבָר רָע לְהִתְעוֹלֵל עֲלִלוֹת בְּרֶשַׁע. מִכָּאן שָׁנִינוּ, בְּדֶרֶךְ שֶׁבָּהּ רוֹצֶה אָדָם לָלֶכֶת, בָּהּ מַנְהִיגִים אוֹתוֹ. אָמַר רַבִּי יִצְחָק, הַפָּסוּק הַזֶּה קָשֶׁה, וְכִי הַקָּדוֹשׁ בָּרוּךְ הוּא מַסְטֶה אֶת הָאָדָם לָלֶכֶת בְּדֶרֶךְ שֶׁל חֵטְא וְלַעֲשׂוֹת מַעֲשִׂים רָעִים? אִם כָּךְ, אֵין דִּין בְּזֶה הָעוֹלָם וְלֹא בָּעוֹלָם הַבָּא, וְהַתּוֹרָה לֹא מְתֻקֶּנֶת, שֶׁכָּתוּב בָּהּ אִם תִּשְׁמַע וְאִם לֹא תִשְׁמַע!"],[2,"","אֶלָּא דָּוִד הִזְהִיר אֶת לִבּוֹ לְהַנְהִיגוֹ בְּדֶרֶךְ אֱמֶת, כְּמוֹ שֶׁנֶּאֱמַר (דברים ד) וַהֲשֵׁבתָ אֶל לְבָבֶךְ. מַה זֶּה וַהֲשֵׁבֹתָ? אֶלָּא פַּעַם אַחַת וּפַעֲמַיִם וְשָׁלֹשׁ לַחֲזֹר כְּנֶגְדּוֹ, וּלְהוֹלִיךְ וּלְהַזְהִיר אוֹתוֹ. וְכָךְ אָמַר לוֹ: אַל תַּט לִבִּי לְדָבָר רָע. לְלִבּוֹ אָמַר דָּוִד, (כלומר) אַל תַּטֶּה לְפִי דַרְכֵי הָאָדָם (וכך אמר לו', לבי, אל תט לדבר רע. שהרי דבר) רָע גּוֹרֵם נֶגַע בָּעוֹלָם, וְהַדִּין שׁוֹרֶה בָעוֹלָם, וְהַיְנוּ נֶגַע צָרַעַת."],[3,"","נֶגַע צָרַעַת, הִנֵּה הִתְעוֹרְרוּ הַחֲבֵרִים, אֲבָל צָרַעַת כְּתַרְגּוּמוֹ. אָמַר רַבִּי יְהוּדָה, מַה זֶּה כְּתַרְגּוּמוֹ? הַסְגָּרָה, שֶׁסּוֹגֵר וְלֹא פוֹתֵחַ. וּכְשֶׁהוּא סוֹגֵר וְלֹא פוֹתֵחַ, הוּא נִקְרָא נֶגַע. רַבִּי יוֹסֵי אָמַר, שֶׁאֵין הָאָבוֹת נֶהֱנִים, כָּל שֶׁכֵּן הַבָּנִים, וְהַיְנוּ שֶׁכָּתוּב נֶגַע צָרַעַת כִּי תִהְיֶה בְּאָדָם, בָּאָדָם מַמָּשׁ, וּמִכָּאן יוֹרֵד לְמִי שֶׁיּוֹרֵד. נִמְצָא נֶגַע לַכֹּל מֵאוֹתָהּ הַהַסְגָּרָה."],[4,"","אָמַר רַבִּי יִצְחָק, וַדַּאי זֶהוּ סוֹד הַדָּבָר, שֶׁכָּתוּב (איכה ב) נִאֵר מִקְדָּשׁוֹ. מָה הַטַּעַם? מִשּׁוּם שֶׁבְּנֵי הָעוֹלָם גָּרְמוּ אֶת זֶה, שֶׁכָּתוּב (במדבריט) אֶת מִקְדַּשׁ ה' טִמֵּא, טִמֵּא מַמָּשׁ. אָמַר רַבִּי אֶלְעָזָר, טִמֵּא, מִשּׁוּם שֶׁהִסְתַּלְּקָה (השכינה ממנו) מִי שֶׁהִסְתַּלְּקָה, וְהַנָּחָשׁ הַתַּקִּיף שָׁרוּי וּמַטִּיל זֻהֲמָא, וּמְטַמֵּא אֶת מִי שֶׁמְּטַמֵּא, וְכֻלָּם מִשּׁוּם חֲטָאֵי הָעוֹלָם."],[5,"","לָמַדְנוּ, כְּשֶׁמַּתְחִיל הַנָּחָשׁ (החזק) לְהִתְגַּלּוֹת, מִסְתַּלְּקִים הַבִּנְיָנִים וְהָעַמּוּדִים וְעוֹבְרִים, וּבָא הַנָּחָשׁ הַתַּקִּיף וּמַטִּיל זֻהֲמָא, וְאָז נִמְצָא הַמִּקְדָּשׁ טָמֵא. מִי הַמִּקְדָּשׁ? כְּמוֹ שֶׁנֶּאֱמַר וְנָתַתִּי נֶגַע צָרַעַת בְּבֵית אֶרֶץ אֲחֻזַּתְכֶם. וְכָתוּב (בראשית ג) וְהַנָּחָשׁ הָיָה עָרוּם מִכֹּל חַיַּת הַשָּׂדֶה אֲשֶׁר עָשָׂה ה' אֱלֹהִים וַיֹּאמֶר אֶל הָאִשָּׁה. אֶל הָאִשָּׁה מַמָּשׁ, שֶׁמְּקוֹם הַמִּקְדָּשׁ נֶאֱחָז בְּתוֹכָהּ, וְהַיְנוּ אֶת מִקְדַּשׁ ה' טִמֵּא, מִשּׁוּם חֶטְאוֹ, מִשּׁוּם שֶׁהִתְגַּלָּה הַנָּחָשׁ הַתַּקִּיף."],[6,"","מַה חֶטְאוֹ? זֶה לָשׁוֹן הָרָע, שֶׁבִּגְלַל לָשׁוֹן הָרָע הַנָּחָשׁ מִזְדַּמֵּן, בֵּין לְמַעְלָה בֵּין לְמַטָּה, שֶׁכָּתוּב (במדבר כא) וַיְשַׁלַּח ה' בָּעָם אֵת הַנְּחָשִׁים הַשְּׂרָפִים. הַשּׂוֹרְפִים אוֹ הַשְּׂרוּפִים לֹא כָתוּב, אֶלָּא הַשְּׂרָפִים. מִי הַשְּׂרָפִים? שֶׁכָּתוּב (תהלים עד) רָאשֵׁי תַנִּינִים, (שנים. אחד נאחז למעלה ואחד למטה) (שנים, אחד חוזרים לפעמים) וְכָתוּב (ישעיה ו) שְׂרָפִים עֹמְדִים מִמַּעַל לוֹ, מִמַּעַל לוֹ וַדַּאי, כְּמוֹ שֶׁנֶּאֱמַר (איוב א) לְהִתְיַצֵּב עַל ה', וְאָז הַסְגָּרָה בַּכֹּל, וְאֵין מִי שֶׁפּוֹתֵחַ. וְעַל זֶה כָּתוּב, (משלי ל) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת אָכְלָה וּמָחֲתָה פִיהָ וְגוֹ'. מַה זֶּה מְנָאָפֶת? מְנָאֶפֶת מַמָּשׁ וַדַּאי, אָכְלָה וּמָחֲתָה פִיהָ וְאָמְרָה לֹא פָעַלְתִּי אָוֶן."],[7,"","אָמַר רַבִּי חִיָּיא אָמַר רַבִּי יִצְחָק, בָּרָצוֹן שֶׁל הַכֹּל לֹא נִמְצָא לְמַטָּה, אֶלָּא מִשּׁוּם שֶׁנִּמְצָא לְמַעְלָה. וּלְמַעְלָה לֹא נִמְצָא, אֶלָּא כְּשֶׁנִּמְצָא לְמַטָּה בַּחֲטָאֵי הָעוֹלָם, שֶׁלָּמַדְנוּ שֶׁהַכֹּל תָּלוּי זֶה בָּזֶה, וְזֶה בָּזֶה."],[8,"","וְאִישׁ כִּי יִמָּרֵט רֹאשׁוֹ וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (קהלת ב) וְרָאִיתִי אָנִי שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה מִן הַסִּכְלוּת וְגוֹ'. בְּכַמָּה מְקוֹמוֹת הִסְתַּכַּלְתִּי בְּדִבְרֵי שְׁלֹמֹה הַמֶּלֶךְ וְהִשְׁגַּחְתִּי בַחָכְמָה הָרַבָּה שֶׁלּוֹ, וְהִסְתִּיר דְּבָרָיו בְּתוֹכוֹ, לְתוֹךְ הַהֵיכָל הַקָּדוֹשׁ. בְּפָסוּק זֶה יֵשׁ לְהִסְתַּכֵּל, לָמָּה אָמַר וְרָאִיתִי אָנִי? וְכִי שְׁאָר בְּנֵי הָעוֹלָם לֹא יוֹדְעִים וְלֹא רוֹאִים אֶת זֶה? אֲפִלּוּ מִי שֶׁלֹּא יוֹדֵעַ חָכְמָה מִיָּמָיו וְלֹא הִשְׁגִּיחַ בָּהּ, יוֹדֵעַ אֶת זֶה שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה מִן הַסִּכְלוּת כִּיתְרוֹן הָאוֹר מִן הַחֹשֶׁךְ, וְהוּא מְשַׁבֵּחַ אֶת עַצְמוֹ וְאוֹמֵר רָאִיתִי אָנִי?"]]],[["אֶלָּא הָכִי תָּאנָא, מַאן חַכִּים כִּשְׁלֹמֹה דִּבְשִׁבְעָה דַּרְגִּין דְּחָכְמָה אִתְקְרֵי כְּגַוְונָא דִּלְעֵילָּא. שִׁיתָא יוֹמִין לְעֵילָּא, שְׁבִיעָאָה עִלָּאָה עָלַיְיהוּ. שִׁיתָא יוֹמִין לְתַתָּא, שְׁבִיעָאָה עָלַיְיהוּ. שִׁיתָא דַּרְגִּין לְכוּרְסְיָיא, הוּא עַל כּוּרְסְיָיא, דִּכְתִּיב, (דברי הימים א כ״ט:כ״ג) וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא יְיָ' לְמֶלֶךְ. שִׁבְעָה כִּתְרִין דְּיוֹמִין לְעֵילָּא, וּכְדֵין לָקֳבְלֵיהוֹן שִׁבְעָה שְׁמָהָן לִשְׁלֹמֹה. לְאִתְחֲזָאָה בֵּיהּ חָכְמְתָא קַדִּישָׁא. וּבְגִין כָּךְ אִתְקְרֵי שֶׁבַע שְׁמָהָן: שְׁלֹמֹה. יְדִידְיָה. אָגוּר. בֶּן יָקֶה. לְמוּאֵל, אִיתִיאֵל, קֹהֶלֶת.","וְאָמַר שִׁבְעָה הֲבָלִים. וּמַה דְּאִיהוּ חָמָא לָא חָמָא בַּר נָשׁ אָחֳרָא, וְכַד כָּנַשׁ חָכְמְתָא וְאִסְתַּלָּק בְּדַרְגִּין דְּחָכְמְתָא, אִקְרֵי קֹהֶלֶת. וְשִׁבְעָה הֲבָלִין אָמַר, לָקֳבֵיל ז' כִּתְרִין דִּלְעֵילָּא, וְכָל הֶבֶל קָלָא אִתְעָבִיד מִנֵּיהּ, וְעָלְמָא לָא מִתְקַיְּימָא אֶלָּא בַּהֶבֶל.","וְתָאנָא מִשְּׁמֵיהּ דְּרַבִּי שִׁמְעוֹן, הֶבֶל אַפִּיק קָלָא בְּרוּחָא וּמַיָא דְּבֵיהּ, וְלֵית קָלָא אֶלָּא בַּהֶבֶל. וְתָאנָא בְּשִׁבְעָה הֲבָלִין אִתְקַיְּימִין עִלָּאִין וְתַתָּאִין. וְתָאנֵי רִבִּי יִצְחָק, תָּא חֲזֵי, דְּעַל הֶבֶל מִתְקַיֵּים עָלְמָא, דְּאִלְמָלֵא לָא הֲוָה הֲבָל דְּנָפִיק מִפּוּמָא, לָא אִתְקַיָּים בַּר נָשׁ אֲפִילּוּ שַׁעֲתָא חֲדָא.","כְּגַוְונָא דָּא אָמַר שְׁלֹמֹה מִלּוֹי, דְּעָלְמָא מִתְקַיְּימָא בְּהוּ, דְּהַאי הֶבֶל דְּמִתְקַיֵים בֵּיהּ עָלְמָא. וְהַאי הֶבֶל דְּמִתְקַיֵים בֵּיהּ עָלְמָא, מֵהֲבָלִים דִּלְעֵילָּא קָאֲתֵי, הֲדָא הוּא דִכְתִיב הֲבֵל הֲבָלִים, הֲבֵל מֵהֲבָלִים דִּלְעֵילָּא. וְכָל מִלּוֹי הָכִי הֲווֹ. וּבַהֲבָלִים דִּלְעֵילָּא כְּתִיב, (דברים ח׳:ג׳) כִּי עַל כָּל מוֹצָא פִי יְיָ' יִחְיֶה הָאָדָם. מַאי מוֹצָא פִי יְיָ'. דָּא הֲבָלִים דִּלְעֵילָּא.","וְתַנְיָא, וְרָאִיתִי אָנִי שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה מִן הַסִּכְלוּת. מִן הַסִּכְלוּת מַמָּשׁ, אָתֵי תּוֹעַלְתָּא לְחָכְמְתָא, דְּאִלְמָלֵא לָא אִשְׁתְּכַח שְׁטוּתָא בְּעָלְמָא, לָא אִשְׁתְּמוֹדְעָא חָכְמְתָא וּמִלּוֹי. (תיקון קכ\"ג ע\"א) וְתָאנָא חִיּוּבָא הוּא עַל בַּר נָשׁ דְּאוֹלִיף חָכְמְתָא, לְמֵילַף זְעֵיר מִן שְׁטוּתָא, וּלְמִנְדַּע לָהּ. בְּגִין דְּאָתֵי תּוֹעַלְתָּא לְחָכְמְתָא בְּגִינֵיהּ. כְּמָה דְּאַתְיָא תּוֹעַלְתָּא לִנְהוֹרָא מֵחֲשׁוֹכָא, דְּאִלְמָלֵא חֲשׁוֹכָא לָא אִשְׁתְּמוֹדַע נְהוֹרָא. וְלָא אַתְיָיא (נ\"א אתחזיא) תּוֹעַלְתָּא לְעָלְמָא מִנֵּיהּ.","תָּנָא שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה, לַחָכְמָה סְתָם. דְּאָמַר רִבִּי שִׁמְעוֹן לְרִבִּי אַבָּא, תָּא חֲזֵי רָזָא דְּמִלָּה, לָא נָהִיר חָכְמְתָא דִּלְעֵילָּא, וְלָא אִתְנְהִיר, אֶלָּא בְּגִין שְׁטוּתָא דְּאִתְּעַר מֵאֲתַר אָחֳרָא, וְאִלְמָלֵא הַאי, נְהִירוּ וּרְבוּ סַגִיא וְיַתִּיר לָא הֲוָה (להוי), וְלָא אִתְחַזְיָא תּוֹעַלְתָּא דְּחָכְמְתָא. וּבְגִין שְׁטוּתָא אִתְנְהִיר יַתִּיר, וּנְהִירִין לֵיהּ יַתִּיר, הֲדָא הוּא דִכְתִיב שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה, לַחָכְמָה סְתָם, מִן הַסִּכְלוּת סְתָם. וְכַךְ לְתַתָּא, אִלְמָלֵא לָא הֲוָה שְׁטוּתָא שְׁכִיחַ בְּעָלְמָא, לָא הֲוִי חָכְמְתָא שְׁכִיחַ בְּעָלְמָא.","וְהַיְינוּ דְּרַב הַמְנוּנָא סָבָא, כַּד הֲווֹ יַלְפִין מִנֵּיהּ חַבְרַיָּיא רָזֵי דְּחָכְמְתָא, הֲוָה מְסַדֵּר קָמַיְיהוּ פִּרְקָא דְּמִלֵּי דִּשְׁטוּתָא, בְּגִין דְּיֵיתֵי תּוֹעַלְתָּא לְחָכְמְתָא בְּגִינֵיהּ. הֲדָא הוּא דִכְתִיב (קהלת י׳:א׳) יָקָר מֵחָכְמָה וּמִכָּבוֹד סִכְלוּת מְעַט, מִשּׁוּם דְּהִיא תִּקּוּנָא דְּחָכְמְתָא, וִיקָרָא דְּחָכְמְתָא. וְעַל דָּא כְּתִיב, וְלִבִּי נוֹהֵג בַּחָכְמָה וְלֶאֱחוֹז בְּסִכְלוּת.","רִבִּי יוֹסֵי אָמַר יָקָר מֵחָכְמָה וּמִכָּבוֹד, כְּלוֹמַר יְקָרָא דְּחָכְמְתָא וְנוֹי דִּילָהּ, וִיקָרָא דְּכָבוֹד דִּלְעֵילָּא, מַאי הִיא. סִכְלוּת מְעַט. זְעֵיר דִּשְׁטוּתָא אַחְזֵי וְגַלֵּי יְקָרָא דְּחָכְמְתָא וְכָבוֹד דִּלְעֵילָּא, יַתִּיר מִכָּל אָרְחִין דְּעָלְמָא.","כְּיִתְרוֹן הָאוֹר מִן הַחֹשֶׁךְ, תּוֹעַלְתָּא דִּנְהוֹרָא לָא אַתְיָיא (נ\"א אתחזיא) אֶלָּא מִן חֲשׁוֹכָא. (ולעולם) תִּקּוּנָא דְּחִוָּורָא מַאי הִיא. אוּכָמָא, אִלְמָלֵא אוּכָמָא לָא אִשְׁתְּמוֹדַע חִוָּורָא, וּבְגִין אוּכָמָא, אִסְתָּלִיק חִוָּורָא וְאִתְיָקָר. אָמַר רִבִּי יִצְחָק, מָשָׁל לְמָתוֹק בְּמַר, דְּלָא יָדַע אֱינָשׁ טַעֲמָא דִּמְתִיקָא, עַד דְּטָעִים מְרִירָא, מַאן עָבִיד לְהַאי מְתִיקָא. הֶוִי אוֹמֵר הַאי מְרִירָא. וְהַיְינוּ דִּכְתִּיב, (קהלת ז׳:י״ד) גַּם אֶת זֶה לְעוּמַּת זֶה עָשָׂה הָאֱלֹהִים. וּכְתִיב (קהלת ז׳:י״ח) טוֹב אֲשֶׁר תֶּאֱחוֹז בָּזֶה וְגַם מִזֶּה אַל תָּנַּח יָדֶךָ."],[[0,"אלא הכי תאנא וכו׳:","אלא כך למדנו מי חכם כשלמה, שבשבעה מדרגות של חכמה הוא יקרא, כעין של מעלה, דהיינו כנגד חג״ת נהי״מ דמלמת שה״ס חכמה תתאה, שהיא מדרגת שלמה. כי ששה ימים למעלה, חג\"ת נה\"י דז״א, ושביעי עליון עליהם שהוא בינה. ששה ימים למטה במלכות, חג״ת נה״י, ושביעי עליהם, שהוא בינה. שש מדרגות לכסא של שלמה, והוא על הכסא, שכתוב, וישב שלמה על כסא ה׳ למלך. שבעה כתרים, של ימים, דהיינו ז׳ ספירות חג״ת נה״ימ יש למעלה, וכן כנגדם ז׳ שמות לשלמה, כנ״ל, להראות בהם חכמה הקדושה, ומשום זה נקרא שבעה שמות, שהם, שלמה ידידיה, אגור, בן יקא, למואל, איתיאל, קהלת."],[1,"ואמר שבעה הבלים וכו׳:","ואמר ז׳ הבלים, דהיינו הבל הבלים אמר קהלת הבל הבלים הכל הבל, שיש כאן ג׳ פעמים הבל, וב׳ פעמים הבלים שהם ארבעה. וביחד הם ז'. ומה שהוא ראה לא ראה אדם אחר, וכשאסף החכמה ונתעלה במדרגת החכמה נקרא קהלת. וז׳ הבלים אמר, כנגד ז׳ ספירות שלמעלה, וכל הבל נעשה ממנו קול, והעולם אינו מתקיים אלא בהבל. פי׳ ז' הבלים ה״ס ז״ס תחתונות דישסו״ת, ועיקרם הוא קו השמאל דישסו״ת, שמטרם ההכרעה מקו האמצעי המיחד ימין ושמאל, נבחן הארת השמאל להבל וחלי רע, ורעות רוח. ואחר היחוד ע״י קו האמצעי, ה״ס ז׳ הבלים שמהם נאצל ז״א הנקרא קול (כנ״ל ויצא אות ט״ו בהסולם, ובפרשת בא אות קמ״ד עש״ה) ושמהם מתקיים העולם."],[2,"ותאנא משמיה דר״ש וכו׳:","ולמדנו בשמו של ר׳ שמעון, כי הבל שהוא קו שמאל, כנ״ל בסמוך, מוציא קול, ברוח ומים שבו, דהיינו בהתכללות קו ימין הנקרא מים, וקו אמצעי הנקרא רוח. ואין קול אלא בהבל, ולמדנו שבז' הבלים, שהם חג״ת נהי״מ דישסו״ת, מתקיימים העליונים שהם זו\"ן, ותחתונים, שהם דרי בי״ע. ולמד ר׳ יצחק, בוא וראה שעל הבל מתקיים העולם, כי אם לא היה הכל יוצא מפיו של אדם, לא היה יכול להתקיים אפילו שעה אחת."],[3,"כגוונא דא אמר וכו׳:","כעין זה, שהאדם אינו יכול להתקיים בלי הבל פיו, אמר שלמה, דבריו שהעולם מתקיים בהם, ואמר, שעל ידי הבל הזה מתקיים העולם. והבל הזה שמתקיים בו העולם בא מהבלים שלמעלה. ז\"ש הבל הבלים. דהיינו הבל מהבלים שלמעלה. וכל דבריו כך היה. ובהבלים שלמעלה כתוב, כי על כל מוצא פי ה׳ יהיה האדם. מהו, מוצא פי ה', זה הוא הבלים של מעלה. דהיינו ז״ס תחתונות דישסו״ת (כנ״ל באות צ״ז)."],[4,"ותניא וראיתי אני וכו׳:","ולמדנו, וראיתי אני שיש יתרון לחכמה מן הסכלות. מן הסכלות ממש באה תועלת לחכמה. כי אם לא היה נמצאת שטות בעולם, לא היה נודעת חכמה ודבריה. ולמדנו חוב הוא על האדם שלמד חכמה שילמוד מעט מן שטות ולדעת אותה, משום שבא תועלת לחכמה בשבילה, כמו שיש תועלת אל האור מן החשך, שלולא החשך לא היה נודע האור ולא בא לעולם תועלת ממנה."],[5,"תאנא שיש יתרון וגו׳:","למדנו, \u0003שיש יתרון לחכמה,\u0004 היינו חכמה סתם, שכולל הן חכמה עליונה, והן חכמה שבעולם הזה. כי אמר, ר׳ שמעון לר׳ אבא, בוא וראה סוד הדבר, החכמה שלמעלה אינה מאירה ואינה מוארת, אלא בשביל שטות שנתעורר ממקום אחר, ולולא שטות הזו, לא היה האור והגאות הגדולה והיתרה, ולא היה נראה תועלת החכמה, ומשום השטות האירה החכמה יותר ומאירים לה יותר, ז״ש, \u0003שיש יתרון לחכמה.\u0004 לחכמה סתם, בין למעלה ובין למטה, מן הסכלות סתם, בין למעלה ובין למטה. כי כך הוא למטה, אם לא היתה נמצאת שטות בעולם, לא היתה נמצאת חכמה בעולם."],[6,"והיינו דרב המנונא וכו׳:","והיינו, שרב המנונא סבא, כשלמדו ממנו החברים סודות החכמה, היה מסדר לפניהם פרקים של דברי שטות, כדי שתבא תועלת לחכמה בשבילם, ז״ש, יקר מחכמה ומכבוד סכלות מעט. משום שהסכלות היא תקון החכמה, ויקר החכמה וע״כ כתוב, ולבי נוהג בחכמה ולאחוז בסכלות."],[7,"ר' יוסי אמר וכו׳:","רי״א, יקר מחכמה ומכבוד, כלומר, היקר של החכמה והיופי שלה, ויקר הכבוד של מעלה, שהוא המלכות, מה היא. הוא סכלות מעט, כי מעט סכלות מראה ומגלה יקר החכמה והכבוד של מעלה, יותר מכל דרכי העולם."],[8,"כיתרון האור מתוך החשך:","כי תועלת האור אינה באה אלא מתוך החשך. תקון הלבן מה הוא. שחור, כי לולא השחור לא היה מושג הלבן, ומשום שיש שחור, מתעלה הלבן ומתכבד. א״ר יצחק משל למתוק ומר, שאין איש יודע טעם מתיקות, מטרם שטועם טעם מר. מי עושה לזה שיהיה טעמו מתוק, הוי אומר זה המר. כי הדברים שיש ביניהם יחס הפיכות, הרי האחד מגלה את חברו, שכן בלבן ושחור, ובאור וחשך, ובחולה ובריא, כי אם לא היה חולה בעולם לא היה שום מושג להשם בריא. וכו׳ עד״ז. והיינו שכתוכ גם את זה לעומת זה עשה האלקים. וכתוב, טוב אשר תאחז בזה וגם מזה אל תנח ידך."],[8,"","ביאור המאמר. כי הקשה (באות צ״ו) מה משמיענו בזה שלמה המלך, בהכתוב, וראיתי אני שיש יתרון לחכמה על הסכלות כיתרון האור מן החשך, כי מי אינו יודע זה. וכדי לתרץ זה הביא ביאור ז׳ הבלים שאמר בקהלת. שיש בהבל ב׳ בחינות, א׳ בהיותו בבחינת קו שמאל בלי יחוד עם הימין, ואע״פ שאז מאיר בו ג״ר דחכמה, מ״מ נבחן הבל הזה, להבל וחולי רע, להבל ורעות רוח. כי בהיותו נפרד לעצמו בלי ימין, הרי הוא חכמה בלי חסדים, שאז הוא חשך ולא אור, ולא עוד אלא שנמשכים משם דינים קשים. וע״כ נבחן להבל וחלי רע. בחינה ב׳ הוא בהיותו מיוחד עם הימין ע״י קו האמצעי, המכריע בין ימין ושמאל, שהימין שהוא חסדים, יאיר ממעלה למטה, והשמאל שהוא חכמה, יאיר ממטה למעלה (כנ״ל ב״א דף ס׳ ד״ה מחלוקת) שהוא ו״ק דחכמה, שאז מתלבשת החכמה דשמאל בחסדים שבימין. והנה מכאן יוצאים כל המוחין דזו״ן ובי״ע, וכל העולמות מתקיימים מן הבל הזה. (כמ״ש ר״ש באות צ״ט) \u0003הבל,\u0004 שהוא שמאל, \u0003אפיק קלא,\u0004 שהוא מוחין דז\"א, \u0003ברוחא ומיא,\u0004 דהיינו בהתכללותו בקו אמצעי שהוא רוח, ובקו ימין שהוא מים. \u0003ותאנא, בז׳ הבלים,\u0004 שהם ז״ס דישסו״ת, שכל אחת כלולה מהבל ורוח ומים, \u0003אתקיימין עלאין ותתאין,\u0004 כי כל המוחין של העליונים שהם זו״ן, והתחתונים שהם בג׳ עולמות בי״ע יוצאים מהבלים האלו. ונתבאר מזה, שאע״פ שבהיות הקו שמאל לבדו יש לו ג״ר דג״ר, אינו מאיר אז כלום, אלא להיפך, שהוא הבל וחלי רע. ובשעה שמתיחד עם הימין, אע״פ שנתמעט מחמת זה לו״ק דחכמה, והוא מחוסר ג״ר דחכמה, הנה כל העולמות מתקיימים ממנו. עי׳ לעיל כל ההמשך."],[8,"","וז\"ש, וראיתי אני שיש יתרון לחכמה על הסכלות כיתרון האור מתוך החשך. ובג׳ דברים דומים החכמה והסכלות, לאור וחשך. א) כמו שאם לא היה חשך לא היה שום יתרון בהאור, ולא היה מושג כלל לכנהו בשם זה. כך לולא הסכלות, לא היה שום יתרון בחכמה, שנכנהו בשם זה, אלא להיפך, שהיינו קוראים אותו, הבל וחלי רע. ב) שאע״פ, שבלי החשך לא היה לנו שום מושג באור, אין זה אומר, שהאור לא היה בלעדו מציאות ממשי, אלא שלא היה לנו למושג בפני עצמו, לגדרהו בשם, כך החכמה אע״פ שבלי הסכלות לא היתה מושגת, אין זה אומר שלא היתה אז מציאות החכמה כל עיקר, אלא אדרבה, שאז החכמה נמצאת, כשהיא בלי סכלות לגמרי, כי אז מאירים הג״ר דחכמה, כמ״ש לפנינו, אלא לא היתה אז מושגת להגדרה בשם חכמה. ג) כמו שבמקום שאין אור, שם הוא חשך, כן במקום שאין חכמה, שם הוא סכלות."],[8,"","ובזה יובן לנו כל המאמר. כי הבאנו לעיל שמטרם שקו שמאל נתיחד בימין, יש לו ג״ר דחכמה, אלא שאינם מאירים, והם בבחינת הבל וחולי רע. ורק אח״כ שנכלל עם קו ימין ע״י קו האמצעי, הוא נשלם, וכל המוחין שבעולמות נמשכים ממנו, אלא שאובד הג״ר דחכמה, מחמת הכרעת קו האמצעי, שהימין יאיר מלמעלה למטה, והשמאל, שהוא חכמה יאיר ממטה למעלה, שההארה שממטה למעלה היא הארת ו״ק דחכמה. והיא מחוסרת ג״ר. ונתבאר לעיל בהשואה הג׳ מחכמה לאור, אשר במקום שחסר חכמה שם יש סכלות, כמו במקום שחסר האור שיש שם חשך. נמצא עתה אחר יחוד קו שמאל עם הימין שיש בשמאל סכלות, דהיינו במקום חסרון הג״ר. ונמצא שמקודם יחודו עם הימין. אע״פ שלא היה מאיר, מ״מ מציאות החכמה שהיתה אז בקו שמאל, כנ״ל בהשואה ב׳, היתה במציאות הזו בלי שום סכלות, כי אז היה הקו שמאל בג״ר דחכמה. משא״כ עתה, שחסר ג״ר דחכמה, הרי יש כנגד זה סכלות. והבן היטב."],[8,"","וז״ש (באות ק״א) \u0003מן הסכלות ממש אתי תועלתא לחכמתא, דאלמלא לא אשתכח שטותא בעלמא, לא אשתמודעא חכמתא ומלוי,\u0004 כי חסרון ג״ר דחכמה שנעשה אחר יחוד ימין ושמאל, נבחן לסכלות, אמנם מן הסכלות הזאת נתגלתה הארת החכמה אל העולמות, כי מקודם היחוד, שהיתה בלי סכלות, היתה החכמה חשך ולא היתה מאירה, אבל עתה מאירה החכמה בכל השלמות מחמת הסכלות, דהיינו מחמת שנתמעטה מג״ר, ויכולה להתיחד עם החסדים שבימין, הרי שהסכלות, שהיא חסרון הג״ר, מגלה את הו״ק דחכמה שתאיר בכל השלמות. ואם לא היתה נמצאת הסכלות, לא היתה נמצאת החכמה."],[8,"","וז\"ש (באות ק״ב) \u0003רזא דמלה לא נהיר חכמתא דלעילא ולא אתנהיר, אלא בגין שטותא דאתער מאתר אחרא.\u0004 כי אם לא נתעוררה הסכלות ממקום אחר, דהיינו ממיעוט הג״ר, אלא שהיו נשארות ג״ר דחכמה בקו שמאל, ולא היה מתיחד עם הימין, הרי אז אין החכמה מאירה, והיא חשך. וז\"ש, \u0003ואלמלא האי, נהירו ורבו סגיא ויתיר לא הוה, ולא אתחזיא תועלתא דחכמתא\u0004 שלא היו מתגלים כל אלו המוחין הגדולים אל העולמות. וז\"ש \u0003חיובא על בר נש דאוליף חכמתא,\u0004 כלומר שחוב הוא על האדם הממשיך חכמה עליונה, \u0003למילף זעיר מן שטותא ולמנדע לה.\u0004 דהיינו שימשוך ידו להמשיך מג״ר וחכמה, ואע״פ שמתגלה סכלות במקום חסרון החכמה, הנה כנגד זה, נמצא לומד החכמה מן הסכלות הזאת, כלומר שהחכמה שמשיג הוא מכח הסכלות הזה שאינו נוגע בו, כנ\"ל, וע״כ אינו נחשב לסכלות ממש, אלא \u0003לזעיר מן שטותא,\u0004 המספיק ללמוד ולדעת החכמה המאירה. וז״ש, \u0003והיינו דרב המנונא סבא, כד הוו ילפין מניה חבריא רזי דחכמתא,\u0004 דהיינו שהיו לומדים ממנו איך להמשיך החכמה המאירה, \u0003הוה מסדר קמייהו פרקא דמלי דשטותא, בגין דייתי תועלתא לחכמתא בגיניה,\u0004 שהיה מסדר להם, שלא ימשיכו החכמה בפרקי ג״ר דחכמה, אשר הסכלות מתגלה אז בפרקים ההם, ולימד אותם שמסכלות הזה יבא תועלת לחכמה המאירה. כנ״ל. \u0003הה״ד יקר מחכמה ומכבוד סכלות מעט.\u0004 כי כל עוד שהאירו הג״ר דחכמה, ולא היתה סכלות מעט, הרי היתה החכמה בבחי׳ הבל ורעות רוח, בלי חכמה ובלי כבוד, ועתה אחר שנתיחד השמאל עם הימין, אע\"פ שיש סכלות מעט מחמת חסרון ג\"ר דחכמה, הנה בשביל זה היא מאירה ברוב פאר והדר, שהמשיגה זוכה לחכמה וכבוד. \u0003וע״ד כתיב, ולבי נוהג בחכמה,\u0004 היינו בו״ק דחכמה. \u0003ולאחוז בסכלות,\u0004 היינו שלא להמשיך הג״ר דחכמה. וז״ש, \u0003טוב אשר תאחוז בזה,\u0004 דהיינו בחכמה, \u0003וגם מזה אל תנח ידך,\u0004 שתאחוז גם בסכלות של חסרון הג״ר דחכמה."]],[[0,"","אֶלָּא כָּךְ לָמַדְנוּ, מִי חָכָם כְּמוֹ שְׁלֹמֹה, שֶׁבְּשֶׁבַע דְּרָגוֹת שֶׁל חָכְמָה נִקְרָא כְּמוֹ שֶׁלְּמַעְלָה. שִׁשָּׁה יָמִים לְמַעְלָה, שְׁבִיעִי עֶלְיוֹן עֲלֵיהֶם. שִׁשָּׁה יָמִים לְמַטָּה, שְׁבִיעִי עֲלֵיהֶם. שֵׁשׁ דְּרָגוֹת לַכִּסֵּא, הוּא עַל הַכִּסֵּא, שֶׁכָּתוּב וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא ה' לְמֶלֶךְ. שִׁבְעָה כְתָרִים שֶׁל יָמִים לְמַעְלָה, וְאָז כְּנֶגְדָּם שִׁבְעָה שֵׁמוֹת לִשְׁלֹמֹה, לְהַרְאוֹת בּוֹ הַחָכְמָה הַקְּדוֹשָׁה. וּמִשּׁוּם כָּךְ נִקְרָא שִׁבְעָה שֵׁמוֹת: שְׁלֹמֹה. יְדִידְיָה. אָגוּר. בֶּן יָקֶה. לְמוּאֵל. אִיתִיאֵל. קֹהֶלֶת."],[1,"","וְאָמַר שִׁבְעָה הֲבָלִים. וּמַה שֶּׁהוּא רָאָה לֹא רָאָה אָדָם אַחֵר, וּכְשֶׁכִּנֵּס חָכְמָה וְהִתְעַלָּה לְדַרְגוֹת הַחָכְמָה, נִקְרָא קֹהֶלֶת. וְשִׁבְעָה הֲבָלִים אָמַר, כְּנֶגֶד שִׁבְעָה כְתָרִים שֶׁלְּמַעְלָה, וְכָל הֶבֶל נַעֲשָׂה מִמֶּנּוּ קוֹל, וְהָעוֹלָם אֵינוֹ מִתְקַיֵּם אֶלָּא בְּהֶבֶל."],[2,"","וְלָמַדְנוּ מִשְּׁמוֹ שֶׁל רַבִּי שִׁמְעוֹן, הַהֶבֶל מוֹצִיא קוֹל בְּרוּחַ וּמַיִם שֶׁבּוֹ, וְאֵין קוֹל אֶלָּא עִם הֶבֶל. וְלָמַדְנוּ, בְּשִׁבְעָה הֲבָלִים מִתְקַיְּמִים הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים. וְלָמַד רַבִּי יִצְחָק, בֹּא תִרְאֶה שֶׁעַל הַהֶבֶל מִתְקַיֵּם הָעוֹלָם, שֶׁאִלְמָלֵא לֹא הָיָה הֶבֶל שֶׁיּוֹצֵא מִן הַפֶּה, לֹא הִתְקַיֵּם אָדָם אֲפִלּוּ שָׁעָה אַחַת."],[3,"","כְּמוֹ כֵן אָמַר שְׁלֹמֹה דְּבָרָיו, שֶׁהָעוֹלָם מִתְקַיֵּם בָּהֶם, שֶׁבַּהֶבֶל הַזֶּה מִתְקַיֵּם הָעוֹלָם. וְהַהֶבֶל הַזֶּה שֶׁמִּתְקַיֵּם בּוֹ הָעוֹלָם, בָּא מִן הַהֲבָלִים שֶׁלְּמַעְלָה. זֶהוּ שֶׁכָּתוּב הֲבֵל הֲבָלִים, הֶבֶל מֵהַהֲבָלִים שֶׁלְּמַעְלָה, וְכָל דְּבָרָיו הָיוּ כָּךְ. וּבַהֲבָלִים שֶׁלְּמַעְלָה כָּתוּב, (דברים ח) כִּי עַל כָּל מוֹצָא פִּי ה' יִחְיֶה הָאָדָם. מַה זֶּה מוֹצָא פִּי ה'? זֶה הַהֲבָלִים שֶׁלְּמַעְלָה."],[4,"","וְלָמַדְנוּ, וְרָאִיתִי אָנִי שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה מִן הַסִּכְלוּת. מִן הַסִּכְלוּת מַמָּשׁ בָּאָה תוֹעֶלֶת לַחָכְמָה. שֶׁאִלְמָלֵא לֹא נִמְצְאָה שְׁטוּת בָּעוֹלָם, לֹא נוֹדְעָה הַחָכְמָה וּדְבָרֶיהָ. וְלָמַדְנוּ, חִיּוּב הוּא עַל אָדָם שֶׁלָּמַד חָכְמָה לִלְמֹד מְעַט מִן הַשְּׁטוּת וְלָדַעַת אוֹתוֹ, מִשּׁוּם שֶׁבָּאָה תוֹעֶלֶת לַחָכְמָה בִּשְׁבִילוֹ, כְּמוֹ שֶׁבָּאָה תוֹעֶלֶת לָאוֹר מִן הַחֲשֵׁכָה. שֶׁאִלְמָלֵא הַחֲשֵׁכָה לֹא נוֹדָע הָאוֹר, וְלֹא בָאָה (נראית) לָעוֹלָם תּוֹעֶלֶת מִמֶּנּוּ."],[5,"","שָׁנָה, שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה, לַחָכְמָה סְתָם. שֶׁאָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אַבָּא, בֹּא וּרְאֵה סוֹד הַדָּבָר, לֹא מְאִירָה הַחָכְמָה שֶׁלְּמַעְלָה וְלֹא נְאוֹרָה אֶלָּא בִּשְׁבִיל הַשְּׁטוּת שֶׁמִּתְעוֹרֶרֶת מִמָּקוֹם אַחֵר, וְאִלְמָלֵא זֶה, אוֹר וּמִשְׁחָה רַבָּה וְיוֹתֵר לֹא הָיְתָה (להיות), וְלֹא נִרְאֲתָה תוֹעַלְתָּהּ שֶׁל הַחָכְמָה, וּמִשּׁוּם הַשְּׁטוּת מֵאִיר יוֹתֵר, וּמְאִירִים לוֹ יוֹתֵר. זֶהוּ שֶׁכָּתוּב שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה, לַחָכְמָה סְתָם, מִן הַסִּכְלוּת סְתָם. וְכָךְ לְמַטָּה, אִלְמָלֵא לֹא הָיְתָה שְׁטוּת מְצוּיָה בָעוֹלָם, לֹא הָיְתָה הַחָכְמָה מְצוּיָה בָעוֹלָם."],[6,"","וְהַיְנוּ שֶׁרַב הַמְנוּנָא סָבָא, כְּשֶׁהָיוּ לוֹמְדִים מִמֶּנּוּ הַחֲבֵרִים סוֹדוֹת הַחָכְמָה, הָיָה מְסַדֵּר לִפְנֵיהֶם פֶּרֶק שֶׁל דִּבְרֵי שְׁטוּת, כְּדֵי שֶׁתָּבֹא תוֹעֶלֶת לַחָכְמָה בִּשְׁבִילוֹ. זֶהוּ שֶׁכָּתוּב (קהלת י) יָקָר מֵחָכְמָה וּמִכָּבוֹד סִכְלוּת מְעָט, מִשּׁוּם שֶׁהִיא הַתִּקּוּן שֶׁל הַחָכְמָה וּכְבוֹד הַחָכְמָה. וְעַל זֶה כָּתוּב, וְלִבִּי נֹהֵג בַּחָכְמָה וְלֶאֱחֹז בְּסִכְלוּת."],[7,"","רַבִּי יוֹסֵי אָמַר, יָקָר מֵחָכְמָה וּמִכָּבוֹד, כְּלוֹמַר, כְּבוֹד הַחָכְמָה וְהַנּוֹי שֶׁלָּהּ וְהַיְקָר שֶׁל הַכָּבוֹד שֶׁלְּמַעְלָה מַה הוּא? סִכְלוּת מְעָט, מְעַט שֶׁל שְׁטוּת, מַרְאֶה וּמְגַלֶּה אֶת כְּבוֹד הַחָכְמָה וְהַכָּבוֹד שֶׁל מַעְלָה יוֹתֵר מִכָּל דַּרְכֵי הָעוֹלָם."],[8,"","כִּיתְרוֹן הָאוֹר מִן הַחֹשֶׁךְ, תּוֹעֶלֶת הָאוֹר לֹא בָאָה (נראית) אֶלָּא מִתּוֹךְ הַחֲשֵׁכָה. (ולעולם) תִּקּוּן הַלָּבָן מַהוּ? הַשָּׁחֹר. אִלְמָלֵא הַשָּׁחֹר לֹא נוֹדָע הַלָּבָן, וּמִשּׁוּם הַשָּׁחֹר מִתְעַלֶּה הַלָּבָן וּמִתְיַקֵּר. אָמַר רַבִּי יִצְחָק, מָשָׁל לְמָתוֹק בְּמַר, שֶׁאֵין יוֹדֵעַ אִישׁ טַעַם הַמָּתוֹק עַד שֶׁטּוֹעֵם אֶת הַמַּר. מִי עוֹשֶׂה אֶת זֶה מָתוֹק? הֱוֵה אוֹמֵר זֶה הַמַּר. וְהַיְנוּ שֶׁכָּתוּב (שם ז) גַּם אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים. וְכָתוּב טוֹב אֲשֶׁר תֶּאֱחֹז בָּזֶה וְגַם מִזֶּה אַל תַּנַּח אֶת יָדֶךְ."]]],[["תָּאנָא בְּכַמָּה דַּרְגִּין אִתְקְרֵי בַּר נָשׁ: אָדָם, גֶּבֶר, אֱנוֹשׁ, אִישׁ. גָּדוֹל שֶׁבְּכֻלָּם אָדָם. (משום) דִּכְתִּיב, (בראשית א׳:כ״ז) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ. וּכְתִיב (בראשית ט׳:ו׳) כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. וְלָא כְּתִיב, גֶּבֶר, אֱנוֹשׁ, אִישׁ. אָמַר רִבִּי יְהוּדָה, אִי הָכִי, וְהָא כְּתִיב (ויקרא א׳:ב׳) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַיְיָ'. (ולא גבר, אנוש, איש) מַאן בָּעֵי לְמִקְרַב קָרְבְּנָא. מַאן דְּאִיהוּ חַטָּאָה וּכְתִיב אָדָם.","אָמַר רִבִּי יִצְחָק תָּא חֲזֵי, קִיּוּמָא דְּעָלְמָא דְּעִלָּאִין וְתַתָּאִין, הוּא קָרְבְּנָא. נַיְיחָא דְּקוּדְשָׁא בְּרִיךְ הוּא. וּמַאן אִתְחֲזֵי לְמִקְרַב קַמֵּיהּ הַאי נַיְיחָא, הֶוִי אוֹמֵר הַאי אָדָם, דְּיַקִּירָא מִכֹּלָּא. אָמַר לֵיהּ אִי הָכִי, הָא כְּתִיב, אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ וְגוֹ', וְהָיָה בְעוֹר בְּשָׂרוֹ לְנֶגַע צָרָעַת. אָמַר לֵיהּ, לְהַאי בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְדַכָּאָה יַתִּיר מִכֹּלָּא, דְּמַאן דְּאִיהוּ בְּדַרְגָּא עִלָּאָה דְּכֻלְּהוּ, לָא לִיתִיב הָכֵי.","וּבְגִין כַּךְ כְּתִיב בָּאָדָם, וְהוּבָא אֶל הַכֹּהֵן. וּבָא לָא כְּתִיב, אֶלָּא וְהוּבָא, דְּכָל מַאן דְּחָמֵי לֵיהּ, אִתְחַיָּיב בֵּיהּ לְאַקְרוֹבֵי קָמֵי כַּהֲנָא, דְּדִיּוּקְנָא קַדִּישָׁא לָא לֵיתִיב הָכִי. וּכְתִיב אִישׁ אוֹ אִשָּׁה כִּי יִהְיֶה בוֹ נָגַע וְגוֹ', וְאִישׁ אוֹ אִשָּׁה כִּי יִהְיֶה בְּעוֹר בְּשָׂרָם בֶּהָרוֹת וְגוֹ', וְלָא כְּתִיב בְּהוּ וְהוּבָא.","אָמַר לֵיהּ, וְהָא כְּתִיב (במדבר י״ב:ג׳) וְהָאִישׁ מֹשֶׁה, (שמות ל״ב:א׳) כִּי זֶה מֹשֶׁה הָאִישׁ, אֲמַאי לָא אִקְרֵי אָדָם. אָמַר לֵיהּ מִשּׁוּם דְּאִקְרֵי עֶבֶד לְמַלְכָּא, דִּכְתִּיב, (במדבר י״ב:ז׳) לֹא כֵן עַבְדִּי מֹשֶׁה. (יהושע א׳:ב׳) מֹשֶׁה עַבְדִּי. וְאוֹף הָכִי אִקְרֵי אִישׁ לְגַבֵּי אָדָם דִּלְעֵילָּא. אָמַר לֵיהּ אִי הָכִי, וְהָא כְּתִיב (שמות ט״ו:ג׳) יְיָ' אִישׁ מִלְחָמָה, וְלָא כְּתִיב אָדָם. אָמַר לֵיהּ (תהלים כה) סוֹד יְיָ' לִירֵאָיו. אָמַר לֵיהּ אִי הָכִי אֲנָא בֵּינַיְיהוּ (ס\"א יתיב) אָתִיבוּ בְּכֹלָּא, וּבַאֲתַר דָּא לָא זָכִינָא.","אָמַר לֵיהּ זִיל לְרִבִּי אַבָּא, דַּאֲנָא אוֹלִיפְנָא מִנֵּיהּ עַל מְנָת דְּלָא לְגַלָּאָה. אָזַל לְגַבֵּי דְּרִבִּי אַבָּא, אַשְׁכָּחֵיהּ דְּהֲוָה דָּרִישׁ וְאָמַר, אֵימָתַי אִתְקְרֵי שְׁלֵימוּתָא דִּלְעֵילָּא (נ\"א דכלא), כַּד יָתִיב קוּדְשָׁא בְּרִיךְ הוּא בְּכוּרְסְיָּיא. וְעַד דְּלָא יָתִיב בְּכוּרְסְיָּיא, לָא אִשְׁתְּכַח שְׁלֵימוּתָא. דִּכְתִּיב, (יחזקאל א׳:כ״ו) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה, מַשְׁמַע דִּכְתִּיב אָדָם, דְּהוּא כְּלָלָא, וּשְׁלֵימוּתָא דְּכֹלָּא. אָמַר רִבִּי יְהוּדָה, בְּרִיךְ רַחֲמָנָא דְּאַשְׁכָּחִית לָךְ בְּהַאי. אָמַר לֵיהּ אִי הָכִי הָא כְּתִיב (שמות ט״ו:ג׳) יְיָ' אִישׁ מִלְחָמָה, וְלָא כְּתִיב אָדָם. אָמַר לֵיהּ יָאוּת שָׁאַלְתָּ.","תָּא חֲזֵי, הָתָם לָא אִשְׁתְּכַח שְׁלֵימוּתָא דְּכֹלָּא, וּבְגִּינֵי כַּךְ אִקְרֵי אִישׁ. אֲבָל הָכָא, שְׁלֵימוּתָא דְּכֹלָּא, וּכְלָלָא דְּכֹלָּא, בְּגִין כַּךְ אִקְרֵי אָדָם. קָארֵי עָלֵיהּ (תהילים קי״ט:ע״ב) טוֹב לִי תוֹרַת פִּיךָ מֵאַלְפֵי זָהָב וָכָסֶף.","תּוּ אָמַר לֵיהּ, כְּתִיב (תהלים לו) אָדָם וּבְהֵמָה, וְלָא כְּתִיב אִישׁ וּבְהֵמָה. אָמַר לֵיהּ וְלָא. וְהָכְּתִיב (שמות י״א:ז׳) לְמֵאִישׁ וְעַד בְּהֵמָה. אֲבָל מַה דִּכְתִּיב אָדָם וּבְהֵמָה, כְּמָה דִּכְתִּיב, (מלכים א ה׳:י״ג) מִן הָאֶרֶז אֲשֶׁר בַּלְּבָנוֹן עַד הָאֵזוֹב אֲשֶׁר יוֹצֵא בַּקִּיר. אוֹרְחֵיהּ דִּקְרָא הוּא, דְּנָקִיט עִלָּאָה מְכֻּלְּהוּ, וְנָמִיךְ מְכֻּלְּהוּ. אוּף הָכָא עִלָּאָה דְּכֹלָּא, אָדָם, וְנָמִיךְ מִכֹּלָּא בְּהֵמָה.","אָמַר לֵיהּ וְהָא כְּתִיב (בראשית ב׳:ה׳) וְאָדָם אַיִן לַעֲבוֹד אֶת הָאֲדָמָה. אָמַר לֵיהּ, תָּא חֲזֵי, דְּכָל מַה דִּי בְּעָלְמָא לָא הֲוִי אֶלָּא בְּגִינֵיהּ דְּאָדָם, וְכֻלְּהוּ בְּגִינֵיהּ מִתְקַיְּימֵי, וְלָא אִתְחֲזִיאוּ בְּעָלְמָא, וְכֻלְּהוּ אִתְעַכְּבוּ עַד דְּיֵיתֵי הַהוּא דְּאִקְרֵי אָדָם. הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ה׳) וְכֹל שִׁיחַ הַשָּׂדֶה טֶרֶם יִהְיֶה בָאָרֶץ וְגוֹ'. טֶרֶם: עַד לָא, כְּתַרְגּוּמוֹ. מִשּׁוּם דְּדִיּוּקְנָא עִלָּאָה לָא אִתְחֲזֵי, הֲדָא הוּא דִכְתִיב וְאָדָם אַיִן, כְּלוֹמַר, כֻּלְּהוּ אִתְעַכְּבוּ בְּגִינֵיהּ דְּהַאי דִּיּוּקְנָא, עַד דְּאִתְחֲזֵי. וּבְגִין כָּךְ לָא אִתְחֲזֵי (נ\"א אתברי) הַאי דִּיּוּקְנָא, אֶלָּא בְּדִיּוּקְנָא דְּאִתְחֲזֵי לֵיהּ, הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ז׳) וַיִּיצֵר יְיָ' אֱלֹהִים אֶת הָאָדָם, בְּשֵׁם מָלֵּא. כְּמָה דְּאוֹקִימְנָא, דְּאִיהוּ שְׁלֵימוּתָא דְּכֹלָּא, וּכְלָלָא דְּכֹלָּא.","תָּאנָא, בַּשִּׁשִּׁי נִבְרָא אָדָם, בְּשָׁעָה שֶׁנִּשְׁלַם הַכִּסֵא. וְנִקְרָא כִּסֵּא, דִּכְתִּיב, (מלכים א י׳:י״ט) שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. וּלְפִיכָךְ נִבְרָא הָאָדָם בַּשִּׁשִּׁי, שֶׁהוּא רָאוּי לֵישֵׁב עַל הַכִּסֵּא. וְתָאנָא כֵּיוָן דְּנִבְרָא אָדָם אִתְתָּקַּן כֹּלָּא, וְכָל מַה דִּלְעֵילָּא וְתַתָּא, וְכֹלָּא אִתְכְּלִיל בָּאָדָם.","תַּנְיָא אָמַר רִבִּי יוֹסֵי, כְּתִיב (יחזקאל א׳:י׳) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, כְּלָלָא דְּכֹלָּא, וְכֹלָּא כְּלִילָן בְּהַאי דִּיּוּקְנָא. אָמַר רִבִּי יְהוּדָה וְהָא כְּתִיב (יחזקאל א׳:י׳) וּפְנֵי אַרְיֵה אֶל הַיָמִין לְאַרְבַּעְתָּם, וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל לְאַרְבַּעְתָּן, אָמַר לֵיהּ כֹּלָּא אַפֵּי אָדָם הֲווֹ, וּבְהַהוּא דִּיּוּקְנָא דְּאָדָם, אִתְחַזְיָין כָּל גַּוְונִין וְכָל דִּיוּקְנִין. כְּמָה דְּתָנֵינָן אַנְפּוֹי אַנְפֵּי נִשְׁרָא, לָא דְּהוּא נִשְׁרָא, אֶלָּא דְּאִתְחֲזֵי בְּדִיּוּקְנָא דְּאָדָם, מִשּׁוּם דְּכָּלִיל כָּל גַּוְונִין וְכָל דִּיוּקְנִין."],[[0,"תאנא בכמה דרגין וכו׳:","למדנו, בכמה מדרגות נקרא בן אדם, שנקרא, אדם, גבר, אנוש, איש. הגדול שבכולם הוא אדם. שכתוב, ויברא אלקים את האדם בצלמו. וכתוב, כי בצלם אלקים עשה את האדם, ולא כתוב, גבר, אנוש, איש. אר״י, אם כן, הרי כתוב, אדם כי יקריב מכם קרבן לה׳. מי צריך להקריב קרבן, היינו רק מי שהוא חוטא, שהוא מדרגה גרועה, ועכ״ז כתוב אדם."],[1,"אמר ר׳ יצחק וכו׳:","אר״י, בוא וראה, הקיום של העולם, של העליונים ושל התחתונים הוא קרבן, שהוא נחת של הקב״ה, ומי ראוי להקריב לפניו נחת הזה, הוי אומר, שהוא האדם, היקר מכל, דהיינו שהוא יקר מגבר, אנוש, איש. אמר לו, אם כן, הרי כתוב, אדם כי יהיה בעור בשרו וגו׳ והיה בעור בשרו לנגע צרעת, ועכ״ז נקרא אדם. אמר לו, לזה, צריך הקב״ה לטהר אותו יותר מכל אחר, כי מי שהוא במדרגה עליונה על הכל, דהיינו אותו שנקרא אדם, לא ישב כך בלי טהרה."],[2,"ובגין כך כתיב וכו׳:","ומשום זה כתוב, באדם, והובא אל הכהן. ובא אל הכהן לא כתוב, אלא והובא, שיורה, שכל מי שרואה אותו, מחויב להקריב אותו לפני הכהן, כדי שהצורה הקדושה, של אדם, לא תשב כך. וכתוב, איש או אשה כי יהיה בו נגע וגו׳, איש או אשה כי יהיה בעור בשרם בהרות וגו', ולא כתוב בהם \u0003והובא,\u0004 אלא באדם בלבד, כתוב, והובא, מפני חשיבותו."],[3,"אמר ליה והא וכו׳:","אמר לו הרי כתוב, והאיש משה. כי זה משה האיש. למה לא נקרא אדם. אמר לו, משום שנקרא עבד אל המלך, שכתוב, לא כן עבדי משה, משה עבדי. ובערך הזה, נקרא ג״כ איש אל אדם העליון, שהוא ז״א, בהויה דאלפין שהוא בגימטריא אד״ם. אמר לו, א״כ והרי כתוב, ה׳ איש מלחמה, ולא כתוב אדם. אמר לו, סוד ה' ליראיו. אמר לו. א״כ, אני יושב ביניהם לגמרי, כלומר, שהוא מיראי ה', ובמקום הזה לא זכיתי להבין."],[4,"א״ל זיל לר׳ אבא וכו׳:","אמר לו לך לר״א, כי אני למדתי ממנו על מנת שלא לגלות. הלך לר׳ אבא. מצאו שהיה דורש ואומר, מתי נקרא שלמות הכל, בשעה שהקב״ה יושב על הכסא, שהוא מלכות, ומטרם שיושב על הכסא, דהיינו מטרם שמתחבר עם המלכות, לא נמצא שלמות. שכתוב, ועל דמות הכסא דמות כמראה אדם עליו מלמעלה, ומשכתוב, אדם, בשעה שיושב על הכסא, משמע, שהוא בשלמות, כי השם אדם הוא כלל, מד' פנים שבמרכבה, שכתוב, ודמות פניהם פני אדם, והוא שלמות הכל. אמר לו ר׳ יהודה ברוך הרחמן שמצאתי אותך בזה. אמר לו א״כ, הרי כתוב ה׳ איש מלחמה, ולא כתוב אדם, אמר לו, יפה שאלת."],[5,"ת״ח חתם לא וכו׳:","בוא וראה, שם על הים לא נמצא שלמות הכל, משום שעשה דין במצרים, ומשום זה כתוב, איש. אבל כאן, כשיושב על הכסא, הוא שלמות הכל וכלל הכל משום זה נקרא אדם. קרא עליו ר׳ יהודה טוב לי תורת פיך מאלפי זהב וכסף."],[6,"תו אמר ליה וכו׳:","עוד אמר לו. הרי כתוב, אדם ובהמה ולא כתוב איש ובהמה. אע״פ שכאן מדרגה קטנה, שהרי משוה אותו לבהמה. אמר לו, ולא כתוב איש, והרי כתוב, למאיש ועד בהמה. אבל מה שכתוב אדם ובהמה, הוא כמו שכתוב, מן הארז אשר בלבנון עד האזוב אשר יוצא בקיר. שכן דרך הכתוב לאחוז העליון מכולם והנמוך שבכולם. אף כאן העליון שבכולם הוא אדם, והנמוך שבכולם היא בהמה."],[7,"א״ל והא כתיב וכו׳:","אמר לו, והרי כתוב, ואדם אין לעבוד את האדמה. ואיזה חשיבות יש כאן שמזכיר השם אדם. א\"ל בוא וראה, כל מה שיש בעולם לא היה אלא בשביל האדם, והכל מתקיים בשבילו. ע״כ לא נראו בעולם והכל נעכב, עד שבא אותו הנקרא אדם. ז״ש וכל שיח השדה טרם יהיה בארץ וגו', טרם פירושו עד לא, כתרגומו, משום שצורה עליונה, שנקראת אדם, לא נראתה. ז\"ש ואדם אין לעבוד את האדמה. כלומר הכל נתעכב בשביל אותה הצורה עד שנראתה. ומשום כך, לא נבראה צורה זו, אדם, אלא בצורה הראויה לו, ז״ש, וייצר ה׳ אלקים את האדם, בשם מלא, כמו שהעמדנו, שהשם אדם הוא שלמות הכל וכלל הכל."],[8,"תאנא בששי נברא וכו׳:","למדנו ביום ששי נברא האדם, שהוא מרכבה לאדם העליון ז״א, בשעה שנשלם הכסא, שהוא המלכות, שנקרא כסא, שכתוב שש מעלות לכסא, שהם חג״ת נה״י, דמלכות הנקראת כסא. ולפיכך נברא האדם בששי, שכבר נשלמו שש הספירות חג״ת נה״י, שהוא, אדם העליון, ראוי לישב על הכסא, ולמדנו, כיון שנברא אדם נתתקן הכל, וכל מה שלמעלה, דהיינו ז״א ומלכות, ושלמטה, והכל נכלל באדם."],[8,"","פירוש. מטרם שנברא אדם הראשון, היו ז״א ומלכות אב״א בלי חיבור. וביום הששי אחר שנשלמו הו״ק ונולד האדם גרם במעשיו שז״א ומלכות ישובו פב״פ ויתחברו. וז״ש \u0003ולפיכך נברא האדם בששי,\u0004 אחר שנשלמו ו״ק דז״א, שאז \u0003ראוי\u0004 הז״א \u0003לישב על הכסא,\u0004 דהיינו שאז אפשר לאדם שיחזיר ז״א ומלכות פב״פ ויתחברו, מה שלא היה אפשר לפני יום הששי, שעוד לא נשלמו הו״ק עצמם, לא בז\"א ולא במלכות."],[9,"תניא א״ר יוסי וכו׳:","למדנו, אר״י, כתוב, ודמות פניהם פני אדם, היינו שפני אדם הוא כלל הכל, וכל ג׳ פנים, אריה שור נשר, כלולים בצורה זו של פני אדם. אמר ר׳ יהודה, והרי כתוב, ופני אריה אל הימין לארבעתם. ופני שור מהשמאל לארבעתן. הרי שיש צורות אריה ושור גם כן. אמר לו הכל פני אדם היו, ובצורה זו של אדם, נראים כל הגוונים וכל הצורות. כמו שלמדנו, פניו פני נשר, לא שהוא נשר, אלא שנראה בצורת אדם צורת נשר, ועקרו הוא צורת אדם, משום שפני אדם כולל כל הגוונים וכל הצורות."]],[[0,"","שָׁנִינוּ, בְּכַמָּה דְרָגוֹת נִקְרָא בֶּן אָדָם: אָדָם, גֶּבֶר, אֱנוֹשׁ, אִישׁ. גָּדוֹל שֶׁבְּכֻלָּם אָדָם, (משום) שֶׁכָּתוּב (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ. וְכָתוּב (שם ט) כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. וְלֹא כָתוּב גֶּבֶר, אֱנוֹשׁ, אִישׁ. אָמַר רַבִּי יְהוּדָה, אִם כָּךְ, וַהֲרֵי כָּתוּב (ויקרא א) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַה'. מִי צָרִיךְ לְהַקְרִיב קָרְבָּן? מִי שֶׁהוּא חוֹטֵא, וְכָתוּב אָדָם."],[1,"","אָמַר רַבִּי יִצְחָק, בֹּא רְאֵה, קִיּוּם הָעוֹלָם שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים הוּא קָרְבָּן, הַנַּחַת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִי רָאוּי לְהַקְרִיב לְפָנָיו אֶת הַנַּחַת הַזּוֹ? הֱוֵה אוֹמֵר זֶה אָדָם, שֶׁיָּקָר מִן הַכֹּל. אָמַר לוֹ, אִם כָּךְ, הִנֵּה כָּתוּב, אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ וְגוֹ', וְהָיָה בְעוֹר בְּשָׂרוֹ לְנֶגַע צָרָעַת. אָמַר לוֹ, אֶת זֶה צָרִיךְ לְטַהֵר הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹתֵר מֵהַכֹּל, שֶׁמִּי שֶׁהוּא בְּדַרְגָּה עֶלְיוֹנָה שֶׁל כֻּלָּם, לֹא יֵשֵׁב כָּךְ."],[2,"","וּמִשּׁוּם כָּךְ כָּתוּב בָּאָדָם, וְהוּבָא אֶל הַכֹּהֵן. וּבָא לֹא כָתוּב, אֶלָּא וְהוּבָא. שֶׁכָּל מִי שֶׁרוֹאֶה אוֹתוֹ, מִתְחַיֵּב בּוֹ לְהַקְרִיבוֹ לִפְנֵי הַכֹּהֵן, שֶׁהַדְּמוּת הַקְּדוֹשָׁה לֹא תֵשֵׁב כָּךְ. וְכָתוּב אִישׁ אוֹ אִשָּׁה כִּי יִהְיֶה בוֹ נָגַע וְגוֹ', וְאִישׁ אוֹ אִשָּׁה כִּי יִהְיֶה בְעוֹר בְּשָׂרָם בֶּהָרֹת וְגוֹ'. וְלֹא כָתוּב בָּהֶם וְהוּבָא."],[3,"","אָמַר לוֹ, וַהֲרֵי כָּתוּב (במדבר יב) וְהָאִישׁ מֹשֶׁה, כִּי זֶה מֹשֶׁה הָאִישׁ, לָמָּה לֹא נִקְרָא אָדָם? אָמַר לוֹ, מִשּׁוּם שֶׁנִּקְרָא עֶבֶד לַמֶּלֶךְ, שֶׁכָּתוּב (שם) לֹא כֵן עַבְדִּי מֹשֶׁה. (יהושע א) מֹשֶׁה עַבְדִּי. וְאַף כָּךְ נִקְרָא אִישׁ כְּלַפֵּי אָדָם שֶׁלְּמַעְלָה. אָמַר לוֹ, אִם כָּךְ, הֲרֵי כָּתוּב (שמות טו) ה' אִישׁ מִלְחָמָה, וְלֹא כָתוּב אָדָם. אָמַר לוֹ, סוֹד ה' לִירֵאָיו. אָמַר לוֹ, אִם כָּךְ אֲנִי בֵּינֵיהֶם (יושב) הוֹשִׁיבוּ בַּכֹּל, וּבַמָּקוֹם הַזֶּה לֹא זָכִיתִי."],[4,"","אָמַר לוֹ, לֵךְ לְרַבִּי אַבָּא, שֶׁאֲנִי לָמַדְתִּי מִמֶּנּוּ שֶׁלֹּא עַל מְנָת לְגַלּוֹת. הָלַךְ אֵצֶל רַבִּי אַבָּא, מָצָא אוֹתוֹ שֶׁהָיָה דוֹרֵשׁ וְאוֹמֵר: מָתַי נִקְרֵאת שְׁלֵמוּת שֶׁל מַעְלָה (של הכל) ? כְּשֶׁיּוֹשֵׁב הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכִסֵּא, וְעַד שֶׁלֹּא יוֹשֵׁב בְּכִסֵּא, לֹא נִמְצֵאת שְׁלֵמוּת, שֶׁכָּתוּב (יחזקאלא) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. מַשְׁמָע שֶׁכָּתוּב אָדָם, שֶׁהוּא הַכְּלָל וּשְׁלֵמוּת הַכֹּל. אָמַר רַבִּי יְהוּדָה, בָּרוּךְ הָרַחֲמָן שֶׁמָּצָאתִי אוֹתְךְ בָּזֶה. אָמַר לוֹ, אִם כָּךְ, הֲרֵי כָּתוּב ה' אִישׁ מִלְחָמָה, וְלֹא כָתוּב אָדָם. אָמַר לוֹ, יָפֶה שָׁאַלְתָּ."],[5,"","בֹּא רְאֵה, שָׁם לֹא נִמְצֵאת שְׁלֵמוּת שֶׁל הַכֹּל, וּמִשּׁוּם כָּךְ נִקְרָא אִישׁ. אֲבָל כָּאן שְׁלֵמוּת הַכֹּל וְהַכְּלָל שֶׁל הַכֹּל, מִשּׁוּם כָּךְ נִקְרָא אָדָם. קָרָא עָלָיו, (תהלים קיט) טוֹב לִי תּוֹרַת פִּיךְ מֵאַלְפֵי זָהָב וָכָסֶף."],[6,"","עוֹד אָמַר לוֹ, כָּתוּב (שם לו) אָדָם וּבְהֵמָה, וְלֹא כָתוּב אִישׁ וּבְהֵמָה. אָמַר לוֹ, וָלֹא?! וַהֲרֵי כָּתוּב (שמות יא) לְמֵאִישׁ וְעַד בְּהֵמָה. אֲבָל מַה שֶּׁכָּתוּב אָדָם וּבְהֵמָה, כְּמוֹ שֶׁכָּתוּב (מלכים א ה) מִן הָאֶרֶז אֲשֶׁר בַּלְּבָנוֹן עַד הָאֵזוֹב אֲשֶׁר יֹצֵא בַּקִּיר. דֶּרֶךְ הַכָּתוּב הוּא, שֶׁלּוֹקֵחַ הָעֶלְיוֹן מִכֻּלָּם וְהַנָּמוּךְ מִכֻּלָּם. אַף כָּאן הָעֶלְיוֹן שֶׁל הַכֹּל - אָדָם, וְהַנָּמוּךְ מֵהַכֹּל - בְּהֵמָה."],[7,"","אָמַר לוֹ, וַהֲרֵי כָּתוּב (בראשיתב) וְאָדָם אַיִן לַעֲבֹד אֶת הָאֲדָמָה. אָמַר לוֹ, בֹּא וּרְאֵה שֶׁכָּל מַה שֶּׁבָּעוֹלָם אֵינוֹ אֶלָּא בִּשְׁבִיל הָאָדָם, וְכֻלָּם בִּגְלָלוֹ מִתְקַיְּמִים וְלֹא נִרְאִים בָּעוֹלָם, וְכֻלָּם הִתְעַכְּבוּ עַד שֶׁיָּבֹא אוֹתוֹ שֶׁנִּקְרָא אָדָם. זֶהוּ שֶׁכָּתוּב (שם) וְכֹל שִׂיחַ הַשָּׂדֶה טֶרֶם יִהְיֶה בָאָרֶץ וְגוֹ'. טֶרֶם: עַד שֶׁלֹּא, כְּתַרְגּוּמוֹ. מִשּׁוּם שֶׁלֹּא נִרְאֲתָה הַדְּמוּת הָעֶלְיוֹנָה. זֶהוּ שֶׁכָּתוּב וְאָדָם אַיִן. כְּלוֹמַר, כֻּלָּם הִתְעַכְּבוּ בִשְׁבִילָהּ שֶׁל הַדְּמוּת הַזֹּאת עַד שֶׁנִּרְאֲתָה. וּמִשּׁוּם כָּךְ לֹא נִרְאֲתָה (נבראה) הַדְּמוּת הַזּוֹ אֶלָּא בַּדְּמוּת שֶׁרְאוּיָה לָהּ. זֶהוּ שֶׁכָּתוּב (שם) וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם, בְּשֵׁם מָלֵא, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁהוּא שְׁלֵמוּת הַכֹּל וְהַכְּלָל שֶׁל הַכֹּל."],[8,"","לָמַדְנוּ, בְּשִׁשִּׁי נִבְרָא אָדָם, בְּשָׁעָה שֶׁנִּשְׁלַם הַכִּסֵּא. וְנִקְרָא כִסֵּא, שֶׁכָּתוּב (מלכים א י) שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. וּלְפִיכָךְ נִבְרָא הָאָדָם בַּשִּׁשִּׁי, שֶׁהוּא רָאוּי לֵישֵׁב עַל הַכִּסֵּא. וְלָמַדְנוּ, כֵּיוָן שֶׁנִּבְרָא אָדָם, הַכֹּל הִתְתַּקֵּן, וְכָל מַה שֶּׁלְּמַעְלָה וּלְמַטָּה, וְהַכֹּל נִכְלָל בָּאָדָם."],[9,"","שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, כָּתוּב (יחזקאל א) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, הַכְּלָל שֶׁל הַכֹּל, וְהַכֹּל כְּלוּלִים בַּדְּמוּת הַזֹּאת. אָמַר רַבִּי יְהוּדָה, וַהֲרֵי כָּתוּב וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם וּפְנֵי שׁוֹר מֵהַשְּׂמֹאול לְאַרְבַּעְתָּן? אָמַר לוֹ, הַכֹּל הָיוּ פְּנֵי אָדָם, וּבְאוֹתָהּ דְּמוּת שֶׁל אָדָם נִרְאִים כָּל הַגְּוָנִים וְכָל הַדְּמֻיּוֹת. כְּמוֹ שֶׁשָּׁנִינוּ, פָּנָיו פְּנֵי נֶשֶׁר, לֹא שֶׁהוּא נֶשֶׁר, אֶלָּא שֶׁנִּרְאֶה בִּדְמוּת שֶׁל אָדָם, מִשּׁוּם שֶׁכּוֹלֵל אֶת כָּל הַגְּוָנִים וְכָל הַדְּמֻיּוֹת."]]],[["אָמַר רִבִּי יִצְחָק, תָּא חֲזֵי, כָּל מַאן דְּאִיהוּ תְּחוֹת שׁוּלְטָנֵי דְּאָדָם, אִתְקְרֵי אִישׁ. מִשּׁוּם דְּאִתְתָּקַן בְּגַוְונָא דְּאָדָם, מִדַּרְגָּא אָחֳרָא דְּהֲוָה בֵּיהּ בְּקַדְמִיתָא. דְּתַנְיָא בְּרָזָא עִלָּאָה (תרומה קע\"ח ע\"ב, מ\"ו ע\"ב) בְּסִפְרָא דִּצְנִיעוּתָא, כַּד אִתְבְּרֵי אָדָם, נָחַת בְּדִיּוּקְנָא קַדִּישָׁא עִלָּאָה, וְנַחְתּוּ עִמֵּיהּ תְּרֵין רוּחִין, מִתְּרֵין סִטְרִין, מִימִינָא וּמִשְּׂמָאלָא, כְּלָלָא דְּאָדָם. וְרוּחָא דִּימִינָא, אִתְקְרֵי נִשְׁמְתָא קַדִּישָׁא, דִּכְתִּיב, (בראשית ב׳:ז׳) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים. וְרוּחָא דִּשְׂמָאלָא, אִתְקְרֵי נֶפֶשׁ חַיָּה, וַהֲוָה אָזִיל וְנָחִית מֵעֵילָּא לְתַתָּא, וְלָא אִתְיַישְׁבָא בַּהֲדֵי אָחֳרָא.","כַּד הֲוָה עַיִּיל שַׁבְּתָא, וַהֲוָה חָב אָדָם, אִתְעָבִידוּ (נ\"א אתנגידו) מֵהַהוּא רוּחָא שְׂמָאלָא, בִּרְיָין מִתְפַּשְּׁטָן בְּעָלְמָא, וְלָא אִסְתְּיָימוּ גּוּפָא דִּלְהוֹן. וְאִתְחַבָּרוּ בְּהַאי גּוּפָא דְּאָדָם, בִּדְכוּרָא וְנוּקְבָּא, וְאִתְיְלִידוּ בְּעָלְמָא. וְאִלֵּין אִקְרוּן נִגְעֵי בְּנֵי אָדָם. (כ\"ה ע\"א) תָּנָא, עִלָּאִין מִנַּיְיהוּ דְּלָא אִתְדְּבָקוּ לְתַתָּא, וְתַּלְיָין בַּאֲוִירָא, וְשַׁמְעִין מַה דְּשַׁמְעִין מִלְּעֵילָּא. וּמִנַּיְיהוּ יַדְעִין אִינּוּן אָחֳרָנִין לְתַתָּא.","תָּנָא, מִן בּוּצִינָא דְּקַרְדִּינוּתָא, נָפְקִין תְּלַת מְאָה וְעֶשְׂרִים וְחָמֵשׁ נִיצוֹצֵי, מִתְגַּלְּפִין וּמִתְאַחֲדָן כַּחֲדָא מִסִּטְרָא דִּגְבוּרָה, דְּאִקְרוּן גְּבוּרוֹת, (ס\"א ומתלכדן) כַּחֲדָא, וְאִתְעָבִידוּ חַד. (גופא) וְכַד עַיְילִין אִלֵּין בְּגוּפָא, אִקְרֵי אִישׁ. (ס\"א ולא איש דא) דָּא דְּתָנֵינָן אִישׁ תָּם וְיָשָׁר אִישׁ צַדִּיק, וְאִישׁ דְּהָכָא, אִישׁ מִלְחָמָה כְּתִיב, דְּכֹלָּא סָלִיק דִּינָא, וְכֹלָּא חֲדָא. אָמַר רִבִּי יְהוּדָה אֲמַאי. לָא הֲוָה בִּידֵיהּ (דרבי יצחק). אָתוּ שָׁאִילוּ קָמֵיהּ דְּרַבִּי שִׁמְעוֹן, אָמַר לוֹן, תּוּ קַשְׁיָא, דְּהָא תָּנֵינָן כְּתִיב (בראשית ב׳:כ״ג) לְזֹאת יִקָּרֵא אִשָּׁה כִּי מֵאִישׁ לֻקֳחָה זֹּאת, וְתָנֵינָן מַאן אִישׁ דָּא חֶסֶד, וְהָכָא אַמְרִיתּוּ דְּהוּא דִּינָא.","אֶלָּא הָכִי תָּאנָא, כֹּלָּא הוּא בְּחַד מַתְקְלָא סַלְּקָא, וְכֹלָּא חַד. וּמִשּׁוּם דְּדִינֵי תַּתָּאֵי מִתְאַחֲדָן (נ\"א ומתלכדן) וּמִתְחַבְּרָן בְּשַׂעֲרוֹי דְּהַאי. אִקְרֵי הוּא דִּינָא קַשְׁיָא, וְכַד אִתְעַבָּר מִנֵּיהּ שַׂעֲרָא דְּרֵישָׁא, אִתְבְּסָם, וְדִינִין דִּלְתַתָּא לָא אִזְדְּמָנוּ. וּבְגִין כָּךְ אִקְרֵי טָהוֹר. דְּלָא אִקְרֵי טָהוֹר, אֶלָּא כַּד נָפִיק מִסִּטְרָא דִּמְסָאֲבָא, וְכַד נָפִיק מִן מִסְאֲבָא, אִקְרֵי טָהוֹר. דִּכְתִּיב, (איוב י״ד:ד׳) מִי יִתֵּן טָהוֹר מִטָּמֵא. מִטָּמֵא וַדַּאי, וְהָכָא כְּתִיב, וְאִישׁ כִּי יִמָּרֵט רֹאשׁוֹ קֵרֵחַ הוּא טָהוֹר הוּא.","וְתָּא חֲזֵי, בְּרֵישָׁא דְּהַאי אִישׁ, בּוּצִינָא דְּקַרְדִּינוּתָא. וּבְגִין כָּךְ גּוּלְגַלְתָּא דְּרֵישָׁא דְּהַאי, סוּמָקָא כֹּלָּא כְּוַורְדָּא, וְשַׂעְרֵי סוּמָקֵי בְּגוֹ סוּמָקֵי, וְתַּלְיָין מִנֵּיהּ כִּתְרִין תַּתָּאִין דִּלְתַתָּא, דְּמִתְעֲרִין דִּינִין בְּעָלְמָא. וְכַד אִתְעַבָּר מִנֵּיהּ שַׂעֲרָא וְאִתְגְלִישׁ, מֵחֶסֶד עִלָּאָה אִתְבְּסָם כֹּלָּא, וְאִתְקְרֵי טָהוֹר עַל שְׁמֵיהּ.","אָמַר רִבִּי יְהוּדָה, אִי אִתְקְרֵי עַל שְׁמֵיהּ, קָדוֹשׁ אִתְקְרֵי, וְלָא טָהוֹר. אָמַר לֵיהּ לָאו הָכֵי, דְּקָדוֹשׁ לָא אִתְקְרֵי אֶלָּא כַּד תָּלֵי שַׂעֲרָא. דִּקְדוּשָּׁה בְּשַׂעְרָא תָּלֵי, דִּכְתִּיב, (במדבר ו׳:ה׳) קָדוֹשׁ יִהְיֶה גַּדֵל פֶּרַע שְׂעַר רֹאשׁוֹ. וְהַאי אִקְרֵי טָהוֹר, מִסִּטְרָא דְּתַּלְיָין לְתַתָּא מִנֵיהּ, וּבְגִּינֵי כַּךְ אִתְעַבָּר מִנֵּיהּ שַׂעֲרָא, וְאִתְדַּכְיָא.","וְתָא חֲזֵי כָּל מַאן דְּאִיהוּ מִסִּטְרָא דְּדִינָא, וְדִינִין מִתְאַחֲדִין בֵּיהּ, לָא אִתְדָּכֵי, עַד דְּאִתְעֲבָר מִנֵּיהּ שַׂעֲרָא, וּמִדְאִתְעֲבָר מִנֵּיהּ שַׂעֲרָא אִתְדָּכֵי. וְאִי תֵּימָא אָדָם. לָאו הָכִי, דְּהָא הוּא שְׁלֵימוּתָא דְּכֹלָּא, וְרַחֲמֵי אִשְׁתְּכָחוּ בֵּיהּ. בְּגִין כַּךְ לָאו הָכִי דְּכֻלְּהוּ קְדוּשָׁאן וְקַדִּישִׁין אִתְיָיחֲדוּ בֵּיהּ. אֲבָל הַאי, הוּא דִּינָא, וְדִינֵי אִתְאַחֲדָן בֵּיהּ, לָא אִתְבְּסָם עַד דְּאִתְעֲבָר מִנֵּיהּ שַׂעֲרָא.","תָּא חֲזֵי, דְּהָא לֵיוָאֵי דְּאָתוּ מֵהַאי סִטְרָא דְּדִינָא, לָא מִתְדַּכְּאָן עַד דְּאִתְעֲבָרוּ מִנְּהוֹן שַׂעֲרָא, דִּכְתִּיב, (במדבר ח׳:ז׳) וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם הַזֵּה עֲלֵיהֶם מֵי חַטָּאת וְהֶעֱבִירוּ תַעַר עַל כָּל בְּשָׂרָם וְגוֹ'. וּבְגִין דְּיִתְבַּסְּמוּן יַתִּיר, בָּעֵי כַּהֲנָא דְּאָתָא מִסִּטְרָא דְּחֶסֶד עִלָּאָה, לְאָרָמָא לוֹן, דִּכְתִּיב, (במדבר ח׳:י״א) וְהֵנִיף אַהֲרֹן אֶת הַלְוִיִּם תְּנוּפָה לִפְנֵי יְיָ'. כְּמָה דְּאִיהוּ לְהַאי אִישׁ דִּלְעֵילָּא, דְּכַד בָּעֵי לְאִתְבַּסְּמָא יַתִּיר, אִתְגַּלְיָיא בֵּיהּ חֶסֶד עִלָּאָה, וְאִתְבְּסָם. וּמְבָסֵּם הוּא, לְתַתָּא."],[[0,"א״ר יצחק וכו׳:","אר״י, בוא וראה, כל שהוא תחת שליטתו של אדם, נקרא, איש. משום שנתתקן באפן של אדם, ממדרגה אחרת שהיתה בו תחילה שהיא מדרגת ו״ק, שהיתה לאדם בטרם שהשיג הג״ר. כי למדנו בסוד עליון בספרא דצניעותא, (אות נ״א) כאשר נברא האדם, ירד בצורה עליונה קדושה, וירדו עמו ב׳ רוחות מב׳ צדדים, מימין ומשמאל שהן כלל האדם, ורוח הימין נקרא נשמה הקדושה, שכתוב, ויפה באפיו נשמת חיים. ורוח השמאל נקרא נפש חיה. והיה הולך ויורד ממעלה למטה לגן עדן. והנשמה שמימין לא נתישבה עם האחר שמשמאל. כלומר, שחטא בעצה״ד והפריד הימין מן השמאל."],[1,"כד הוה עייל וכו׳:","כשנכנס השבת, והאדם כבר חטא, נעשו מרוח שמאל ההוא, בריות המתפשטות בעולם, שלא נגמרו הגופים שלהם, דהיינו שדים, ונתחברו בגוף הזה של אדם בזכר, ובנקבה שהיא חוה, והולידו בעולם, ואלו נקראים נגעי בני אדם למדנו שיש רוחות עליונים, מאלו שנעשו מרוח השמאל דאדם הראשון, שהם אינם מתדבקים למטה בעולם הזה, ותלוים באויר, ושומעים מה ששומעים מלמעלה, ומהם יודעים רוחות אחרות שלמטה בעולם הזה, הנראים לאנשים בחלומם ומודיעים להם. (כנ״ל ויקרא אות תל״א)."],[2,"תאנא מן בוצינא וכו׳:","למדנו, מבוצינא דקרדינותא יוצאים שכ״ה ניצוצים, נחקקים ונאחדים יחד מצד הגבורה, ונקראים גבורות, ומתלכדים יחד ונעשים אחד, וכשאלו נכנסים בגוף, דהיינו ז\"א המכונה גוף, נקרא איש. וזה שלמדנו, שיש, איש תם וישר, איש צדיק, אבל איש שבכאן, הוא איש מלחמה כתוב, דהיינו ה׳ איש מלחמה. כי כולו עולה בדין, והכל אחד. אמר ר׳ יהודה, למה הכל אחד, הלא איש תם וישר, הוא רחמים, ואיש מלחמה הוא דין. לא היה בידו להשיב לו. באו ושאלו לפני ר׳ שמעון. אמר להם עוד קשה שהרי למדנו, כתוב, לזאת יקרא אשה כי מאיש לקחה זאת, ולמדנו, מהו איש, זה חסד. וכאן אמרתם שהוא דין."],[2,"","ביאור הדברים. כי מדבר כאן מתקון פרצוף הקטנות דז״א. ונודע, כי כל הפרצופים שבעולמות נבררו ונעשו מכלים וניצוצים של ז׳ מלכים דנקודים שנשברו, שבכללם יש בהם ש״כ בחינות המכונים ש״כ ניצוצים, כמו שנתבאר זה היטב לעיל (ויקהל אות תצ״ב, בהסולם, ע״ש) וכן כל פרט קטן הנברר מהם, כלול מכולם, ומספרו ג״כ ש״כ ניצוצים. וכיון שהשבירה היתה מחמת מלכות דמדת הדין שנתערבה בהם, ע״כ נבחנים כולם שהמלכות דמדת הדין רוכב עליהם. וכדי לתקן אותם שיהיו ראוים לקבל אור, צריכים להמתיק מלכות זו בבינה, שהיא מדת הרחמים, וע״כ נמשכים להם ה׳ ניצוצים מחג״ת נ״ה שבבינה, שהם בחינת הקטנות של הבינה, כדי שיהיו ראוים אח״כ לקבל גם הגדלות מן הבינה. ובאלו מתתקנים פרצוף הקטנות של ז״א. ונודע, שכל פרצוף תחתון מתתקן בפרצוף העליון ממנו. ונמצא שאלו שכ\"ה ניצוצים דז״א נתתקנו בבינה."],[2,"","וזה אמרו, \u0003מן בוצינא דקרדינותא,\u0004 דהיינו כחות הדין שבבינה, \u0003נפקין תלת מאה ועשרין וחמש ניצוצי,\u0004 שהם ש״כ ניצוצי דז״א שעלו אל הבינה משבירת ז׳ מלכים, וה׳ ניצוצים של הבינה עצמה המתקנים הש״כ ניצוצים. וכולם הם \u0003מסטרא דגבורה, דאקרון גבורות ומתלכדן כחדא ואתעבידו חד,\u0004 שהש״כ ניצוצין וה' ניצוצים מתלכדים יחד ונעשים אחד, כלומר, שמקבלים כולם רק כח דין הממותק של הבינה, וכחות המלכות דמדת הדין נבלעים בכחות המלכות הממותקת בבינה. \u0003וכד עיילין אלין בגופא,\u0004 היינו כשנכנסים בז\"א, הם מתתקנים בו בבחינת גוף בלי ראש, ואז, \u0003אקרי איש,\u0004 שמדת הקטנות הזאת של ז״א נקרא בשם \u0003איש.\u0004"],[3,"אלא הכי תאנא וכו׳:","אלא כך למדנו הכל עולה במשקל אחד והכל אחד, דהיינו שאיש הוא חסד וגם הוא דין, שמשום שדינים דתחתונים מתאחדים ומתחברים בשערות של זה. הוא נקרא דין קשה, וכשנעברו ממנו שערות ראשו, הוא מתבשם, והדינים דתחתונים אינם מזדמנים. ומשום זה נקרא טהור, כי אין טהור אלא כשיוצא מצד הטומאה, וכשיוצא מצד הטומאה נקרא טהור. שכתוב, מי יתן טהור מטמא. מטמא ודאי. וכאן כתוב, ואיש כי ימרט ראשו קרח הוא טהור הוא."],[4,"ות״ח ברישא דהאי וכו׳:","ובוא וראה בראש של איש הזה הוא ניצוץ הקשה, ומשום כך הגלגלת, של ראש של זה, הוא אדום כמו ורד, והשערות הם אדומות בתוך האודם של הגלגלתא, ותלויות ממנו ספירות התחתונות שלמטה המעוררות דינים בעולם. וכשנעברו ממנו השערות ונקרחו, מחסד העליון אתבסם הכל, שהארת החכמה שבו מתבסמת בחסד עליון, ונקרא טהור על שמו."],[5,"א״ר יהודה וכו׳:","אר״י, אם נקרא על שמו, קדוש היה צריך להקרא, ולא טהור. אייל, אינו כן, כי קדוש אינו נקרא אלא כשתלויות שערות בראשו, כי הקדושה תלויה בשערות, שכתוב, קדוש יהיה גדל פרע שער ראשו. וזה, איש, נקרא טהור, מצד התלוים למטה ממנו, שהם החצונים הטמאים, שנעברו עם העברת שערותיו, ומשום זה נעברו ממנו השערות ונטהר."],[5,"","ביאור הדברים. שערות ראש שבכאן, פירושם הדינים הממעטים אורות דראש מן הפרצוף וקובעים אותו בבחינת ו״ק בלי ראש. כי ידעת שה׳ ניצוצות הנוספות על ש״ך ניצוצות הנ״ל, הם ה׳ בחינות מחג״ת נ״ה דבינה מבחינת הקטנות שלה, וקטנות שלה באה מסוד כניסת \u0003י׳\u0004 ב \u0003אור\u0004 הג״ר שלה ונעשו ל \u0003אויר,\u0004 שפירושו ו״ק (כנ״ל ב״א דף מ״ד ד״ה בקע ע״ש). ומסוד \u0003י׳\u0004 זו המסלקת הג״ר יוצאות השערות ראש דקטנות. כי שערות, הם כמו סערות, דהיינו דינים, ובהם נאחזים החיצונים, שדרכם להתאחז במקום חסרון שבקדושה."],[5,"","וזה אמרו (באות קי״ט) \u0003ומשום דדיני תתאי מתאחדן ומתחברן בשערוי דהאי, אקרי הוא דינא קשיא,\u0004 כי אע״פ שאיש הוא חסד, דהיינו שיש בו קומת חסדים דבחי״א שה״ס ו״ק, עכ״ז יוצאים בו שערות ראש, מכח ה \u0003י׳\u0004 שנכנס ב \u0003אור\u0004 ומיעטו לו״ק חסר ג״ר, ובאלה השערות מתאחזים החיצונים למטה, ומשום אחיזת החיצונים, הוא נקרא דין קשה. \u0003וכד אתעבר מניה שערא דרישא אתבסם, ודינין דלתתא לא אזדמנו,\u0004 דהיינו בשעה שה \u0003י׳\u0004 חוזרת ויוצאת מן ה \u0003אויר,\u0004 וחזר האויר להיות \u0003אור,\u0004 דהיינו שחזרו הג״ר, (כנ״ל ב״א דף מ״ה ד\"ה כד) אז נעברו ממנו שערות ראשו. כי כיון שנעברה ה \u0003י׳\u0004 מאויר, שהיתה השורש להם, נעברו עמה כל ענפיה, ואחיזת החצונים שלמטה נתבטלה. \u0003ובגין כך אקרי טהור, דלא אקרי טהור אלא כד נפיק מסטרא דמסאבא,\u0004 כי כיון שנעברו השערות, נתבטלה אחיזת החיצונים הטמאים שנתאחזו בשערות, ונמצא שיצא ונפרד לגמרי מן הטומאה, ע״כ נקרא טהור, \u0003דלא אקרי טהור\u0004 וכו׳ והכא כתיב, \u0003ואיש כי ימרט ראשו קרח הוא טהור הוא,\u0004 כי אחר שנעברו השערות מן \u0003איש,\u0004 הרי נפרדה ממנו אחיזת טומאת החצונים, וע״כ טהור הוא."],[5,"","וזה אמרו (באות ק\"כ) \u0003ברישא דהאי איש, בוצינא דקרדינותא.\u0004 שבראשו של \u0003איש\u0004 זה, דהיינו דפרצוף קטנות דז״א, יש ניצוץ הקשה, שה״ס כח הדין דקטנות דבינה, שה״ס ה \u0003י׳\u0004 שנכנסה ל \u0003אור\u0004 הראש ונעשה ו״ק, שה״ס \u0003אויר\u0004 כנ״ל, \u0003ובגין כך גולגלתא דרישא דהאי, סומקא\u0004 וכו', כי גוון אדום הוא מבינה וכיון שיש בו קטנות בינה, ע״כ גוון הגלגלת אדום, וגם, \u0003ושערי סומקי בגו סומקי,\u0004 משא״כ אם הקטנות באה מכח המלכות, שאינה נמתקת בבינה, אז השערות הן בגוון שחור. ומשמיענו, שאע״פ, שז״א, שערותיו שחורות, שכתוב, קוצותיו תלתלים שחורות כעורב. זה הוא כשהוא במוחין דגדלות, אבל כשעודו בקטנות, שערותיו אדומות, וכשמשיג ג״ר דקטנות, שה״ס ירידת ה \u0003י׳\u0004 מאויר כנ״ל, נעברות ממנו השערות לגמרי, וכשמשיג המוחין דגדלות, שאז נגנזת המלכות הבלתי נמתקת בבינה, בג״ר שלו (כמ״ש לעיל בהקדמת ספר הזהר דף מ\"ד ד״ה וטעם ע״ש) שממנה נמשך גוון שחור, אז צומחות לו שערות מחדש, ושערותיו שחורות כעורב. המלכות הבלתי נמתקת בבינה, בג״ר שלו (כמ״ש לעיל בהקדמת ספר הזהר דף מ\"ד ד״ה וטעם ע״ש) שממנה נמשך גוון שחור, אז צומחות לו שערות מחדש, ושערותיו שחורות כעורב."],[5,"","ודע, שאע״פ שאמרנו כאן, שהשערות צומחות מבחינת \u0003אויר,\u0004 דהיינו מ \u0003י׳\u0004 שנכנס ב \u0003אור\u0004 ונעשה \u0003אויר\u0004 כנ״ל וע״כ נאחזים החצונים הטמאים בשערות. עכ״ז יש בחינת \u0003אויר טהור,\u0004 שאין שום אחיזה לחצונים נמשכת ממנו, והיינו באבא ואמא עלאין המתוקנים מג׳ ראשונות דבינה דא״א, שבהם אין ה \u0003י׳\u0004 יוצאת מ \u0003אויר\u0004 לעולם (כנ״ל ב״א דף רנ״א ד״ה נחית) ועכ״ז נבחן האויר הזה להם, ל \u0003אוירא דכיא\u0004 והוא מטעם כי מיעוט הזה הנמשך מן ה \u0003י׳\u0004 שנכנס לאויר, הוא רק מיעוט מקבלת חכמה, וכיון שאו״א אינם מקבלים חכמה לעולם, שהם בםו״ה, כי חפץ חסד הוא, ולא בחכמה, ע״כ אין המיעוט הזה נחשב להם לחסרון כלום, והחסדים שלהם הם בתכלית השלמות, ואין מקום בהם לאחיזת החיצונים, ונבחנים לג״ר גמורים, ולא עוד, אלא שהם יותר חשובים מחכמה, משום שמהם מושפעת החכמה לכל הפרצופים, אע״פ שהם עצמם הם רק חסדים בלי חכמה כנודע."],[5,"","וכל זה רק באו״א עלאין, משא״כ בז״א, שכל עקרו הוא חסדים בהארת חכמה, (כמ״ש בתלמוד עשר הספירות בשיעור א׳ דף ו׳ ד״ה וטעם) נמצא, שכניסת ה \u0003י׳\u0004 באור הממעטו מחכמה, נחשב אצלו לחסרון, וע״כ נאחזים החצונים בשערות הצומחות מן \u0003י׳\u0004 זו, כי דרכם להתאחז בכל מקום שיש חסרון, וע״כ האויר הזה של ז״א אינו אוירא דכיא כמו האויר דאו״א, שהרי יש בו אחיזה לחיצונים הטמאים, ורק בזמן שנעברים ממנו אלו השערות נקרא טהור."],[5,"","ונתבאר שכל זה הוא בו״ק וג״ר דקטנות דז״א, שבמצב ו״ק צומחות לו שערות אדומות, ובמצב ג״ר דקטנות נעברים ממנו, והוא \u0003טהור,\u0004 ואח״כ ע״י עלית מ״ן מתחתונים עולה ז״א למצב מוחין דגדלות ועולה ומלביש לאו״א עלאין, ונודע שהתחתון העולה לעליון נעשה כמוהו, וע״כ נבחן אז שגם בו אין ה \u0003י׳\u0004 יוצא מאויר כמו באו״א, ומן \u0003י׳\u0004 זו נמשך המסך הממשיך החסדים דאו״א שהם אוירא דכיא, וכן נמשכות ממנו שערות ראש. וכשז״א מקבל אוירא דכיא זה מאו״א, הוא נקרא \u0003קדוש\u0004 כמו או״א."],[5,"","וז״ש (באות קכ״א) \u0003דקדוש לא אתקרי אלא כד תלי שערא, דקדושה בשערא תלי,\u0004 כי קדושה נמשכת מאו״א עלאין, אחר שעולה ומלבישם, שאז נמצאת ה \u0003י׳\u0004 באויר שלו כמו באו״א, וע״כ יש לו שערות. ואם אין לו שערות נמצא שאינו מלביש את או״א עלאין, וא״כ אינו קדוש, הרי שהקדושה תלויה בשערות. ומביא ראיה מנזיר, \u0003דכתיב, קדוש יהיה גדל פרע שער ראשו.\u0004 כי הנזיר מקבל עליו קדושת או״א עלאין כדי להמשיך עליו אוירא דכיא, כי ע״כ מתרחק מיין ושכר וענבים, שהם בחינת שמאל והמשכת חכמה, שאין להם שום מקום באו״א עלאין, כנ\"ל, שבהם אין \u0003י׳\u0004 יוצאת מאויר, ש \u0003י׳\u0004 זו היא שורש השערות, וע״כ הנזיר גם הוא צריך לגדל השערות שלו."],[5,"","אמנם או״א עצמם, אין להם שערות כלל, כי שערות נמשכות מחסרון חכמה, ובהם אין זה שום חסרון, משום שאין מקבלים חכמה לעצמם לעולם כנ״ל. משא״כ ז״א, כיון שבאמת צריך להארת חכמה, אלא אחר שקבל הארת חכמה ונעברו שערות דקטנות שלו, הוא יכול לפרוש עצמו מחכמה ולהיות כאו״א בחסדים מכוסים ולהחזיק ה \u0003י׳\u0004 באויר שלו כמוהם, אבל משום שמשורשו צריך לחכמה, גורמת לו ה \u0003י׳\u0004 שב \u0003אויר\u0004 הממעטת חכמה, את צמיחת השערות, ובזה יש הפרש בינו לאו״א. וכן הנזיר הנמשך מז״א, יש לו ג״כ שערות מאותו ה \u0003י׳\u0004 שבאויר דאו\"א, אבל סוף סוף כיון שהשערות באות מן ה \u0003י׳\u0004 שבאויר דאו״א הן מורות על \u0003אויר\u0004 א דכיא שמקבל מאו״א, שמשם נמשכת הקדושה. וז״ש, קדוש יהיה גדל פרע שער ראשו. ונתבאר המרחק הגדול בין קדוש לטהור, כי הטהור, כל טהרתו באה מקריחת השערות. והקדוש, כל קדושתו באה מגידול השערות."],[6,"ות״ח כל מאן וכו׳:","ובוא וראה, כל מי שהוא מצד הדין, ודינין נאחזים בו אינו נטהר, עד שנעברות ממנו השערות, וכשנעברות ממנו השערות נטהר. (כמ״ש בדבור הסמוך) ואם תאמר \u0003אדם,\u0004 שה״ס ז״א במוחין דגדלות שיש לו הויה במילוי אלפין שבגימטריא אדם, תאמר ג״כ שצריכים להעביר ממנו השערות. אינו כן. כי הוא שלמות הכל ורחמים נמצאים בו, ומשום זה אינו כן, כי כל הקדושות והקדושים, שהם או״א עלאין, מתיחדים בו. וע״כ אדרבא, גידול השערות הוא כל יפיו, להיותן נמשכות מאוירא דכיא שמקבל מאו״א עלאין אבל זה, שנקרא \u0003איש\u0004 ולא אדם, שהוא ז״א כשהוא בבחינת קטנות וו״ק בחסרון ג״ר, הוא אז דין ודינים מתאחזים בו, דהיינו בשערותיו, ע״כ אינו מתבשם עד שנעברות ממנו השערות."],[7,"ת״ח דהא ליואי וכו׳:","בוא וראה, כי הלוים הבאים מצד הזה של דין, אינם נטהרים עד שנעברים מהם השערות. שכתוב, וכה תעשה להם לטהרם וגו׳ והעבירו תער על כל בשרם וגו'. וכדי שיתבשמו יותר, צריך הכהן, הבא מצד חסד עליון להניף אותם, שכתוב והניף אהרן את הלוים תנופה לפני ה'. כדי לכלול הארת החכמה שבהם בחסדים של הכהן, כמו שהוא אצל \u0003איש\u0004 זה שלמעלה, שהוא ז״א דקטנות, אשר אחר שנקרחו שערותיו ע״י הארת החכמה שקבל (כנ״ל בסולם אות קכ״א) וכאשר הוא רוצה להתבשם יותר, מתגלה בו חסד עליון המלביש החכמה, ומתבסם וכן מבשם הוא. החסד, למטה, בלוים."]],[[0,"","אָמַר רַבִּי יִצְחָק, בּא רְאֵה, כָּל מִי שֶׁהוּא תַּחַת שִׁלְטוֹנוֹ שֶׁל אָדָם, נִקְרָא אִישׁ, מִשּׁוּם שֶׁהִתְתַּקֵּן בְּגָוֶן שֶׁל אָדָם מִדַּרְגָּה אַחֶרֶת שֶׁהָיְתָה לוֹ בָּרִאשׁוֹנָה. שֶׁלָּמַדְנוּ בְּסוֹד עֶלְיוֹן בְּסִפְרָא דִצְנִיעוּתָא, כְּשֶׁנִּבְרָא אָדָם, יָרַד בִּדְמוּת קְדוֹשָׁה עֶלְיוֹנָה, וְיָרְדוּ עִמּוֹ שְׁתֵּי רוּחוֹת מִשְּׁנֵי צְדָדִים, מִיָּמִין וּמִשְּׂמֹאל, הַכְּלָל שֶׁל אָדָם. וְהָרוּחַ שֶׁל הַיָּמִין נִקְרֵאת נְשָׁמָה קְדוֹשָׁה, שֶׁכָּתוּב (בראשית ב) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים. וְהָרוּחַ שֶׁל הַשְּׂמֹאל נִקְרֵאת נֶפֶשׁ חַיָּה, וְהָיְתָה הוֹלֶכֶת וְיוֹרֶדֶת מִמַּעְלָה לְמַטָּה, וְלֹא מִתְיַשֶּׁבֶת עִם הָאַחֶרֶת."],[1,"","כַּאֲשֶׁר נִכְנְסָה הַשַּׁבָּת וְאָדָם הָיָה חוֹטֵא, נַעֲשׂוּ (נשפעו) מֵאוֹתָהּ רוּחַ הַשְּׂמֹאל בְּרִיּוֹת שֶׁמִּתְפַּשְּׁטוֹת בָּעוֹלָם, וְגוּפָם לֹא הִסְתַּיֵּם, וְהִתְחַבְּרוּ עִם גּוּף הָאָדָם הַזֶּה, עִם זָכָר וּנְקֵבָה, וְנוֹלְדוּ בָעוֹלָם. וְאֵלּוּ נִקְרָאִים נִגְעֵי בְּנֵי אָדָם. לָמַדְנוּ, הָעֶלְיוֹנִים מֵהֶם שֶׁלֹּא נִדְבְּקוּ לְמַטָּה וּתְלוּיִים בָּאֲוִיר, וְשׁוֹמְעִים מַה שֶּׁשּׁוֹמְעִים מִלְמַעְלָה, וּמֵהֶם יוֹדְעִים אוֹתָם הָאֲחֵרִים לְמַטָּה."],[2,"","לָמַדְנוּ, מֵהַנִּיצוֹץ הַקָּשֶׁה יוֹצְאִים שְׁלֹשׁ מֵאוֹת וְעֶשְׂרִים וַחֲמִשָּׁה נִיצוֹצוֹת, חֲקוּקִים וַאֲחוּזִים יַחַד מִצַּד הַגְּבוּרָה, שֶׁנִּקְרָאִים גְּבוּרוֹת, (ומתלכדים) יַחַד וְנַעֲשׂוּ אֶחָד (גוף). וּכְשֶׁאֵלֶּה נִכְנָסִים לְגוּף, הוּא נִקְרָא אִישׁ. (ולא איש זה) זֶה שֶׁשָּׁנִינוּ, אִישׁ תָּם וְיָשָׁר אִישׁ צַדִּיק. וְהָאִישׁ שֶׁל כָּאן, כָּתוּב אִישׁ מִלְחָמָה, שֶׁהַכֹּל עוֹלֶה דִין, וְהַכֹּל אֶחָד. אָמַר רַבִּי יְהוּדָה, לָמָּה? לֹא הָיָה בְיָדוֹ (של רבי יצחק) ? בָּאוּ שָׁאֲלוּ לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לָהֶם, עוֹד קָשֶׁה, שֶׁהֲרֵי שָׁנִינוּ שֶׁכָּתוּב, (בראשית ב) לְזֹּאת יִקָּרֵא אִשָּׁה כִּי מֵאִישׁ לֻקֳחָה זֹּאת. וְשָׁנִינוּ, מִי זֶה אִישׁ חֶסֶד, וְכָאן אֲמַרְתֶּם שֶׁהוּא דִּין?"],[3,"","אֶלָּא כָּךְ לָמַדְנוּ, הַכֹּל הוּא בְּמִשְׁקָל אֶחָד עוֹלֶה, וְהַכֹּל אֶחָד. וּמִשּׁוּם שֶׁהַדִּינִים הַתַּחְתּוֹנִים אֲחוּזִים (ומתלכדים) וּמְחֻבָּרִים בְּשַׂעֲרוֹתָיו שֶׁל זֶה, הוּא נִקְרָא הַדִּין הַקָּשֶׁה, וּכְשֶׁעוֹבֵר מִמֶּנּוּ הַשֵּׂעָר שֶׁל הָרֹאשׁ - נִמְתָּק, וְהַדִּינִים שֶׁל מַטָּה לֹא מִזְדַּמְּנִים, וּמִשּׁוּם כָּךְ נִקְרָא טָהוֹר. שֶׁלֹּא נִקְרָא טָהוֹר, אֶלָּא כְּשֶׁיּוֹצֵא מִצַּד הַטֻּמְאָה, וּכְשֶׁיּוֹצֵא מִצַּד הַטֻּמְאָה נִקְרָא טָהוֹר, שֶׁכָּתוּב (איוביד) מִי יִתֵּן טָהוֹר מִטָּמֵא. מִטָּמֵא וַדַּאי, וְכָאן כָּתוּב וְאִישׁ כִּי יִמָּרֵט רֹאשׁוֹ קֵרֵחַ הוּא טָהוֹר הוּא."],[4,"","וּבֹא רְאֵה, בְּרֹאשׁ הָאִישׁ הַזֶּה נִיצוֹץ הַקָּשֶׁה, וּמִשּׁוּם כָּךְ גֻּלְגֹּלֶת הָרֹאשׁ שֶׁל זֶה אֲדֻמָּה כֻּלָּהּ כַּשּׁוֹשַׁנָּה, וְהַשְּׂעָרוֹת אֲדֻמּוֹת בְּתוֹךְ אֲדֻמּוֹת, וּתְלוּיִים מִמֶּנּוּ כְּתָרִים תַּחְתּוֹנִים שֶׁלְּמַטָּה שֶׁמְּעוֹרְרִים דִּינִים בָּעוֹלָם, וּכְשֶׁעוֹבֵר מִמֶּנּוּ הַשֵּׂעָר וְנִגְלָשׁ, מֵהַחֶסֶד הָעֶלְיוֹן הַכֹּל נִמְתָּק, וְנִקְרָא טָהוֹר עַל שְׁמוֹ."],[5,"","אָמַר רַבִּי יְהוּדָה, אִם נִקְרָא עַל שְׁמוֹ - קָדוֹשׁ נִקְרָא וְלֹא טָהוֹר? אָמַר לוֹ, לֹא כָּךְ, שֶׁקָּדוֹשׁ לֹא נִקְרָא אֶלָּא כְּשֶׁהַשֵּׂעָר תָּלוּי, שֶׁהַקְּדֻשָּׁה תְּלוּיָה בַּשֵּׂעָר, שֶׁכָּתוּב (במדבר ו) קָדוֹשׁ יִהְיֶה גַּדֵּל פֶּרַע שְׂעַר רֹאשׁוֹ. וְזֶה נִקְרָא טָהוֹר, מֵהַצַּד שֶׁתְּלוּיִים לְמַטָּה מִמֶּנּוּ. וּמִשּׁוּם כָּךְ עוֹבֵר מִמֶּנּוּ הַשֵּׂעָר וְנִטְהָר."],[6,"","וּבֹא רְאֵה, כָּל מִי שֶׁהוּא מִצַּד הַדִּין וְהַדִּינִים נֶאֱחָזִים בּוֹ, לֹא נִטְהָר, עַד שֶׁעוֹבֵר מִמֶּנּוּ הַשֵּׂעָר. וּמִשֶּׁעוֹבֵר מִמֶּנּוּ הַשֵּׂעָר, נִטְהָר. וְאִם תֹּאמַר אָדָם - לֹא כָּךְ, שֶׁהֲרֵי הוּא שְׁלֵמוּת הַכֹּל, וְנִמְצָאִים בּוֹ רַחֲמִים. מִשּׁוּם כָּךְ לֹא כָּךְ, שֶׁכָּל הַקְּדֻשּׁוֹת וְהַקְּדוֹשִׁים הִתְיַחֲדוּ בוֹ. אֲבָל זֶה - הוּא דִּין, וְהַדִּינִים אֲחוּזִים בּוֹ, לֹא נִמְתָּק עַד שֶׁעוֹבֵר מִמֶּנּוּ הַשֵּׂעָר."],[7,"","בֹּא רְאֵה, שֶׁהֲרֵי הַלְוִיִּם שֶׁבָּאוּ מִצַּד הַדִּין הַזֶּה לֹא נִטְהָרִים עַד שֶׁעוֹבֵר מֵהֶם הַשֵּׂעָר, שֶׁכָּתוּב (שם ח) וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם הַזֵּה עֲלֵיהֶם מֵי חַטָּאת וְהֶעֱבִירוּ תַעַר עַל כָּל בְּשָׂרָם וְגוֹ'. וּכְדֵי שֶׁיֻּמְתְּקוּ יוֹתֵר, צָרִיךְ הַכֹּהֵן, שֶׁהוּא מִצַּד הַחֶסֶד הָעֶלְיוֹן, לְהָרִים אוֹתָם, שֶׁכָּתוּב וְהֵנִיף אַהֲרֹן אֶת הַלְוִיִּם תְּנוּפָה לִפְנֵי ה'. כְּמוֹ שֶׁהוּא לָאִישׁ הַזֶּה שֶׁלְּמַעְלָה, שֶׁכַּאֲשֶׁר רוֹצֶה לְהִתְמַתֵּק יוֹתֵר, מִתְגַּלֶּה בּוֹ חֶסֶד עֶלְיוֹן, וְנִמְתָּק. וּמַמְתִּיק הוּא לְמַטָּה."]]],[["וְהַאי אִישׁ בִּכְלָלָא דְּאָדָם הוּא. וְכַד בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְאַגָּחָא קְרָבָא, בְּהַאי אִישׁ אֲגַח בְּהוּ קְרָבָא, דִּכְתִּיב (שמות ט״ו:ג׳) יְיָ' אִישׁ מִלְחָמָה, בְּהַאי אִישׁ מַמָּשׁ. וְלָא אֲגַח בְּהוּ קְרָבָא, עַד דְּאַעְבָּר לֵיהּ שַׂעֲרָא דְּרֵישָׁא, בְּגִין דְּיִשְׁתַּלְשְׁלוּן מִשִּׁלְשׁוּלֵיהוֹן, וְיִתָּבְּרוּן כָּל אִינּוּן כִּתְרִין דְּמִתְאַחֲדָן בְּשַׂעֲרֵי. הֲדָא הוּא דִכְתִיב, (ישעיהו ז׳:כ׳) בַּיוֹם הַהוּא יְגַלַּח יְיָ' וְגוֹ'. בְּעֶבְרֵי נָהָר בְּמֶלֶךְ אַשּׁוּר אֶת הָרֹאשׁ וְשַׂעַר הָרַגְלָיִם וְגַם אֶת הַזָּקָן תִּסְפֶּה.","תָּאנָא, וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם. מַאי וְכֹה. כְּגַוְונָא דִּלְעֵילָּא, הַזֵּה עֲלֵיהֶם מֵי חַטָּאת, שִׁיּוּרֵי טַלָּא דִּבְדוֹלְחָא הָכָא מֵי חַטָּאת, דְּאִינּוּן שִׁיּוּרֵי טַלָּא. לְזִמְנָא דְּאָתֵי כְּתִיב, (יחזקאל ל״ו:כ״ה) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים. וְכִבְּסוּ בִגְדֵיהֶם, כְּגַוְונָא דִּלְעֵילָּא, דְּתִקוּנוֹי דְּהַאי אִישׁ אִתְסָחָן בְּחֶסֶד עִלָּאָה וְאִתְדַכֵּי מִכֹּלָּא.","וְתָנֵינָן, אֲמַאי כְּתִיב בְּתַעַר וְלֹא בְּמִסְפְּרַיִם. אֶלָּא מִשּׁוּם דְּיִתְעַבָר שַׂעֲרָא בְּשָׁרְשׁוֹי, וְיִתְעֲבְּרוּן מִנֵיהּ דִּינִין תַּתָּאִין מִשּׁוּלְשׁוּלֵיהוֹן. וּלְזִמְנָא דְּיִתְכַּשְׁרוּן עוֹבָדִין לְתַתָּא, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא שַׂעֲרָא דָּא לְאַעְבְּרָא לֵיהּ, וּלְמִגְלְשֵׁיהּ בְּגִין דְּלָא יִצְמַח וְיִרְבֶּה, דִּכְתִּיב כִּי יִמָּרֵט רֹאשׁוֹ.","אָמַר רִבִּי יִצְחָק, רַב מִכָּל לֵיוָאֵי, קֹרַח הֲוָא, דְּעַבְדֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְתַתָּא, כְּגַוְונָא דִּלְעֵילָּא, וְקַרְיֵיהּ קֹרַח. אֵימָתַי. בְּשַׁעֲתָא דְּגָלִישׁ בְּגִינֵיהּ לְהַאי אִישׁ, דִּכְתִּיב קֵרֵחַ הוּא.","וְכַד חָמָא קֹרַח רֵישֵׁיהּ בְּלָא שַׂעֲרָא, וְחָמָא לְאַהֲרֹן מִתְקַשֵּׁט בְּקִשׁוּטֵי מַלְכִין, אִתְזַלְזָל בְּעֵינֵיהּ וְקִנֵּא לְאַהֲרֹן. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אֲנָא עֲבָדִית לָךְ כְּגַוְונָא דִּלְעֵילָּא, לָא בָּעָאת לְאַעְלָאָה בְּעִלָּאִין, חוּת לְתַתָּא וַהֲוִי בְּתַתָּאִין. דִּכְתִּיב, (במדבר ט״ז:ל׳) וְיָרְדוּ חַיִּים שְׁאוֹלָה. מַאי אִיהוּ שְׁאוֹל. גֵּיהִנָּם. דְּתַמָּן צַוְוחִין חַיָּיבִין, וְלֵית מַאן דִּמְרַחֲמֵי עָלַיְיהוּ. וּזְמִינִין אִינּוּן לְאַחֲיָיא וּלְאַעֲלָא, כַּד יִתְּעַר קוּדְשָׁא בְּרִיךְ הוּא לְעַמֵּיהּ, וּלְאַחֲיָיא לְהוּ. דִּכְתִּיב, (שמואל א ב׳:ו׳) יְיָ' מֵמִית וּמְחַיֶּה מוֹרִיד שְׁאוֹל וַיָּעַל.","(ויקרא י״ג:מ״א) וְאִם מִפְּאַת פָּנָיו יִמָּרֵט רֹאשׁוֹ. תָּאנָא, אִית פָּנִים וְאִית פָּנִים, וּמַאן פָּנִים הַלָּלוּ. אִלֵּין אִינּוּן דְּאִקְרוּן פָּנִים שֶׁל זַעַם. וְכָל אִלֵּין דְּתַּלְיָין מֵאִינּוּן פָּנִים חֲצִיפִין, כֻּלְּהוּ תַּקִּיפִין. כֻּלְּהוּ דְּלָא מֵרַחֲמֵי, וְכַד אִתְעַבָּר שַׂעֲרָא מִסִּטְרָא דְּאִינּוּן פָּנִים, מִתְעַבְּרָן כֻּלְּהוּ וְאִתְּבָּרוּ.","דְּתַנְיָא, (קל\"א ע\"ב, קמ\"א) כָּל אִינּוּן דְּתַּלְיָין מִשַּׂעֲרָא דְּרֵישָׁא, אִינּוּן עִלָּאִין עַל אָחֳרָנִין, וְלָא חֲצִיפִין כְּוָותַיְיהוּ. וְכָל אִינּוּן דְּתַּלְיָין מִסִּטְרָא דְּשַׂעֲרָא דְּאִינּוּן פָּנִים, כֻּלְּהוּ חֲצִיפִין וְתַקִיפִין, וּבְגִין כָּךְ אַנְפּוֹי מִתְלַהֲטָן כְּאֶשָּׁא, מִשּׁוּם נִיצוֹצָא דְּבוּצִינָא דְּקַרְדִּינוּתָא. וּבְהַאי כְּתִיב, (איכה ד) פְּנֵי יְיָ' חִלְּקָם. (תהילים ל״ד:י״ז) פְּנֵי יְיָ' בְּעוֹשֵׂי רָע.","אָמַר רִבִּי יִצְחָק מַהוּ נֶגַע לָבָן אֲדַמְדָּם. נֶגַע מַמָּשׁ הוּא, אִי חִוָּורָא אִתְחֲזֵי, וְסוּמָקָא לָא אִתְעַבָּר. מַשְׁמַע דִּכְתִּיב לָבָן אֲדַמְדָּם. אָמַר רִבִּי יוֹסֵי, דְּחִוָּורָא לָא אִתְחֲזֵי אֶלָּא בְּסוּמָקָא, כְּגַוְונָא חִוָּורָא וְסוּמָקָא. רִבִּי יִצְחָק אָמַר, אַף עַל גַּב דְּחִוָּורָא אִתְחֲזֵי, אִי סוּמָקָא לָא אָזִיל, נֶגַע הוּא. דִּכְתִּיב, (ישעיהו א׳:י״ח) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וְכַד אִתְחֲוָּור, כֹּלָּא רַחֲמֵי אִשְׁתְּכָחוּ, וְדִינִין לָא אִשְׁתְּכָחוּ. (ס\"א דהא אתעקרו)","תָּאנֵי רִבִּי אַבָּא, כְּתִיב נֶגַע הוּא, וּכְתִיב נֶגַע הִיא. חַד דְּכַר וְחַד נוּקְבָּא. אֶלָּא כַּד נוּקְבָּא, אִסְתְּאָבַת בְּגִין חוֹבֵי תַּתָּאֵי, כְּתִיב נֶגַע הִיא. וְכַד דְּכַר לָא אִתְדָּכֵי בְּגִין חוֹבֵי תַּתָּאֵי, כְּתִיב נֶגַע הוּא.","וְאִשְׁתְּמוֹדְעָן מִלִּין אִלֵּין לְגַבֵּי כַּהֲנָא, דִּינִין דְּאָתוּ מֵהַאי, וְדִינִין דְּאָתוּ מֵהַאי. וְאִשְׁתְּמוֹדְעָן קָרְבָּנֵי דְּבַעְיָין לְקָרְבָא, דִּכְתִּיב זָכָר תָּמִים. וּכְתִיב נְקֵבָה תְּמִימָה יְבִיאֶנָּה, דְּהָא אִשְׁתְּמוֹדְעָן מִלֵי, מֵאָן אָתוּ דִּינִין, וּמֵאָן אִינּוּן חוֹבֵי. דְּאִתְאַחֲדָן בְּהַאי אוֹ בְּהַאי. וְעַל דָּא כְּתִיב, (תהילים נ״א:י״ט) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה. לְאַפָּקָא שְׁאָר קָרְבְּנִין דְּלָא כְּתִיב רוּחַ נִשְׁבָּרָה, דְּאִינּוּן שְׁלָמָא לְעָלְמָא, וְחֶדְוָה דְּעִלָּאִין וְתַתָּאִין."],[[0,"והאי איש בכללא וכו׳:","והאיש הזה הוא בכלל אדם, דהיינו שהם ב׳ פרצופין של פרצוף אחד, שהוא ז״א, כי \u0003איש\u0004 הוא פרצוף הקטנות שבו, \u0003ואדם\u0004 הוא פרצוף הגדלות שבו, והם מלובשים זה בזה, אדם באיש. וכשרוצה הקדוש ברוך הוא לערוך מלחמה, בפרצוף איש הזה עורך בהם מלחמה, שכתוב, ה׳ \u0003איש\u0004 מלחמה, דהיינו באיש הזה ממש. ואינו עורך עמהם מלחמה, עד שמעביר מעצמו שערות ראש, כדי שירדו מתליתם ואחיזתם, וישברו כל אלו הכתרים של החצוניות התלויות ונאחזות בשערות דז״א שמבחינת איש, ז״ש ביום ההוא יגלח ה׳ וגו׳, בעברי נהר במלך אשור את הראש ושער הרגלים וגם את הזקן תספה. כלומר, כדי להפיל את מלך אשור, יגלח כל השערות העליונים שבהן הם מתאחדים."],[1,"תאנא, וכה תעשה להם לטהרם:","מהו. וכה, היינו כעין של מעלה, כמו בפרצוף איש דז״א, הזה עליהם מי חטאת. היינו שיור טל הבדולח, דהיינו הארת חכמה סתימאה בבינה, שע״י הארה זו חוזרת הבינה להיות חכמה, וכל התחתונים ממנה מקבלים על ידה הארת חכמה, שממנה באה הטהרה, (כנ״ל באות קכ״א) כאן מי חטאת, שהם שיור הטל, \u0003לעתיד לבא.\u0004 כתוב, וזרקתי עליכם מים טהורים. היינו החסדים דאו״א עלאין הנקראים מים טהורים וכן האויר שלהם אוירא דכיא (כנ״ל באות קכ״א) \u0003לעתיד לבא,\u0004 רומז על או״א עלאין. \u0003וכבסו בגדיהם,\u0004 הוא כעין של מעלה, בז״א, שתקונו של \u0003איש\u0004 הזה שכובס בחסד עליון ונטהר מכל. (כנ״ל אות קכ״ג) אף כאן וכבסו בגדיהם, היינו בחסד המכונה מים."],[2,"ותנינן אמאי כתיב וכו׳:","ולמדנו למה כתוב, בתער, ולא במספרים. ומשיב, אלא כדי שהשערות יהיו נעברות בשורשיהן, שהתער מסיר השערות משורשיהן, ויעברו ממנו הדינים התחתונים מאחיזתם בשערותיו. ובזמן שמעשים התחתונים ישרים עתיד הקב״ה להעביר שערות אלו, ולמרוט אותם, כדי שלא יצמח וירבה. שכתוב, כי ימרט ראשו."],[3,"אמר ר׳ יצחק וכו׳:","אר״י, הגדול מכל הלוים הוא קרח, שעשהו הקב״ה למטה כעין \u0003איש\u0004 של מעלה, וקראו קרח, מתי קראו קרח, היינו בשעה שמרט בשבילו ל \u0003איש\u0004 זה של מעלה, שכתוב \u0003איש\u0004 כי ימרט ראשו קרח הוא. (כנ״ל אות קי״ט)."],[4,"וכד חמא קרח וכו׳:","וכשראה קרח את ראשו בלי שערות, וראה את אהרן שמתקשט בקשוטי מלכים, נעשה נקלה בעיניו, וקנא את אהרן. אמר לו הקב״ה, אני עשיתי לך כעין של מעלה, ואינך רוצה לעלות בעליונים להתכלל בקו ימין, כדרך פרצופי הקדושה, (כנ״ל ב״א אות מ״ז ובהסולם) רד למטה והיה בתחתונים, שכתוב, וירדו חיים שאולה. מהו שאול. הוא גיהנם, ששם צועקים הרשעים ואין מי שירחם עליהם. והם עתידים לעמוד לתחיה, ולעלות מגיהנם, בשעה שיעיר הקב״ה את עמו, ויחיה אותם. שכתוב, ה׳ ממית ומחיה מוריד שאול ויעל."],[5,"ואם מפאת פניו ימרט ראשו:","למדנו יש פנים ויש פנים, דהיינו שיש פנים המאירים, בסו״ה יאר ה׳ פניו אליך, ויש פנים חשכים של זעם. ומי הם פנים האלו, שבכתוב, ואם מפאת פניו וגו׳. אלו הם הנקראים פנים של זעם, וכל אלו התלוים מפנים העזים האלו, כולם קשים, כולם אינם מרחמים. וכשנעברות השערות מפאת פנים האלו, נעברים כל אלו החצונים התלוים בהן, ונשברים."],[6,"דתניא כל אינון וכו׳:","שלמדנו, כל אלו החצונים התלוים משערות ראש, הם עליונים על אחרים ואינם חצופים כמוהם. וכל אלו התלוים מפאת השערות של אלו הפנים העזים, כולם חצופים וקשים, ומשום זה פניו לוהטים כאש, משום ניצוץ הקשה שבהם. ובזה כתוב, פני ה׳ חלקם. פני ה׳ בעושי רע."],[6,"","פירוש. כי נתבאר לעיל (בספרא דצניעותא אות ו' בהסולם) ההפרש מבחינת גלגלתא לבחינת פנים, אשר הגלגלתא מתוקנת בסוד \u0003ם׳\u0004 דצלם ואין שם מקום גילוי החכמה, אבל בחינת הפנים ה״ס \u0003ל׳ צ׳\u0004 דצלם, שבהם מתגלה החכמה. ע״ש. ולפיכך בשעה שיש הבוצינא דקרדינותא בראש, יש לחיצונים ב׳ בחינות אחיזות בשערות ראש, א) שמחאחזים בהן, בבחינת חסרון חכמה שיש בגלגלתא. ב) שמתאחזים בהן, בבחינת חסרון חכמה שיש בפנים. ומתוך שבין כך ובין כך אין גילוי חכמה בגלגלתא, ע\"כ אין שם חסרון ניכר, והחיצונים האחוזים מבחינתה, אינם חצופים כל כך, וז״ש, \u0003כל אינון דתליין משערא דרישא,\u0004 דהיינו שנאחזים בבחינת חסרון שיש בגלגלתא, \u0003אינון עלאין על אחרנין ולא חציפין כותייהו.\u0004 משום שאין שם חסרון ניכר, כי בין כך ובין כך אין שם מקום גילוי חכמה. \u0003וכל אינון דתליין מסטרא דשערא דאינון פנים,\u0004 דהיינו אותם המתאחדים בבחינת חסרון חכמה שיש בפנים, \u0003כלהו חציפין ותקיפין,\u0004 כי החסרון ניכר רק בבחינת הפנים, ששם מקום גילוי חכמה. בסו״ה חכמת אדם תאיר פניו, וע״כ הם עזים וחצופים."],[7,"אמר ר׳ יצחק וכו׳:","אר״י, מהו, נגע לבן אדמדם. ומשיב, נגע ממש הוא, אם הלבן נראה, והאדום אינו עובר. זה משמע משכתוב לבן אדמדם. הרי ששניהם נראים שם. אמר ר׳ יוסי, לבן אדמדם פירושו, שהלבן אינו נראה אלא באדום, כמו לבן ואדום ביחד. ר׳ יצחק אמר, שהפירוש הוא כמו שאמר לעיל, שאע\"פ שהלבן נראה, אם האדום אינו הולך משם, נגע הוא. שכתוב, אם יהיו חטאיכם כשנים כשלג ילבינו. כי כשנעשה לבן לגמרי, נמצאים רחמים, והדינים אינם נמצאים."],[7,"","פירוש. לבן הוא חסד, ואדום הוא דין, דהיינו כמ״ש לעיל (באות ק״כ) \u0003ברישא דהאי איש בוצינא דקרדינותא ובגין כד גולגלתא דרישא דהאי סומקא\u0004 וכו', הרי שה \u0003י׳\u0004 שנכנסה באור ונעשה אויר, שה״ס בוצינא דקרדינותא, גורם להראות צבע אדום. ואם ה \u0003י׳\u0004 יוצאת מאויר, וחזר להיות אור, אז הולך לו האודם. ונודע שה \u0003י׳\u0004 הזו שנכנסה באור, ה״ס המסך דבחי״א, שעליו יוצאת קומת חסדים. ובזה נחלקו ר׳ יצחק ור׳ יוסי, שר׳ יצחק סבר, שנקרא נגע מטעם האודם, שה״ס הדינים דחסרון חכמה, ואפילו שיש חסדים אין החסדים מועילים לטהרו עד שתצא ה \u0003י׳\u0004 מאויר, שה״ס הליכת האודם, וד׳ יוסי סבר, שבזמן שהחסדים יוצאים על מסך דבחי״א, שה״ס ה \u0003י׳\u0004 שנכנסה באויר, גם החסדים הם בבחינת דין כמו הגורם אותם. וז״ש ר׳ יוסי, \u0003דחוורא לא אתחזי אלא בסומקא,\u0004 כיון שקומת החסדים אינה נראית אלא מחמת המסך דבחי״א שה\"ס אדום, ע״כ גם הלבן שהוא הסד אינו חשוב יותר ממנו."],[8,"תאני ר׳ אבא וכו׳:","למד ר׳ אבא, כתוב, פעם, נגע הוא, וכתוב פעם נגע היא, שפעם בלשון זכר ופעם בנקבה. ומשיב, אלא כשהנוקבא שהיא המלכות נטמאה בעונות התחתונים, כתוב נגע היא, בלשון נקבה. וכשהזכר אינו נטהר, מחמת עונות התחתונים, שהוא ז״א, (כנ״ל אות קי״ט בהסולם) שהוא במדרגת איש, כתוב נגע הוא בלשון זכר."],[9,"ואשתמודען מלין אלין וכו׳:","ודברים אלו נודעים לכהן אם הדינים באים מזה, מז״א, או שבאים הדינים מזה, ממלכות. ונודעים הקרבנות שצריך להקריב, שכתוב, זכר תמים, וכתוב, נקבה תמימה יביאנה, כי הדברים נודעים לכהן, מאין באו הדינים ומאין הם העונות, אם נאחזים בזה, בדכר, או בזה, בנוקבא. וע״כ כתוב, על קרבנות אלו, זבחי אלקים רוח נשברה. להוציא, שאר הקדמות, שלא כתוב בהם, רוח נשברה, להיותם שלום לעולם ושמחת העליונים ותחתונים."]],[[0,"","וְהָאִישׁ הַזֶּה הוּא בִּכְלָל שֶׁל אָדָם, וּכְשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִלָּחֵם בִּקְרָב, בָּאִישׁ הַזֶּה הוּא נִלְחָם בָּהֶם בִּקְרָב, שֶׁכָּתוּב (שמות טז) ה' אִישׁ מִלְחָמָה, בָּאִישׁ הַזֶּה מַמָּשׁ. וְלֹא נִלְחָם בָּהֶם בִּקְרָב, עַד שֶׁעוֹבֵר לוֹ שְׂעַר הָרֹאשׁ, כְּדֵי שֶׁיִּשְׁתַּלְשְׁלוּ מֵהִשְׁתַּלְשְׁלוּתָם, וְיִשָּׁבְרוּ כָּל אוֹתָם הַכְּתָרִים הָאֲחוּזִים בַּשְּׂעָרוֹת. זֶהוּ שֶׁכָּתוּב (ישעיה ז) בַּיּוֹם הַהוּא יְגַלַּח ה' וְגוֹ', בְּעֶבְרֵי נָהָר בְּמֶלֶךְ אַשּׁוּר אֶת הָרֹאשׁ וְשַׂעַר הָרַגְלָיִם וְגַם אֶת הַזָּקָן תִּסְפֶּה."],[1,"","לָמַדְנוּ, וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם. מַה זֶּה וְכֹה? כְּמוֹ שֶׁלְּמַעְלָה, הַזֵּה עֲלֵיהֶם מֵי חַטָּאת, שִׁיּוּרֵי הַטַּל שֶׁל הַבְּדוֹלַח כָּאן מֵי חַטָּאת, שֶׁהֵם שִׁיּוּרֵי הַטַּל. לֶעָתִיד לָבֹא כָּתוּב, (יחזקאל לז) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים. וְכִבְּסוּ בִגְדֵיהֶם, כְּמוֹ שֶׁלְּמַעְלָה, שֶׁתִּקּוּנֵי הָאִישׁ הַזֶּה רוֹחֲצִים בְּחֶסֶד עֶלְיוֹן, וְנִטְהָר מִן הַכֹּל."],[2,"","וְשָׁנִינוּ, לָמָּה כָּתוּב בְּתַעַר, וְלֹא בְמִסְפָּרַיִם? אֶלָּא, מִשּׁוּם שֶׁיַּעֲבֹר הַשֵּׂעָר בְּשָׁרְשׁוֹ וְיַעַבְרוּ מִמֶּנּוּ הַדִּינִים הַתַּחְתּוֹנִים מֵהִשְׁתַּלְשְׁלוּתָם. וּבִזְמַן שֶׁיֵּכְשְׁרוּ הַמַּעֲשִׂים לְמַטָּה, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִיר לוֹ אֶת הַשֵּׂעָר הַזֶּה וּלְגַלֵּחַ אוֹתוֹ, כְּדֵי שֶׁלֹּא יִצְמַח וְיִרְבֶּה, שֶׁכָּתוּב כִּי יִמָּרֵט רֹאשׁוֹ."],[3,"","אָמַר רַבִּי יִצְחָק, גָּדוֹל מִכָּל הַלְוִיִּם הָיָה קֹרַח, שֶׁעָשָׂה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה, וְקָרָא לוֹ קֹרַח. מָתַי? בְּשָׁעָה שֶׁגִּלַּח בִּשְׁבִילוֹ אֶת הָאִישׁ הַזֶּה, שֶׁכָּתוּב קֵרֵחַ הוּא."],[4,"","וּכְשֶׁרָאָה קֹרַח אֶת רֹאשׁוֹ בְּלִי שֵׂעָר וְרָאָה אֶת אַהֲרֹן מִתְקַשֵּׁט בְּקִשּׁוּטֵי מְלָכִים, הִזְדַּלְזֵל בְּעֵינָיו וְקִנֵּא לְאַהֲרֹן. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: אֲנִי עָשִׂיתִי אוֹתְךְ כְּמוֹ שֶׁלְּמַעְלָה, לֹא רָצִיתָ לַעֲלוֹת לָעֶלְיוֹנִים, רֵד לְמַטָּה וְתִהְיֶה בַתַּחְתּוֹנִים. שֶׁכָּתוּב (במדבר טז) וְיָרְדוּ חַיִּים שְׁאוֹלָה. מַהוּ הַשְּׁאוֹל? גֵּיהִנֹּם, שֶׁשָּׁם צוֹוְחִים הָרְשָׁעִים, וְאֵין מִי שֶׁמְּרַחֲמִים עֲלֵיהֶם. וַעֲתִידִים הֵם לִחְיוֹת וְלַעֲלוֹת כְּשֶׁיְּעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עַמּוֹ וּלְהַחֲיוֹתָם, שֶׁכָתוּב (שמואל א ב) ה' מֵמִית וּמְחַיֶּה מוֹרִיד שְׁאוֹל וַיָּעַל."],[5,"","וְאִם מִפְּאַת פָּנָיו יִמָּרֵט רֹאשׁוֹ. לָמַדְנוּ, יֵשׁ פָּנִים וְיֵשׁ פָּנִים. וּמִי הַפָּנִים הַלָּלוּ? אֵלּוּ הֵם שֶׁנִּקְרָאִים פָּנִים שֶׁל זַעַם. וְכָל אֵלּוּ שֶׁתְּלוּיִים מֵאוֹתָם פָּנִים חֲצוּפִים, כֻּלָּם תַּקִּיפִים, כֻּלָּם לֹא מְרַחֲמִים. וּכְשֶׁעוֹבֵר הַשֵּׂעָר מִצַּד אוֹתָם הַפָּנִים, כֻּלָּם עוֹבְרִים וְנִשְׁבָּרִים."],[6,"","שֶׁלָּמַדְנוּ, כָּל אוֹתָם שֶׁתְּלוּיִים מֵהַשֵּׂעָר שֶׁל הָרֹאשׁ, הֵם עֶלְיוֹנִים עַל הָאֲחֵרִים וְלֹא חֲצוּפִים כְּמוֹתָם, וְכָל אוֹתָם שֶׁתְּלוּיִים מִצַּד הַשֵּׂעָר שֶׁל אוֹתָם הַפָּנִים, כֻּלָּם חֲצוּפִים וְתַקִּיפִים, וּמִשּׁוּם כָּךְ פָּנָיו מְלֹהָטִים כָּאֵשׁ, מִשּׁוּם הַנִּיצוֹץ שֶׁל הַנִּיצוֹץ הַקָּשֶׁה. וּבָזֶה כָּתוּב (איכה ד) פְּנֵי ה' חִלְּקָם. (תהלים לד) פְּנֵי ה' בְּעֹשֵׂי רָע."],[7,"","אָמַר רַבִּי יִצְחָק, מַהוּ נֶגַע לָבָן אֲדַמְדָּם? נֶגַע מַמָּשׁ הוּא, אִם נִרְאֶה לָבָן, וְהָאָדם לֹא עָבַר. מַשְׁמָע שֶׁכָּתוּב לָבָן אֲדַמְדָּם. אָמַר רַבִּי יוֹסֵי, שֶׁהַלָּבָן לֹא נִרְאֶה אֶלָּא עִם אָדם, כְּמוֹ הַלָּבָן וְהָאָדם. רַבִּי יִצְחָק אָמַר, אַף עַל גַּב שֶׁהַלָּבָן נִרְאֶה, אִם הָאָדם לֹא הוֹלֵךְ - נֶגַע הוּא, שֶׁכָּתוּב (ישעיה א) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וּכְשֶׁמַּלְבִּין, כָּל הָרַחֲמִים נִמְצָאִים, וְדִינִים לֹא נִמְצָאִים. (שהרי נעקרו)."],[8,"","לָמַד רַבִּי אַבָּא, כָּתוּב נֶגַע הוּא, וְכָתוּב נֶגַע הִיא. אֶחָד זָכָר וְאֶחָד נְקֵבָה. אֶלָּא כְּשֶׁהַנְּקֵבָה נִטְמֵאת מִשּׁוּם חֲטָאֵי הַתַּחְתּוֹנִים, כָּתוּב נֶגַע הִיא. וּכְשֶׁהַזָּכָר לֹא נִטְהָר מִשּׁוּם חֲטָאֵי הַתַּחְתּוֹנִים, כָּתוּב נֶגַע הוּא."],[9,"","וְהַדְּבָרִים הַלָּלוּ נוֹדָעִים לַכֹּהֵן, הַדִּינִים שֶׁבָּאִים מִזֶּה וְהַדִּינִים שֶׁבָּאִים מִזֶּה. וְנוֹדָעִים הַקָּרְבָּנוֹת שֶׁצָּרִיךְ לְהַקְרִיב, שֶׁכָּתוּב זָכָר תָּמִים, וְכָתוּב נְקֵבָה תְּמִימָה יְבִיאֶנָּה. שֶׁהֲרֵי הַדְּבָרִים נוֹדָעִים מֵאֵיפֹה בָּאוּ הַדִּינִים וּמֵאֵיפֹה אוֹתָם הַחֲטָאִים, שֶׁאֲחוּזִים בָּזֶה אוֹ בָּזֶה. וְעַל כֵּן כָּתוּב, (תהלים נא) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה. לְהוֹצִיא שְׁאָר הַקָּרְבָּנוֹת שֶׁלֹּא כָתוּב רוּחַ נִשְׁבָּרָה, שֶׁהֵם שָׁלוֹם לָעוֹלָם וְשִׂמְחַת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים."]]],[["(ויקרא י״ג:כ״א) וְאִם יִרְאֶנָּה הַכֹּהֵן. תָּאנֵי רִבִּי יוֹסֵי, כְּתִיב (תהילים ס״ה:ג׳) שׁוֹמֵעַ תְּפִלָּה עָדֶיךָ וְגוֹ'. שׁוֹמֵעַ תְּפִלָּה, דָּא קוּדְשָׁא בְּרִיךְ הוּא. רִבִּי חִזְקִיָּה אָמַר, שׁוֹמֵעַ תְּפִלָּה, שׁוֹמֵעַ תְּפִלּוֹת מִבָּעֵי לֵיהּ, מַהוּ שׁוֹמֵעַ תְּפִלָּה. אֶלָּא תְּפִלָּה, דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי תְּפִלָּה, דִּכְתִּיב, (תהילים ק״ט:ד׳) ואֲנִי תְפִלָּה (ס\"א (תהילים ס״ט:י״ד) ואני תפלתי) וְדָוִד בְּגִין כְנֶסֶת יִשְׂרָאֵל קָאָמַר לָהּ. וּמַה דְּאָמַר וַאֲנִי תְפִלָּה, כֹּלָּא חַד, וְעַל דָּא שׁוֹמֵעַ תְּפִלָּה, וְדָא תְּפִלָּה שֶׁל יַד, דִּכְתִּיב, (שמות יג) עַל יָדְכָה בְּהֵ\"א.","עָדֶיךָ כָּל בָּשָׂר יָבוֹאוּ. בְּשַׁעֲתָא דְּגוּפָא שַׁרְיָא בְּצַעֲרָא, בְּמַרְעִין בְּמַכְתְּשִׁין. כְּמָה דְאַתְּ אָמֵר וּבָשָׂר כִּי יִהְיֶה בְעוֹרוֹ. אֶת הַנֶּגַע בְּעוֹר הַבָּשָׂר. הַבָּשָׂר הַחַי. וּבְגִין כָּךְ לָא כְּתִיב, כָּל רוּחַ יָבֹאוּ, אֶלָּא כָּל בָּשָׂר יָבֹאוּ. מַהוּ עָדֶיךָ. אֶלָּא כְּמָה דְּאִתְּמַר, וְהוּבָא אֶל הַכֹּהֵן, דָּא הוּא קוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, וְאִם יִרְאֶנָּה הַכֹּהֵן. תָּא חֲזֵי, בַּאֲתַר חַד אַהֲרֹן הַכֹּהֵן, וּבְאַתְרָא אָחֳרָא הַכֹּהֵן סְתָם, וְדָא קוּדְשָׁא בְּרִיךְ הוּא.","אָמַר רִבִּי יִצְחָק, וְהָא כְּתִיב נֶגַע צָרַעַת כִּי תִהְיֶה בְּאָדָם וְהוּבָא אֶל הַכֹּהֵן, אִי הָכִי דָּא קוּדְשָׁא בְּרִיךְ הוּא. אָמַר לֵיהּ אִין. בְּגִין דְּבֵיהּ תַּלְיָא כָּל דַּכְיוּתָא וְכָל קְדוּשָּׁה. אָמַר לֵיהּ, אִי הָכִי, אֲמַאי וְהוּבָא, וְהוּעֲלָה מִבָּעֵי לֵיהּ. אָמַר לֵיהּ, כְּמָה דְאַתְּ אָמֵר (שמות כ״ז:ז׳) וְהוּבָא אֶת בַּדָּיו בַּטַּבָּעוֹת, דְּעָיִיל דָּא בְּגוֹ דָּא. אוּף הָכָא וְהוּבָא, דְּיִכָּנְסוּן לֵיהּ לְכַהֲנָא, לְדַכְּאָה לֵיהּ (כד אהדר ביה) וְיֵעָלוּן מִלָּה קַמֵּיהּ.","אָמַר רִבִּי יִצְחָק, הָכִי תָּנֵינָן, נֶגַע צָרַעַת. נֶגַע הוּא דִּינָא תַּקִּיפָא שַׁרְיָא בְּעָלְמָא. צָרַעַת: סְגִירוּ. כְּמָה דְאַתְּ אָמֵר, סְגִירוּ דִּנְהוֹרָא עִלָּאָה. סְגִירוּ דְּטִיבוּ עִלָּאָה, דְּלָא נָחִית לְעָלְמָא. כִּי תִהְיֶה בְּאָדָם, בְּאָדָם סְתָם. וְהוּבָא אֶל הַכֹּהֵן. דָּא כֹּהֵן דִּלְתַתָּא, דְּהוּא אִתְתְּקַּן לְמִפְתַּח הַהוּא סְגִירוּ, וּלְאֲדְלָקָא בּוּצִינִיָא דְּיִשְׁתְּכָחוּ עַל יְדוֹי בִּרְכָן לְעֵילָּא וּלְתַתָּא. וְיִתְעֲבָר וְיִסְתָּלַק הַהוּא נֶגַע, וְיִשְׁרֵי נְהִירוּ דְּרַחֲמֵי עַל כֹּלָּא, וּבְגִין כָּךְ וְהוּבָא אֶל הַכֹּהֵן.","אָמַר רִבִּי אַבָּא, חֲמֵינָא לְאִינְהוּ בְּנֵי עָלְמָא, דְּלָא מַשְׁגְּחָן, וְלָא יַדְעִין בִּיקָרָא דְּמָארֵיהוֹן, כְּתִיב בְּהוּ בְּיִשְׂרָאֵל, (ויקרא כ׳:כ״ד) אֲשֶׁר הִבְדַּלְתִּי אֶתְכֶם מִן הָעַמִּים לִהְיוֹת לִי. וּכְתִיב, (ויקרא כ׳:כ״ד) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים כִּי קָדוֹשׁ אָנִי יְיָ'. אִי אִינּוּן מִתְרַחֲקָן, אָן הוּא קְדוּשָּׁה דִּלְהוֹן, הָא רְעוּתָא דִּלְהוֹן אִתְרַחֲקַת מִנֵּיהּ. וּקְרָא אַכְרִיז וְאָמַר, (תהילים ל״ב:ט׳) אַל תִּהְיוּ כְּסוּס כְּפֶרֶד אֵין הָבִין, בְּמָה אִתְפָּרְשָׁן בְּנֵי נָשָׁא מִסּוּס וָפֶרֶד, בִּקְדוּשָּׁה דְּגַרְמַיְיהוּ, לְאִשְׁתַּכְּחָא שְׁלֵימִין וּרְשִׁימִין מִכֹּלָּא.","וְעַל דָּא זִוּוּגָא דִּבְנֵי נָשָׁא הוּא בְּזִמְנִין יְדִיעָן, לְכַוְּונָא רְעוּתָא לְאִתְדַּבְּקָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. וְהָא אִתְּעֲרוּ, בְּפַלְגוּת לֵילְיָא קוּדְשָׁא בְּרִיךְ הוּא עָאל בְּגִנְתָּא דְּעֵדֶן, לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּיא, וּכְּנֶסֶת יִשְׂרָאֵל מְשַׁבַּחַת לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, וְהִיא שַׁעֲתָא דִּרְעוּתָא לְאִתְדַּבְּקָא בְּהוּ.","וְחַבְרַיָּיא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, מִשְׁתַּתְּפֵי בָּהּ בִּכְּנֶסֶת יִשְׂרָאֵל, לְשַׁבְּחָא לְמַלְכָּא קַדִּישָׁא, וְאִתְעַסְּקָן בְּאוֹרַיְיתָא, שְׁאָר בְּנֵי נָשָׁא כְּדֵין עִידָּן רְעוּתָא לְאִתְקַדְּשָׁא בִּקְדוּשָּׁה דְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְכַוְּונָא רְעוּתָא לְאִתְדַּבְּקָא בֵּיהּ. וְאִינּוּן חַבְרַיָּיא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא זִוּוּגָא דִּלְהוֹן בְּשַׁעֲתָא דְּזִוּוּגָא אָחֳרָא אִשְׁתְּכַח, וְהַאי מִשַּׁבָּת לְשַׁבָּת לְכַוְּונָא רְעוּתָא לְאִתְדַּבְּקָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא וּבִכְנֶסֶת יִשְׂרָאֵל, דְּהוּא עִידָּן רְעוּתָא דְּמִתְבָּרְכָן כֹּלָּא עִלָּאֵי וְתַתָּאֵי.","אִי בְּנֵי נָשָׁא אִתְרַחֲקוּ מִנֵּיהּ, וְעַבְדָּן כִּבְעִירֵי, אָן הוּא קְדוּשָּׁה דִּלְהוֹן, לְאִשְׁתַּכְּחָא קַדִּישִׁין. אָן אִינּוּן נַפְשָׁאָן קַדִּישִׁין דְּמָשְׁכָן מֵעֵילָּא. וּשְׁלֹמֹה מַלְכָּא צָוַוח וְאָמַר, (משלי י״ט:ב׳) גַּם בְּלֹא דַּעַת נֶפֶשׁ לֹא טוֹב. גַּם בְּלֹא דַּעַת, מַאן הוּא דַּעַת. דָּא קוּדְשָׁא בְּרִיךְ הוּא. נֶפֶשׁ לֹא טוֹב, דָּא הוּא נֶפֶשׁ, דְּאִינּוּן מַשְׁכִין בְּעוֹבָדַיְיהוּ, לֹא טוֹב, דְּהָא מִסִּטְרָא אָחֳרָא אִתְמַשְּׁכָאן עָלַיְיהוּ נַפְשָׁתָא דְּלָאו אִיהוּ טוֹב, בְּגִין דְּלָא מְכַוְּונֵי לִבַּיְיהוּ לְּקוּדְשָׁא בְּרִיךְ הוּא.","מַאן דְּאִתְלְהִיט בְּיֵצֶר הָרָע, בְּלָא רְעוּתָא וְכַוָּונָה דְּלִבָּא לְּקוּדְשָׁא בְּרִיךְ הוּא. מִסִּטְרָא דְּיֵצֶר הָרָע אִתְמְשַׁךְ עָלֵיהּ נַפְשָׁא, דְּלָאו אִיהִי טוֹב, הֲדָא הוּא דִכְתִיב גַּם בְּלֹא דַּעַת נֶפֶשׁ לֹא טוֹב וְאָץ בְּרַגְלַיִם חוֹטֵא. מַאן דְּאִיהוּ אָץ בְּרַגְלַיִם וְדָחֵי שַׁעֲתָא בְּלָא רְעוּתָא קַדִּישָׁא, חוֹטֵא. חוֹטֵא וַדַּאי, בְּכֹלָּא.","וְעַל דָּא שַׁרְיָין מַכְתְּשִׁין בִּישִׁין בִּבְנֵי נָשָׁא, וְאַסְהִידוּ בְּאַנְפַּיְיהוּ בַּחֲצִיפוּתָא דִּלְהוֹן, לְאַחֲזָאָה דְּהָא קוּדְשָׁא בְּרִיךְ הוּא מָאִיס בְּהוּ, וְלָאו דַּעְתֵּיהּ בְּהוֹן, עַד דְּאִינּוּן זַכָּאן וּמַכְשְׁרָאן עוֹבָדַיְיהוּ כְּמִלְּקַדְּמִין, וּמִתְבָּרְכָן (ס\"א ומתדכאן). וְעַל דָּא אִשְׁתְּמוֹדְעָן מַכְתְּשִׁין לְגַבֵּי כַּהֲנָא, אִינּוּן דְּאַתְיָין מִסִּטְרָא דִּמְסָאֲבָא, וְאִינּוּן דְּאַתְיָין מִסִּטְרָא אָחֳרָא."],[[0,"ואם יראנה הכהן:","למד ר׳ יוסי, כתוב, שומע תפלה עדיך וגו׳. שומע תפלה זהו הקב״ה. דהיינו ז״א, רבי חזקיה אמר, \u0003שומע תפלה,\u0004 שומע תפלות היה צריך לומר, מהו, שומע תפלה. ומשיב, אלא תפלה, זו היא כנסת ישראל, דהיינו המלכות, שהיא נקראת \u0003תפלה,\u0004 שכתוב, \u0003ואני תפלה.\u0004 ודוד אמר זה, בשביל כנסת ישראל, ומה שאמר \u0003ואני תפלה,\u0004 הכל אחד, כי המלכות, היא נקראת \u0003אני,\u0004 והיא נקראת \u0003תפלה,\u0004 ועל זה נאמר, \u0003שומע תפלה,\u0004 שהיא המלכות. וזו היא תפלה של יד, שכתוב בה \u0003על ידכה\u0004 ב \u0003ה׳\u0004 לבסוף, שיורה על המלכות."],[1,"עדיך כל בשר יבואו:","היינו בשעה שהגוף שורה בצער ובמחלות ובנגעים, כש״א, ו \u0003בשר\u0004 כי יהיה בעורו. את הנגע בעור ה \u0003בשר\u0004. ה \u0003בשר\u0004 החי, ומשום זה לא כתוב, עדיך כל רוח יבואו, אלא כל \u0003בשר\u0004 יבואו. מהו עדיך. אלא הוא כמו שלמדנו, והובא אל הכהן. זה הוא הקב״ה. ז״ש, ואם יראנה הכהן. שהוא הקב״ה, בוא וראה, במקום אחד כתוב, אהרן הכהן, ובמקום אחר, הכהן סתם, ואינו כתוב אהרן, וזהו הקב״ה."],[2,"א\"ר יצחק וכו׳:","אר״י, והרי כתוב, נגע צרעת כי תהיה באדם והובא אל הכהן, וא״כ, הוא, הקב״ה. אמר לו כן. שהוא הקב״ה, משום שבהקב״ה תלויה כל טהרה וכל קדושה. אמר לו, א״כ, למה נאמר והובא, והועלה אל הכהן, היה צריך לומר כי להקב״ה נוהג עליה, ולא ביאה. א״ל הוא כש״א, והובא את בדיו בטבעות, שפירושו שמביא זה בתוך זה, אף כאן, והובא, פירושו, שמכניס אותו אל הקב״ה שנקרא כהן, כדי לטהר אותו, ויביאו הדבר לפניו."],[3,"א״ר יצחק הכי וכו׳:","אר״י, כך למדנו, \u0003נגע צרעת,\u0004 נגע, פירושו דין קשה השורה בעולם. צרעת. פירושו סגירה, כמו שלמדנו, שהיא סגירה של אור העליון, סגירה של טוב העליון שאינו יורד לעולם. \u0003כי תהיה באדם,\u0004 באדם סתם שיורה הן על אדם שלמעלה והן על אדם שלמטה. \u0003והובא אל הכהן,\u0004 היינו הכהן שלמטה, שהוא נתתקן שיפתח אותה הסגירה. ולהדליק הנרות, שהם הספירות, שימצאו על ידיו ברכות למעלה ולמטה, ויהיה נעבר ויסתלק אותו הנגע, וישרה אור הרחמים על כולם, ומשום זה, והובא אל הכהן."],[4,"א״ר אבא חמינא וכו׳:","אר״א, רואה אני אותם בני העולם, שאינם מסתכלים ואינם יודעים בכבוד אדונם, כתוב בישראל, אשר הבדלתי אתכם מן העמים להיות לי. וכתוב, והתקדשתם והייתם קדושים כי קדוש אני ה׳. ואם הם מתרחקים מהקב״ה, איפה היא הקדושה שלהם, הרי רצונם מתרחק ממנו. והכתוב מכריז ואומר, אל תהיו כסוס כפרד אין הבין. כי במה נבדלים בני אדם מסוס ופרד, הוא רק בקדושה שלהם, להמצא שלמים ומצוינים מכל."],[5,"ועל דא זווגא וכו׳:","וע\"כ זווג בני אדם הוא בזמנים ידועים, לכוון רצונם להתדבק בהקב״ה. והרי העירו, שבחצות לילה הקב״ה נכנס לגן עדן להשתעשע עם הצדיקים, וכנסת ישראל, שהיא המלכות, משבחת להקב״ה. והיא שעת רצון להתדבק בהם, בהקב״ה ושכינתו."],[6,"וחברייא דמשתדלי וכו׳:","והחברים העוסקים בתורה, מתחברים עם כנסת ישראל, לשבח להקב״ה, ועוסקים בתורה ושאר בני אדם הוא אז שעת רצון להתקדש בקדושת הקב״ה, דהיינו בזווג. ולכוון הרצון להתדבק בו. ואלו החברים העוסקים בתורה, הזווג שלהם הוא בשעה שזווג אחר, העליון, נמצא. שזהו משבת לשבת, לכוון הרצון להתדבק בהקב\"ה ובכנסת ישראל. כי היא שעת רצון שמתברכים הכל, העליונים והתחתונים."],[7,"אי בני נשא וכו׳:","אם בני אדם מתרחקים מהקב״ה, ועושים כבהמות, איפה היא הקדושה שלהם, שיהיו נמצאים קדושים, איפה הם הנפשות הקדושות שמושכים מלמעלה. ושלמה המלך צווח ואמר, גם בלא דעת נפש לא טוב. \u0003גם בלא דעת,\u0004 מי הוא דעת. זה הוא הקב״ה. \u0003נפש לא טוב,\u0004 זו היא נפש שהם מושכים במעשיהם. \u0003לא טוב,\u0004 משום שמסטרא אחרא נמשכת עליהם הנפש, שהיא אינה טובה, משום שאינם מכוונים לבם להקב״ה."],[8,"מאן דאתלהיט ביצר וכו׳:","מי שמתלהט ביצר הרע, בלי רצון וכוונת הלב להקב״ה, הרי מצד היצר הרע נמשכת עליו נפש שאינה טובה, ז״ש גם בלא דעת נפש לא טוב. ואץ ברגלים חוטא, מי שהוא \u0003אץ ברגלים,\u0004 ודוחה את השעה, דהיינו שאינו רואה שתהיה השעה כשרה לכך, אלא שהוא בלא רצון קדוש, \u0003חוטא,\u0004 שהוא חוטא ודאי, בכל."],[9,"ועל דא שריין וכו׳:","וע״כ שורים נגעים רעים בבני אדם, ומעידים בפניהם בחוצפה שלהם, להראות, שהקב״ה מואס בהם, ודעתו אינה להם, עד שיהיו זכאים, ויטיבו מעשיהם כמקודם, ומתברכים. ועל זה, ניכרים הנגעים אל הכהן, אותם שהם באים מצד הטומאה, ואותם שהם באים מסטרא אחרא."]],[[0,"","וְאִם יִרְאֶנָּה הַכֹּהֵן. שָׁנָה רַבִּי יוֹסֵי, כָּתוּב (תהלים סה) שֹׁמֵעַ תְּפִלָּה עָדֶיךְ וְגוֹ'. שֹׁמֵעַ תְּפִלָּה - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי חִזְקִיָּה אָמַר, שּמֵעַ תְּפִלָּה?! שׁוֹמֵעַ תְּפִלּוֹת הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה שּמֵעַ תְּפִלָּה? אֶלָּא תְּפִלָּה זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא תְּפִלָּה, שֶׁכָּתוּב (שם קט) וַאֲנִי תְפִלָּה. ((תהלים סט) ואני תפלתי) וְדָוִד אָמַר אוֹתָהּ בִּשְׁבִיל כְּנֶסֶת יִשְׂרָאֵל. וּמַה שֶּׁאָמַר וַאֲנִי תְפִלָּה, הַכֹּל אֶחָד, וְעַל זֶה שֹׁמֵעַ תְּפִלָּה, וְזוֹ תְּפִלָּה שֶׁל יָד, שֶׁכָּתוּב (שמות יג) עַל יָדְכָה, בְּהֵ\"א."],[1,"","עָדֶיךָ כָּל בָּשָׂר יָבאוּ - בְּשָׁעָה שֶׁהַגּוּף שָׁרוּי בְּצַעַר, בְּמַחֲלוֹת וּמַכּוֹת, כְּמוֹ שֶׁנֶּאֱמַר וּבָשָׂר כִּי יִהְיֶה בְעוֹרוֹ. אֶת הַנֶּגַע בְּעוֹר הַבָּשָׂר. הַבָּשָׂר הַחַי. וּמִשּׁוּם כָּךְ לֹא כָתוּב כָּל רוּחַ יָבאוּ, אֶלָּא כָּל בָּשָׂר יָבֹאוּ. מַה זֶּה עָדֶיךְ? אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר וְהוּבָא אֶל הַכֹּהֵן, זֶה הוּא הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב וְאִם יִרְאֶנָּה הַכֹּהֵן. בֹּא רְאֵה, בְּמָקוֹם אֶחָד אַהֲרֹן הַכֹּהֵן, וּבְמָקוֹם אַחֵר הַכֹּהֵן סְתָם, וְזֶה הַקָּדוֹשׁ בָּרוּךְ הוּא."],[2,"","אָמַר רַבִּי יִצְחָק, וַהֲרֵי כָּתוּב נֶגַע צָרַעַת כִּי תִהְיֶה בְּאָדָם וְהוּבָא אֶל הַכֹּהֵן, אִם כָּךְ, זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא? אָמַר לוֹ, כֵּן, מִשּׁוּם שֶׁבּוֹ תְלוּיָה כָּל טָהֳרָה וְכָל קְדֻשָּׁה. אָמַר לוֹ, אִם כָּךְ, לָמָּה וְהוּבָא? וְהָעֳלָה הָיָה צָרִיךְ לִהְיוֹת! אָמַר לוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שם כז) וְהוּבָא אֶת בַּדָּיו בַּטַּבָּעֹת, שֶׁמַּכְנִיס זֶה לְתוֹךְ זֶה. אַף כָּאן וְהוּבָא, שֶׁיִּכָּנְסוּ לַכֹּהֵן לְטַהֵר אוֹתוֹ (כשחוזר בו) וְיַכְנִיסוּ דָבָר לְפָנָיו."],[3,"","אָמַר רַבִּי יִצְחָק, כָּךְ שָׁנִינוּ, נֶגַע צָרַעַת: נֶגַע - הוּא הַדִּין הַקָּשֶׁה הַשָּׁרוּי בָּעוֹלָם. צָרַעַת - הַסְגָּרָה, כְּמוֹ שֶׁנֶּאֱמַר הֶסְגֵּר הָאוֹר הָעֶלְיוֹן. הֶסְגֵּר שֶׁל הַטּוֹב הָעֶלְיוֹן שֶׁלֹּא יוֹרֵד לָעוֹלָם. כִּי תִהְיֶה בְּאָדָם - בְּאָדָם סְתָם. וְהוּבָא אֶל הַכֹּהֵן - זֶה הַכֹּהֵן שֶׁלְּמַטָּה, וְהוּא מְתֻקָּן לִפְתֹּחַ אוֹתוֹ הַסֶּגֶר וּלְהַדְלִיק מְאוֹרוֹת, שֶׁיִּמָּצְאוּ עַל יָדוֹ בְּרָכוֹת לְמַעְלָה וּלְמַטָּה, וְיַעֲבֹר וְיִסְתַּלֵּק אוֹתוֹ הַנֶּגַע, וְיִשְׁרֶה אוֹר שֶׁל רַחֲמִים עַל הַכֹּל, וּמִשּׁוּם כָּךְ וְהוּבָא אֶל הַכֹּהֵן."],[4,"","אָמַר רַבִּי אַבָּא, רָאִיתִי אוֹתָם בְּנֵי הָעוֹלָם שֶׁלֹּא מַשְׁגִּיחִים וְלֹא יוֹדְעִים בִּכְבוֹד רִבּוֹנָם. כָּתוּב בְּיִשְׂרָאֵל, (ויקרא כ) אֲשֶׁר הִבְדַּלְתִּי אֶתְכֶם מִן הָעַמִּים לִהְיוֹת לִי. וְכָתוּב (שם) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים כִּי קָדוֹשׁ אֲנִי ה'. אִם הֵם מִתְרַחֲקִים, אֵיפֹה הַקְּדֻשָּׁה שֶׁלָּהֶם? הֲרֵי רְצוֹנָם הִתְרַחֵק מִמֶּנּוּ, וְהַכָּתוּב מַכְרִיז וְאוֹמֵר, (תהלים לב) אַל תִּהְיוּ כְּסוּס כְּפֶרֶד אֵין הָבִין. בַּמֶּה נִפְרָדִים בְּנֵי אָדָם מִסּוּס וּפֶרֶד? בִּקְדֻשַּׁת עַצְמָם, שֶׁיִּמָּצְאוּ שְׁלֵמִים וּרְשׁוּמִים מֵהַכֹּל."],[5,"","וְעַל כֵּן זִוּוּגָם שֶׁל בְּנֵי אָדָם הוּא בִּזְמַנִּים יְדוּעִים, לְכַוֵּן הָרָצוֹן לְהִדָּבֵק בַּקָּדוֹשׁ בָּרוּךְ הוּא. וַהֲרֵי הֵעִירוּ, בַּחֲצוֹת הַלַּיְלָה הַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לְגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים, וּכְנֶסֶת יִשְׂרָאֵל מְשַׁבַּחַת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהִיא עֵת רָצוֹן לִדְבֹּק בָּהֶם."],[6,"","וְהַחֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, מִשְׁתַּתְּפִים עִם כְּנֶסֶת יִשְׂרָאֵל לְשַׁבֵּחַ אֶת הַמֶּלֶךְ הַקָּדוֹשׁ, וּמִתְעַסְּקִים בַּתּוֹרָה לִשְׁאָר בְּנֵי הָאָדָם, אָז עֵת רָצוֹן לְהִתְקַדֵּשׁ בִּקְדֻשַּׁת הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְכַוֵּן רָצוֹן לִדְבֹּק בּוֹ. וְאוֹתָם הַחֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, הַזִּוּוּג שֶׁלָּהֶם בְּשָׁעָה שֶׁנִּמְצָא זִוּוּג אַחֵר, וְזֶה מִשַּׁבָּת לְשַׁבָּת, לְכַוֵּן הָרָצוֹן לִדְבֹּק בַּקָּדוֹשׁ בָּרוּךְ הוּא וּבִכְנֶסֶת יִשְׂרָאֵל, שֶׁהִיא עֵת רָצוֹן שֶׁהַכֹּל מִתְבָּרְכִים, הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים."],[7,"","אִם בְּנֵי אָדָם הִתְרַחֲקוּ מִמֶּנּוּ וְעוֹשִׂים כַּבְּהֵמוֹת, אֵיפֹה הַקְּדֻשָּׁה שֶׁלָּהֶם שֶׁיִּמָּצְאוּ קְדוֹשִׁים? אֵיפֹה הַנְּפָשׁוֹת הַקְּדוֹשׁוֹת שֶׁמּוֹשְׁכִים מִלְּמַעְלָה? וּשְׁלֹמֹה הַמֶּלֶךְ צוֹוֵחַ וְאוֹמֵר, (משלי יט) גַּם בְּלֹא דַעַת נֶפֶשׁ לֹא טוֹב. גַּם בְּלֹא דַעַת, מִי הוּא הַדַּעַת? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. נֶפֶשׁ לֹא טוֹב - זוֹהִי הַנֶּפֶשׁ שֶׁהֵם מוֹשְׁכִים בְּמַעֲשֵׂיהֶם. לֹא טוֹב, שֶׁהֲרֵי מֵהַצַּד הָאַחֵר נִמְשָׁכוֹת עֲלֵיהֶם נֶפֶשׁ שֶׁאֵינָהּ טוֹב, מִשּׁוּם שֶׁלֹּא מְכַוְּנִים לִבָּם לַקָּדוֹשׁ בָּרוּךְ הוּא."],[8,"","מִי שֶׁמִּתְלַהֵט בַּיֵּצֶר הָרָע בְּלִי רָצוֹן וְכַוָּנַת הַלֵּב לַקָּדוֹשׁ בָּרוּךְ הוּא, מֵהַצַּד שֶׁל יֵצֶר הָרָע נִמְשֶׁכֶת עָלָיו נֶפֶשׁ שֶׁאֵינָהּ טוֹב. זֶהוּ שֶׁכָּתוּב גַּם בְּלֹא דַעַת נֶפֶשׁ לֹא טוֹב וְאָץ בְּרַגְלַיִם חוֹטֵא. מִי שֶׁהוּא אָץ בָּרַגְלַיִם וְדוֹחֶה אֶת הַשָּׁעָה בְּלִי רָצוֹן קָדוֹשׁ - חוֹטֵא, חוֹטֵא וַדַּאי בַּכֹּל."],[9,"","וְעַל זֶה שׁוֹרוֹת מַכּוֹת רָעוֹת בִּבְנֵי אָדָם, וּמְעִידִים בִּפְנֵיהֶם עַל חֻצְפָּתָם, לְהַרְאוֹת שֶׁהִנֵּה הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹאֵס בָּהֶם וְאֵין דַּעְתּוֹ בָּהֶם, עַד שֶׁהֵם זוֹכִים וּמַכְשִׁירִים אֶת מַעֲשֵׂיהֶם כְּמִקֹּדֶם וּמִתְבָּרְכִים (ומטהרים). וְעַל זֶה נוֹדָעוֹת הַמַּכּוֹת לַכֹּהֵן, אוֹתָן שֶׁבָּאוֹת מִצַּד הַטֻּמְאָה וְאוֹתָן שֶׁבָּאוֹת מֵהַצַּד הָאַחֵר."]]],[["כְּגַוְונָא דָּא כְּתִיב, כִּי תָבֹאוּ אֶל אֶרֶץ כְּנַעַן וְגוֹ', וְנָתַתִּי נֶגַע צָרַעַת בְּבֵית אֶרֶץ אֲחוּזַּתְכֶם. וְכִי אֲגָר טַב הוּא, דְּיִשְׁתְּכַח בְּאִינּוּן דְּזַכָּאן לְמֵיעָל בְּאַרְעָא. אֶלָּא הָא אוּקְמוּהָ לְאַשְׁכְּחָא מַטְמוֹנִין דְּאַטְמְרָן בְּבֵיתַיְיהוּ, וּלְאַהֲנָאָה לוֹן לְיִשְׂרָאֵל.","אֲבָל תָּא חֲזֵי, זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּאִינּוּן מִתְדַּבְּקָן בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְקוּדְשָׁא בְּרִיךְ הוּא רָחִים לְהוּ, דִּכְתִּיב, (מלאכי א׳:ב׳) אָהַבְתִּי אֶתְכֶם אָמַר יְיָ'. וּמִגּוֹ רְחִימוּתָא דִּילֵיהּ, אָעִיל לְהוּ לְאַרְעָא קַדִּישָׁא, לְאַשְׁרָאָה שְׁכִינְתֵּיהּ בֵּינַיְיהוּ, וּלְמֶהֱוִי דִּיּוּרֵיהּ עִמְּהוֹן, וְיִשְׂרָאֵל דְּיִשְׁתַּכְּחוּן קַדִּישִׁין עַל כָּל בְּנֵי עָלְמָא.","תָּא חֲזֵי, כְּתִיב (שמות ל״ה:כ״ו) וְכָל הַנָּשִׁים אֲשֶׁר נָשָׂא לִבָּן וְגוֹ'. בְּשַׁעֲתָא דַּהֲווֹ עַבְדִּין עֲבִידְתָּא, הֲווֹ אַמְרֵי, דָּא לְמַקְדְּשָׁא. דָּא לְמַשְׁכְּנָא. דָּא לְפָרוֹכְתָּא. וְכֵן כָּל אִינּוּן אוּמְנִין בְּגִין דְּיִשְׁרֵי קְדוּשָּׁה עַל יְדַיְיהוּ, וְאִתְקַדַּשׁ הַהוּא עֲבִידְתָּא. וְכַד סָלִיק לְאַתְרֵיהּ, בִּקְדוּשָּׁה סָלִיק.","כְּגַוְונָא דָּא מַאן דְּעָבִיד עֲבִידְתָּא לְעֲבוֹדָה זָרָה, אוֹ לְסִטְרָא אָחֳרָא, דְּלָא קַדִּישָׁא. כֵּיוָן דְּאִדְכַּר לֵיהּ עַל הַהוּא עֲבִידְתָּא, הָא רוּחַ מִסְאֲבָא שַׁרְיָא עֲלוֹי, וְכַד סָלִיק עֲבִידְתָּא, בִּמְסָאֲבָא סָלִיק. כְּנַעֲנִיִם פַּלְחֵי לְעֲבוֹדָה זָרָה אִינְהוּ, וּמִתְדַּבְּקָן כֻּלְּהוּ כַּחֲדָא בְּרוּחַ מִסְאֲבָא בְּעֲבוֹדָה זָרָה, וַהֲווּ בִּנְיָין בָּנִין לְפַרְצוּפַיְיהוּ (ס\"א לטנופייהו) וּלְגִעוּלַיְיהוּ לִסְטַר מִסְאֲבָא לְעֲבוֹדָה זָרָה, וְכַד שָׁרָאן לְמִבְנֵי, הֲווֹ אַמְרֵי מִלָּה, וְכֵיוָן דְּאִתְדְּכָר בְּפוּמַיְיהוּ, סָלִיק עָלֵיהּ רוּחַ מִסְאֲבָא. כַּד אִסְתָּלִיק עֲבִידְתָּא, בְּרוּחַ מִסְאֲבָא אִסְתָּלִיק.","כֵּיוָן דְּעָאלוּ יִשְׂרָאֵל לְאַרְעָא, בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְדַכְּאָה לוֹן, וּלְקַדְּשָׁא לוֹן אַרְעָא, וּלְאַפְנָאָה אֲתַר לִשְׁכִינְתָּא דְּלָא תִּשְׁרֵי שְׁכִינְתָּא גּוֹ מִסְאֲבָא. וְעַל דָּא בְּהַהוּא נֶגַע צָרַעַת, הֲווֹ סָתְרִין בִּנְיָינִין דְּאָעִין וַאֲבָנִין דְּאִתְעָבֵידוּ בִּמְסָאֲבוּ.","תָּא חֲזֵי, אִי עוֹבָדָא דָּא הֲוָה לְאַשְׁכְּחָא מַטְמוֹנִין בִּלְחוֹדוֹי, יְהַדְרוּן אֲבָנִין לְבָתַר כְּמָה דְּאִינּוּן לְאַתְרַיְיהוּ, וְעַפְרָא לְאַתְרֵיהּ. אֲבָל קְרָא כְּתִיב, וְחִלְּצוּ אֶת הָאֲבָנִים. וּכְתִיב וְעָפָר אַחֵר יִקַּח. בְּגִין דְּיִתְעַבָּר רוּחַ מִסְאֲבָא, וְיִתְפְּנֵי וְיִתְקַדַּשׁ הַשְׁתָּא כְּמִלְּקַדְּמִין, וְיִשְׁתְּכָחוּ יִשְׂרָאֵל בִּקְדוּשָּׁה, וּבְדִיּוּרָא קַדִּישָׁא, לְמִשְׁרֵי בֵּינַיְיהוּ שְׁכִינְתָּא.","וְעַל דָּא מַאן דְּבָנֵי בִּנְיָן כַּד שָׁארֵי לְמִבְנֵי, בָּעֵי לְאַדְכְּרָא בְּפוּמֵיהּ, דְּהָא לְפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא הוּא בָּנֵי. בְּגִין דִּכְתִּיב, (ירמיהו כ״ב:י״ג) הוֹי בּוֹנֶה בֵיתוֹ בְּלֹא צֶדֶק וְגוֹ', וּכְדֵין סִיַּיעְתָּא דִּשְׁמַיָּא שָׁארֵי עֲלוֹי, וְקוּדְשָׁא בְּרִיךְ הוּא זַמִּין עָלֵיהּ קְדוּשָׁתָא, וְקָארִי עָלֵיהּ שָׁלוֹם, הֲדָא הוּא דִכְתִיב, (איוב ה׳:כ״ד) וְיָדַעְתָּ כִּי שָׁלוֹם אָהֳלֶךָ וְגוֹ'. מַהוּ (איוב ה׳:כ״ד) וּפָקַדְתָּ נָוְךָ, הָא אוּקְמוּהָ, אֲבָל וּפָקַדְתָּ, לְאַפְקְדָא מִלָּה בְּפוּמָא כַּד אִיהוּ בָּנֵי. וּכְדֵין וְלֹא תֶחֱטָא כְּתִיב. וְאִי לָאו הָא זַמִּין לְבֵיתֵיהּ סִטְרָא אָחֳרָא.","כָּל שֶׁכֵּן, מַאן דְּבָנֵי וּרְעוּתֵיהּ בְּגַוְונָא אָחֳרָא, בְּגִין דִּמְיַחֵד בֵּיתָא לְסִטְרָא אָחֳרָא, לְאִסְתַּאֲבָא בֵּיהּ. הָא וַדַּאי שַׁרְיָא בֵּיהּ רוּחַ מִסְאֲבָא, וְלָא נָפִיק הַהוּא בַּר נָשׁ מֵעָלְמָא, עַד דְּאִתְעֲנָשׁ בְּהַהוּא בֵּיתָא, וּמַאן דְּדָיִיר בֵּיהּ, יָכִיל לְאַתְזְקָא, דְּהָא הַהוּא דִּירָה רוּחַ מִסְאֲבָא שַׁרְיָא בֵּיהּ, וְאָזִיק מַאן דְּאִשְׁתְּכַח בֵּיהּ.","וְאִי תֵּימָא בְּמַה יְדִיעַ. כְּגוֹן דְּאִתְּזַק בְּהַהוּא בֵּיתָא, הַהוּא דְּבָנֵי לָהּ, אוֹ אַנְשֵׁי בֵּיתֵיהּ, אוֹ בְּנִזְקֵי דְּגוּפָא, אוֹ בְּנִזְקֵי מָמוֹנָא, הוּא וּתְרֵין אָחֳרָנִין אֲבַתְרֵיהּ. הָא וַדַּאי יַעֲרוֹק בַּר נָשׁ לְטוּרָא, וְלָא יָדוּר בֵּיהּ. יָדוּר בְּטִיחֲלָא דְּעַפְרָא, וְלָא יָדוּר בֵּיהּ.","וּבְגִין כַּךְ, קוּדְשָׁא בְּרִיךְ הוּא חָס עָלַיְיהוּ דְּיִשְׂרָאֵל, דְּאִינּוּן לָא יַדְעִין מִלָּה בְּכָל אִינּוּן בָּתֵי. וְהוּא אָמַר, אַתּוּן לָא יַדְעִין, אֲנָא יְדַעְנָא, וְאַרְשִׁימְנָא לוֹן בְּנֶגַע. נֶגַע דָּיִיר בְּבֵיתָא, הָא נֶגַע אָחֳרָא תַּקִּיפָא, דְּיָפִּיק לֵיהּ, וְיַּעֲבַּר לֵיהּ מִן עָלְמָא. וּכְדֵין וְנָתַץ אֶת הַבַּיִת אֶת אֲבָנָיו וְאֶת עֵצָיו. כֵּיוָן דְּאָזִיל לֵיהּ, מַאי טַעֲמָא וְנָתַץ אֶת הַבַּיִת. אֶלָּא בְּכָל זִמְנָא דְּהַהוּא בִּנְיָן לִהֱוִי קַיָּים, דִּילֵיהּ הוּא, וְיָכִיל לְאָהַדְּרָא."],[[0,"כגוונא דא כתיב וכו׳:","כעין זה כתוב, כי תבאו אל ארץ כנען וגו׳. ונתתי נגע צרעת בבית ארץ אחוזתכם. שואל, וכי הוא זה שכר טוב שימצאו נגעים בבתים של אלו שזכו לכנוס לארץ. ומשיב, אלא הרי העמידוהו, שהוא, כי אחר שיתצו הבתים המנוגעים, ימצאו אוצרות שהצפינו הכנענים בבתיהם, ויהנו מהם ישראל. (ויק״ר פי״ז ו׳)."],[1,"אבל ת״ח זכאין וכו׳:","אבל בוא וראה, אשריהם ישראל שהם דבקים בהקב״ה, והקב״ה אוהב אותם, שכתוב, אהבתי אתכם אמר ה'. ומתוך אהבתו, הכניסם לארץ הקדושה, להשרות שכינתו ביניהם, ולדור עמהם, ושימצאו ישראל קדושים מכל בני העולם."],[2,"ת״ח כתיב וכל וכו׳:","בוא וראה, כתוב, וכל הנשים אשר נשא לבן וגו׳. היינו, בשעה שהיו עושות מלאכתן, היו אומרות, זה למקדש, זה למשכן, זה לפרכת, וכן עשו כל האומנים, כדי שתשרה הקדושה על ידיהם, ותתקדש המלאכה ההיא, וכאשר הביאוה למקומה עלתה והיתה בקדושה."],[3,"כגוונא דא מאן וכו׳:","כעין זה מי שעובד עבודה לעבודה זרה, או לצד האחר שאינו קדוש, כיון שמזכירה על עבודה ההיא, הנה רוח הטומאה שורה עליו, וכשעולה העבודה, היא עולה בטומאה. הכנענים, עובדי עבודה זרה היו, וכולם יחד היו דבוקים ברוח הטומאה בעבודה זרה, והיו בונים בנינים לפרצופיהם ולתועבתם של צד הטומאה, לעבודה זרה, וכשהתחילו לבנות, היו אומרים איזה דבר, וכיון שנזכר בפיהם, עלה על הבנין רוח הטומאה. וכשעלתה העבודה, עלתה ברוח הטומאה."],[4,"כיון דעאלו ישראל וכו׳:","כיון שבאו ישראל לארץ, רצה הקב״ה לטהר למענם ולקדש למענם את הארץ, ולפנות מקום לשכינה, כדי שלא תשרה השכינה במקום טמא. וע״כ בנגע צרעת ההוא היו הורסים הבנינים של עצים ואבנים שנעשו בטומאה."],[5,"ת״ח אי עובדא וכו׳:","בוא וראה, אם מעשה זה, של נתיצת הבתים המניגעים, היה כדי למצוא אוצרות בלבד, היו צריכים אח״כ להחזיר האבנים למקומן כמו שהיו, וכן היו צריכים להחזיר העפר למקומו. אבל המקרא כתוב, וחלצו את האבנים. וכתוב ועפר אחר יקח. שהוא, כדי להעביר את רוח הטומאה, ותפונה, ותתקדש עתה הארץ כמקודם, וימצאו ישראל בקדושה, ובדיור קדוש, שתשרה ביניהם השכינה."],[6,"ועל דא מאן וכו׳:","וע״כ מי שבונה בנין, כשמתחיל לבנותו, צריך להזכיר בפיו, שבונה אותו לעבודת הקב״ה, משום שכתוב, הוי בונה ביתו בלא צדק, ואז עזרת השמים שורה עליו, על ביתו, והקב״ה מכין עליו קדושתו, וקורא עליו שלום. ז״ש וידעת כי שלום אהלך ופקדת נוך ולא תחטא מהו \u0003ופקדת נוך,\u0004 הרי העמידוהו, אבל, \u0003ופקדת,\u0004 פירושו, לפקוד דבור בפיו כשהוא בונה. דהיינו שיאמר בפיו שבונה אותו לעבודת הקב״ה כנ״ל. ואז כתוב, \u0003ולא תחטא,\u0004 ואם לא, הרי סטרא אחרא מוכן לשרות על ביתו."],[7,"כ״ש מאן דבני וכו׳:","כל שכן מי שבונה, ורצונו הוא באופן אחר, כי מיחד ביתו לצד האחר, להטמא בו, הרי ודאי שורה בו רוח הטומאה, ואדם ההוא אינו נפטר מן העולם עד שנענש באותו בית, ומי שיושב בו יכול להנזק, כי רוח הטומאה שורה בדירה ההיא, ומזיק את מי שנמצא בה."],[8,"ואי תימא במה וכו׳:","ואם תאמר במה ידוע, אם הבונה אותו המשיך שם רוח הטומאה. היינו אם נזוק בבית ההוא מי שבנה אותו, או בני ביתו, הן בנזקי הגוף הן בנזקי כסף, וכן נזוקו שני שכנים אחריו שישבו בו, אז ודאי יברח האדם להר, ולא ישב בו, ישב במערת עפר ולא ישב בו."],[9,"ובגין כך קב״ה וכו׳:","ומשום זה הקב״ה חס על ישראל, שהם אינם יודעים דבר, בכל אלו הבתים שמצאו בארץ, אם יש שם רוח הטומאה או לא, והקב״ה אמר, אתם אינכם יודעים, אני יודע, ואציין אותם בנגע. נגע יושב בבית, שהוא הסטרא אחרא, הרי נגע אחר תקיף, ששלחתי שם, שיוציאו ויעבירו מן העולם. ואז, ונתץ את הבית את אבניו ואת עציו. שואל, כיון שהנגע הלך לו, מכח נגע האחר שהוציאו, מה הטעם, ונתץ את הבית, הרי הס״א כבר הלך משם. ומשיב אלא בכל זמן שהבנין ההוא יהיה עומד, שלו הוא, של הס״א, ויכול לחזור."],[9,"","ביאור המאמר. הבונה בית צריך לבנותו ב \u0003צדק,\u0004 דהיינו שיהיה מרכבה של השכינה שנקראת בית, ונקראת צדק, והיינו בסוד הארת חכמה שבה, בסו״ה בחכמה יבנה בית. וז״ש (באות ק״ז) \u0003בעי לאדכרא בפומיה דהא לפולחנא דקב\"ה הוא בני,\u0004 ואם לא, הסטרא אחרא נמשך אל הבית, ורוח הטומאה של הס״א שורה בו, שהוא לעומת רוח הקדוש של השכינה. ועליו כתוב, \u0003הוי בונה ביתו בלא צדק,\u0004 שהוא השכינה הנקראת צדק. וההפרש בין הס״א אל השכינה, הוא, כי תקון הארת החכמה שבמלכות הוא שתאיר ממטה למעלה, כהכרעת קו האמצעי כנ״ל (ב״א דף ס׳ ד״ה מחלוקת) והסטרא אחרא ממשיך החכמה ממעלה למטה, ומפריד השמאל מן הימין. ואותם הבתים של הכנענים שבנו ביתם לסטרא אחרא ועבודה זרה, שכן בהם רוח הזה דס״א מקו שמאל, וע״כ דינין דקו שמאל הקשים יש שם שמזיקים בני אדם. וז״ש (באות קנ״א) \u0003ומאן דדייר ביה יכיל לאתזקא דהא\u0004 וכו׳, דהיינו שדינין דקו שמאל יזיקו לו."],[9,"","ונודע שבעת שקו השמאל נפרד מן הימין אין עצה להכניעו ולהחזירו לימין אלא ע״י התעוררות הדינים ממסך דחירק, שה״ס להעלות המלכות למקום בינה הממעט את קו שמאל מג\"ר דחכמה, (כנ\"ל לך י״ג ד״ה ונתבאר) וסוד הנגעים נמשכים ג״כ מדינין אלו דעלית המלכות למקום בינה, כנ״ל (באות קל״א) שה״ס ה \u0003י׳\u0004 שנכנסה \u0003לאור\u0004 והאור נתמעט ל \u0003אויר\u0004 ע״ש."],[9,"","וזה אמרו \u0003קב״ה חס עלייהו\u0004 וכו׳ \u0003וארשימנא לון בנגע, נגע דייר בביתא הא נגע אחר תקיפא דיפיק ליה\u0004 וכו׳ כיון שנגע של השראת הסטרא אחרא ישנו בבית, שהוא הארת השמאל ממעלה למטה בפירוד מן הימין, \u0003הא נגע אחר,\u0004 שהוא הנגע ששולח הקב״ה בבתים אלו, הנמשכים מן \u0003י׳\u0004 שנכנסה לאור, הממעט קו השמאל מחכמה. והס״א יוצא מן הבית, כי אין לו כח עוד להמשיך מה משמאל הנפרד. וז״ש, \u0003דיפיק ליה ויעבר ליה מן עלמא,\u0004 כי כיון שממעט קו השמאל שהוא כחו של הס״א, נמצא שיוצא, לא לבד מן הבית, אלא \u0003מן עלמא,\u0004 שנתבטלה כולה. אמנם אחר שהנגע נתגבר על רוח הטומאה ובטלו, הרי נשאר הנגע בבית, ואין מי שיבטלו וז\"ש, \u0003בכל זמנא דחהוא בנין להוי קיים\u0004 וכו' (ועי׳ מצורע אות מ״ט)."]],[[0,"","כְּמוֹ זֶה כָּתוּב, כִּי תָבֹאוּ אֶל אֶרֶץ כְּנַעַן וְגוֹ', וְנָתַתִּי נֶגַע צָרַעַת בְּבֵית אֶרֶץ אֲחֻזַּתְכֶם. וְכִי שָׂכָר טוֹב הוּא שֶׁיִּמָּצֵא בְאוֹתָם שֶׁזּוֹכִים לְהִכָּנֵס לָאָרֶץ? אֶלָּא הִנֵּה פֵּרְשׁוּהָ, לִמְצֹא מַטְמוֹנִים שֶׁהִטְמִינוּ בְּבֵיתָם, וְלֵהָנוֹת בָּהֶם אֶת יִשְׂרָאֵל."],[1,"","אֲבָל בּא רְאֵה, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהֵם מִתְדַּבְּקִים לַקָּדוֹשׁ בָּרוּךְ הוּא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֵב אוֹתָם, שֶׁכָּתוּב (מלאכי א) אָהַבְתִּי אֶתְכֶם אָמַר ה'. וּמִתּוֹךְ אַהֲבָתוֹ הִכְנִיס אוֹתָם לָאָרֶץ הַקְּדוֹשָׁה, לְהַשְׁרוֹת שְׁכִינָתוֹ בֵּינֵיהֶם, וְשֶׁיִּהְיֶה דִיּוּרוֹ עִמָּהֶם, וְיִשְׂרָאֵל שֶׁיִּמָּצְאוּ קְדוֹשִׁים עַל כָּל בְּנֵי הָעוֹלָם."],[2,"","בֹּא רְאֵה, כָּתוּב (שמות לה) וְכָל הַנָּשִׁים אֲשֶׁר נָשָׂא לִבָּן וְגוֹ'. בְּשָׁעָה שֶׁהָיוּ עוֹשִׂים מַעֲשֶׂה, הָיוּ אוֹמְרִים: זֶה לַמִּקְדָּשׁ, זֶה לַמִּשְׁכָּן, וְזֶה לַפָּרֹכֶת. וְכֵן כָּל אוֹתָם הָאָמָּנִים, כְּדֵי שֶׁתִּשְׁרֶה קְדֻשָּׁה עַל יְדֵיהֶם, וּמִתְקַדֶּשֶׁת אוֹתָהּ עֲבוֹדָה. וּכְשֶׁעוֹלֶה לִמְקוֹמוֹ, עוֹלֶה בִקְדֻשָּׁה."],[3,"","כְּמוֹ כֵן מִי שֶׁעוֹשֶׂה עֲבוֹדָה לַעֲבוֹדָה זָרָה אוֹ לַצַּד הָאַחֵר שֶׁאֵינוֹ קָדוֹשׁ, כֵּיוָן שֶׁמַּזְכִּיר אוֹתוֹ עַל אוֹתוֹ הַמַּעֲשֶׂה, הֲרֵי רוּחַ טֻמְאָה שׁוֹרָה עָלָיו. וּכְשֶׁעוֹלֶה הַמַּעֲשֶׂה, עוֹלֶה בְטֻמְאָה. הַכְּנַעֲנִיִּים הֵם עוֹבְדֵי עֲבוֹדָה זָרָה, וּמְדֻבָּקִים כֻּלָּם יַחַד בְּרוּחַ טֻמְאָה בַּעֲבוֹדָה זָרָה, וְהָיוּ בּוֹנִים בִּנְיָן לְפַרְצוּפֵיהֶם (לטנופיהם) וּלְגִעוּלֵיהֶם לַצַּד הַטָּמֵא לַעֲבוֹדָה זָרָה. וּכְשֶׁמַּתְחִילִים לִבְנוֹת, הָיוּ אוֹמְרִים דִּבּוּר. וְכֵיוָן שֶׁנִּזְכָּר בְּפִיהֶם, עוֹלָה עָלָיו רוּחַ שֶׁל טֻמְאָה. כְּשֶׁעוֹלֶה הַמַּעֲשֶׂה, הוּא עוֹלֶה בְּרוּחַ טֻמְאָה."],[4,"","כֵּיוָן שֶׁנִּכְנְסוּ יִשְׂרָאֵל לָאָרֶץ, רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְטַּהֵר אוֹתָם וּלְקַדֵּשׁ לָהֶם אֶת הָאָרֶץ, וּלְפַנּוֹת מָקוֹם לַשְּׁכִינָה, שֶׁלֹּא תִשְׁרֶה הַשְּׁכִינָה בְּתוֹךְ הַטֻּמְאָה. וְעַל כֵּן בְּאוֹתוֹ נֶגַע צָרַעַת הָיוּ סוֹתְרִים בִּנְיָנִים שֶׁל עֵצִים וַאֲבָנִים שֶׁנַּעֲשׂוּ בְטֻּמְאָה."],[5,"","בֹּא רְאֵה, אִם הַמַּעֲשֶׂה הַזֶּה הָיָה לִמְצֹא מַטְמוֹנִים בִּלְבַד, יַחֲזִירוּ הָאֲבָנִים אַחַר כָּךְ כְּמוֹת שֶׁהֵם לִמְקוֹמָם, וְהֶעָפָר לִמְקוֹמוֹ. אֲבָל הַפָּסוּק כּוֹתֵב, וְחִלְּצוּ אֶת הָאֲבָנִים. וְכָתוּב וְעָפָר אַחֵר יִקַּח. כְּדֵי שֶׁתַּעֲבֹר רוּחַ הַטֻּמְאָה, וְיִתְפַּנֶּה וְיִתְקַדֵּשׁ כָּעֵת כְּמִקֹּדֶם, וְיִמָּצְאוּ יִשְׂרָאֵל בִּקְדֻשָּׁה וּבְדִיּוּר קָדוֹשׁ, לְהַשְׁרוֹת בֵּינֵיהֶם שְׁכִינָה."],[6,"","וְעַל כֵּן, מִי שֶׁבּוֹנֶה בִּנְיָן, כְּשֶׁמַּתְחִיל לִבְנוֹת צָרִיךְ לְהַזְכִּיר בְּפִיו, שֶׁהֲרֵי לַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא בּוֹנֶה, מִשּׁוּם שֶׁכָּתוּב (ירמיה כב) הוֹי בּנֶה בֵיתוֹ בְּלֹא צֶדֶק וְגוֹ'. וְאָז סִיּוּעַ שְׁמֵימִי שׁוֹרֶה עָלָיו, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַזְמִין עָלָיו קְדֻשָּׁה וְקוֹרֵא עָלָיו שָׁלוֹם. זֶהוּ שֶׁכָּתוּב (איוב ה) וְיָדַעְתָּ כִּי שָׁלוֹם אָהֳלֶךְ וְגוֹ'. מַה זֶּה וּפָקַדְתָּ נָוְךְ? הֲרֵי פֵּרְשׁוּהָ. אֲבָל וּפָקַדְתָּ, לְהַפְקִיד דִּבּוּר בַּפֶּה כְּשֶׁהוּא בּוֹנֶה. וְאָז כָּתוּב וְלֹא תֶחֱטָא. וְאִם לֹא, הֲרֵי מַזְמִין לְבֵיתוֹ אֶת הַצַּד הָאַחֵר."],[7,"","כָּל שֶׁכֵּן מִי שֶׁבּוֹנֶה, וּרְצוֹנוֹ בְּצוּרָה אַחֶרֶת, מִשּׁוּם שֶׁמְּיַחֵד הַבַּיִת לַצַּד הָאַחֵר לְהִטָּמֵא בּוֹ, הֲרֵי וַדַּאי שׁוֹרָה בּוֹ רוּחַ שֶׁל טֻמְאָה, וְלֹא יוֹצֵא אוֹתוֹ אָדָם מִן הָעוֹלָם עַד שֶׁנֶּעֱנָשׁ בַּבַּיִת הַהוּא. וּמִי שֶׁדָּר בּוֹ יָכוֹל לְהִנָּזֵק, שֶׁהֲרֵי בַּדִּירָה הַהִיא שׁוֹרָה בָּהּ רוּחַ טֻמְאָה, וּמַזִּיקָה מִי שֶׁנִּמְצָא בָּהּ."],[8,"","וְאִם תֹּאמַר, בַּמֶּה יָדוּעַ? כְּגוֹן שֶׁנִּזּוֹק בַּבַּיִת הַהוּא אוֹתוֹ שֶׁבָּנָה אוֹתוֹ, אוֹ אַנְשֵׁי בֵיתוֹ, אוֹ בְּנִזְקֵי גוּף, אוֹ בְּנִזְקֵי מָמוֹן, הוּא וּשְׁנֵי אֲחֵרִים אַחֲרָיו. הֲרֵי וַדַּאי יִבְרַח אָדָם לְהַר, וְלֹא יָדוּר בּוֹ. יָדוּר בִּמְחִלַּת עָפָר, וְלֹא יָדוּר בּוֹ."],[9,"","וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל יִשְׂרָאֵל, שֶׁהֵם לֹא יוֹדְעִים דָּבָר בְּכָל אוֹתָם הַבָּתִּים, וְהוּא אוֹמֵר: אַתֶּם לֹא יוֹדְעִים - אֲנִי יוֹדֵעַ, וְרָשַׁמְתִּי אוֹתָם בְּנֶגַע. נֶגַע דָּר בְּבַיִת, הִנֵּה נֶגַע אַחֵר תַּקִּיף שֶׁיּוֹצִיא אוֹתוֹ וְיַעֲבִיר אוֹתוֹ מִן הָעוֹלָם. וְאָז - וְנָתַץ אֶת הַבַּיִת אֶת אֲבָנָיו וְאֶת עֵצָיו. כֵּיוָן שֶׁהוֹלֵךְ לוֹ, מָה הַטַּעַם וְנָתַץ אֶת הַבַּיִת? אֶלָּא בְּכָל זְמַן שֶׁאוֹתוֹ בִּנְיָן יִהְיֶה קַיָּם - שֶׁלּוֹ הוּא, וְיָכוֹל לַחֲזֹּר."]]],[["הַאי בְּאַרְעָא קַדִּישָׁא, כָּל שֶׁכֵּן בְּאַרְעָא אָחֳרָא, דִּזְמִינָא רוּחַ מִסְאֲבָא יַתִּיר, וְיָכִיל בַּר נָשׁ לְאִתְזְקָא. אָמַר רִבִּי אֶלְעָזָר, וְכָּל שֶׁכֵּן דְּאִקְרֵי בִּקְלִפּוֹי דְּחַבְרוֹי אָחֳרָנִין, לְאִשְׁתַּכְּחָא תַּמָּן, וַאֲפִילּוּ טוּרְפֵי דְּקַסְפְּתָא לָא מַעְבְּרָן לֵיהּ מֵהַהוּא בֵּיתָא, וּבְגִין כָּךְ הַאי קְרָא אַכְרִיז וְאָמַר, הוֹי בּוֹנֶה בֵיתוֹ בְּלֹא צֶדֶק. הוֹי וַדַּאי קָאַמְרֵי כָּל יוֹמָא בְּהַהוּא בֵּיתָא.","רִבִּי יוֹסֵי עָאל חַד יוֹמָא בְּחַד בֵּיתָא, מָטָא בַּסִּפְתָא (ס\"א אטרח בטיפסא), עָאל לְגוֹ. שָׁמַע חַד קָלָא דְּאָמַר, אִתְכְּנָשׁוּ עוּלוּ, הָא חַד פְּלוּגְתָּא דִּילָן. סִיפְתוּ וְנָנְזִיק לֵיהּ עַד לָא יִנְפּוֹק, אָמְרוּ, לָא נֵיכוּל אֶלָּא אִי דִּיּוּרֵיהּ הָכָא. נָפַק רִבִּי יוֹסֵי וְדָחִיל. אָמַר, ודַּאי מַאן דְּאַעְבָּר עַל מִלּוֹי דְּחַבְרַיָּיא, אִתְחַיָּיב בְּנַפְשֵׁיהּ.","אָמַר לֵיהּ רִבִּי חִיָיא, וְהָא גּוֹיִם וּשְׁאָר בְּנֵי נָשָׁא דַּיְּירֵי בְּגַוִּיהּ, וְאִשְׁתְּלִימוּ. אָמַר לֵיהּ, אִינּוּן מִסִּטְרַיְיהוּ קָא אַתְיָין, אֲבָל מַאן דְּדָחִיל חַטָּאָה, יָכִיל לְאַתְזְקָא. וַאֲפִילּוּ אִינּוּן, אִי יְעַכְּבוּ דִּיּוּרֵיהוֹן בֵּיהּ, לָא יִפְקוּן בִּשְׁלָם. אָמַר לֵיהּ, וְהָא כְּתִיב (איוב כ״א:ט׳) בָּתֵּיהֶם שָׁלוֹם מִפָּחַד. אָמַר לֵיהּ כְּגוֹן דְּהֲוָה מֵאָחֳרָא, וְאִתְבְּנֵי מִצֶּדֶק. וְקְרָא הָכִי הוּא, בָּתֵּיהֶם שָׁלוֹם מִפָּחַד, כְּשֶׁבָּתֵּיהֶם שָׁלוֹם מִפָּחַד שֵׁבֶט אֱלוֹהַּ לָא שַׁרְיָא עֲלֵיהֶם.","(ויקרא י״ד:ל״ה) וּבָא אֲשֶׁר לוֹ הַבַּיִת וְהִגִּיד וְגוֹ'. וְהִגִּיד, וַיֹּאמֶר מִבָּעֵי לֵיהּ, אוֹ וַיְדַבֵּר, מַהוּ וְהִגִּיד. אֶלָּא בְּכָל אֲתַר מִלָּה דְּחָכְמְתָא הוּא, וְהָא אוּקְמוּהָ. כְּנֶגַע נִרְאָה לִי בַּבַּיִת, כְּנֶגַע, נֶגַע מִבָּעֵי לֵיהּ. נִרְאָה לִי, יֵשׁ לִי מִבָּעֵי לֵיהּ. דְּהָא כְּתִיב, וְנָתַתִּי נֶגַע צָרַעַת בְּבֵית אֶרֶץ אֲחֻזַתְכֶם, דְּיִתְחֲזֵי לְכֹלָּא. אֲמַאי כְּנֶגַע נִרְאָה לִי.","אֶלָּא בְּשַׁעֲתָא דְּהַאי עַיִּיל, אָחֳרָא אִתְגַּלְיָא. וּמְקַטְרְגָא דָּא בְּדָא. וְעַל דָּא נִרְאָה לִי, הַהוּא דְּאִתְכַּסֵּי אִתְגַּלְיָא, וּדְאִתְגַּלְיָא אִתְכַּסֵּי, וּלְבָתַר מִתְחֲזֵי לֵיהּ בְּדִיּוּקְנָא דְּהַהוּא נֶגַע דְּבֵיתָא, וְאִתְכַּסְּיָא אָחֳרָא. וְעַל דָּא וְהִגִּיד לַכֹּהֵן, דְּמִלָּה דְּחָכְמְתָא הִיא.","וּכְדֵין אָתֵי כַּהֲנָא, וְיִרְמוּן בֵּיתָא, וְיִנְתְּצוּן לֵיהּ אֲבָנִין וְאָעִין וְכֹלָּא. כֵּיוָן דְּאִנְתְּצָן וְאִתְדָּכָן כֹּלָּא, מִתְבָּרְכָאן, כְּדֵין כְּתִיב, (דברים ח׳:י״ב) וּבָתִּים טוֹבִים תִּבְנֶה וְיָשָׁבְתָּ. אִלֵּין אִקְרוּן טוֹבִים, דְּהָא קַדְמָאֵי לָאו אִינּוּן טוֹבִים, וְלָאו בִּכְלָלָא דִּקְדוּשָּׁה וְדַכְיוּ נִינְהוּ.","אָמַר רִבִּי יְהוּדָה, אִי הָכִי בְּמַאי מוּקְמֵינָן קְרָא דִּכְתִּיב, (דברים ו׳:י״א) וּבָתִּים מְלֵאִים כָּל טוּב אֲשֶׁר לֹא מִלֵּאתָ. אִי רוּחַ מִסְאֲבָא שַׁרְיָא בְּגַוַויְיהוּ הֵיךְ מְלֵאִים כָּל טוּב. אָמַר רִבִּי אֶלְעָזָר, מְלֵאִים כָּל טוּב: בְּמָמוֹנָא, בְּכַסְפָּא, וּבְדַהֲבָא, וּבְכֹלָּא. כְּמָה דְאַתְּ אָמֵר (בראשית מ״ה:ח׳) כִּי טוּב כָּל אֶרֶץ מִצְרַיִם. וְאָמַר רִבִּי יְהוּדָה, וְהָא כָּל בָּתֵּי דְּמִצְרָאֵי, מַלְּיָין חַרְשִׁין וְטַעֲוָון הֲווֹ. אֶלָּא בְּגִין עוּתְרָא דְּאַרְעָא אִתְּמַר. אוּף הָכָא בְּגִין עוּתְרָא וּמָמוֹנָא הוּא.","תְּרֵין עוּתְרִין נַטְלוּ יִשְׂרָאֵל, חַד כַּד נָפְקוּ מִגָּלוּתָא דְּמִצְרַיִם. וְחַד כַּד עָאלוּ לְאַרְעָא. רִבִּי שִׁמְעוֹן אָמַר, כָּל דָּא וַדַּאי הֲוָה לְאִתְקַדְשָׁא אַרְעָא, וּלְאַעְבְּרָא רוּחַ מִסְאֲבָא מֵאַרְעָא, וּמִגּוֹ יִשְׂרָאֵל. וְכַד בֵּיתָא הֲוָה נָתִיץ, הֲוָה אִשְׁתְּכַח בָּהּ מָמוֹנָא, לְמִבְנֵי לֵיהּ, וּלְמַלְיָא בֵּיתֵיהּ, בְּגִין דְּלָא יִצְטָעֵר עַל בֵּיתָא, וְיִשְׁרוּן בְּדִיּוּרָא דִּקְדוּשָּׁה.","(ויקרא י״ג:ל״ח) וְאִישׁ אוֹ אִשָּׁה כִּי יִהְיֶה בְעוֹר בְּשָׂרָם בֶּהָרוֹת וְגוֹ'. רִבִּי יוֹסֵי אָמַר, כְּסִילְתָּא דְּמוֹקְפֵי בְּבַהֶרֶת עַזָּה, חֵיזוֹ תָּנֵינָא, וּבְחֵיזוֹ אִתְּדָּן, בְּאִינּוּן גַּוְונִין. אָמַר רִבִּי יִצְחָק ש' טַעְמֵי אִית מַאן דְּגָרִיס בְּבַהֶרֶת עַזָּה. וְכֻלְּהוּ אוֹלִיפְנָא מֵאַבָּא, בַּר חֵיזוּר (חיור) חַד סָאִיב, סָהֲדָא חַד. תְּרֵין, תְּרֵי סַהֲדֵי, וְדָכֵי. מִכָּאן וּלְהָלְאָה, אֲפִילּוּ מֵאָה כִּתְרֵי, וּתְרֵי כְּמֵאָה. וְדָא אוֹלִיפְנָא לְבָתַר דִּכְתִּיב, (דברים י״ט:ט״ו) לֹא יָקוּם עֵד אֶחָד בְּאִישׁ וְגוֹ', עַל פִּי שְׁנַיִם עֵדִים וְגוֹ'.","רִבִּי חִזְקִיָּה הֲוָה יָתִיב קַמֵּיהּ דְּרִבִּי שִׁמְעוֹן, אָמַר, כְּתִיב נֶגַע לָבָן אֲדַמְדָּם, כְּדֵין הוּא נֶגַע, דְּהָא חִוָּורָא לָא קָאִים בְּעֵינֵיהּ. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, כְּתִיב (ישעיהו א׳:י״ח) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים וְגוֹ', זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְדַכְּאָה לוֹן בְּכֹלָּא, בְּגִין דְּלָא יִשְׁתַּכְּחוּן בְּדִינָא קַמֵּיהּ. וּמָארֵיהוֹן דְּדִינָא לָא יִשְׁלְטוּן בְּהוֹן, דְּהָא כֹּלָּא אָזִיל בָּתַר זִינֵיהּ. סוּמָקָא לְסוּמָקָא, וְחִוָּורָא לְחִוָּורָא. יְמִינָא לִימִינָא, וּשְׂמָאלָא לִשְׂמָאלָא."],[[0,"האי בארעא קדישא וכו':","זה הוא בארץ הקדושה, כל שכן בארץ אחרת, שרוח הטומאה נמצא שם יותר, באותם הבתים שיכול האדם להנזק ממנו. א״ר אלעזר, וכל שכן, שרוח הטומאה שנמצא שם, קורא לחביריו הקליפות האחרים שימצאו שמה. ואפילו דפיקות בכלים, שהיו נוהגים לדפוק בכלים, כדי לגרש רוחות ומזיקים מאיזה מקום, אינם מעבירים את המזיקים מבית ההוא. ומשום זה המקרא מכריז ואומר, הוי בונה ביתו בלא צדק. שהדרים באותו בית ודאי אומרים מקרא הזה, בכל יום. \u0003טורפי\u0004 פירושו דפיקות, מלשון טרפה בכותל (חולין נ״ו.) \u0003דקספתא,\u0004 פירושו כלים, מלשון אכוספא דתמר, (תענית כ״ד:)."],[1,"ר׳ יוסי עאל וכו׳:","ר׳ יוסי נכנס יום אחד בבית אחד, הגיע אל מפתן הבית, ונתישב בדעתו, ונכנס בפנים הבית. שמע קול אחד שאמר, התאספו בואו, הרי כאן אחד מבעלי המחלוקת שלנו, הלקחו ונזיק אותו בטרם שיצא. אמרו לו, לא נוכל להזיקו אלא אם היה דר פה, יצא ר׳ יוסי והיה מתירא. אמר ודאי מי שעבר על דברי החברים, מתחייב בנפשו. \u0003בספתא\u0004 הוא מלשון סף, דהיינו מפתן, \u0003סיפתו,\u0004 הוא מלשון, לא יספות ממנה (שבת קכ״׳ד:) דהיינו לקיחה. וספתו פירושו הלקחו."],[2,"א״ל ר׳ חייא וכו׳:","אמר לו ר״ח, והרי עכו\"ם ושאר בני אדם דרים בתוך הבית, והם שלמים, שאינם נזוקים. אמר לו, הם באים מן הצד שלהם, וע״כ אין מזיקים להם. אבל מי שהוא ירא חטא, יכול להנזק. ואפילו הם, אם ממשיכים לדור בו, אינם יוצאים בשלום. א״ל, והרי כתוב, בתיהם שלום מפחד. אמר לו, היינו שהבית היה מאחר שבנה אותו בצדק, והרשעים לקחוהו וישבו בו, והמקרא הוא כך, \u0003בתיהם שלום מפחד,\u0004 דהיינו כשבתיהם שלום מפחד, כי נבנה בצדק, אז שבט אלוה אינו שורה עליהם."],[3,"ובא אשר לו הבית והגיד וגו':","שואל, אומר, והגיד, ויאמר היה צריך לומר, או וידבר, מהו והגיד. ומשיב, אלא בכל מקום רומז דבר חכמה. והעמידוהו, וכנגע נראה לי בבית, אומר כנגע, נגע היה צריך לומר. אומר, נראה לי, יש לי היה צריך לומר. שהרי כתוב, ונתתי נגע צרעת בבית ארץ אחוזתכם, שמשמע שיהיה נראה לכל, ולמד, אומר כנגע נראה לי."],[4,"אלא בשעתא דהאי וכו׳:","ומשיב, אלא בשעה שזה, דהיינו הנגע, נכנס בבית, נתגלה האחר, דהיינו רוח הטומאה שהיה בבית כמ״ש לעיל (אות קנ״ג) ונלחמו זה בזה. וע״כ אמר, \u0003נראה לי,\u0004 כי נראה לי תחילה, שאותו שנתכסה, שהוא רוח הטומאה, שהיה מתכסה בביאת הנגע, חזר ונתגלה. ואותו שנתגלה, שהוא הנגע, נתכסה. ואחר כך נראה לו בצורה, שנתגלה נגע ההוא בבית, ונתכסה האחר, שהוא רוח הטומאה, ועל כן כתוב \u0003והגיד לכהן,\u0004 כי דבר חכמה הוא. כי הגדה רומזת על חכמה."],[4,"","פירוש. כי נתבאר לעיל (באות קנ״ג) שהנגע ורוח הטומאה השורה בבית מחמת שנבנה שלא בצדק, הם הפכים זה לזה, כי רוח הטומאה הוא מהמשכת הארת החכמה דקו שמאל ממעלה למטה, שהוא בחינת ג״ר. והנגע הוא מבחינת אויר דקטנות הממעט הג\"ר דקו שמאל. עש״ה. ולפיכך כשהנגע נראה בבית, תכף מתכסה רוח הטומאה, מחמת שנתמעטו הג״ר דשמאל, ואין לו ממה לינק. אמנם אח״כ חוזר ומתגבר על הנגע והוא מתגלה והנגע מתכסה ואינו נראה."],[4,"","וזה אמרו, \u0003בשעתא דהאי עייל,\u0004 שהנגע נכנס ומתגלה בבית, \u0003אחרא אתגלייא,\u0004 האחר, שהוא רוח הטומאה מתגבר עליו, והוא מתגלה, והנגע מתכסה, \u0003ומקטרגא דא בדא,\u0004 שנלחמים זה בזה. \u0003ועל דא, נראה לי,\u0004 וע״כ אומר \u0003נראה לי,\u0004 שפירושו, כי ראה תחילה, \u0003ההוא דאתכסי אתגליא,\u0004 שרוח הטומאה שנתכסה בביאת הנגע, חזר ונתגלה, \u0003ודאתגליא אתכסי\u0004 והנגע שהיה מגולה בבית, נתכסה מחמת התגלות רוח הטומאה, \u0003ולבתר מתחזי ליה בדיוקנא דההוא נגע דביתא,\u0004 דהיינו שהנגע חזר ונתגבר על רוח הטומאה וצורת הנגע נראה לו שוב בבית, \u0003ואתכסיא אחרא,\u0004 ורוח הטומאה נתכסה ונעלם. וז״ש הכתוב כנגע נראה לי בבית. כי ע״כ אומר \u0003כנגע,\u0004 ולא נגע ודאי, מחמת שראה אותם נלחמים זה בזה, וחשב שאפשר שיתגבר עוד רוח הטומאה ויכסה ויעלים הנגע. וע״כ אומר, \u0003נראה לי,\u0004 שלו נדמה כך, אשר הנגע גבר על רוח הטומאה וצורתו נראתה בבית, אבל לאחר, או לכהן, אפשר שיראה באפן אחר. \u0003ועל דא והגיד לכהן, דמלה דחכמתא היא,\u0004 כלומר שהמדובר הוא בדבר החכמה, כי הנגע מבטל ומכסה הארת החכמה כנ״ל."],[5,"וכדין אתי כהנא וכו׳:","ואז בא הכהן. ויפילו הבית ויתצו אותו, העצים והאבנים והכל. כיון שנתצו ונטהרו הכל, הם מתברכים, אז כתוב, ובתים שובים תבנה וישבת. דהיינו שיבנו אותם בצדק (כנ״ל אות ק״נ) אלו נקראים טובים, כי בתים הראשונים לא היו טובים, ואינם בכלל הקדושה והטהרה."],[6,"אמר ר׳ יהודה וכו׳:","אר״י, אם כן, במה נעמיד המקרא, שכתבו, ובתים מלאים כל טוב אשר לא מלאת. ואם רוח הטומאה שורה בתוכם, איך הם מלאים כל טוב. אמר ר׳ אלעזר, מלאים כל טוב, בממון בכסף ובזהב ובכל. כש\"א, כי טוב כל ארץ מצרים. וא״ר יהודה, הרי כל הבתים של המצרים מלאים כשפים ועבודת אלילים היו, ואיך אמר הכתוב, כי טוב כל ארץ מצרים. אלא, בשביל עושר הארץ נאמר כל טוב וגו׳. אף כאן, בשביל העושר והממון נאמר בתים מלאים כל טוב."],[7,"תרין עותרין נטלו וכו׳:","ב׳ פעמים עושר לקחו ישראל, אחד, כשיצאו מגלות מצרים, ואחד, כשבאו לארץ. דהיינו בנתיצת הבתים המנוגעים. ר׳ שמעון אמר, כל זה, דהיינו נגעי הבתים, היה ודאי להתקדש הארץ ולהעביר רוח הטומאה מן הארץ ומן ישראל (כנ״ל אות קמ״ט) ועם זה, כשנתץ הבית, היה מוצא בו ממון, המספיק לבנותו ולמלאות ביתו, כדי שלא יצטער על הבית שנתצו, וישרו במשכנה של הקדושה."],[8,"ואיש או אשה וגו׳:","ואיש או אשה כי יהיה בעור בשרם בהרות בהרות לבנות. ר׳ יוסי אמר, החריפות המרובה בבהרת עזה, שנאמרו בה תלת מאה הלכות פסוקות (כנ״ל וירא אות ל״ו) למדנו, שהוא במראה, ובמראה נידון באלו אפנים המרובים. א״ר יצחק, שלש מאות טעמים יש מי שלומד בבהרת עזה. וכולם למדתי מאבי, חוץ, במה ששערה אחת שחורה, עודו טמא מטעם שהוא עד אחד, שתי שערות שחורות הן ב׳ עדים, והוא טהור. ומכאן והלאה, אפילו מאה שערות הן כשתים, ושתי שערות הן כמאה, שזה למדתי אח״כ, מטעם שכתוב, לא יקום עד אחד באיש לכל עון ולכל חטאת וגו׳. על פי שני עדים וגו׳. \u0003כסילתא,\u0004 הוא חריפות מלשון המסולתין שבכם. (ספרי דברים) שפירושו המחודדים שבכם. \u0003דמוקפי,\u0004 הוא מלשון, וקפוי הוא לעוה״ב, שפירושו הרבה בשפע (פסחים נ.)."],[9,"רבי חזקיה הוה וכו׳:","ר״ח היה יושב לפני ר׳ שמעון, אמר, כתוב, נגע לבן אדמדם. כי אז הוא נגע, משום שהלבן הרומז על חסד, אינו עומד בעינו, אלא שנוטה לאדום הרומז על דין. פתח ר״ש ואמר, כתוב, אם יהיה חטאיכם כשנים כשלג ילבינו וגו׳. אשרי הם ישראל, שהקב״ה רצה לטהרם לגמרי, כדי שלא ימצאו בדין לפניו, ובעלי הדין לא ישלטו בהם. כי הכל הולך אחר מינו, אדום הולך לדין שהוא סוד אדום, ולבן הולך לחסד שה״ס לבן. ימין שהוא לבן לימין שהוא חסד, ושמאל שהוא אדום לשמאל שהוא דין."]],[[0,"","זְהִ בָּאָרֶץ הַקְּדוֹשָׁה, כָּל שֶׁכֵּן בְּאֶרֶץ אַחֶרֶת, שֶׁרוּחַ הַטֻּמְאָה מְצוּיָה יוֹתֵר, וְיָכוֹל אָדָם לְהִנָּזֵק. אָמַר רַבִּי אֶלְעָזָר, וְכָל שֶׁכֵּן שֶׁנִּקְרָא בַקְּלִפּוֹת שֶׁל חֲבֵרָיו הָאֲחֵרִים לְהִמָּצֵא שָׁם, וַאֲפִלּוּ דְּפִיקוֹת בַּכֵּלִים לֹא מַעֲבִירִים אוֹתוֹ מִן הַבַּיִת. וּמִשּׁוּם כָּךְ הַפָּסוּק הַזֶּה מַכְרִיז וְאוֹמֵר, הוֹי בּנֶה בֵיתוֹ בְּלֹא צֶדֶק. הוֹי וַדַּאי שֶׁאוֹמְרִים כָּל יוֹם בַּבַּיִת הַהוּא."],[1,"","רַבִּי יוֹסֵי נִכְנַס יוֹם אֶחָד לְבַיִת אֶחָד, הִגִּיעַ לַסַּף (טרח בטפוס) וְנִכְנַס פְּנִימָה. שָׁמַע קוֹל אֶחָד שֶׁאוֹמֵר: הִתְכַּנְּסוּ וְהִכָּנְסוּ, הִנֵּה אֶחָד מֵהַיְרִיבִים שֶׁלָּנוּ. הִתְחַבְּרוּ וְנַזִּיק אוֹתוֹ לִפְנֵי שֶׁיֵּצֵא. אָמְרוּ, לֹא נוּכַל אֶלָּא אִם דִּיּוּרוֹ כָּאן. יָצָא רַבִּי יוֹסֵי וּפָחַד. אָמַר, וַדַּאי מִי שֶׁעוֹבֵר עַל דִּבְרֵי הַחֲבֵרִים, מִתְחַיֵּב בְּנַפְשׁוֹ."],[2,"","אָמַר לוֹ רַבִּי חִיָּיא, וַהֲרֵי הַגּוֹיִם וּשְׁאָר בְּנֵי אָדָם דָּרִים בְּתוֹכוֹ, וְנִשְׁלְמוּ. אָמַר לוֹ, הֵם מִצִּדָּם הֵם בָּאִים, אֲבָל מִי שֶׁיְּרֵא חֵטְא יָכוֹל לְהִנָּזֵק. וַאֲפִלּוּ הֵם, אִם יְעַכְּבוּ אֶת דִּיּוּרָם בּוֹ, לֹא יֵצְאוּ בְשָׁלוֹם. אָמַר לוֹ, וַהֲרֵי כָּתוּב (איוב כא) בָּתֵּיהֶם שָׁלוֹם מִפָּחַד. אָמַר לוֹ, כְּגוֹן שֶׁהָיָה מֵאַחֵר, וְנִבְנָה מִצֶּדֶק. וְהַפָּסוּק כָּךְ הוּא, בָּתֵּיהֶם שָׁלוֹם מִפָּחַד - כְּשֶׁבָּתֵּיהֶם שָׁלוֹם מִפַּחַד, שֵׁבֶט אֱלוֹהַּ לֹא שׁוֹרֶה עֲלֵיהֶם."],[3,"","וּבָא אֲשֶׁר לוֹ הַבַּיִת וְהִגִּיד וְגוֹ' (ויקרא יד). וְהִגִּיד?! וַיֹּאמֶר הָיָה צָרִיךְ לִהְיוֹת, אוֹ וַיְדַבֵּר. מַה זֶּה וְהִגִּיד? אֶלָּא בְּכָל מָקוֹם דָּבָר שֶׁל חָכְמָה הוּא, וְהִנֵּה פֵּרְשׁוּהָ. כְּנֶגַע נִרְאָה לִי בַּבָּיִת. כְּנֶגַע?! נֶגַע הָיָה צָרִיךְ לִהְיוֹת! נִרְאָה לִי?! יֵשׁ לִי הָיָה צָרִיךְ לִהְיוֹת, שֶׁהֲרֵי כָּתוּב וְנָתַתִּי נֶגַע צָרַעַת בְּבֵית אֶרֶץ אֲחֻזַּתְכֶם, שֶׁיֵּרָאֶה לַכֹּל! לָמָּה כְּנֶגַע נִרְאָה לִי."],[4,"","אֶלָּא בְּשָׁעָה שֶׁזֶּה נִכְנָס, אַחֵר מִתְגַּלֶּה, וּמִתְגָּרִים זֶה בָּזֶה. וְעַל זֶה נִרְאָה לִי. אוֹתוֹ שֶׁהִתְכַּסָּה הִתְגַּלָּה, וְשֶׁהִתְגַּלָּה הִתְכַּסָּה, וְאַחַר כָּךְ נִרְאָה לוֹ בִּדְמוּת אוֹתוֹ הַנֶּגַע שֶׁל הַבַּיִת, וְאַחֵר מִתְכַּסֶּה. וְעַל זֶה וְהִגִּיד לַכֹּהֵן, שֶׁדְּבַר חָכְמָה הוּא."],[5,"","וְאָז בָּא הַכֹּהֵן, וְיַפִּילוּ הַבַּיִת, וִינַתְּצוּ לוֹ הָאֲבָנִים וְהָעֵצִים וְהַכֹּל. כֵּיוָן שֶׁנִּתְּצוּ וְטִהֲרוּ הַכֹּל, מִתְבָּרְכִים. אָז כָּתוּב (דברים ה) וּבָתִּים טוֹבִים תִּבְנֶה וְיָשָׁבְתָּ. אֵלּוּ נִקְרָאִים טוֹבִים, שֶׁהֲרֵי הָרִאשׁוֹנִים אֵינָם טוֹבִים, וְאֵינָם בִּכְלָל שֶׁל קְדֻשָּׁה וְטָהֳרָה."],[6,"","אָמַר רַבִּי יְהוּדָה, אִם כָּךְ, בַּמֶּה מְפָרְשִׁים אֶת הַפָּסוּק שֶׁכָּתוּב, (שם ו) וּבָתִּים מְלֵאִים כָּל טוּב אֲשֶׁר לֹא מִלֵּאתָ? אִם רוּחַ טֻמְאָה שׁוֹרָה בְתוֹכָם, אֵיךְ מְלֵאִים כָּל טוּב? אָמַר רַבִּי אֶלְעָזָר, מְלֵאִים כָּל טוֹב - בְּמָמוֹן, בְּכֶסֶף וּבְזָהָב, וּבַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מה) כִּי טוּב כָּל אֶרֶץ מִצְרַיִם. וְאָמַר רַבִּי יְהוּדָה, וְהִנֵּה כָּל בָּתֵּי הַמִּצְרִים הָיוּ מְלֵאִים כְּשָׁפִים וְתוֹעֵבוֹת? אֶלָּא עֲבוּר הָעֹשֶׁר שֶׁל הָאָרֶץ זֶה נֶאֱמַר. אַף כָּאן עֲבוּר הָעֹשֶׁר וְהַמָּמוֹן הוּא."],[7,"","שְׁתֵּי עֲשִׁירֻיּוֹת נָטְלוּ יִשְׂרָאֵל, אַחַת כְּשֶׁיָּצְאוּ מִגָּלוּת מִצְרַיִם, וְאַחַת כְּשֶׁנִּכְנְסוּ לָאָרֶץ. רַבִּי שִׁמְעוֹן אָמַר, כָּל זֶה וַדַּאי הָיָה לְקַדֵּשׁ אֶת הָאָרֶץ, וּלְהַעֲבִיר רוּחַ הַטֻּמְאָה מִן הָאָרֶץ וּמִתּוֹךְ יִשְׂרָאֵל. וּכְשֶׁהַבַּיִת הָיָה מְנֻתָּץ, הָיָה נִמְצָא בּוֹ מָמוֹן לִבְנוֹת אוֹתוֹ וּלְמַלֵּא אֶת בֵּיתוֹ, כְּדֵי שֶׁלֹּא יִצְטַעֵר עַל הַבַּיִת וְיִשְׁהוּ בְדִיּוּר שֶׁל קְדֻשָּׁה."],[8,"","וְאִישׁ אוֹ אִשָּׁה כִּי יִהְיֶה בְעוֹר וְגוֹ'. רַבִּי יוֹסֵי אָמַר, כְּמוֹ מָקוֹם גָּבוֹהַּ שֶׁמַּקִּיף בְּבַהֶרֶת עַזָּה, מַרְאֶה שָׁנִינוּ, וּבְמַרְאֶה נִדּוֹן, בְּאוֹתָם הַגְּוָנִים. אָמַר רַבִּי יִצְחָק, שְׁלֹשׁ מֵאוֹת טְעָמִים יֵשׁ מִי שֶׁגּוֹרֵס בְּבַהֶרֶת עַזָּה, וְכֻלָּם לָמַדְתִּי מֵאָבִי, פְּרָט לְשַׂעֲרָה (לבנה) אַחַת טְמֵאָה, עֵד אֶחָד. שְׁנַיִם, שְׁנֵי עֵדִים, וְטָהוֹר. מִכָּאן וָהָלְאָה, אֲפִלּוּ מֵאָה כִּשְׁנַיִם, וּשְׁנַיִם כְּמֵאָה. וְזֶה לָמַדְנוּ לְאַחַר שֶׁכָּתוּב, (דברים יט) לֹא יָקוּם עֵד אֶחָד בְּאִישׁ וְגוֹ', עַל פִּי שְׁנַיִם עֵדִים וְגוֹ'."],[9,"","רַבִּי חִזְקִיָּה הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר, כָּתוּב נֶגַע לָבָן אֲדַמְדָּם, אָז הוּא נֶגַע, שֶׁהֲרֵי הַלָּבָן לֹא עוֹמֵד בְּעֵינוֹ. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, כָּתוּב אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים וְגוֹ'. אַשְׁרֵיהֶם יִשְׂרָאֵל, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְטַהֵר אוֹתָם בַּכֹּל כְּדֵי שֶׁלֹּא יִמָּצְאוּ בְדִין לְפָנָיו, וּבַעֲלֵי הַדִּין לֹא יִשְׁלְטוּ בָהֶם, שֶׁהֲרֵי הַכֹּל הוֹלֵךְ אַחַר מִינוֹ. אָדם לְאָדם, וְלָבָן לְלָבָן, יָמִין לְיָמִין, וּשְׂמֹאל לִשְׂמֹאל."]]],[["בְּעֵשָׂו כְּתִיב, (בראשית כ״ה:כ״ה) וַיֵצֵא הָרִאשׁוֹן אַדְמוֹנִי, וְעַל דָּא שַׁרְיָא בֵּיהּ זִינֵיהּ. וְאִי תֵּימָא אַדְמוֹנִי כְּתִיב בְּעֵשָׂו. וּכְתִיב בֵּיהּ בְּדָוִד, (שמואל א ט״ז:י״ב) וַיְבִיאֵהוּ וְהוּא אַדְמוֹנִי. אֶלָּא דָּא מִזּוֹהֲמָא דְּדַהֲבָא אִתְעַבִיד, וְדָא בְּזוֹהֲרָא דְּדַהֲבָא אִתְדְּבַק, בְּעֵשָׂו כְּתִיב בֵּיהּ, אַדְמוֹנִי כֻּלּוֹ כְּאַדֶּרֶת שֵׂעָר, (מ\"ח ע\"ב) בְּזוּהֲמָא דְּהִתוּכָא נָפַק. בֵּיהּ כְּתִיב בְּדָוִד, עִם יְפֵה עֵינַיִם וְטוֹב רֹאִי.","תָּא חֲזֵי, מַאי טַעְמָא. גַּוְונָא חִוָּורָא אִשְׁתְּמוֹדַע, וְגַוְונָא סוּמָקָא אִשְׁתְּמוֹדַע, סוּמָקָא בְּקַדְמִיתָא, וְהָא אִתְחֲזֵי בֵּיהּ חִוָּורָא, הָא דַּכְיוּתָא אִתְיְילִיד בֵּיהּ, וְשָׁארִי לְאִתְדַכְּאָה. חִוָּורָא בְּקַדְמִיתָא, וְאִתְחַזֵּי בֵּיהּ סוּמָקָא, הָא שָׁארֵי לְאִסְתַּאֲבָא, וּכְתִיב וְטִמְּאוֹ הַכֹּהֵן, דְּהָא אִתְיְילִיד בֵּיהּ סוּמָקָא, לְאִסְתַּאֲבָא. וְכַהֲנָא הֲוָה יָדַע בְּכָל אִינּוּן גַּוְונִין. וּלְזִמְנִין דְּאִתְחֲזֵי בֵּיהּ גַּוְונָא דְּדַכְיוּתָא, וְיַסְגִר לֵיהּ לְמֵחֱמֵי אִי אִתְיְילִיד בֵּיהּ גַּוְונָא אָחֳרָא. וְאִי לָא, מַדְכֵּי לֵיהּ, הֲדָא הוּא דִכְתִיב וְטִהֲרוֹ הַכֹּהֵן וְגוֹ'.","רִבִּי יִצְחָק וְרִבִּי יְהוּדָה הֲווֹ אָזְלֵי בְּאָרְחָא, אָמַר רִבִּי יְהוּדָה, כְּתִיב (מלכים ב ה׳:כ״ז) וְצָרַעַת נַעֲמָן תִּדְבַּק בְּךָ וּבְזַרְעֲךָ לְעוֹלָם וְגוֹ', אִי הוּא חָטָא בְּנוֹי אֲמַאי יִלְקוּן. אָמַר לֵיהּ, אֱלִישָׁע יַתִּיר מִשְּׁאַר נְבִיאֵי חָמָא. חָמָא דְּלָא נָפִיק מִגֵחֲזִי בְּרָא דִּמְעַלְיָא, וְעַל דָּא לָיִיט לְכֻלְּהוּ.","וְלֹא עוֹד, אֶלָּא אָמַר לֵיהּ, אֲנָא פּוּלְחָנָא בְּשִׁמוּשָׁא עִלָּאָה לְגַבֵּי אֵלִיָּהוּ, וְזָכֵינָא בִּתְרֵין חוּלָקִין, דְּהָא פְּלַחְנָא לֵיהּ בִּקְשׁוֹט, וְאַנְתְּ רָשָׁע פְּגִימַת לִי, אוּמֵית לְשִׁקְרָא, וַחֲמִידַת, הָא עָבַרְתָּ עַל אוֹרַיְיתָא כֹּלָּא, וּמַאן דְּאַעְבָּר עַל דָּא, מִית הוּא לְעָלְמָא דְּאָתֵי. אֲבָל בְּגִין דְּפַלְחַת לִי, שִׁמּוּשָׁא דִּילָךְ לָא לִהֱוִי לְמַגָּנָא, תֶּהֱוִי מִיתָה דִּילָךְ בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי לָא. וּבְגִין כַּךְ, וְצָרַעַת נַעֲמָן תִּדְבַּק בְּךָ וּבְזַרְעֲךָ. (גוונא דחיוורא אשתמודע, וגוונא דסומקא אשתמודע)","אָמַר רִבִּי יוֹסֵי, בֶּגֶד הַצֶּמֶר אוֹ הַפִּשְׁתִּים אֲמַאי. אָמַר רִבִּי יִצְחָק, בְּכֹלָּא שַׁרְיָא, וּבְכֹלָּא שַׁלְטָא. וְאִית כְּגַוְונָא דָּא דִּכְתִּיב, (משלי ל״א:י״ג) דָּרְשָׁה צֶמֶר וּפִשְׁתִּים. וּבְגִּינֵי כַּךְ, שׁוּלְטָנֵיהּ דְּהַהוּא נֶגַע דְּנָפִיק מֵאֲתַר עִלָּאָה, דָּא שַׁלְטָא בְּכֹלָּא, בִּתְרֵי גַּוְונֵי, בְּצֶמֶר וּבְפִשְׁתִּים. וּבְגִין כַּךְ, זֹאת תּוֹרַת נֶגַע הַצָּרַעַת בֶּגֶד הַצֶּמֶר אוֹ הַפִּשְׁתִּים.","רִבִּי יִצְחָק הֲוָה אָזִיל לְקַטְפוּרֵי דַּאֲבוֹי. חָמָא חַד בַּר נָשׁ, דְּסַאטֵי בְּקוּטְרָא דְּמָטוּלָא אֲכַתְפוֹי. אָמַר לֵיהּ, שׁוּרְטָא דְּקִישְׁטָא בְּכַתְפָךְ אֲמַאי, לָא אָמַר לֵיהּ מִדִי. אָזַל אֲבַתְרֵיהּ, חָמָא דְּעַיִּיל בִּמְעַרְתָּא חֲדָא, עָאל אֲבַתְרֵיהּ, חָמָא קְטוּרָא דִּתְנָנָא דְּהֲוָה סָלִיק מִתְּחוֹת אַרְעָא, וְעָאל הַהוּא בַּר נָשׁ בְּנוּקְבָּא חַד, וְאִתְכַּסְיָא מִנֵּיהּ. דָּחִיל רִבִּי יִצְחָק, וְנָפַק לְפוּם מְעַרְתָּא.","עַד דְּהֲוָה יָתִיב, אַעְבְּרוּ רִבִּי יְהוּדָה וְרִבִּי חִזְקִיָּה, חָמָא לוֹן, וְקָרִיב גַּבֵּיהוֹן, סַח לוֹן עוֹבָדָא. אָמַר רִבִּי יְהוּדָה, בְּרִיךְ רַחֲמָנָא דְּשֵׁזְבָךְ. הַאי מְעַרְתָּא דְּסָגִיר, דִּסְרוֹנְיָא הִיא, וְכָל יַתְבֵי הַהִיא קַרְתָּא, חַרְשִׁין אִינּוּן, וְאַתְיָין לְמַדְבְּרָא לְחִוְויָין אוּכָמִין, דְּאִינּוּן בְּנֵי עֶשֶׂר שְׁנִין, אוֹ יַתִּיר, לְמֶעְבַּד חַרְשִׁין, וְלָא מְנַטְרָא מִנַּיְיהוּ, וְאִתְעָבִידוּ סְגִירִין וְכָל זַיְינֵי חַרְשִׁין דִּלְהוֹן בְּהַאי מְעַרְתָּא אִינּוּן.","אָזְלוּ, עַד דַּהֲווֹ אָזְלֵי, אִעְרָעְרוּ בְּחַד בַּר נָשׁ דְּהֲוָה אָתֵי, וּבְרֵיהּ דְּהֲוָה מְרַע, קָטִיר עַל חֲמָרָא. אָמְרוּ לֵיהּ מַאן אַתְּ. אָמַר לְהוֹ יוּדָאי, וְדָא הוּא בְּרִי דְּאִיהוּ קָטִיר עַל חֲמָרָא. אָמְרוּ לֵיהּ, אֲמַאי הוּא קָטִיר. אָמַר לוֹן דִּיוּרִי הוּא בְּחַד כְּפַר, דְּאִיהוּ מִבְּנֵי רוֹמָאֵי, וְהַאי בְּרִי הֲוָה אוֹלִיף אוֹרַיְיתָא בְּכָל יוֹמָא, וַהֲוָה אַהְדָּר לְבֵיתָא, וְלָעֵי לוֹן לְאִינּוּן מִלִּין. וְג' שְׁנִין הֲוָה דִּיוּרִי בְּהַהוּא בֵּיתָא, וְלָא חֲמֵינָא מִדִי. וְהַשְׁתָּא יוֹמָא חַד עָאל בְּרִי לְבֵיתָא לְאָהַדְּרָא מִלִּין, אַעְבָּר חַד רוּחָא קָמֵיהּ, וְנָזִיק לֵיהּ, אַעֲקָם פּוּמֵיהּ וְעֵינוֹי, וִידוֹי אִתְעַקָמוּ, וְלָא יָכִיל לְמַלְּלָא. וַאֲתֵינָא לְגַבֵּי מְעַרְתָּא דִּסְגִירוּ דִּסְרוֹנְיָא דִּלְמָא יִלְּפוּן לִי מִלָּה דְּאַסוּותָא."],[[0,"בעשו כתיב וכו׳:","בעשו כתוב, ויצא הראשון אדמוני. וע״כ שורה בו מינו, דהיינו דינים שה״ס אדום, ואם תאמר, אדמוני כתוב בעשו וכתוב בדוד ויביאהו והוא אדמוני. ומשיב, אלא זה, עשו, נעשה מזוהמא של זהב, שהם דינים קשים. וזה, דוד נתדבק בזוהרו של זהב, שהוא השמאל דבינה הנקראת זהב. והיא רחמים. בעשו כתוב, אדמוני כולו כאדרת שער, דהיינו שיצא מן הפסולת הנשארת בהתוך הזהב. וכתוב בו בדוד, עם יפה עינים וטוב רואי. הרומז על הארת החכמה שנקראת עינים וראיה, הנמשכת מקו שמאל, של הבינה, הכלול עם הימין שבה."],[1,"ת״ח מ״ט גוונא וכו׳:","בוא וראה, מה הטעם, שנגע לבן אדמדם הוא טמא. כי מראה לבן נודע, שהוא חסד, ומראה אדום שהוא דין, ולפיכך, אם היה אדום תחלה, ועתה נראה בו לבן, הרי טהרה נולד בו ומתחיל להטהר, ואם היה לבן תחילה ועתה נראה בו אדום, הרי מתחיל להטמא, וכתוב, וטמאו הכהן. כי נולד בו אדום, שהוא דין, להטמא. והכהן היה יודע בכל אלו מראות. ולפעמים שנראה בו מראה של טהרה, ויסגור אותו לראות אם יולד בו מראה אחרת ואם לא, מטהר אותו, ז״ש, וטהרו הכהן."],[2,"רבי יצחק ור' יהודה וכו':","ר״י ור\"י היו הולכים בדרך, אמר ר׳ יהודה, כתוב, וצרעת נעמן תדבק בך ובזרעך לעולם וגו'. שואל, אם הוא חטא, בניו למה יהיו מוכים. א״ל, אלישע ראה יותר משאר הנביאים, ראה שלא יצא מגחזי בן הגון, וע״כ קלל את כולם."],[3,"ולא עוד אלא וכו':","ולא עוד אלא אמר לו, אני עבדתי בשרות עליון אצל אליהו, וזכיתי בשני חלקים, דהיינו שזכה פי שנים ברוחו של אליהו, כי עבדתיו באמת. ואתה רשע, פגמת אותי, שנשבעת לשקר, וחמדת למתנת נעמן, הרי עברת על התורה כולה, ומי שעובר על זה, מת הוא לעולם הבא, אבל משום שעבדת אצלי, השרות שלך לא יהיה בחנם, והמיתה שלך תהיה בעולם הזה, ולא לעולם הבא, ומשום זה וצרעת נעמן תדבק בך ובזרעך."],[4,"א״ר יוסי וכו׳:","אר״י, בגד הצמר או הפשתים למה. היה לו לומר בגד סתם. א״ר יצחק, והכתוב מלמדנו, שהנגע שורה בכל ושולט על כל. כי צמר בא מבינה ופשתים ממלכות והנגע שולט על שניהם. ויש כעין זה, שכתוב, דרשה צמר ופשתים, שמלמדנו שהמלכות משמשת בשניהם. ומשום זה גם כאן מלמדנו ששליטתו של הנגע הזה היוצא ממקום עליון דהיינו מבחינת דינין דמלכות שבבינה, (כנ״ל אות קנ״ג) שולט בכל, דהיינו בב' המינים, בצמר ובפשתים. ומשום זה אוה\"כ, זאת תורת נגע הצרעת בגד הצמר או הפשתים."],[5,"ר׳ יצחק הוה וכו׳:","ר׳ יצחק היה הולך אל הבציר של אביו. ראה אדם אחד שנטה מן הדרך, עם משא קשורה על כתפיו. אמר לו, חבל המקשט כתפיך למה לך, כלומר, למה קשרת המשא לכתפיך. לא השיב לו כלום, הלך אחריו, ראה שהיה נכנס למערה אחת. נכנס אחריו. ראה קיטור עשן עולה מתחת הארץ, ואיש ההוא נכנס בנקב אחד, ונעלם ממנו. פחד ר׳ יצחק ויצא אל פי המערה. \u0003קטפורי,\u0004 הוא כמו \u0003קטפא\u0004 שהוא תרגומו של בציר (ויקרא כ״ו ה') \u0003שורטא,\u0004 הוא חבל מלשון \u0003סרט\u0004 של צמר (כלאים ט')."],[6,"עד דהוה יתיב וכו׳:","בעוד שהיה יושב, עברו ר׳ יהודה ור׳ חזקיה. ראה אותם וקרב אליהם. סיפר להם המעשה. אמר ר׳ יהודה ברוך הרחמן שהצילך. מערה זו היא של מצורעים, מעיר סרוניא, וכל יושבי העיר ההיא מכשפים, ובאים למדבר לנחשים שחורים, שהם בני עשר שנים או יותר, לעשות כשפים, ואינם שומרים עצמם מהם, ונעשו מצורעים. וכל מיני כשפים שעושים, הם במערה הזו."],[7,"אזלו עד דהוו וכו׳:","הלכו. בעוד שהיו הולכים, פגשו אדם אחד שהיה בא, ובנו החולה היה קשור על החמור. אמרו לו מי אתה. אמר להם אני יהודי, וזה הוא בני שקשור על החמור. אמרו לו למה הוא קשור. אמר להם, דירתי היא בכפר אחד, שהוא מבני רומי, ובני הזה היה לומד תורה בכל יום, וחזר לביתו ועסק באלו הדברים. ושלש שנים היתה דירתי בבית ההוא ולא ראיתי כלום. ועתה, יום אחד נכנס בני אל הבית, לחזור על הדברים שלמד, עבר רוח אחד לפניו והזיק לו, והעקים פיו ועיניו, וידיו נעקמו, ואינו יכול לדבר. ואני בא למערת המצורעים של סרוניא, אולי ילמדו לי דבר רפואה."]],[[0,"","בְּעֵשָׂו כָּתוּב וַיֵּצֵא הָרִאשׁוֹן אַדְמוֹנִי, וְעַל כֵּן שׁוֹרֶה בּוֹ מִינוֹ. וְאִם תֹּאמַר אַדְמוֹנִי כָּתוּב בְּעֵשָׂו, וְכָתוּב בּוֹ בְּדָוִד, (שמואל א טז) וַיְבִיאֵהוּ וְהוּא אַדְמוֹנִי. אֶלָּא זֶה מִזֻּהֲמַת הַזָּהָב נַעֲשָׂה, וְזֶה נִדְבַּק בְּזֹּהַר הַזָּהָב. כָּתוּב בְּעֵשָׂו, אַדְמוֹנִי כֻּלּוֹ כְּאַדֶּרֶת שֵׂעָר, יָצָא בְזֻהֲמַת הַהִתּוּךְ. בְּדָוִד כָּתוּב, עִם יְפֵה עֵינַיִם וְטוֹב רֹאִי."],[1,"","בֹּא וּרְאֵה מָה הַטַּעַם. הַגָּוֶן הַלָּבָן נוֹדָע, וְהַגָּוֶן הָאָדם נוֹדָע. אָדם בָּרִאשׁוֹנָה, וְהִנֵּה נִרְאֶה בּוֹ לָבָן, הֲרֵי טָהֳרָה נוֹלְדָה בּוֹ וּמַתְחִיל לְהִטָּהֵר. לָבָן בָּרִאשׁוֹנָה וְנִרְאֶה בּוֹ אָדם, הִנֵּה מַתְחִיל לְהִטָּמֵא. וְכָתוּב וְטִמְּאוֹ הַכֹּהֵן, שֶׁהִנֵּה נוֹלָד בּוֹ אָדם לְהִטָּמֵא. וְהַכֹּהֵן הָיָה יוֹדֵעַ בְּכָל אוֹתָם הַגְּוָנִים. וְלִפְעָמִים שֶׁנִּרְאֶה בּוֹ גָּוֶן שֶׁל טָהֳרָה, וְיַסְגִּירוֹ לִרְאוֹת אִם יִוָּלֵד בּוֹ גָּוֶן אַחֵר. וְאִם לֹא, מְטַהֵר אוֹתוֹ. זֶהוּ שֶׁכָּתוּב וְטִהֲרוֹ הַכֹּהֵן וְגוֹ'."],[2,"","רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יְהוּדָה, כָּתוּב (מלכים ב ה) וְצָרַעַת נַעֲמָן תִּדְבַּק בְּךְ וּבְזַרְעֲךְ לְעוֹלָם וְגוֹ'. אִם הוּא חָטָא, לָמָּה יִלְקוּ בָנָיו? אָמַר לוֹ, אֱלִישָׁע רָאָה יוֹתֵר מִשְּׁאָר הַנְּבִיאִים. רָאָה שֶׁלֹּא יֵצֵא מִגֵּיחֲזִי בֵּן מְעֻלֶּה, וְעַל כֵּן קִלֵּל אֶת כֻּלָּם."],[3,"","וְלֹא עוֹד, אֶלָּא אָמַר לוֹ: אֲנִי עָבַדְתִּי בְּשִׁמּוּשׁ עֶלְיוֹן אֵצֶל אֵלִיָּהוּ, וְזָכִיתִי בִּשְׁנֵי חֲלָקִים, שֶׁהֲרֵי עָבַדְתִּי אוֹתוֹ בֶּאֱמֶת. וְאַתָּה רָשָׁע פָּגַמְתָּ אוֹתִי, נִשְׁבַּעְתָּ לַשֶּׁקֶר וְחָמַדְתָּ, הֲרֵי עָבַרְתָּ עַל כָּל הַתּוֹרָה כֻּלָּהּ, וּמִי שֶׁעוֹבֵר עַל זֶה, מֵת הוּא לָעוֹלָם הַבָּא. אֲבָל מִשּׁוּם שֶׁעָבַדְתָּ אוֹתִי, הַשִּׁמּוּשׁ שֶׁלְּךְ לֹא יִהְיֶה לְחִנָּם; תִּהְיֶה מִיתָתְךְ בָּעוֹלָם הַזֶּה, וְלֹא בָּעוֹלָם הַבָּא. וּמִשּׁוּם כָּךְ, וְצָרַעַת נַעֲמָן תִּדְבַּק בְּךְ וּבְזַרְעֲךְ. (גון הלבן נודע, וגון האדם נודע)."],[4,"","אָמַר רַבִּי יוֹסֵי, בֶּגֶד הַצֶּמֶר אוֹ הַפִּשְׁתִּים לָמָּה? אָמַר רַבִּי יִצְחָק, בַּכֹּל שׁוֹרֶה וּבַכֹּל שׁוֹלֵט. וְיֵשׁ כְּמוֹ זֶה, שֶׁכָּתוּב (משלי לא) דָּרְשָׁה צֶמֶר וּפִשְׁתִּים. וּמִשּׁוּם כָּךְ שִׁלְטוֹנוֹ שֶׁל אוֹתוֹ נֶגַע שֶׁיּוֹצֵא מִמָּקוֹם עֶלְיוֹן, זֶה שׁוֹלֵט בַּכֹּל, בִּשְׁנֵי גְוָנִים, בְּצֶמֶר וּבְפִשְׁתִּים. וּמִשּׁוּם כָּךְ, זֹּאת תּוֹרַת נֶגַע הַצָּרַעַת בֶּגֶד הַצֶּמֶר אוֹ הַפִּשְׁתִּים."],[5,"","רַבִּי יִצְחָק הָיָה הוֹלֵךְ לַבָּצִיר שֶׁל אָבִיו. רָאָה אִישׁ אֶחָד שֶׁסָּטָה עִם קֶשֶׁר שֶׁל מַשָּׂא עַל כְּתֵפוֹ. אָמַר לוֹ, קָנִים שֶׁל עֵצִים שֶׁעַל כְּתֶפְךְ לְשֵׁם מָה? לֹא אָמַר לוֹ דָּבָר. הָלַךְ אַחֲרָיו. רָאָה שֶׁנִּכְנַס לִמְעָרָה אַחַת, נִכְנַס אַחֲרָיו. רָאָה קִיטוֹר שֶׁל עָשָׁן שֶׁהָיָה עוֹלֶה מִתַּחַת לָאָרֶץ, וְנִכְנַס הָאִישׁ הַהוּא לְנֶקֶב אֶחָד וְהִתְכַּסָּה מִמֶּנּוּ. פָּחַד רַבִּי יִצְחָק, וְיָצָא לְפִי הַמְּעָרָה."],[6,"","בְּעוֹדוֹ יוֹשֵׁב, עָבְרוּ רַבִּי יְהוּדָה וְרַבִּי חִזְקִיָּה. רָאָה אוֹתָם וְקָרַב אֲלֵיהֶם. סִפֵּר לָהֶם אֶת הַמַּעֲשֶׂה. אָמַר רַבִּי יְהוּדָה, בָּרוּךְ הָרַחֲמָן שֶׁהִצִּילְךְ. זוֹהִי מְעָרַת הַמְּצֹרָעִים שֶׁל סְרוֹנְיָא, וְכָל יוֹשְׁבֵי הַקִּרְיָה הַהִיא הֵם מְכַשְּׁפִים, וּבָאִים לַמִּדְבָּר לַנְּחָשִׁים הַשְּׁחֹרִים, שֶׁהֵם בְּנֵי עֶשֶׂר שָׁנִים אוֹ יוֹתֵר, לַעֲשׂוֹת כְּשָׁפִים, וְלֹא נִשְׁמָרִים מֵהֶם וְנַעֲשִׂים מְצֹרָעִים, וְכָל מִינֵי כְשָׁפִים שֶׁלָּהֶם הֵם בַּמְּעָרָה הַזּוֹ."],[7,"","הָלְכוּ, בְּעוֹדָם הוֹלְכִים פָּגְשׁוּ בְאִישׁ אֶחָד שֶׁהָיָה בָּא, וּבְנוֹ שֶׁהָיָה חוֹלֶה קָשׁוּר עַל הַחֲמוֹר. אָמְרוּ לוֹ, מִי אַתָּה? אָמַר לָהֶם, יְהוּדִי, וְזֶה הוּא בְּנִי שֶׁקָּשׁוּר עַל הַחֲמוֹר. אָמְרוּ לוֹ, לָמָּה הוּא קָשׁוּר? אָמַר לָהֶם, מְגוּרַי הֵם בִּכְפָר אֶחָד, שֶׁהוּא מִבְּנֵי הָרוֹמָאִים, וּבְנִי הַזֶּה הָיָה לוֹמֵד תּוֹרָה בְּכָל יוֹם, וְהָיָה חוֹזֵר הַבַּיְתָה וְלוֹמֵד אֶת אוֹתָם הַדְּבָרִים, וְשָׁלֹשׁ שָׁנִים הָיוּ מְגוּרַי בַּבַּיִת הַהוּא וְלֹא רָאִיתִי דָבָר. וְכָעֵת יוֹם אֶחָד נִכְנַס בְּנִי לַבַּיִת לַחֲזֹּר עַל הַדְּבָרִים, עָבְרָה רוּחַ אַחַת לְפָנָיו וְהִזִּיקָה לוֹ, הִתְעַקְּמוּ פִיו וְעֵינָיו, וְיָדָיו הִתְעַקְּמוּ וְלֹא יָכֹל לְדַבֵּר. וּבָאתִי לִמְעָרַת הַמְּצֹרָעִים שֶׁל סְרוֹנְיָא אוּלַי יְלַמְּדוּ אוֹתִי דָּבָר שֶׁל רְפוּאָה."]]],[["אָמַר לֵיהּ רִבִּי יְהוּדָה, וּבְהַהוּא בֵּיתָא יַדְעַת מִן קַדְמַת דְּנָא, דְּאִתְנְזַק בֵּיהּ בַּר נָשׁ אָחֳרָא. אָמַר לֵיהּ יְדַעְנָא, דְּהָא מִכַּמָּה יוֹמִין אִתְנְזַק בֵּיהּ חַד בַּר נָשׁ, וַהֲווּ אַמְרֵי דְּמַרְעָא הֲוָה, וּמִנַּיְיהוּ אַמְרֵי דְּרוּחָא דְּבֵיתָא, וּלְבָתַר עָאלוּ בֵּיהּ כַּמָה בְּנֵי נָשָׁא, וְלָא אִתְנְזִיקוּ. אָמְרוּ, הַיְינוּ דְּאַמְרֵי חַבְרַיָּיא, וַוי לְאִינוּן דְּעַבְרִין עַל מִלַּיְיהוּ.","פָּתַח רִבִּי יְהוּדָה וְאָמַר, (ירמיהו כ״ב:י״ג) הוֹי בּוֹנֶה בֵיתוֹ בְּלֹא צֶדֶק, דְּהָא בְּכָל אֲתַר דְּאִשְׁתְּכַח בֵּיהּ צֶדֶק, כָּל רוּחִין וְכָל מַזִּיקֵי עָלְמָא עַרְקֵי מִנֵּיהּ, וְלָא מִשְׁתַּכְּחֵי קַמֵּיהּ. וְעִם כָּל דָּא, מַאן דְּאַקְדִים וְנָטִיל אֲתַר, אָחִיד בֵּיהּ. אָמַר לֵיהּ רִבִּי חִזְקִיָּה, אִי הָכִי שָׁקִיל שְׁמָא קַדִּישָׁא כְּרוּחַ מִסְאֲבָא.","אָמַר לֵיהּ, לָאו הָכִי, אֶלָּא שְׁמָא קַדִּישָׁא לָא שַׁרְיָא בַּאֲתַר מִסְאֲבָא, וּבְגִין כַּךְ, אִי שְׁמָא קַדִּישָׁא נָטִיל אֲתַר מִקַּדְמַת דְּנָא, כָּל רוּחִין וְכָל מַזִּיקִין דְּעָלְמָא לָא יַכְלִין לְאִתְחֲזָאָה בֵּיהּ, כָּל שֶׁכֵּן לְקָרְבָא בַּהֲדֵיהּ. אִי רוּחַ מִסְאֲבָא קָדִים, נָטִיל אֲתַר. שְׁמָא קַדִּישָׁא לָא שַׁרְיָא בֵּיהּ, דְּהָא לָאו אַתְרֵיהּ.","וְכַד הֲוָה נָחִית נֶגַע צָרַעַת, הֲוָה מַדְכֵּי אַתְרָא, וְאַפִּיק לְרוּחַ מִסְאֲבָא מֵאַתְרֵיהּ, וּלְבָתַר מְנַתְּצֵי בֵּיתָא, אֲבָנִין וְאָעִין וְכֹלָּא, וּבָנֵי לָהּ כְּמִלְּקַדְּמִין, בִּסְטָר קַדִּישָׁא בְּצֶדֶק, דְּדָכִיר לֵיהּ לִשְׁמָא קַדִּישָׁא, וְלִשְׁרֵי עָלֵיהּ קְדוּשָּׁה, וְעִם כָּל דָּא בְּעַפְרָא אָחֳרָא, וְיַרְחִיק בֵּיתָא מֵאַתְרֵיהּ, מִיְּסוֹדָא קַדְמָאָה תְּרֵי טְפָחִים.","הַשְׁתָּא דְּלָא אִתְחֲזֵי, וְלָא נָחִית מַאן דִּמְקַטְרֵג בֵּיהּ בְּהַהוּא רוּחַ מִסְאֲבָא, לְאַפָּקָא לֵיהּ מֵאַתְרֵיהּ, מַאי תָּקַנְתֵּיה. אִי יָכִיל לְנָפְקָא מֵהַאי בֵּיתָא שַׁפִּיר. וְאִי לָאו יִבְנֶה לֵיהּ כְּמִלְּקַדְּמִין, בַּאֲבָנִין אָחֳרָנִין, וְאָעִין וְכֹלָּא, וְיַפִּיק וְיַרְחִיק לֵיהּ מֵאֲתַר קַדְמָאָה, וְיִבְנֵי לֵיהּ עַל שְׁמָא קַדִּישָׁא.","וְעִם כָּל דָּא, לָא נָפִיק הַהוּא רוּחָא מִן אֲתַר קַדְמָאָה, בְּגִין דִּקְדוּשָּׁה לָא שַׁרְיָא עַל אֲתַר מִסְאֲבָא. אָמַר רִבִּי יִצְחָק לָמָּה לֵיהּ לְאַטְרְחָא כּוּלֵי הַאי, בְּזִמְנָא דָּא כְּתִיב, (קהלת א׳:ט״ו) מְעֻוָּות לֹא יוּכַל לִתְקוֹן וְגוֹ'. מִיּוֹמָא דְּאִתְחָרַב בֵּי מַקְדְּשָׁא, לָא אִשְׁתְּכַח אַסוּותָא בְּעָלְמָא, בְּגִינֵי כַּךְ בָּעֵי בַּר נָשׁ לְאִזְדַּהֲרָא, כִּי הֵיכִי דְּלִהֱוִי נָטִיר.","אַמְרֵי נְזִיל בַּהֲדֵי הַאי בַּר נָשׁ וְנֶחֱמֵי. אָמַר רִבִּי יִצְחָק, אָסִיר לָן. אִי הֲוָה אָזִיל לְגַבֵּי גַּבְרָא רַבָּא דָּחִיל חַטָּאָה, כְּגוֹן נַעֲמָן לְגַבֵּי אֱלִישָׁע, נֵזִיל אֲבַתְרֵיהּ. הַשְׁתָּא דְּאִיהוּ אָזִיל לְגַבֵּי רְחִיקֵי עָלְמָא, רְחִיקֵי אוֹרַיְיתָא, גַּעֲלֵי מִכֹּלָּא, אָסִיר לָן לְאִתְחֲזָאָה קָמַיְיהוּ. בְּרִיךְ רַחֲמָנָא דִּי שֵׁזִיב לָן מִנַּיְיהוּ. וְהַאי בַּר נָשׁ אָסִיר לֵיהּ. אָמַר רִבִּי יְהוּדָה, וְהָא תָּנֵינָן בַּכֹּל מִתְרַפְּאִין, חוּץ מֵעֲצֵי אֲשֵׁרָה וְכוּ'. אָמַר לֵיהּ, וְדָא עֲבוֹדָה זָרָה אִיהוּ, וְלָא עוֹד, אֶלָּא דְּהָא כְּתִיב (דברים י״ח:י׳) לֹא יִמָּצֵא בְךָ מַעֲבִיר בְּנוֹ וּבִתּוֹ בָּאֵשׁ וְגוֹ'. אַזְלוּ לְאָרְחַיְיהוּ.","אָזַל הַהוּא בַּר נָשׁ לְהַהִיא מְעַרְתָּא, הוּא וּבְרֵיהּ, שָׁרֵי לֵיהּ בִּמְעַרְתָּא. עַד דְּנָפַק אֲבוֹי לְקַטְרָא לַחֲמָרֵיהּ, נָפַק קִיטוּרָא דְּאֶשָּׁא, וּמָחָא לֵיהּ בְּרֵישָׁא, וְקַטְלֵיהּ. אַדְּהָכִי עָאל אֲבוֹי, וְאַשְׁכְּחֵיהּ מִית. נָטַל לֵיהּ וְלַחֲמָרֵיהּ, וְאָזַל לֵיהּ. וְאַשְׁכַּח לְהוּ לְבָתַר יוֹמָא חַד, לְרִבִּי יִצְחָק, וּלְרִבִּי יְהוּדָה, וְרִבִּי חִזְקִיָּה, דַּהֲווֹ אַזְלֵי. בָּכָה קָמַיְיהוּ, וְסָח לוֹן עוֹבָדָא. אָמַר רִבִּי יִצְחָק, וְלָא זִמְנִין סַגִּיאִין אֲמֵינָא לָךְ, דְּאָסִיר לְמֵיהַךְ תַּמָּן. בְּרִיךְ רַחֲמָנָא, (דניאל ד׳:ל״ד) דִּי כָל מַעֲבָדוֹהִי קְשׁוֹט, וְאֹרְחָתֵיהּ דִּין. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּאַזְלִין בְּאֹרַח קְשׁוֹט, בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, וְעָלַיְיהוּ כְּתִיב, (משלי ד׳:י״ח) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ וְגוֹ'.","אָמַר רִבִּי אֶלְעָזָר, בְּכָל עוֹבָדוֹי דְּבַּר נָשׁ, לִבְעֵי לֵיהּ דְּלִהֱווֹן כֻּלְּהוּ לִשְׁמָא קַדִּישָׁא. מַאי לִשְׁמָא קַדִּישָׁא. לְאַדְכְּרָא בְּפוּמֵיהּ שְׁמָא קַדִּישָׁא עַל כָּל מַה דְּאִיהוּ עָבִיד, דְּכֹלָּא הוּא לְפוּלְחָנֵיהּ, וְלָא יִשְׁרֵי עֲלוֹי סִטְרָא אָחֳרָא. בְּגִין דְּאִיהוּ זַמִּין תְּדִירָא לְגַבֵּי בְּנֵי נָשָׁא, וְיָכִיל לְאַשְׁרָאָה עַל הַהוּא עֲבִידְתָּא. וְעַל דָּא, הַשְּׁתִּי אוֹ הָעֵרֶב הֲוָה אִסְתְּאַב, וְשַׁרְיָא עָלֵיהּ רוּחַ מִסְאֲבָא. וּמַה בְּהַאי כַּךְ, מַאן דְּפָקִיד מִלּוֹי לְסִטְרָא אָחֳרָא דְּלָא אִצְטְרִיךְ, עַל אַחַת כַּמָּה וְכַמָּה. וּבְגִין כָּךְ כְּתִיב (דברים כ״ג:י׳) וְנִשְׁמַרְתָּ מִכָּל דָּבָר רָע."],[[0,"אמר ליה ר׳ יהודה וכו׳:","א״ל ר״י, הידעת אם אדם אחר ניזק בבית ההוא מקודם לכן. אמר לו אני יודע שמכמה ימים ניזק בו בן אדם אחד, והיו אומרים שמחלה היא, ומהם אמרו שהרוח שבבית הזיקו. ואח״כ נכנסו בו כמה בני אדם ולא נזוקו. אמרו, ר׳ יהודה ור׳ חזקיה, היינו שאמרו החברים, שבית שלא נבנה בצדק שורה בו רוח הטומאה, המזיק את יושביו. כנ״ל (אות ק״נ) אוי לאלו שעוברים על דבריהם."],[1,"פתח ר׳ יהודה וכו׳:","פר״י ואמר, הוי בונה ביתו בלא צדק. כי בכל מקום שנמצא בו צדק, שהוא המלכות, כל הרוחות וכל מזיקי עולם בורחים ממנו ואינם נמצאים לפניו. ועם כל זה מי שמקדים ולוקח המקום זכה בו. אם מלכות הקדושה מקדמת לקחת המקום זוכה בו הקדושה, ואם הסטרא אחרא מקדים למקום זוכה בו הס״א. אמר לו ר׳ חזקיה, אם כן, שוה השם הקדוש לרוח הטומאה, שאתה אומר מי שמקדים זוכה בו."],[2,"אמר ליה לאו וכו׳:","א\"ל אינו כן. אלא השם הקדוש, שהוא מלכות, אינו שורה במקום טומאה, ומשום זה אם השם הקדוש לוקח המקום מקודם לכן, כל הרוחות וכל מזיקי העולם אינם יכולים להראות שם, כל שכן לקרב אליו, ואם רוח הטומאה הוא קודם, הוא לוקח המקום, והשם הקדוש אינו שורה בו, כי אין זה מקומו."],[3,"וכד הוה נחית וכו׳:","וכשהיה יורד נגע צרעת, אל הבית, היה מטהר המקום ומוציא את רוח הטומאה ממקומו (כנ״ל אות קנ\"ג) ואח״כ נותצים הבית, העצים והאבנים והכל, ובונה אותו כבתחילה בצד הקדוש, בצדק, שמזכיר השם הקדוש ומשרה עליו הקדושה (כנ״ל אות ק״נ) ועם כל זה יבנה אותו בעפר אחר, וירחיק הבית ממקומו, מיסוד הראשון, ב׳ טפחים."],[4,"השתא דלא אתחזי וכו׳:","עתה שאינו נראה ואינו יורד מי שילחם ברוח הטומאה ההוא להוציאו ממקומו, כי עתה אינם נוהגים נגעים, מה התקנה, של אותו בית שרוח הטומאה הקדים לשבת שם. ומשיב, אם יכול בעצמו להוציאו מן הבית, טוב. ואם לא יבנה אותי כבתחילה באבנים אחרות ועצים והכל, ויוציאו וירחיקו ממקומו הראשון, ויבנה אותו בשביל השם הקדוש."],[5,"ועם כל דא וכו׳:","ועם כל זה, אין רוח הטומאה יוצא ממקום הראשון, והקדושה אינה שורה על מקום טמא. א\"ר יצחק, למה לו להטריח כל כך. לסתור הבית ולחזור לבנותו שלא במקומו הראשון כנ״ל, בזמן הזה, שאין נגעים, כתוב, מעוות לא יוכל לתקון וגו', כי מיום שנחרב בית המקדש, שאין נגעים נוהגים, אין רפואה נמצאת בעולם, משום זה צריך האדם להזהר כדי שיהיה שמור, מרוח הטומאה. דהיינו שלא ישב עוד בבית הזה."],[6,"אמרי נזיל בהדי וכו׳:","אמרו, נלך עם איש ההוא, למערת המצורעים, ונראה. א״ר יצחק, אסור לנו, אם היה הולך לקבל רפואה מאדם גדול ירא חטא, כמו נעמן שהלך אל אלישע, היינו הולכים אחריו, עתה שהוא הולך לרחוקים מן העולם. שהם מצורעים ומכשפים, לרחוקים מן התורה, מתועבים מכל, אסור לנו להראות לפניהם. ברוך הרחמן שהצילנו מהם. ואותו אדם אסור לו לקבל רפואה מהם. א\"ר יהודה, והרי למדנו בכל מתרפאים חוץ מעצי אשרה וכו', (פסחים כה.) אמר לו, זה, עבודה זרה הוא, ואסור. ולא עוד, אלא שכתוב, לא ימצא בך מעביר בנו ובתו באש וגו׳. הלכו לדרכם."],[7,"אזל ההוא בר נש וכו׳:","הלך אותו האדם למערה ההיא, הוא ובנו, והניח אותו במערה. בעוד שיצא אביו לקשור חמורו, יצא קיטור אש והכה את בנו בראשו, והרגו. בתוך כך נכנס אביו ומצאו שמת, לקח אותו ואת חמורו והלך לו. אחר זה, ביום אחד, מצא את ר׳ יצחק ור׳ יהודה ור׳ חזקיה שהיו הולכים, בכה לפניהם, וסיפר להם המעשה. א\"ר יצחק, וכי לא אמרתי לך פעמים הרבה שאסור ללכת שמה. ברוך הרחמן, שכל מעשיו אמת ודרכיו דין. אשרי הם הצדיקים שהולכים בדרך האמת בעולם הזה ובעולם הבא. ועליהם כתוב, וארח צדיקים כאור נגה וגו'."],[8,"אמר ר׳ אלעזר וכו׳:","אר״א, בכל מעשיו של האדם, צריך לו, שיהיו כולם לשמו הקדוש. מהו לשמו הקדוש, היינו שיזכיר בפיו את השם הקדוש על כל מה שעושה, שיהיה הכל לעבודתו, ולא ישרה עליו הסטרא אחרא, משום שהס״א מוכן תמיד לבני אדם, ויכול לשרות על מעשה ההוא שעושה, וע״כ, השתי או הערב היה נטמא, ורוח הטומאה שורה עליו. ומה בזה כך, מי שמצוה דבריו לסטרא אחרא, דהיינו בהשבעות וכדומה, שאינו צריך לעשות כך, על אחת כמה וכמה, שרוח הטומאה שורה עליו. ומשום זה כתוב, ונשמרת מכל דבר רע."]],[[0,"","אָמַר לוֹ רַבִּי יְהוּדָה, וּבְאוֹתוֹ הַבַּיִת הַאִם יָדַעְתָּ מִקֹּדֶם לָכֵן אִם נִזּוֹק בּוֹ אִישׁ אַחֵר? אָמַר לוֹ, יָדַעְתִּי, שֶׁהֲרֵי מִכַּמָּה יָמִים נִזּוֹק בּוֹ אִישׁ אֶחָד, וְהָיוּ אוֹמְרִים שֶׁהָיָה חוֹלֶה, וּמֵהֶם אוֹמְרִים שֶׁרוּחַ שֶׁל הַבַּיִת, וְאַחַר כָּךְ נִכְנְסוּ בוֹ כַּמָּה אֲנָשִׁים וְלֹא נִזּוֹקוּ. אָמְרוּ, זֶהוּ שֶׁאוֹמְרִים הַחֲבֵרִים, אוֹי לְאוֹתָם שֶׁעוֹבְרִים עַל דִּבְרֵיהֶם."],[1,"","פָּתַח רַבִּי יְהוּדָה וְאָמַר, (ירמיה כב) הוֹי בֹּנֶה בֵיתוֹ בְּלֹא צֶדֶק, שֶׁהֲרֵי בְּכָל מָקוֹם שֶׁנִּמְצָא בּוֹ צֶדֶק, כָּל הָרוּחוֹת וְכָל מַזִּיקֵי הָעוֹלָם בּוֹרְחִים מִמֶּנּוּ, וְלֹא נִמְצָאִים לְפָנָיו. וְעִם כָּל זֶה, מִי שֶׁמַּקְדִּים וְנוֹטֵל הַמָּקוֹם, אוֹחֵז בּוֹ. אָמַר לוֹ רַבִּי חִזְקִיָּה, אִם כָּךְ, שָׁקוּל הַשֵּׁם הַקָּדוֹשׁ כְּרוּחַ הַטֻּמְאָה?"],[2,"","אָמַר לוֹ, לֹא כָּךְ, אֶלָּא הַשֵּׁם הַקָּדוֹשׁ לֹא שׁוֹרֶה בְמָקוֹם טָמֵא, וּמִשּׁוּם כָּךְ, אִם הַשֵּׁם הַקָּדוֹשׁ נוֹטֵל הַמָּקוֹם מִקֹּדֶם לָכֵן, כָּל הָרוּחוֹת וְכָל מַזִּיקֵי הָעוֹלָם לֹא יְכוֹלִים לְהֵרָאוֹת בּוֹ, כָּל שֶׁכֵּן לִקְרַב עִמּוֹ. אִם רוּחַ טֻמְאָה קוֹדֵם וְנוֹטֵל אֶת הַמָּקוֹם - הַשֵּׁם הַקָּדוֹשׁ לֹא שׁוֹרֶה בּוֹ, שֶׁהֲרֵי אֵינוֹ מְקוֹמוֹ."],[3,"","וּכְשֶׁהָיָה יוֹרֵד נֶגַע צָרַעַת, הָיָה מְטַהֵר אֶת הַמָּקוֹם, וּמוֹצִיא אֶת רוּחַ הַטֻּמְאָה מִמְּקוֹמוֹ, וְאַחַר כָּךְ מְנַתְּצִים אֶת הַבַּיִת, הָאֲבָנִים וְהָעֵצִים וְהַכֹּל, וּבוֹנֶה אוֹתוֹ כְּמִקֹּדֶם, בַּצַּד הַקָּדוֹשׁ בְּצֶדֶק, שֶׁמַּזְכִּיר אֶת הַשֵּׁם הַקָּדוֹשׁ וּמַשְׁרֶה עָלָיו קְדֻשָּׁה, וְעִם כָּל זֶה בְּעָפָר אַחֵר, וְיַרְחִיק אֶת הַבַּיִת מִמְּקוֹמוֹ, מֵהַיְסוֹד הָרִאשׁוֹן שְׁנֵי טְפָחִים."],[4,"","עֵכְשָׁו שֶׁלֹּא נִרְאֶה וְלֹא יוֹרֵד מִי שֶׁמִּתְגָּרֶה בְּאוֹתָהּ רוּחַ טֻמְאָה לְהוֹצִיאָהּ מִמְּקוֹמוֹ, מַה תַּקָּנָתוֹ? אִם יָכוֹל לָצֵאת מִן הַבַּיִת הַזֶּה - יָפֶה, וְאִם לֹא - יִבְנֶה אוֹתוֹ כְּמִקֹּדֶם בַּאֲבָנִים אֲחֵרוֹת, וְעֵצִים וְהַכֹּל. וְיוֹצִיא וְיַרְחִיק אוֹתוֹ מֵהַמָּקוֹם הָרִאשׁוֹן, וְיִבְנֶה אוֹתוֹ עַל הַשֵּׁם הַקָּדוֹשׁ."],[5,"","וְעִם כָּל זֶה לֹא יוֹצֵאת אוֹתָהּ הָרוּחַ מִן הַמָּקוֹם הָרִאשׁוֹן, מִשּׁוּם שֶׁקְּדֻשָּׁה לֹא שׁוֹרָה עַל מָקוֹם טָמֵא. אָמַר רַבִּי יִצְחָק, לָמָּה לוֹ לִטְרֹחַ עַל זֶה? בַּזְּמַן הַזֶּה כָּתוּב, (קהלתא) מְעֻוָּת לֹא יוּכַל לִתְקוֹן וְגוֹ'. מִיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ לֹא נִמְצְאָה רְפוּאָה בָּעוֹלָם, מִשּׁוּם כָּךְ צָרִיךְ אָדָם לְהִזָּהֵר, כָּךְ שֶׁיִּהְיֶה שָׁמוּר."],[6,"","אָמְרוּ, נֵלֵךְ עִם הָאִישׁ הַזֶּה וְנִרְאֶה. אָמַר רַבִּי יִצְחָק, אָסוּר לָנוּ. אִם הָיָה הוֹלֵךְ לְאִישׁ גָּדוֹל יְרֵא חֵטְא, כְּמוֹ נַעֲמָן לֶאֱלִישָׁע, נֵלֵךְ אַחֲרָיו. עַכְשָׁו שֶׁהוּא הוֹלֵךְ לִרְחוֹקֵי הָעוֹלָם, רְחוֹקֵי הַתּוֹרָה, מְגֹעָלִים מִן הַכֹּל, אָסוּר לָנוּ לְהֵרָאוֹת לִפְנֵיהֶם. בָּרוּךְ הָרַחֲמָן שֶׁהִצִּיל אוֹתָנוּ מֵהֶם. וְהָאִישׁ הַזֶּה אָסוּר לוֹ. אָמַר רַבִּי יְהוּדָה, וַהֲרֵי שָׁנִינוּ, בַּכֹּל מִתְרַפְּאִים חוּץ מֵעֲצֵי אֲשֵׁרָה וְכוּ'. אָמַר לוֹ, וְזֶהוּ עֲבוֹדָה זָרָה, וְלֹא עוֹד, אֶלָּא שֶׁהֲרֵי כָּתוּב, (דברים יח) לֹא יִמָּצֵא בְךְ בְּנוֹ וּבִתּוֹ בָּאֵשׁ וְגוֹ'. הָלְכוּ לְדַרְכָּם."],[7,"","הָלַךָ אוֹתוֹ הָאִישׁ לַמְּעָרָה הַהִיא, הוּא וּבְנוֹ, שָׂם אוֹתוֹ בַּמְּעָרָה. עַד שֶׁיָּצָא אָבִיו לִקְשֹׁר אֶת חֲמוֹרוֹ, יָצָא קִיטוֹר שֶׁל אֵשׁ וְהִכָּה אוֹתוֹ בְּרֹאשׁוֹ וְהָרַג אוֹתוֹ. בֵּינְתַיִם נִכְנַס אָבִיו וּמָצָא אוֹתוֹ מֵת. לָקַח אוֹתוֹ וְאֶת חֲמוֹרוֹ וְהָלַךְ לוֹ. וּמָצָא אַחַר יוֹם אֶחָד אֶת רַבִּי יִצְחָק וְאֶת רַבִּי יְהוּדָה וְאֶת רַבִּי חִזְקִיָּה שֶׁהָיוּ הוֹלְכִים. בָּכָה לִפְנֵיהֶם, וְסִפֵּר לָהֶם אֶת הַמַּעֲשֶׂה. אָמַר רַבִּי יִצְחָק, וְהַאִם לֹא אָמַרְתִּי לְךְ פְּעָמִים רַבּוֹת שֶׁאָסוּר לָלֶכֶת לְשָׁם? בָּרוּךְ הָרַחֲמָן שֶׁכָּל מַעֲשָׂיו אֱמֶת, וּדְרָכָיו אֱמֶת. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁהוֹלְכִים בְּדֶרֶךְ הָאֱמֶת בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וַעֲלֵיהֶם כָּתוּב (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ וְגוֹ'."],[8,"","אָמַר רַבִּי אֶלְעָזָר, בְּכָל מַעֲשֵׂי הָאָדָם צָרִיךְ שֶׁכֻּלָּם יִהְיוּ לַשֵּׁם הַקָּדוֹשׁ. מַה זֶּה לַשֵּׁם הַקָּדוֹשׁ? לְהַזְכִּיר בְּפִיו אֶת הַשֵּׁם הַקָּדוֹשׁ עַל כָּל מַה שֶּׁהוּא עוֹשֶׂה שֶׁהַכֹּל הוּא לַעֲבוֹדָתוֹ, וְלֹא יִשְׁרֶה עָלָיו הַצַּד הָאַחֵר, מִשּׁוּם שֶׁהוּא תָּמִיד מְזֻמָּן לִבְנֵי הָאָדָם וְיָכוֹל לִשְׁרוֹת עַל אוֹתוֹ הַמַּעֲשֶׂה. וְעַל כֵּן, הַשְּׁתִי אוֹ הָעֵרֶב הָיָה נִטְמָא, וְשׁוֹרָה עָלָיו רוּחַ טֻמְאָה. וּמַה בָּזֶה כָּךְ - מִי שֶׁמַּפְקִיד דְּבָרָיו לַצַּד הָאַחֵר שֶׁלֹּא צָרִיךְ עַל אַחַת כַּמָּה וְכַמָּה. וּמִשּׁוּם כָּךְ כָּתוּב, (דברים כב) וְנִשְׁמַרְתָּ מִכָּל דָּבָר רָע."]]],[["רִבִּי אֶלְעָזָר הֲוָה אָזִיל לְמֵחֱמֵי לַאֲבוֹי (ס\"א לחמוי) וַהֲוָה עִמֵּיהּ רִבִּי אַבָּא. אָמַר רִבִּי אַבָּא נֵימָא מִלִּין דְּאוֹרַיְיתָא וְנֵזִיל. פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (בראשית י״ב:י״ג) אִמְרִי נָא אֲחוֹתִי אָתְּ, הַאי קְרָא קַשְׁיָא. וְכִי אַבְרָהָם דְּאִיהוּ דָּחִיל חַטָּאָה, רְחִימוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, הֲוָה אָמַר הָכִי עַל אִתְּתֵיהּ, בְּגִין דְּיוֹטְבִין לֵיהּ. אֶלָּא אַבְרָהָם, אַף עַל גַּב דְּהֲוָה דָּחִיל חַטָּאָה, לָא סָמִיךְ עַל זְכוּתָא דִּילֵיהּ, וְלָא בָּעָא מִן קוּדְשָׁא בְּרִיךְ הוּא לְאַפָּקָא זְכוּתֵיהּ, אֶלָּא עַל זְכוּתָא דְּאִתְּתֵיהּ, דְּיִרְוַוח בְּגִינָהּ מָמוֹנָא דִּשְׁאָר עַמִּין, דְּהָא מָמוֹנָא בְּאִתְּתֵיהּ זָכֵי לֵיהּ בַּר נָשׁ, הֲדָא הוּא דִכְתִיב, (משלי י״ט:י״ד) בַּיִת וָהוֹן נַחֲלַת אָבוֹת וּמֵיְיָ' אִשָּׁה מַשְׂכָּלֶת. מַאן דְּזָכֵי בְּאִשָּׁה מַשְׂכָּלֶת, זוֹכֶה בְּכֹלָּא. וּכְתִיב, (משלי ל״א:י״א) בָּטַח בָּהּ לֵב בַּעְלָהּ וְשָׁלָל לֹא יֶחְסָר.","וְאַבְרָהָם הֲוָה אָזִיל בְּגִינָהּ, לְמֵיכַל שְׁלָלָא מִשְּׁאַר עַמִּין, וְסָמִיךְ עַל זְכוּתָא דִּילָהּ, דְּלָא יֵכְלוּן לְאַעְנְשָׁא לֵיהּ, וּלְחַיְיכָא בָּהּ. וּבְגִּינֵי כַּךְ לָא יָהִיב מִדִי לְמֵימַר אֲחוֹתִי הִיא. וְלֹא עוֹד, אֶלָּא דְּחָמָא חַד מַלְאָכָא אָזִיל קַמָהּ, וְאָמַר לֵיהּ לְאַבְרָהָם, לָא תִּדְּחַל מִנָּהּ, קוּדְשָׁא בְּרִיךְ הוּא שָׁדַר לִי, לְאַפָּקָא לֵהּ מָמוֹנָא דִּשְׁאַר עַמִּין, וּלְנַטְרָא לָהּ מִכֹּלָּא. וּכְדֵין לָא דָּחִיל אַבְרָהָם מְאִתְּתֵיהּ, אֶלָּא מִנֵיהּ, דְּלָא חָמָא עִמֵּיהּ מַלְאָכָא, אֶלָּא עִמָּהּ. אָמַר הָא הִיא מִתְנַטְרָא, וַאֲנָא לָא נְטִירְנָא. וּבְגִּינֵי כַּךְ אָמַר, אִמְרִי נָא אֲחוֹתִי אַתְּ וְגוֹ'.","יִיטַב לִי, יֵיטִיבוּ לִי מִבָּעֵי לֵיהּ, דִּכְתִּיב וְהָיָה כִּי יִרְאוּ אוֹתָךְ הַמִצְרִים וְאָמְרוּ אִשְׁתּוֹ זֹאת, וְעַל דָּא יֵיטִיבוּ לִי מִבָּעֵי לֵיהּ. אֶלָּא יִיטַב לִי, דָּא דְּאָזִיל קַמָּךְ. יִיטַב לִי בְּהַאי עָלְמָא קוּדְשָׁא בְּרִיךְ הוּא בְּמָמוֹנָא. וְחָיְתָה נַפְשִׁי בְּהַהוּא עָלְמָא בִּגְלָלֵךְ, דְּלָא תִּסְטִי מִן אוֹרְחָא דִּקְשׁוֹט, דְּאִי אַזְכֵּי בְּגִינָךְ בְּמָמוֹנָא בְּהַאי עָלְמָא, וְתִסְטִי אַנְתְּ בְּאוֹרְחָא, הָא מִיתָא זְמִינָא בְּהַהוּא עָלְמָא, אֶלָּא תִּסְתַּמֵר, דִּתְחִי נַפְשִׁי בְּהַהוּא עָלְמָא בִּגְלָלֵךְ.","וּבְגִין דְּהַהוּא מַלְאָכָא אָזִיל קַמָה לְנַטְרָא לָהּ, מַה כְּתִיב. וַיְנַגַּע יְיָ' אֶת פַּרְעֹה וְגוֹ', עַל דְּבַר שָׂרַי וַדַּאי, דַּהֲוַת אַמְרַת לְמַלְאָכָא מָחֵי, וְהוּא מָחֵי. וְעַל דָּא לָא דָּחִיל אַבְרָהָם מִנָּהּ כְּלוּם, דְּהָא הִיא מִתְנַטְרָא. וּמַה דְּדָחִיל, מִגַּרְמֵיהּ דָּחִיל, דְּלָא חָמָא עִמֵּיהּ נְטוּרָא הָכִי.","תָּא חֲזֵי, עֶשֶׂר זִמְנִין פְּקִידַת שָׂרָה לְמַלְאָכָא, לְמַחֲאָה לְפַרְעֹה. וּבְעֶשֶׂר מַכְתְּשִׁין אַלְקֵי. סִימָנָא עַבְדַת שָׂרָה לִבְנָהָא בַּתְרָאָה בְּמִצְרַיִם.","רִבִּי אַבָּא פָּתַח, (מיכה ז׳:ט״ו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַחֲזָאָה פּוּרְקָנָא לִבְנוֹי, כְּאִינּוּן יוֹמִין דְּשָׁלַח קוּדְשָׁא בְּרִיךְ הוּא לְאַפָּקָא לְיִשְׂרָאֵל, וְאַחְזֵי אִינּוּן מַכְתְּשִׁין בְּמִצְרָאֵי, וְאַלְקֵי לוֹן בְּגִינֵיהוֹן דְּיִשְׂרָאֵל. תָּא חֲזֵי, מַה בֵּין פּוּרְקָנָא דָּא, לְפוּרְקָנָא דְּמִצְרַיִם. פּוּרְקָנָא דְּמִצְרַיִם הֲוָה בְּחַד מַלְכָּא, וּבְמַלְכוּ חֲדָא. הָכָא, בְּכָל מַלְכִין דְּעָלְמָא, וּכְדֵין יִתְיְיקָּר קוּדְשָׁא בְּרִיךְ הוּא בְּכָל עָלְמָא, וְיִנְדְּעוּן כֹּלָּא שׁוּלְטָנוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְכֻלְּהוּ יִלְקוּן בְּמַכְתְּשִׁין עִלָּאִין, עַל חַד תְּרֵין, בְּגִין דְּיִסָּרְבוּן כֻּלְּהוּ בְּיִשְׂרָאֵל.","וּכְדֵין יִתְגְּלֵי שׁוּלְטָנֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (זכריה י״ד:ט׳) וְהָיָה יְיָ' לְמֶלֶךְ עַל כָּל הָאָרֶץ. וּכְדֵין כֻּלְּהוּ יִתְנַדְּבוּן בְּהוּ בְּיִשְׂרָאֵל לְּקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ו:כ׳) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם וְגוֹ'. כְּדֵין קַיְימִין אֲבָהָן בְּחֶדְוָה, לְמֵחֱמֵי פּוּרְקָנָא דִּבְנַיְיהוּ כְּמִלְּקַדְּמִין. הֲדָא הוּא דִכְתִיב, כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. אָמֵן כֵּן יְהִי רָצוֹן. בָּרוּךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן: יִמְלוֹךְ יְיָ' אָמֵן וְאָמֵן:"],[[0,"ר׳ אלעזר הוה וכו׳:","ר״א היה הולך לראות את אביו, והיה עמו ר׳ אבא. א״ר אבא נאמר דברי תורה ונלך. פר״א ואמר, אמרי נא אחותי את. מקרא זה קשה, וכי אברהם שהיה ירא חטא, ואוהבו של הקב״ה, היה אומר כך על אשתו, כדי שיטיבו עמו. ומשיב, אלא אברהם, אע״פ שהיה ירא חטא, לא סמך על זכות שלו, ולא רצה מן הקב״ה לגרוע מן זכותו, אלא סמך על זכות של אשתו, שירויח בשבילה כסף של שאר העמים. כי כסף זוכה האדם בזכות אשתו. זהו שכתוב, בית והון נחלת אבות ומה' אשה משכלת. מי שזוכה באשה משכלת זוכה בכל. וכתוב, בטח בה לב בעלה ושלל לא יחסר."],[1,"ואברהם הוה אזיל וכו׳:","ואברהם היה הולך בזכותה, לאכול שלל שאר העמים, דהיינו, שלל לא יחסר. וסמך על זכות שלה שלא יוכלו להענישו ולצחק בה. ומשום זה לא נתן להם כלום, במה שאמר, אחותי היא. ולא עוד אלא שראה מלאך אחד הולך לפניה, ואמר לאברהם, אל תפחד בשבילה. כי הקב״ה שלח אותי להוציא הכסף של שאר העמים ולשמרה מכל. ואז לא פחד אברהם על אשתו אלא על עצמו, כי לא ראה המלאך עמו, אלא עם אשתו. אמר, הרי היא משומרת ואני איני משומר, ומשום זה אמר, אמרי נא אחותי את וגו׳."],[2,"ייטב לי:","שואל, ייטיבו לי היה צריך לומר. שהרי כתוב. והיה כי יראו אותך המצרים. ואמרו אשתו זאת וגו׳. וע״כ ייטיבו לי היה צריך לומר. ומשיב, אלא, \u0003ייטב לי\u0004 אותו שהולך לפניך, דהיינו המלאך. \u0003ייטיב לי\u0004 הקב״ה בעולם הזה בממון. \u0003וחיתה נפשי,\u0004 בעולם ההוא. \u0003בגללך,\u0004 היינו שלא תסורי מדרך האמת, שאם אזכה בשבילך בכסף בעולם הזה, ואת תסורי מן הדרך, הלא מיתה מוכנה לי בעולם ההוא, אלא תשמרי, שתחיה נפשי בעולם ההוא בגללך."],[3,"ובגין דההוא מלאכא וכו׳:","ומשום שמלאך ההוא הלך לפניה לשמרה, מה כתוב, וינגע ה׳ את פרעה, וגו׳ \u0003על דבר שרי\u0004 ודאי, דהיינו על דבריה, שהיתה אומרת למלאך הכה, והוא הכה. וע״כ לא פחד אברהם בשבילה כלום, שהרי היא משומדת, ומה שפחד בשביל עצמו פחד, שלא ראה שמירה על עצמו."],[4,"ת״ח עשר זמנין וכו׳:","בוא וראה עשר פעמים ציותה ישרה את המלאך להכות את פרעה. ובעשר מכות הוכה. כי סימן עשתה שרה אל בניה אחריה למצרים. דהיינו שיוכו המצרים בעשר מכות, עד שיגאלו מידיהם."],[5,"ר׳ אבא פתח וכו׳:","ר״א פתח, כימי צאתך מארץ מצרים אראנו נפלאות. עתיד הקב״ה להראות גאולה לבניו, כאלו הימים ששלח הקב״ה להוציא ישראל ממצרים, והראה אלו המכות במצרים והכה אותם בשביל ישראל. בוא וראה, מה בין גאולה זו שבסוף הימים, לבין גאולת מצרים. גאולת מצרים היתה במלך אחד, ובמלכות אחת, וכאן בכל המלכים שבעולם. ואז יתכבד הקב״ה בכל העולם, וידעו הכל ממשלתו של הקב״ה, וכולם יוכו במכות עליונות, על אחת פעמים, משום שימאנו כולם לשחרר את ישראל."],[6,"וכדין יתגלי וכו׳:","ואז תתגלה ממשלתו של הקב״ה, שכתוב, והיה ה׳ למלך על כל הארץ. ואז יתנדבו האומות בישראל להביאם להקב״ה. ז״ש, והביאו את כל אחיכם. אז יעמדו האבות לתחיה בשמחה לראות גאולת בניהם כבתחילה. ז״ש, כימי צאתך מארץ מצרים אראנו נפלאות."]],[[0,"","רַבִּי אֶלְעָזָר הָיָה הוֹלֵךְ לִרְאוֹת אֶת אָבִיו (חמיו), וְהָיָה עִמּוֹ רַבִּי אַבָּא. אָמַר רַבִּי אַבָּא, נֹאמַר דִּבְרֵי תוֹרָה וְנֵלֵךְ. פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (בראשית יב) אִמְרִי נָא אֲחֹתִי אָתְּ. הַפָּסוּק הַזֶּה קָשֶׁה, וְכִי אַבְרָהָם שֶׁהוּא יְרֵא חֵטְא, אֲהוּבוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הָיָה אוֹמֵר כָּךְ עַל אִשְׁתּוֹ כְּדֵי שֶׁיֵּיטִיבוּ לוֹ? אֶלָּא אַבְרָהָם, אַף עַל גַּב שֶׁהָיָה יְרֵא חֵטְא, לֹא סָמַךְ עַל זְכוּתוֹ, וְלֹא רָצָה מֵהַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא מִזְּכוּתוֹ, אֶלָּא עַל זְכוּת אִשְׁתּוֹ, שֶׁיַּרְוִיחַ בִּשְׁבִילָהּ מָמוֹן שֶׁל שְׁאָר הָעַמִּים, שֶׁהֲרֵי הַמָּמוֹן זוֹכֶה לוֹ הָאָדָם בְּאִשְׁתּוֹ. זֶהוּ שֶׁכָּתוּב (משלי יט) בַּיִת וָהוֹן נַחֲלַת אָבוֹת וּמֵה' אִשָּׁה מַשְׂכָּלֶת. מִי שֶׁזּוֹכֶה בְּאִשָּׁה מַשְׂכֶּלֶת, זוֹכֶה בַּכֹּל. וְכָתוּב, (שם לא) בָּטַח בָּהּ לֵב בַּעְלָהּ וְשָׁלָל לֹא יֶחְסָר."],[1,"","וְאַבְרָהָם הָיָה הוֹלֵךְ בִּשְׁבִילָהּ לֶאֱכֹל הַשָּׁלָל מִשְּׁאָר הָעַמִּים, וְסָמַךְ עַל זְכוּתָהּ שֶׁלֹּא יוּכְלוּ לְהַעֲנִישׁוֹ וְלִצְחֹק בָּהּ. וּמִשּׁוּם כָּךְ לֹא נָתַן דָּבָר לוֹמַר אֲחֹתִי הִיא, וְלֹא עוֹד, אֶלָּא שֶׁרָאָה מַלְאָךְ אֶחָד הוֹלֵךְ לְפָנֶיהָ, וְאָמַר לְאַבְרָהָם: אַל תִּפְחַד עָלֶיהָ, הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח אוֹתִי לְהוֹצִיא לוֹ אֶת מָמוֹן שְׁאָר הָעַמִּים וְלִשְׁמֹר אוֹתָהּ מֵהַכֹּל. וְאָז לֹא פָחַד עַל אִשְׁתּוֹ, אֶלָּא עָלָיו, שֶׁלֹּא רָאָה עִמּוֹ מַלְאָךְ, אֶלָּא עִמָּהּ. אָמַר, הֲרֵי הִיא שְׁמוּרָה, וַאֲנִי לֹא שָׁמוּר. וּמִשּׁוּם כָּךְ אָמַר, אִמְרִי נָא אֲחֹתִי אָתְּ וְגוֹ'."],[2,"","יִיטַב לִי?! יֵיטִיבוּ לִי הָיָה צָרִיךְ לִהְיוֹת, שֶׁכָּתוּב וְהָיָה כִּי יִרְאוּ אוֹתָךְ הַמִּצְרִים וְאָמְרוּ אִשְׁתּוֹ זֹּאת, וְעַל כֵּן יֵיטִיבוּ לִי צָרִיךְ לִהְיוֹת! אֶלָּא יִיטַב לִי - זֶה שֶׁהוֹלֵךְ לְפָנֶיךְ. יִיטַב לִי הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם הַזֶּה בְּמָמוֹן. וְחָיְתָה נַפְשִׁי בְּאוֹתוֹ הָעוֹלָם בִּגְלָלֵךְ, שֶׁלֹּא תִסְטִי מִדֶּרֶךְ הָאֱמֶת. שֶׁאִם אֶזְכֶּה בִּגְלָלֵךְ בְּמָמוֹן בָּעוֹלָם הַזֶּה וְאַתְּ תִּסְטִי בַדֶּרֶךְ, הֲרֵי מִיתָה זְמִינָה בָּעוֹלָם הַהוּא, אֶלָּא תִּשָּׁמְרִי, שֶׁתְּחִי נַפְשִׁי בָּעוֹלָם הַהוּא בִּגְלָלֵךְ."],[3,"","וּמִשּׁוּם שֶׁהַמַּלְאָךְ הַהוּא הָלַךְ לְפָנֶיהָ לִשְׁמֹר אוֹתָהּ, מַה כָּתוּב? וַיְנַגַּע ה' אֶת פַּרְעֹה וְגוֹ', עַל דְּבַר שָׂרַי, וַדַּאי. שֶׁהָיְתָה אוֹמֶרֶת לַמַּלְאָךְ הַכֵּה - וְהוּא מַכֶּה. וְעַל כֵּן לֹא פָחַד אַבְרָהָם עָלֶיהָ כְּלוּם, שֶׁהֲרֵי הִיא שְׁמוּרָה. וּמַה שֶּׁפָּחַד - עַל עַצְמוֹ פָּחַד, וְלֹא רָאָה עִמּוֹ שְׁמִירָה כָּזוֹ."],[4,"","בֹּא רְאֵה, עֶשֶׂר פְּעָמִים צִוְּתָה שָׂרָה לַמַּלְאָךְ לְהַכּוֹת אֶת פַּרְעֹה, וּבְעֶשֶׂר מַכּוֹת לָקָה. סִימָן עָשְׂתָה שָׂרָה לְבָנֶיהָ אַחֲרֶיהָ בְּמִצְרַיִם."],[5,"","רַבִּי אַבָּא פָּתַח, (מיכהז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַרְאוֹת גְּאֻלָּה לְבָנָיו כְּאוֹתָם הַיָּמִים שֶׁשָּׁלַח הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא אֶת יִשְׂרָאֵל, וְהֶרְאָה אֶת אוֹתָן הַמַּכּוֹת לְמִצְרַיִם, וְהִלְקָה אוֹתָם בִּגְלַל יִשְׂרָאֵל. בֹּא וּרְאֵה מַה בֵּין הַגְּאֻלָּה הַזּוֹ לִגְאֻלַּת מִצְרַיִם. גְּאֻלַּת מִצְרַיִם הָיְתָה בְּמֶלֶךְ אֶחָד, וּבְמַלְכוּת אַחַת - כָּאן בְּכָל הַמְּלָכִים שֶׁל הָעוֹלָם. וְאָז יִתְכַּבֵּד הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל הָעוֹלָם, וְיֵדְעוּ הַכֹּל שִׁלְטוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֻלָּם יִלְקוּ בְמַכּוֹת עֶלְיוֹנוֹת, עַל אַחַת שְׁתַּיִם, מִפְּנֵי שֶׁיְּסָרְבוּ כֻלָּם אֶת יִשְׂרָאֵל."],[6,"","וְאָז יִתְגַּלֶּה שִׁלְטוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (זכריה יד) וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ. וְאָז כֻּלָּם יִתְנַדְּבוּ אֶת יִשְׂרָאֵל לַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב (ישעיה סו) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם וְגוֹ'. אָז יַעַמְדוּ הָאָבוֹת בְּשִׂמְחָה לִרְאוֹת אֶת גְּאֻלַּת בְּנֵיהֶם כְּמִקֹּדֶם. זֶהוּ שֶׁכָּתוּב כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת, אָמֵן כֵּן יְהִי רָצוֹן. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן פרשׁת מְצֹרָע"]]]]};
